insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Psiquiatria','Impulsividade, desinibição, irritabilidade e labilidade afetiva são comuns em pacientes portadores de lesão na área pré-frontal','','','["dorso-lateral.", "órbito-frontal.", "pars opercularis.", "dorso-medial."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Resposta indicada no gabarito: órbito-frontal..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Psiquiatria','Assinale o medicamento cujo uso está indicado no tratamento dos distúrbios do sono que acompanham o transtorno de estresse pós-traumático.','','','["Amantadina.", "Bupropriona.", "Clonidina.", "Sibutramina."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa C. Resposta indicada no gabarito: Clonidina..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Psiquiatria','A inabilidade, ou dificuldade, em descrever ou de ter consciência das próprias emoções ou humor é denominada','','','["disforia.", "anedonia.", "alexitimia.", "anomia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa C. Resposta indicada no gabarito: alexitimia..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Psiquiatria','Reações paradoxais, caracterizadas por desinibição e agitação, são um efeito colateral que pode resultar do uso de','','','["antipsicóticos atípicos.", "benzodiazepínicos.", "inibidores seletivos da recaptação da serotonina.", "neurolépticos."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Resposta indicada no gabarito: benzodiazepínicos..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Psiquiatria','Num atendimento de urgência de um paciente com sintomas mentais, alguns parâmetros podem orientar o médico na distinção entre uma intercorrência clínica e um transtorno psiquiátrico funcional. A correção do exame psicopatológico nestes momentos é de grande relevância para o prognóstico do caso, devendo ser o mais preciso possível. Dentre os itens abaixo, assinale aquele que não contém sintomas altamente sugestivos de doença clínica.','','','["Rebaixamento do nível de consciência.", "Desorientação têmporo-espacial.", "Ilusões e distorções senso-perceptivas.", "Fuga de ideias."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: Fuga de ideias..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Psiquiatria','Assinale a modalidade de psicoterapia que sustenta, como postulado central, a ideia de que as crenças que as pessoas têm e as avaliações que elas fazem a respeito dos acontecimentos e das situações são pelo menos tão importantes na determinação de suas reações emocionais quanto os próprios acontecimentos e situações.','','','["Cognitiva.", "Existencial.", "Interpessoal.", "Psicanalítica."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: Cognitiva..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Psiquiatria','A alteração psicopatológica observada na esquizofrenia que se caracteriza pela manutenção dos membros superiores e/ou inferiores em posições externamente impostas é chamada','','','["negativismo ativo.", "flexibilidade cérea.", "estereotipia.", "postura inadequada."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa C. Resposta indicada no gabarito: estereotipia..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Psiquiatria','Para fins de determinação da responsabilidade penal nos termos do artigo 26 do Código Penal brasileiro, os silvícolas não adaptados são considerados portadores de','','','["desenvolvimento mental incompleto.", "desenvolvimento mental retardado.", "doença mental.", "perturbação da saúde mental."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: desenvolvimento mental incompleto..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Psiquiatria','A síndrome de Wenicke é constituída pelos seguintes sintomas:','','','["confabulação, dismnésia e desorientação.", "ataxia, confabulação e dismnésia.", "convulsão, coma e icterícia.", "ataxia, oftalmoplegia e quadro confusional."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: ataxia, oftalmoplegia e quadro confusional..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Psiquiatria','Assinale o medicamento que é mais indicado para tratamento da ideação suicida em pacientes com esquizofrenia.','','','["Clozapina.", "Haloperidol", "Tioridazina.", "Zuclopentixol."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: Clozapina..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Psiquiatria','Qual destes quadros caracteriza um distúrbio primário do nível de consciência?','','','["Transtorno do pânico.", "Esquizofrenia.", "Demência de Pick.", "Delirium."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: Delirium..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Psiquiatria','Nos transtornos delirantes do tipo erotomaníaco, a(o) paciente geralmente acredita ser amada(o) por uma pessoa','','','["totalmente desconhecida.", "de status social mais elevado.", "do mesmo sexo que ela(e).", "mais jovem e mais bonita."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Resposta indicada no gabarito: de status social mais elevado..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Psiquiatria','Em relação ao mecanismo de ação, aponte qual dos antipsicóticos abaixo tem como principal característica a ação de agonista parcial dos receptores dopaminérgicos (D2) e serotoninérgicos (5HT1A).','','','["Clozapina.", "Amisulprida.", "Aripiprazol.", "Pimozide."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa C. Resposta indicada no gabarito: Aripiprazol..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
