insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Psiquiatria','O uso do exame eletroencefalográfico em psiquiatria é útil em vários casos, dentre eles, para auxiliar o diagnóstico de','','','["doença de Alzheimer.", "transtorno obsessivo compulsivo.", "delirium.", "esquizofrenia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa C. Resposta indicada no gabarito: delirium..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Psiquiatria','Qual é o transtorno da personalidade mais fortemente associado à prática de suicídio?','','','["Anancástica.", "Borderline.", "Dependente.", "Passivo-agressiva."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Resposta indicada no gabarito: Borderline..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Psiquiatria','Na construção de escalas em psiquiatria, entende--se que, quanto mais claro, simples, de fácil compreensão e pontuação for o instrumento, maior deve ser a sua','','','["confiabilidade.", "validade.", "especificidade.", "sensibilidade."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: confiabilidade..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Psiquiatria','Comportamento auto-mutilatório é característica-mente observado na síndrome de','','','["Angelman.", "Down.", "Lesch-Nyhan.", "Williams."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa C. Resposta indicada no gabarito: Lesch-Nyhan..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Psiquiatria','Os critérios diagnósticos da CID 10 para a síndrome de Asperger ajudam a diferenciá-la do autismo, basicamente por não ser característico da segunda, encontrar-se','','','["alteração na interação social recíproca.", "repertório de interesses e comportamentos restritos.", "comportamento estereotipado e repetitivo.", "preservação do desenvolvimento cognitivo global e da linguagem."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: preservação do desenvolvimento cognitivo global e da linguagem..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Psiquiatria','Assinale o antidepressor cujo uso está mais fortemente associado à ocorrência de efeitos adversos de natureza sexual.','','','["Bupropriona.", "Mirtazapina.", "Nefazodona.", "Paroxetina."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: Paroxetina..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Psiquiatria','Qual a demência caracterizada por movimentos involuntários (mioclônicos ou coreoatetóticos), ataxia, e alterações características e periódicas no eletroence- falograma, que ocorre principalmente em indivíduos jovens (40 anos), tendo um curso rápido para a deterioração?','','','["Demência pelo vírus da imunodeficiência adquirida.", "Demência alcoólica.", "Doença de Creutzfeldt-Jakob.", "Neurolues."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa C. Resposta indicada no gabarito: Doença de Creutzfeldt-Jakob..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Psiquiatria','Assinale o transtorno do controle dos impulsos cuja prevalência é mais alta entre as mulheres do que entre os homens.','','','["Jogo patológico.", "Piromania.", "Transtorno explosivo intermitente.", "Tricotilomania."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: Tricotilomania..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Psiquiatria','Anosoagnosia, amusia receptiva e disprosódias são sintomas relacionados a lesões em região','','','["occipital de hemisfério não dominante.", "gânglios da base de hemisfério dominante.", "pré-frontal de hemisfério dominante.", "têmporo-parietal de hemisfério não dominante."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: têmporo-parietal de hemisfério não dominante..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Psiquiatria','O termo catatonia foi cunhado por','','','["Kalhbaum.", "Kraepelin.", "Kretschmer.", "Kohut."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: Kalhbaum..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Psiquiatria','Uma paciente de 30 anos de idade vem, há cerca de 3 semanas, apresentando um quadro alucinatório- delirante em vigência de claridade de consciência, sintomas estes extremamente variáveis quanto ao tipo e à intensidade durante o dia. Mantém ainda intensa instabilidade emocional, ora chorando, ora ansiosa, ora triste, ora exteriorizando estado de êxtase. Esse quadro é compatível com','','','["transtorno polimórfico agudo.", "esquizofrenia residual.", "demência alcoólica.", "delirium."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: transtorno polimórfico agudo..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Psiquiatria','Pode(m) mitigar ou excluir a imputabilidade penal, dependendo do grau de comprometimento que ocasione(m) das capacidades de entendimento e/ou autodeterminação do agente em relação ao caráter ilícito do fato delituoso:','','','["embriaguez completa, voluntária ou culposa, pelo álcool ou substância de efeitos análogos.", "embriaguez completa, proveniente de caso fortuito ou força maior.", "emoção ou paixão.", "idade entre 18 e 21 anos."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Resposta indicada no gabarito: embriaguez completa, proveniente de caso fortuito ou força maior..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Psiquiatria','Na depressão pós-acidente vascular encefálico, um sinal frequentemente presente é','','','["prosopoagnosia.", "heminegligência.", "reação catastrófica.", "anosoagnosia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa C. Resposta indicada no gabarito: reação catastrófica..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Psiquiatria','Entre os medicamentos utilizados para o tratamento de transtornos mentais, assinale aquele que é responsável pelo maior número de mortes por superdosagem.','','','["Amitriptilina.", "Clonazepam.", "Fluoxetina.", "Haloperidol."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: Amitriptilina..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Psiquiatria','O tipo de transtorno dissociativo onde a principal característica é que o paciente responde sistemati-camente às perguntas usando “respostas aproximadas” é chamado','','','["síndrome de Ganser.", "síndrome de Capgras.", "transtorno de transe.", "estupor dissociativo."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: síndrome de Ganser..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Psiquiatria','Bromose é uma preocupação delirante com','','','["aparência física.", "doenças.", "infestações parasitárias.", "odores corporais."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: odores corporais..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Psiquiatria','Tumores cerebrais podem manifestar-se clinicamente como síndromes neuropsiquiátricas distintas, variando também de acordo com suas localizações. Num paciente com esta patologia, que vem apresentando mutismo acinético, há fortes indícios de que sua patologia esteja localizada em qual das regiões abaixo?','','','["Córtex pré-frontal.", "Cíngulo anterior.", "Hipotálamo.", "Cerebelo."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Resposta indicada no gabarito: Cíngulo anterior..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Psiquiatria','No contexto do exame pericial psiquiátrico, fica relativizada a tradicional obrigação ética de','','','["confidencialidade.", "imparcialidade.", "isenção.", "objetividade."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: confidencialidade..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Psiquiatria','É exemplo de dissonia','','','["sonambulismo.", "insônia.", "pesadelo.", "terror noturno."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Resposta indicada no gabarito: insônia..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Psiquiatria','É um teste projetivo da personalidade','','','["escala de temperamento afetivo de Akiskal.", "inventário de personalidade multifásico de Minnesota (MMPI).", "inventário de temperamento e caráter (TCI).", "teste de Rorschach."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: teste de Rorschach..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Psiquiatria','Uma das formas de apresentação do transtorno de personalidade emocionalmente instável é o tipo','','','["histriônico.", "ansioso.", "dependente.", "impulsivo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: impulsivo..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Psiquiatria','A sulpirida é um antipsicótico da classe química das','','','["benzamidas substituídas.", "dibenzodiazepinas.", "difenilbutilpiperidinas.", "fenotiazinas piperidínicas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: benzamidas substituídas..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Psiquiatria','O quadro demencial que tipicamente é transmitido por um gene autossômico dominante é a doença de','','','["Creuzfeldt-Jakob.", "Alzheimer.", "Parkinson.", "Huntington."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: Huntington..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Psiquiatria','Anedonia, culpa, alterações da psicomotricidade e distúrbios vegetativos acentuados são tipicamente observados nos episódios depressivos com características','','','["atípicas.", "melancólicas.", "mistas.", "psicóticas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Resposta indicada no gabarito: melancólicas..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Psiquiatria','O transtorno bipolar do tipo II tem como característica cursar com quadros de','','','["depressão maior com episódios hipoma- níacos discretos.", "depressão maior com mania, alterna- damente.", "episódios maníacos, sempre com psicose.", "episódios maníacos e depressivos com ciclagem rápida."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: depressão maior com episódios hipoma- níacos discretos..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Psiquiatria','A consequência mais importante da privação total de sono é','','','["ideação suicida.", "comprometimento cognitivo.", "humor ansioso.", "psicose."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Resposta indicada no gabarito: comprometimento cognitivo..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Psiquiatria','A síndrome de Landau-Kleffner é um transtorno da infância caracterizado por','','','["afasia adquirida e epilepsia.", "disgrafia e discalculia.", "retardo mental e nistagmo.", "dislalia e dismetria."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: afasia adquirida e epilepsia..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Psiquiatria','Consumidos em suas doses habituais, os alucinógenos, como o LSD e a mescalina, alteram predominantemente as seguintes funções psíquicas:','','','["afetos, emoções e sentimentos.", "memórias episódica e semântica.", "nível de consciência, atenção e orientação.", "percepção, cognição e humor."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: percepção, cognição e humor..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Psiquiatria','Quadros que se manifestam basicamente por alterações do funcionamento motor voluntário ou sensorial de causa psicogênica são denominados transtorno','','','["dos impulsos.", "conversivo.", "dissociativo.", "psicossomático."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Resposta indicada no gabarito: conversivo..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Psiquiatria','A penicilamina pode ser empregada no tratamento da demência associada à doença de','','','["Creutzfeldt-Jakob.", "Huntington.", "Pick.", "Wilson."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: Wilson..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Psiquiatria','Um paciente idoso vem apresentando dificuldade em encontrar palavras para expressar-se, o que o vem perturbando há, pelo menos, 8 meses. O psiquiatra identifica o sintoma no discurso informal do paciente durante o exame clínico, onde o paciente faz várias interrupções, constrangido. Solicitado um exame neuropsicológico, observou-se preservação funcional dos demais domínios cognitivos. Esta disfunção é denominada','','','["disnomia.", "parafasia.", "afasia de Wernicke.", "dislalia."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa A. Resposta indicada no gabarito: disnomia..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Psiquiatria','Homens idosos que matam suas esposas e, logo em seguida, cometem suicídio, tipicamente o fazem porque','','','["apresentam quadros delirantes com temática persecutória.", "estão tomados por ciúmes intensos.", "querem ficar com todos os bens do casal para si e casarem se de novo.", "estão deprimidos e suas esposas estão muito doentes."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: estão deprimidos e suas esposas estão muito doentes..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Psiquiatria','A síndrome de Munchausen é um exemplo de transtorno','','','["de personalidade do tipo antisocial.", "dissociativo.", "factício.", "hipocondríaco."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa C. Resposta indicada no gabarito: factício..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Psiquiatria','A capacidade dos seres humanos de entender o estado mental de outras pessoas e, assim, reconhecer não apenas as metas e intenções delas, mas, também, seus fingimentos e simulações denomina-se','','','["contágio emocional.", "simetria mental.", "telepatia.", "teoria da mente."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa D. Resposta indicada no gabarito: teoria da mente..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Psiquiatria','Ao contrário do que ocorre nas pseudocrises epilépticas, as crises epilépticas verdadeiras são comumente seguidas de um aumento significativo dos níveis sanguíneos do hormônio','','','["calcitonina.", "paratormônio.", "prolactina.", "triiodotironina."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa C. Resposta indicada no gabarito: prolactina..' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Psiquiatria','Leia o enunciado e as alternativas da questão 50 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-psiquiatria-q50-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Psiquiatria: alternativa B. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-psiquiatria' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-radiologia','PMERJ 2010 — Oficial — Médico Radiologia','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Radiologia','Mulher de 50 anos, queixando-se de cefaleia há muito tempo e anosmia recente, realizou tomografia computadorizada do crânio que evidenciou formação expansiva sólida, bem delimitada, localizada na região frontal esquerda, parasagital, hiperdensa em relação ao parênquima cerebral adjacente, com intenso e uniforme realce após administração venosa do meio de contraste. A hipótese diagnóstica mais provável é de','','','["craniofaringeoma.", "glioblastoma multiforme.", "meningeoma.", "Teratoma."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: meningeoma..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Radiologia','Paciente do sexo masculino, com 30 anos de idade, vítima de acidente automobilístico, deu entrada no serviço de emergência em coma profundo e a tomografia computadorizada realizada imediatamente demonstrou obliteração dos sulcos e dos espaços subaracnoides, das cisternas supraselar e perimesen- cefálica e os ventrículos cerebrais de volume reduzido, sem desvios das estruturas da linha média. O provável diagnóstico a ser feito é de','','','["herniação subfalcina.", "isquemia cerebral.", "edema cerebral difuso.", "hemorragia subaracnoide."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: edema cerebral difuso..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Radiologia','Leia o enunciado e as alternativas da questão 3 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q03-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa A. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Radiologia','Paciente do sexo masculino, apresentando múltiplas telangiectasias mucocutâneas, fístulas arterio-venosas no pulmões e no fígado e aneurismas cerebrais, detectados por angiotomografia computadorizada e confirmados por angiografia digital. O diagnóstico mais provável é de','','','["ataxia-telangiectasia.", "melanose neurocutânea.", "angiomatose meníngea.", "doença de Rendu-Osler-Weber."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa D. Resposta indicada no gabarito: doença de Rendu-Osler-Weber..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Radiologia','Paciente masculino, com 25 anos, apresentando febre, cefaleia e sonolência duas semanas após vacinação para tétano, evoluiu com convulsão. Realizou tomografia do crânio que não evidenciou alterações, sendo submetido à ressonância magnética que mostrou focos hiperintensos nas sequências em T2, subcorticais multifocais, bilaterais e assimétricas. O diagnóstico mais provável é de','','','["leucoencefalopatia multifocal progressiva.", "tuberculose.", "pan-encefalite esclerosante subaguda.", "encefalomielite aguda disseminada."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa D. Resposta indicada no gabarito: encefalomielite aguda disseminada..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Radiologia','Paciente do sexo masculino, com 30 anos, apresentando diarreia, realizou exame de trânsito delgado que demonstrou ulcerações transversais na mucosa do íleo terminal e ceco, de maneira contínua, sem sinais de fístulas. O diagnóstico mais provável é de','','','["doença de Crohn.", "tuberculose.", "paracoccidioidomicose.", "linfoma intestinal."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: tuberculose..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Radiologia','Mulher de 50 anos, com dor epigástrica que piora na posição supina e com irradiação para o dorso, associada a náuseas e vômitos, febre baixa e distensão abdominal, procurou um serviço de emergência sendo realizada uma rotina de abdome agudo que demonstrou derrame pleural esquerdo com atelectasias na base pulmonar correspondente, gastroparesia com distorção da grande curvatura gástrica e aumento do espaço gastrocólico, apagamento do contorno do músculo psoas à esquerda. Encaminhado à ultrassonografia, foi evidenciado vesícula bilar com conteúdo heterogêneo, parcialmente preenchida com lama biliar e microcálculos em suspensão, sendo o restante do exame prejudicado pela distensão gasosa de alças intestinais. Deve ser sugerida a hipótese diagnóstica de','','','["colecistite.", "pancreatite.", "diverticulite.", "colite."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: pancreatite..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Radiologia','Homem de 45 anos, alcoolista, em acompanhamento ambulatorial de cirrose e hipertensão portal, realizou ultrassonografia que demonstrou material ecogênico no interior das veias hepáticas média e direita com redução de calibre e ausência de fluxo ao dooppler, sendo evidenciado ainda vasos tortuosos no parênquima hepático compatíveis com vasos acessórios. O diagnóstico a ser sugerido é de','','','["síndrome de Budd-Chiari.", "hepatocarcinoma.", "trombose de veia porta.", "aneurisma de artéria hepática."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa A. Resposta indicada no gabarito: síndrome de Budd-Chiari..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Radiologia','Paciente jovem, do sexo feminino, com dor e distensão abdominal, e com sangramento intestinal, realizou tomografia computadorizada do abdome que mostrou alças do intestino delgado distendidas, algumas delas com importante espessamento da mucosa e redução da luz. Deve ser sugerido o diagnóstico de','','','["doença de Crohn.", "tuberculose intestinal.", "trombose mesentérica com isquemia intestinal.", "paracoccidiodomicose intestinal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: trombose mesentérica com isquemia intestinal..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Radiologia','Paciente com hepatomegalia, miocardiopatia, hiperpigmentação cutânea e diabetes mellitus realizou tomografia computadorizada do abdome sem contraste venoso que demonstrou fígado com densidade difusamente aumentada em comparação com o baço. Os vasos encontram-se mais proeminentes que o normal. O diagnóstico a ser sugerido é de','','','["doença de Wilson.", "esteatose.", "esquistossomose.", "hemocromatose."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa D. Resposta indicada no gabarito: hemocromatose..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Radiologia','Criança com 3 anos de idade, com diagnóstico prévio de neurofibromatose, realizou tomografia computadorizada do crânio que mostrou lesão expansiva sólida, supraselar, com forte reforço após a administração do meio de contraste venoso, envolvendo ambos os nervos ópticos. O diagnóstico a ser sugerido é de','','','["macroadenoma.", "germinoma.", "glioma.", "hamartoma de tuber cinéreo."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: glioma..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Radiologia','Paciente masculino, com 25 anos apresentando cefaleia e convulsões, realizou tomografia computa- dorizada do crânio que mostrou massa arredondada, bem delineada, uniformemente hipodensa (-20 a -40 U.H.) com calcificação capsular, localizada na linha média na fossa posterior. O diagnóstico a ser sugerido é de','','','["tumor dermoide.", "cisto aracnoide.", "lipoma.", "neurofibroma."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa A. Resposta indicada no gabarito: tumor dermoide..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Radiologia','Mulher de 52 anos, apresentando distúrbios de movimentos e alterações mentais e comportamentais, sugerindo quadro demencial, realizou tomografia computadorizada e ressonância magnética do crânio que demonstraram sinais de atrofia cortical e subcortical com acentuada perda de volume dos núcleos caudados e dilatação focal dos cornos frontais dos ventrículos laterais.  O dignóstico a ser sugerido é de doença de','','','["Huntington.", "Alzheimer.", "Fahr.", "Wilson."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa A. Resposta indicada no gabarito: Huntington..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Radiologia','O pâncreas forma-se durante a quarta semana de vida embrionária, a partir da porção caudal do intestino primitivo como broto endodérmico pancreático, dorsal e ventral. Quando não há fusão dos dois brotos pancreáticos e, consequentemente, dos ductos pancreáticos e a ultrassonografia e a tomografia computadorizada diferenciam a porção originada dos brotos dorsal e ventral por diferença de ecogenicidade e atenuação, com o pâncreas ventral apresentando-se mais hipoecogênico e hiperatenuante em relação ao dorsal. O diagnóstico a ser sugerido é de pâncreas','','','["anular.", "divisum.", "heterotópico.", "atrófico."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: divisum..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Radiologia','Paciente com leucemia, apresentando febre contínua, desconforto abdominal, disfagia e palidez, com aumento sério da fosfatase alcalina e da gama-GT e hepatoesplenomegalia ao exame físico, realizou ultrassonografia abdominal que demonstrou formação cística com conteúdo espesso no baço, além de confirmar a hepatoesplenomegalia. O diagnóstico a ser sugerido é de','','','["histoplasmose.", "tuberculose.", "equinococose.", "candidíase."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa D. Resposta indicada no gabarito: candidíase..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Radiologia','Paciente do sexo masculino, com 35 anos, referindo dor abdominal inespecífica, realizou ultrassonografia que demonstrou massa hiperecogênica bem definida na adrenal direita, sendo evidenciado ainda artefato de propagação do som através do tumor, levando a descontinuidade da imagem do diafragma em correspondência. O diagnóstico a ser sugerido é de','','','["carcinoma adrenocortical.", "hemangioma.", "mielolipoma.", "adenoma."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: mielolipoma..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Radiologia','Paciente com 55 anos, diabético e hipertenso com dor perineal e lombar, febre e sintomas urinários diversos, com relato de febre e estando em uso de antibióticos há 1 semana, sem melhora dos sintomas, realizou ultrassonografia da próstata que demonstrou áreas hipoecogênicas de paredes espessas e irregulares, levando a distorção arquitetural da glândula. O diagnóstico a ser sugerido é de','','','["carcinoma.", "abscesso.", "hiperplasia prostática benigna.", "prostatite aguda."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: abscesso..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Radiologia','Paciente apresentando cisto renal multiloculado, de conteúdo ecogênico, com paredes espessas e irregulares, com septos grosseiros e complexos e calcificações murais grosseiras. Pela classificação de Bosniak, o cisto é do tipo:','','','["I.", "II.", "III.", "IV."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa D. Resposta indicada no gabarito: IV..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Radiologia','Paciente esplenectomizado por trauma abdominal, apresentando em exame de controle ultrassonográfico imagens nodulares no hipocôndrio esquerdo, com ecotextura semelhante à do baço. Deve-se sugerir o diagnóstico de','','','["hemocromatose.", "esplenose.", "hamartoma.", "peliose."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: esplenose..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Radiologia','A associação entre hemangiomas cavernosos hepáticos, com trombocitopenia e hipofibrinogenemia, por provável consumo dos fatores de coagulação e de plaquetas, é denominada síndrome de','','','["Rendu-Osler-Weber.", "Caroli.", "Kasabach-Merritt.", "Mirizzi."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Kasabach-Merritt..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Radiologia','A ausência de mudança do calibre da veia porta ou um aumento menor que 20% no seu diâmetro, durante a inspiração profunda, são sinais ultrassonográficos encontrados em pacientes cirróticos com','','','["hipertensão portal.", "trombose de veia porta.", "insuficiência cardíca.", "ascite."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa A. Resposta indicada no gabarito: hipertensão portal..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Radiologia','Criança apresentando sangramento nas fezes, realizou ultrassonografia do abdome que demonstrou  segmento de alça intestinal espessada, em fundo cego, localizada na borda antimesentérica do íleo. O diagnóstico a ser sugerido é de','','','["apendagite epiploica.", "apendicite.", "divertículo de Meckel.", "adenite mesentérica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: divertículo de Meckel..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Radiologia','Criança com icterícia fisiológica prolongada, fontanelas e suturas alargadas, hipotermia e hipoatividade, mixedema e pele seca, áspera e descamativa, pseudo-hipertelorismo ocular e nariz em sela com constipação intestinal, abdome protuberante pela hipotonia muscular e com atraso na maturação óssea, sugere-se o diagnóstico de:','','','["mucoviscidose.", "hipotireoidismo congênito.", "doença de Takayasu.", "hiperplasia fibromuscular."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: hipotireoidismo congênito..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Radiologia','A medida da translucência nucal é considerada o melhor marcador fetal para o rastreamento de anomalias, devendo ser realizada entre que semanas de gestação pela ultrassonografia obstétrica?','','','["5ª a 8ª.", "11ª. a 14ª.", "20ª. a 24ª.", "25ª. a 30ª."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: 11ª. a 14ª..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Radiologia','Paciente com deficiência hereditária de alfa-1- antitripsina apresenta áreas de enfisema predominando no terço caudal dos pulmões. Esse enfisema é do tipo','','','["acinar distal.", "centrolobular.", "panlobular.", "parasseptal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: panlobular..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Radiologia','Opacidade em vidro fosco que circunda um nódulo ou uma área de consolidação arredondada em paciente febril, neutropênico, sugere ser','','','["aspergilose.", "tuberculose.", "sarcoidose.", "silicose."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa A. Resposta indicada no gabarito: aspergilose..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Radiologia','Paciente com crises de asma associada a infiltrados pulmonares transitórios, fugaz eosinofilia sanguínea e, no escarro, sibilância, tosse e febre acompanhada de eliminação de tampões mucosos castanhos espessos. A tomografia computadorizada de alta resolução demonstrou espessamento de paredes brônquicas e ectasias cilíndricas associadas a áreas de impactação de muco. O diagnóstico a ser sugerido é de','','','["alveolite alérgica extrínseca.", "sarcoidose.", "aspergilose broncopulmonar alérgica.", "criptococose."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: aspergilose broncopulmonar alérgica..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Radiologia','Múltiplas opacidades arredondadas, com densidade de partes moles, menores que 1cm, com distribuição randômica nos pulmões, evidenciadas em uma tomografia computadorizada de alta resolução, pode sugerir o diagnóstico de','','','["sarcoidose.", "tuberculose.", "pneumonite por hipersensibilidade.", "linfangite carcinomatosa."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: tuberculose..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Radiologia','Paciente LSM, masculino, com 62 anos é admitido na emergência com um quadro semelhante ao de um insulto vascular e com início há três horas. A acompanhante trouxe exame anterior que demonstrava sequela de insulto vascular isquêmico na ínsula com extensão a coroa radiada à direita. As imagens realizadas no momento da admissão estão a sua disposição. Baseado nas imagens disponibilizadas, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q29-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-radiologia-q29-2-v3.png"]','["Foco epileptogênico fronto-parietal à direita.", "Insulto isquêmico agudo no território da cerebral anterior direita.", "Insulto isquêmico agudo no território da cerebral média direita.", "Sinal do trombo fresco na artéria cerebral média direita."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa D. Resposta indicada no gabarito: Sinal do trombo fresco na artéria cerebral média direita..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Radiologia','Paciente de 55 anos, do sexo feminino, que apresentava episódios de palpitações e dispneia associados a sinais de insuficiência cardíaca direita. A ausculta cardíaca demonstrava um sopro protodiastólico sugerindo obstrução ao fluxo tricúspide. A radiografia simples do tórax em PA e perfil mostrou aumento das cavidades cardíacas direitas. Baseado nas imagens disponibilizadas, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q30-1-v3.png"]','["Fibrosarcoma metastático.", "Fibroelastoma.", "Mixoma.", "Lipoma."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Mixoma..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Radiologia','Paciente masculino, com doença aterosclerótica sabida associada a aneurisma da aorta ascendente dá entrada na emergência com dor torácica importante e interescapular. Baseado na imagem disponibilizada, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q31-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-radiologia-q31-2-v3.png"]','["Dissecção aórtica.", "Hematoma aórtico.", "Ulcera aórtica.", "Pseudoaneurisma"]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Ulcera aórtica..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Radiologia','Paciente do sexo feminino, 21 anos, chegou ao serviço de imagem para realização de exame não sabendo descrever ao certo o que estava acontecendo. Sabemos pelas descrições médicas que a paciente já foi atendida por um oftalmologista e por um ortopedista. Baseado nas imagens disponibilizadas, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q32-1-v3.png"]','["Ectasia anuloaortica.", "Aneurisma da aorta ascendente.", "Marfan.", "Pseudoaneurisma do seio de Valsalva."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Marfan..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Radiologia','Paciente do sexo feminino, 32 anos, em uso de anticoncepcional com baixa dose hormonal deu entrada no serviço de imagem para realização de tomografia computadorizada do tórax devido à discreta dor torácica na base direita que piorava a ventilação. Na tomografia de tórax foi achada a imagem de consolidação em contato com a pleura associada a discreto derrame pleural em correspondência. Baseado nas imagens disponibilizadas, qual a sua conduta como radiologista e o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q33-1-v3.png"]','["Libera a paciente / Pneumonia.", "Libera a paciente / Fratura de arco costal.", "Continua a investigação / Arterite de Takayassu.", "Continua a investigação / Tromboembo- lismo pulmonar."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa D. Resposta indicada no gabarito: Continua a investigação / Tromboembo- lismo pulmonar..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Radiologia','Paciente do sexo masculino, 68 anos, com quadro de cansaço e dispneia importantes realizou exames de tórax no serviço de imagem. Baseado nas imagens disponibilizadas, qual o seu diagnóstico e qual a prótese valvar identificada?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q34-1-v3.png"]','["Derrame pericárdico e pleural / Prótese Aórtica.", "Cardiomegalia global / Prótese Mitral.", "Insuficiência Cardíaca / Prótese Aórtica.", "Derrame pericárdico e pleural / Prótese Mitral."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Insuficiência Cardíaca / Prótese Aórtica..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Radiologia','Paciente do sexo feminino, 55 anos, com cianose perilabial e baqueteamento dos dedos realizou estudo com esôfago contrastado para avaliação de disfagia e compressão esofágica. Baseado nas imagens disponibilizadas, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q35-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-radiologia-q35-2-v3.png"]','["Massa esofágica com envolvimento da artéria pulmonar esquerda.", "Aneurisma da aorta ascendente com desvio para a esquerda.", "Cisto pericárdico com aneurisma da ponta do ventrículo esquerdo.", "Hipertensão arterial pulmonar com aneurisma da artéria pulmonar."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa D. Resposta indicada no gabarito: Hipertensão arterial pulmonar com aneurisma da artéria pulmonar..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Radiologia','A cardiopatia congênita pode ser diagnosticada na idade adulta e em alguns casos pode estar associada a shunts direito-esquerda (Eisenmenger). No entanto, é necessário investir no diagnóstico precoce para que se consiga êxito na correção quando o shunt ainda é esquerdo-direita. Qual o tipo de comunicação cavitária de difícil diagnóstico pelo ecocardiograma transtorácico e que a tomografia multislice ou a ressonância magnética podem auxiliar no diagnóstico precoce?','','','["CIV muscular.", "CIA tipo ostium secundum.", "CIA tipo seio venoso.", "Forame oval patente."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: CIA tipo seio venoso..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Radiologia','Paciente do sexo masculino, 35 anos, praticante de vôlei de praia.  Baseado nas imagens disponibilizadas, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q37-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-radiologia-q37-2-v3.png"]','["Ruptura do tendão.", "Tendinose.", "Tenossinovite.", "Bursite."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Tenossinovite..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Radiologia','Paciente do sexo feminino com dor importante e incapacitante no baixo ventre de início súbito. Realizou exame ultrassonográfico que demonstrou: Baseado nas imagens disponibilizadas, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q38-1-v3.png"]','["Cisto ovariano simples.", "Cisto ovariano hemorrágico.", "Prenhez tubo-ovariana.", "Torção de ovário."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: Cisto ovariano hemorrágico..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Radiologia','Leia o enunciado e as alternativas da questão 39 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q39-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Radiologia','A definição de aborto é expulsão prematura do útero de produtos embrionários da concepção ou de um feto inviável. Paciente GII PI com 15 semanas de acompanhamento. Baseado na imagem disponibilizada, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q40-1-v3.png"]','["Aborto completo.", "Aborto iminente.", "Aborto inevitável.", "Aborto retido."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa D. Resposta indicada no gabarito: Aborto retido..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Radiologia','Num US transfontanela, a imagem de hemorragia aguda da matriz germinal no recém- nascido é de lesão','','','["isoecoica.", "hiperecoica.", "hipoecoica com focos ecogênicos.", "hipoecoica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: hiperecoica..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Radiologia','Cistos pulmonares podem ter diversas formas de apresentação, além de poderem aparecer de forma isolada ou um conjunto.  Baseado na imagem disponibilizada, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q42-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-radiologia-q42-2-v3.png"]','["Histiocitose X.", "Linfangioleiomiomatose.", "Faveolamento.", "Sarcoidose."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Faveolamento..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Radiologia','Dilatação da via aérea distal, com bronquiolectasias e bronquiolomucoceles, é a tradução de um padrão identifcado pela alta resolução no tórax. Baseado na imagem disponibilizada, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q43-1-v3.png"]','["Opacidades lineares.", "Árvore em brotamento.", "Perfusão em mosaico.", "Pavimentação em mosaico."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: Árvore em brotamento..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Radiologia','Paciente de 45 anos, feminina, com fraqueza muscular, perda de apetite, fadiga, formigamentos, constipação e dor abdominal. Relata estar em uma fase difícil da vida e muito estressada, o que está promovendo dificuldade de concentração e confusão mental. Baseado na imagem disponibilizada, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q44-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-radiologia-q44-2-v3.png"]','["Pseudogota.", "Gota.", "Hiperparatireoidismo.", "Tumor de células gigantes."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Hiperparatireoidismo..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Radiologia','Criança levada a emergência por trauma na tíbia em jogo de futebol. Baseado na imagem disponibilizada, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q45-1-v3.png"]','["Displasia fibrosa.", "Desmoide periosteal.", "Fibroma não ossificante.", "Defeito cortical fibroso."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Fibroma não ossificante..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Radiologia','Baseado na imagem disponibilizada, devemos, além dos achados, buscar a coexistência de lipoma, hidromielia, lipomielomeningocele, escoliose e hipertricose. Qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q46-1-v3.png"]','["Chiari.", "Medula ancorada.", "Neurofibromatose.", "Diastematomielia."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa D. Resposta indicada no gabarito: Diastematomielia..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Radiologia','A presença de fragmentos osteocondrais (corpos livres) de base sinovial com baixo sinal na ponderação em T2, como representado na figura disponibilizada, refere-se a um diagnóstico.  Baseado na imagem disponibilizada, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q47-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-radiologia-q47-2-v3.png"]','["Sinovite.", "Tendinopatia calcárea.", "Condromatose sinovial.", "Bursite calcárea."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Condromatose sinovial..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Radiologia','Paciente de 32 anos, do sexo masculino, praticante de natação, corrida e ciclismo, com dor em ambas as pernas há 3 semanas. Baseado na imagem disponibilizada, qual o seu diagnóstico?','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q48-1-v3.png"]','["Metástases.", "Osteoatropatia hipertrófica.", "Estresse tibial medial.", "Osteomielite."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Estresse tibial medial..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Radiologia','A duplicação ureteropélvica completa pode ser relacionada à regra de Weigert-Meyer. Correlacionando com a imagem disponibilizada, marque a relação verdadeira.','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q49-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-radiologia-q49-2-v3.png"]','["Ureter tópico – unidade superior – refluxo e ureterocele.", "Ureter ectópico – unidade inferior – refluxo e obstrução.", "Ureter ectópico – unidade superior – obstrução e ureterocele.", "Ureter tópico – unidade inferior - obstrução e ureterocele."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa C. Resposta indicada no gabarito: Ureter ectópico – unidade superior – obstrução e ureterocele..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Radiologia','Paciente adulto, jovem, com trauma abdominal e hematúria, realizou exame de TC sem contraste. Correlacionando com a imagem disponibilizada, marque a relação verdadeira.','','["/pmerj-arquivo/pmerj-2010-medico-radiologia-q50-1-v3.png"]','["Rim em ferradura com tumor sólido no istmo.", "Rim em ferradura com cisto no istmo.", "Rim em panqueca com tumor sólido.", "Rim em panqueca com cisto no istmo."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Radiologia: alternativa B. Resposta indicada no gabarito: Rim em ferradura com cisto no istmo..' from public.exams where slug='pmerj-2010-medico-radiologia' on conflict(exam_id,number) do nothing;
