insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Reumatologia','No exame físico de uma paciente jovem com queixa de dor na abdução do polegar, o teste semiológico que se impõe é o de','','','["Appley.", "Finkelstein.", "Phalen.", "Nery."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa B. Resposta indicada no gabarito: Finkelstein..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Reumatologia','A manobra semiológica que inclui os movimentos de abdução, flexão e rotação externa do quadril também é conhecida como teste de','','','["Trendelenburg.", "Thomas.", "Ober.", "Patrick Fabere."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa D. Resposta indicada no gabarito: Patrick Fabere..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Reumatologia','Consideramos o ângulo Q (patelar) anormal, quando superior a','','','["15°.", "20°.", "25°.", "30°."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa B. Resposta indicada no gabarito: 20°..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Reumatologia','Em relação aos achados radiológicos encontrados na artrite reumatoide, podemos afirmar que','','','["no pé, a primeira erosão consuma ser observada na cabeça do primeiro metatarso.", "no punho, o acometimento precoce do processo estiloide é raro.", "no quadril, a protusão acetabular e a ausência de reparo ósseo são características.", "no ombro, a subluxação ocorre precocemente."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa C. Resposta indicada no gabarito: no quadril, a protusão acetabular e a ausência de reparo ósseo são características..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Reumatologia','A presença de quadratura vertebral é um sinal radiológico encontrado na','','','["espondilodiscite.", "osteoartrose de coluna.", "espondilite anquilosante.", "doença de Forestier."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa C. Resposta indicada no gabarito: espondilite anquilosante..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Reumatologia','Paciente portadora de lúpus eritematoso sistêmico há 20 anos, já com acometimento renal, apresenta marcha claudicante e dor na coxa direita há 1 ano. O achado radiológico mais provável a ser encontrado é','','','["osteopenia justa-articular no quadril.", "espondilólise na coluna lombar.", "esclerose óssea e redução da interlinha articular no quadril.", "espondilolistese na coluna."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa C. Resposta indicada no gabarito: esclerose óssea e redução da interlinha articular no quadril..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Reumatologia','Dentre os prováveis mecanismos de ação da Colchicina, é destacada sua ação sobre a','','','["inibição direta da síntese de IL-6.", "inibição da fagocitose e quimiotaxia de neutrófilos.", "inibição direta da síntese de IL-1.", "inibição direta da via de COX-1."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa B. Resposta indicada no gabarito: inibição da fagocitose e quimiotaxia de neutrófilos..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Reumatologia','Para uma dose de 5 mg de Prednisona, teremos como equivalente:','','','["0,75 mg de Dexametasona.", "25 mg de Hidrocortisona.", "20 mg de Cortisona.", "15 mg de Hidrocortisona."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa A. Resposta indicada no gabarito: 0,75 mg de Dexametasona..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Reumatologia','Em relação ao acometimento pulmonar da artrite reumatoide, pode-se afirmar que','','','["a fibrose intersticial é mais encontrada nos ápices pulmonares.", "os achados clínicos são mais frequentes do que os histopatológicos.", "a mortalidade por doença pulmonar na artrite reumatoide é duas vezes maior do que na população sem artrite reumatoide.", "o derrame pleural é encontrado em cerca de 50% dos casos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa C. Resposta indicada no gabarito: a mortalidade por doença pulmonar na artrite reumatoide é duas vezes maior do que na população sem artrite reumatoide..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Reumatologia','Na artrite reumatoide, a manifestação ocular mais frequente é','','','["esclerite.", "episclerite.", "cetaroconjuntivite seca.", "escleromalácia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa C. Resposta indicada no gabarito: cetaroconjuntivite seca..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Reumatologia','A vasculite reumatoide apresenta algumas características específicas, tal (tais) como:','','','["acometimento mais frequente nos médios vasos.", "associação com o HLA-DR8 positivo.", "acometimento renal não á raro.", "aspectos histopatológicos iniciais demons- tram necrose fibrinoide vascular, com infiltrado de células inflamatórias."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa D. Resposta indicada no gabarito: aspectos histopatológicos iniciais demons- tram necrose fibrinoide vascular, com infiltrado de células inflamatórias..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Reumatologia','Em relação ao quadro clínico da amiloidose, é correto afirmar que','','','["a neuropatia está presente em cerca de 40% dos pacientes.", "a cardiomiopatia é uma complicação rara.", "pode ocorrer depósito amiloide periarticular.", "a hipertensão arterial sistêmica é um achado precoce."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa C. Resposta indicada no gabarito: pode ocorrer depósito amiloide periarticular..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Reumatologia','É critério para o diagnóstico de doença mista do tecido conjuntivo:','','','["edema de mãos e pés.", "miopatia distal.", "sinovite.", "fator anti-nuclear (FAN) positivo."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa C. Resposta indicada no gabarito: sinovite..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Reumatologia','Em relação à produção de autoanticorpos encontrados na esclerodermia, é correto afirmar que','','','["anticorpos antinucleares estão presentes em cerca de 50% dos pacientes.", "anticorpos antitoiposomerase 1 possuem alta especificidade para doença.", "o isotipo de anticorpos antinucleares são, preferencialmente, do tipo IgM.", "Anticorpos anticentrômero possuem baixa especificidade para doença."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa B. Resposta indicada no gabarito: anticorpos antitoiposomerase 1 possuem alta especificidade para doença..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Reumatologia','Em um paciente do sexo masculino que apresenta quadro de artralgia, isquemia de quarto pododáctilo de pé esquerdo, monoreurite múltipla e hipertensão arterial sistêmica, a principal hipótese diagnóstica é','','','["lúpus eritematosos sistêmico.", "poliarterite nodosa.", "granulomatose de Wegener.", "vasculite reumatoide."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa B. Resposta indicada no gabarito: poliarterite nodosa..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
