insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Reumatologia','Em paciente com radiculopatia cervical,','','','["a manobra de Spurling é realizada com a flexão da coluna cervical e inclinação da cabeça para o lado da dor.", "o teste de Bragard sugere a presença de hérnia cervical.", "a abdução do membro superior do lado da dor acima da cabeça causa alívio dos sintomas.", "a tração cervical manual causa redução nos reflexos profundos do lado comprometido."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa C. Resposta indicada no gabarito: a abdução do membro superior do lado da dor acima da cabeça causa alívio dos sintomas..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Reumatologia','Qual das seguintes condições clínicas está associada à baixa massa óssea?','','','["Obesidade.", "Hipertensão arterial.", "Osteoartrite.", "Doença celíaca."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa D. Resposta indicada no gabarito: Doença celíaca..' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Reumatologia','Leia o enunciado e as alternativas da questão 50 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-reumatologia-q50-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Reumatologia: alternativa A. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-reumatologia' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-assistente-social','PMERJ 2010 — Oficial — Assistente Social','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Assistente Social','Segundo Antunes, o modelo de acumulação flexível que substitui o modelo fordista-keynesiano caracteriza-se','','','["pela segunda revolução tecnológica, pela produção em massa, pela adequação da produção às demandas e pelos trabalhadores especializados.", "pela segunda revolução tecnológica, pela produção em pequena escala, pela adequação da produção às demandas e pelos trabalhadores especializados.", "pela terceira revolução tecnológica, pela produção em pequena escala, pela adequação da produção às demandas e pelos trabalhadores polivalentes.", "pela terceira revolução tecnológica, pela produção em massa, pelos grandes estoques e pelos trabalhadores especializados."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: pela terceira revolução tecnológica, pela produção em pequena escala, pela adequação da produção às demandas e pelos trabalhadores polivalentes..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Assistente Social','Um dos principais temas de debate na atualidade é a questão da “assistencialização” da seguridade social. Ana Elisabete Mota, ao discutir as tendências da previdência e da assistência social brasileira nos anos 80 e 90, considera que','','','["no Brasil, dada a sua condição de país periférico e dependente, as políticas sociais possuem caráter assistencial.", "no Brasil, a pauperização absoluta e o desemprego vêm gestando um segmento cada vez maior de dependentes da política de assistência social.", "no Brasil, o princípio da universalização constitui uma modalidade de associação entre a mercantilização/assistencialização da seguridade social.", "no Brasil, historicamente, a assistência social possui caráter eleitoreiro e clientelista."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: no Brasil, o princípio da universalização constitui uma modalidade de associação entre a mercantilização/assistencialização da seguridade social..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Assistente Social','Segundo José Paulo Netto, o que caracteriza a perspectiva modernizadora é','','','["o resgate dos traços microscópicos e psicossociais do Serviço Social tradicional.", "uma nova fundamentação teórica para legitimar papéis e procedimentos profissionais adequados ao contexto histórico.", "o questionamento sobre o significado sócio--histórico do Serviço Social.", "a recusa das vertentes positivista e estrutural-funcionalista."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: uma nova fundamentação teórica para legitimar papéis e procedimentos profissionais adequados ao contexto histórico..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Assistente Social','Para José Paulo Netto, em seu livro ethos individualista significa que','','','["os indivíduos nascem bons, mas a sociedade os corrompe.", "todos os indivíduos têm direitos naturais.", "os indivíduos são responsáveis pelo seu próprio destino.", "aos indivíduos interessa somente o seu bem-estar individual."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: os indivíduos são responsáveis pelo seu próprio destino..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Assistente Social','A perspectiva de naturalização da sociedade que tende a causar impotência nos sujeitos em face dos rumos do desenvolvimento social encontra-se presente','','','["no marxismo vulgar.", "no pensamento conservador.", "na filosofia da Práxis.", "na dialética do concreto."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: no pensamento conservador..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Assistente Social','O debate acerca do que se tem denominado projeto ético-político do Serviço Social inicia-se na transição da década de 70 para a de 80, período que, segundo José Paulo Netto, se caracteriza pela recusa e pela crítica ao conservadorismo profissional. Marque a alternativa que caracteriza este projeto.','','','["Constitui-se num conjunto de determinações formais sobre o fazer do assistente social, as quais devem ser observadas na prática profissional.", "Apresenta a autoimagem da profissão, elege os valores que a legitimam socialmente, delimita e prioriza os seus objetivos e as suas funções.", "É um conjunto de normas sobre direitos e deveres profissionais.", "Constitui-se em uma pauta de orientações, visando a dar uma homogeneidade ao exercício profissional."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: Apresenta a autoimagem da profissão, elege os valores que a legitimam socialmente, delimita e prioriza os seus objetivos e as suas funções..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Assistente Social','N ão constitui competência do Conselho Federal de Serviço Social (CFESS):','','','["prestar assessoria técnico-consultiva a organismos públicos e privados.", "expedir carteiras profissionais de assistentes sociais fixando a respectiva taxa.", "estabelecer os sistemas de registro dos profissionais habilitados.", "planejar e fiscalizar as rotinas administra- tivas dos Conselhos Regionais."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: prestar assessoria técnico-consultiva a organismos públicos e privados..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Assistente Social','Maria Lúcia Barroco, no debate que realiza sobre os fundamentos ontológicos da ética, considera ética como um espaço de reflexão sobre a moral cuja característica principal é','','','["a apreensão crítica dos componentes essenciais da vida cotidiana.", "a necessidade de adequação às normas, ao ethos e à moral coletiva.", "a superação dos preconceitos e dogmas, suprimindo qualquer discriminação de gênero, credo ou etnia.", "o procedimento de ir à raiz, a constante indagação do profissional sobre o significado dos valores."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa D. Resposta indicada no gabarito: o procedimento de ir à raiz, a constante indagação do profissional sobre o significado dos valores..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Assistente Social','Segundo Yolanda Guerra, o pensamento que se recusa a aceitar a unidade teoria/prática é','','','["cotidiano.", "racionalista formal.", "manipulatório.", "imediatista."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: racionalista formal..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Assistente Social','Na categoria profissional, é consenso a afirmação de que o assistente social atua no âmbito das mais diversas expressões da questão social. Concebida por Marilda Iamamoto e referendada por parte da literatura do Serviço Social como “o conjunto das desigualdades da sociedade capitalista madura”, a questão social é expressão','','','["das precárias e contemporâneas formas de trabalho e seus vínculos: informal, temporário, estável.", "da produção coletiva da riqueza social e de sua apropriação privada.", "do desemprego e suas consequências.", "da inserção contemporânea e desigual de determinados segmentos no mercado de trabalho: mulheres, crianças e adolescentes, aposentados, dentre outros."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: da produção coletiva da riqueza social e de sua apropriação privada..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Assistente Social','A concepção de democracia como um dos princípios fundamentais da profissão incide na prática profissional na condição de deveres do assistente social nas suas relações com o usuário e significa uma nova forma de gestão dos bens e serviços sociais com o objetivo de','','','["contribuir para a viabilização da participação efetiva da população usuária nas decisões institucionais.", "promover o engajamento dos usuários e sua família nos programas institucionais.", "promover a distribuição racional de recursos.", "desenvolver as potencialidades dos usuários das políticas sociais e de sua família, tendo em vista seu empoderamento."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: contribuir para a viabilização da participação efetiva da população usuária nas decisões institucionais..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Assistente Social','A Constituição de 1988 instaura como mecanismo de participação popular os Conselhos de Direitos e de Políticas Sociais. Segundo a Lei 8142, que dispõe sobre a participação da comunidade na gestão do Sistema Único de Saúde, o Conselho de Saúde adota a seguinte organização:','','','["representação majoritária da sociedade civil e caráter deliberativo.", "representação majoritária do governo e caráter executor.", "paridade entre governo e sociedade civil e caráter consultivo.", "paridade entre governo e sociedade civil e caráter deliberativo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa D. Resposta indicada no gabarito: paridade entre governo e sociedade civil e caráter deliberativo..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Assistente Social','Raul de Carvalho, no livro Relações Sociais e discurso profissional das pioneiras do Serviço Social que se originaram no bloco católico demonstra como característica básica a','','','["vocação de apostolado social.", "sua origem de classe social.", "influência norte-americana.", "vinculação com a ideologia burguesa."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: vocação de apostolado social..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Assistente Social','Em um hospital municipal no interior do Rio de Janeiro, a chefia do setor de Serviço Social é ocupada por uma enfermeira que é prima do prefeito. O argumento para sua nomeação é o de que não há assistentes sociais disponíveis para ocuparem o cargo no referido município. Com base nesse argumento, a intervenção do CRESS da respectiva região deve','','','["julgar a veracidade do argumento antes de deliberar contra ou a favor.", "aceitar o argumento com base no princípio da excepcionalidade.", "recusar o argumento com base na lei de Regulamentação da Profissão.", "encaminhar parecer para o Conselho Federal para que tome as providências cabíveis."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: recusar o argumento com base na lei de Regulamentação da Profissão..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Assistente Social','Segundo Raul de Carvalho, há um novo momento vivenciado pela profissão a partir de 1942, no que diz respeito ao aumento da demanda por assistentes sociais. Este se caracteriza pela contratação de grande parte dos alunos das escolas de Serviço Social como funcionários das grandes instituições. Carvalho denomina esse processo de','','','["democratização da profissão.", "alargamento das bases de recrutamento da profissão.", "renovação profissional.", "legitimidade profissional."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: alargamento das bases de recrutamento da profissão..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Assistente Social','Para Carlos Montaño, como uma das estratégias do capital, o neoliberalismo constitui-se a partir dos seguintes eixos:','','','["reforma política, reforma administrativa e reforma fiscal.", "modernização estatal, controle inflacionário e flexibilização.", "combate à organização do trabalho, reestruturação produtiva e reforma do Estado.", "ampliação do Estado, globalização e controle da inflação."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: combate à organização do trabalho, reestruturação produtiva e reforma do Estado..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Assistente Social','Segundo David Harvey, no período de 1945 a 1973, o conjunto de práticas de controle do trabalho, de tecnologias, de consumo e de regulação política foi chamado de','','','["acumulação flexível.", "produção toyotista.", "acumulação fordista.", "produção monopolista."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: acumulação fordista..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Assistente Social','Laura Tavares Soares entende o chamado ajuste neoliberal como','','','["um ajuste de natureza econômica para estimular o capital financeiro.", "uma contrarreforma visando à ampliação do Estado.", "uma reestruturação na produção especialmente nas empresas privadas.", "um ajuste econômico, político-institucional e social."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa D. Resposta indicada no gabarito: um ajuste econômico, político-institucional e social..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Assistente Social','A perspectiva de renovação do Serviço Social brasileiro, durante a ditadura militar, que recorre à fenomenologia como suporte teórico, é denominada por José Paulo Netto de','','','["reatualização do conservadorismo.", "Serviço Social pós-moderno.", "modernizadora.", "Serviço Social alternativo."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: reatualização do conservadorismo..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Assistente Social','Segundo Ana Elizabete Mota, a burguesia brasileira, a partir de 80, procura constituir-se como classe dirigente e não só dominante por meio da formação de uma cultura política da crise.  Tal cultura apresenta as seguintes ideias centrais:','','','["a ética solidária e a universalização dos serviços sociais.", "o pensamento privatista e a constituição do cidadão consumidor.", "a ênfase na eficácia e a superação dos entraves ao desenvolvimento social.", "o conceito de eficiência e a ampliação do mercado de consumo interno."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: o pensamento privatista e a constituição do cidadão consumidor..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Assistente Social','Segundo Ivanete Boschetti, a política de assistência social desenvolvida durante o governo de Fernando Henrique Cardoso apresenta, entre outras, a seguinte característica:','','','["os critérios de acesso aos direitos assistenciais restringiram a abrangência da política social, limitando-se a situações de pobreza extrema.", "os recursos assistenciais foram ampliados através de uma rede social solidária condizente com os princípios constitucio- nais.", "as instituições assistenciais filantrópicas exerceram papel fundamental na garantia de direitos sociais básicos.", "as situações de pobreza e exclusão foram enfrentadas por meio de uma extensão dos direitos àqueles usuários que não tinham garantia legal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: os critérios de acesso aos direitos assistenciais restringiram a abrangência da política social, limitando-se a situações de pobreza extrema..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Assistente Social','Apesar de concordâncias e afinidades teóricas e políticas, José Paulo Netto e Marilda Villela Iamamoto divergem sobre a conceituação da categoria questão social. Enquanto para Iamamoto o assistente social deve analisar suas expressões, para Netto tais fenômenos devem ser considerados como','','','["refrações.", "paradigmas.", "problematizações.", "objetivações."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: refrações..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Assistente Social','Durante a ditadura militar, a política de saúde caracteriza-se pela expansão do seguinte recurso assistencial:','','','["hospitais privados.", "ambulatórios especializados.", "centros de saúde.", "distritos sanitários."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: hospitais privados..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Assistente Social','Dentre as contribuições da perspectiva da intenção de ruptura à renovação do Serviço Social no Brasil pós-64, destaca-se o "Método Belo Horizonte". Apesar de avanços teórico-práticos importantes, para José Paulo Netto essa contribuição apresenta, entre outras, a seguinte limitação:','','','["ênfase na crítica ao tradicionalismo do Serviço Social.", "subestimação do caráter ideológico do Serviço Social.", "supervalorização do compromisso com as lutas populares.", "ausência de reflexão sobre as fontes originais do marxismo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa D. Resposta indicada no gabarito: ausência de reflexão sobre as fontes originais do marxismo..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Assistente Social','Considera-se como marco inaugural da previdência social brasileira a chamada Lei Eloi Chaves, de 1923, expressando uma mudança na postura, até então marcadamente liberal, do Estado frente à questão social. Essa lei foi responsável pela criação do(da)','','','["Instituto de Aposentadoria e Pensões dos Comerciários.", "Cooperativa Nacional de Seguro Social.", "Caixa de Aposentadoria e Pensões dos Ferroviários.", "Ministério do Trabalho e Previdência Social."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: Caixa de Aposentadoria e Pensões dos Ferroviários..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Assistente Social','O Título VII da Constituição de 88 determina que a seguridade social deva ser organizada segundo as seguintes diretrizes:','','','["descentralização, desconcentração e eficiência.", "democratização, liberalização e eficácia.", "universalização, uniformização e equidade.", "competência, unificação e concentração."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: universalização, uniformização e equidade..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Assistente Social','Para José Paulo Netto, o conceito que permite compreender o significado político, econômico e social da ditadura militar, implantada com o golpe de 1964, é','','','["revolução passiva.", "cidadania regulada.", "corporativismo estatal.", "autocracia burguesa."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa D. Resposta indicada no gabarito: autocracia burguesa..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Assistente Social','Desde o surgimento do Estado moderno, pode- se distinguir, em linhas gerais, três modalidades de proteção social: assistência social, seguro social e seguridade social. A previdência social é uma instituição que surge com base na ideia de seguro social, pois o direito aos benefícios se caracteriza por','','','["ser universal.", "depender de contribuição prévia.", "variar conforme as necessidades do segurado.", "independer da existência de contrato."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: depender de contribuição prévia..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Assistente Social','Durante o primeiro governo Vargas (1930- 1945) realizam-se profundas transformações nas relações entre Estado e sociedade. No centro dessas transformações encontra-se uma nova forma de organização política da classe trabalhadora, situando os sindicatos no interior de estruturas centralmente dirigidas, tendo em vista retirar a autonomia das organizações trabalhistas. O Estado procurou despolitizar a maioria das áreas de política pública, como a política social, e convertê-las em matéria administrativa e jurídica. Esse tipo de relação entre Estado e sociedade na Segunda República, que deixou marcas ainda presentes no Brasil atual, é denominado de','','','["liberalismo.", "corporativismo.", "fascismo.", "ditadura."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: corporativismo..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Assistente Social','José Paulo Netto, apesar de discordar da ideia de que exista uma teoria e uma metodologia próprias ao Serviço Social, reconhece a importância da sistematização da prática profissional. Dentre as alternativas abaixo, aponte a que corresponde à concepção de Netto sobre as funções dos "procedimentos sistematizadores".','','','["Estabelecer padrões de condutas institucionais eficazes.", "Produzir campo específico de conhecimento científico do assistente social.", "Regularizar e normatizar a reprodução da categoria profissional.", "Ser um momento pré-teórico a ser elaborado pelas ciências sociais ou pela tradição marxista."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa D. Resposta indicada no gabarito: Ser um momento pré-teórico a ser elaborado pelas ciências sociais ou pela tradição marxista..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Assistente Social','Na Lei Orgânica da Saúde n° 8080, de 1990, a saúde é resultante','','','["de um estado de completo bem-estar físico, mental e social e não consistindo somente na ausência de uma doença ou enfermidade.", "da maneira do homem abordar sua existência através da sensação de não apenas ser portador, possuidor, mas também criador de valor, instaurador de normas vitais.", "dos fatores determinantes e condicionantes, entre outros, a alimentação, a moradia, o saneamento básico, o trabalho, o meio ambiente, a educação, a renda, o transporte, o lazer e o acesso aos bens e serviços essenciais.", "do equilíbrio harmônico e integral entre o homem e o meio ambiente através da adequação dos fatores biopsicossociais e econômicos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: dos fatores determinantes e condicionantes, entre outros, a alimentação, a moradia, o saneamento básico, o trabalho, o meio ambiente, a educação, a renda, o transporte, o lazer e o acesso aos bens e serviços essenciais..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Assistente Social','Não são direitos sociais constitucionais:','','','["educação e saúde.", "trabalho e lazer.", "democracia e propriedade.", "segurança e previdência social."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: democracia e propriedade..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Assistente Social','Segundo José Paulo Netto, o Serviço Social é uma modalidade de intervenção em cujo centro "situa- se, com invulgar ponderação, a manipulação de variáveis empíricas de um contexto determinado". (Capitalismo Monopolista e Serviço Social, 2005, p. 93) Essa característica é, para o autor, um elemento essencial do que ele conceitua como','','','["tradicionalismo ideológico.", "sincretismo prático.", "pragmatismo.", "funcionalismo estrutural."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: sincretismo prático..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Assistente Social','O Desenvolvimento de Comunidade surge no Brasil após a II Guerra Mundial, no contexto da "guerra fria", estimulado por organismos internacionais interessados na expansão da ideologia e do modo de produção capitalista e, consequentemente, em conter o avanço do "perigo comunista" nos países subdesenvolvidos.  Dentre os supostos ideológicos que conformam sua concepção de sociedade, encontram-se','','','["neutralidade e crescimento.", "desenvolvimento e humanismo.", "conflito e integração.", "contradição e equilíbrio."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: neutralidade e crescimento..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Assistente Social','Para Ana Maria de Vasconcelos, uma prática reflexiva é aquela que, entre outros objetivos, contribui para','','','["a politização das demandas apresentadas.", "o processo de humanização dos serviços.", "a adaptação do usuário à instituição.", "o conformismo e a resistência."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: a politização das demandas apresentadas..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Assistente Social','O Conselho Nacional de Saúde, através da Resolução 218 de 1997, reconheceu 13 categorias profissionais como profissões de saúde, entre elas a de serviço social. Esta medida define o estatuto legal para que a formação e a prática das diferentes áreas no campo da saúde estejam orientadas pelos fundamentos contidos na Constituição Federal de 1988 e na Lei Orgânica da Saúde, quais sejam','','','["a descentralização das ações e a democratização das decisões.", "a prevenção e a recuperação da saúde.", "a concepção de saúde e a integralidade da atenção.", "a universalidade e a igualdade no acesso à assistência em saúde."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: a concepção de saúde e a integralidade da atenção..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Assistente Social','Para Maria Inês Bravo, a política de saúde na ditadura militar imprimiu mudanças em face da questão social que se caracteriza pela predominância','','','["das corporações médicas capitalistas, através da reestruturação da assistência.", "dos mecanismos de financiamento.", "dos programas afinados com as metas estabelecidas para “saúde para todos no ano 2000”.", "das campanhas de educação em saúde e reformas integradas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: das corporações médicas capitalistas, através da reestruturação da assistência..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Assistente Social','Jairnilson Paim avalia que o Projeto da Reforma Sanitária Brasileira reduziu-se a uma reforma parcial. O processo da reforma ocorreu através da pactuação pelo alto, verificada na transição democrática. Na avaliação do autor, para a Reforma Sanitária conquistar uma reforma geral, deve estar impulsionada','','','["pelos portadores da antítese, seu núcleo subversivo.", "por processos de judicialização dos direitos sociais.", "através da efetivação dos pactos e metas pela saúde.", "pelo revigoramento das noções de cuidado e de subjetivação."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: pelos portadores da antítese, seu núcleo subversivo..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Assistente Social','As análises de José Paulo Netto sobre a organização monopólica do capital apreendem a realidade pela via de suas mediações, em processo de totalização, protagonizado pelos sujeitos históricos. Com base nesse marco teórico-metodológico, como podemos interpretar as indicações da Comissão Nacional Sobre Determinantes Sociais da Saúde de redes de apoio como um dos determinantes da situação da Saúde?','','','["Uma oportunidade de criar uma base social mais humanizada.", "Um apoio político às ações sobre as os determinantes sociais e empoderamento dos grupos populacionais vulneráveis.", "Uma expressão contemporânea do positivismo.", "Uma forma de mobilizar os sujeitos históricos para uma participação política."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: Uma expressão contemporânea do positivismo..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Assistente Social','No debate em curso sobre o Projeto Fundação Estatal de Direito Privado, Sara Granemann o considera como “um projeto que ao reduzir a ação do Estado para o trabalho o amplia como horizonte de atuação do capital”. (Políticas de Saúde na Atual Conjuntura, 2007, p. 46-47)  De acordo com esta avaliação, as inferências da autora sobre a condição dos trabalhadores são que','','','["o trabalho interdisciplinar, na perspectiva ampliada da saúde, ficará prejudicado.", "os profissionais terão mais autonomia de escolha e mais estímulo para integração e capacitação.", "a priorização da gestão pode levar à focalização dos programas de saúde, mas também ao aumento da participação da sociedade civil.", "a nova forma de contrato de trabalho regulado por cada fundação irá fragmentar e fragilizar ainda mais as condições de trabalho e as lutas sociais."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa D. Resposta indicada no gabarito: a nova forma de contrato de trabalho regulado por cada fundação irá fragmentar e fragilizar ainda mais as condições de trabalho e as lutas sociais..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Assistente Social','Segundo Maria Inês Bravo, identificar o potencial dos conselhos para a universalização do direito e a ampliação da cidadania na direção de uma democracia de massa requer visualizar os conselhos como','','','["espaço de consenso na pactuação entre Estado e Sociedade civil.", "locus do fazer político contraditório e base para uma nova cultura política.", "espaço de empoderamento e valorização das relações intersubjetivas.", "locus privilegiado de capacitação e de qualificação técnica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: locus do fazer político contraditório e base para uma nova cultura política..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Assistente Social','A Lei Orgânica da Saúde define que os níveis de saúde da população expressam a organização social e econômica do país. Esse dispositivo legal dá indicações para','','','["a centralidade do trabalho na produção e repodução da vida e da riqueza social.", "estudos etnográficos sobre estilos de vida nas comunidades e redes sociais.", "a identificação de novos paradigmas para entender a saúde a partir dos padrões de subjetividade.", "a utilização de modelos operativos que estimulem a inclusão social."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: a centralidade do trabalho na produção e repodução da vida e da riqueza social..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Assistente Social','Na avaliação de Maria Lucia Barroco, o Código de Ética do Serviço Social repõe a ética no interior da práxis, considerando','','','["a centralidade do trabalho na vida social, a equidade e a democracia como valores ético-políticos.", "o enfrentamento das iniquidades de classe para promoção da solidariedade e da coesão social.", "a centralidade da política, capaz de reconhecer os trabalhadores como representantes de uma moral universal.", "o ideal ético suficientemente definido como pluralismo social-democrático."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: a centralidade do trabalho na vida social, a equidade e a democracia como valores ético-políticos..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Assistente Social','A direção de uma unidade hospitalar convoca o Serviço Social para realizar campanha educativa sobre a importância da doação de sangue, com vistas a cumprir acordo firmado com unidade de referência na rede do SUS. Qual o argumento para o profissional recusar esta convocação?','','','["A autonomia profissional e os estudos sobre as principais demandas dos usuários é que definem as prioridades do projeto de intervenção.", "A ausência de disponibilidade consequente do excesso da demanda cotidiana para alta hospitalar e nos atendimentos emergentes no fluxo dos serviços.", "Essa demanda é pertinente à equipe multiprofissional e não exclusiva do Serviço Social.", "Essa função é competência da Secretaria de Saúde, responsável pelas ações educativas amplas e extensivas em diferentes espaços sociais."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: A autonomia profissional e os estudos sobre as principais demandas dos usuários é que definem as prioridades do projeto de intervenção..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Assistente Social','Observando os desafios que a democratização da saúde exige no enfrentamento das políticas neoliberais, o Serviço Social utiliza os dados epidemiológicos sobre os usuários da unidade e da população geral para','','','["identificar os grupos portadores de necessidades particulares e contribuir para a definição de critérios de acesso aos programas especiais de saúde.", "auxiliar na identificação de demandas centrais e essenciais ligadas aos interesses e necessidades de saúde dos usuários.", "ajudar na construção de uma nova cartografia da saúde.", "indicar os problemas sociais que interferem na baixa adesão aos programas de saúde."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: auxiliar na identificação de demandas centrais e essenciais ligadas aos interesses e necessidades de saúde dos usuários..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Assistente Social','Ana Maria de Vasconcelos, na sua pesquisa, demonstra que os assistentes sociais, com frequência, declaram que a precarização do trabalho e dos direitos sociais desmobiliza a ação profissional. Considerando as tarefas que o projeto de democracia de massa na saúde e na seguridade social requisita, o paradoxo dessa declaração encontra-se','','','["na suposição de que aquilo que é de fato o seu objeto passa a ser considerado um obstáculo na prática do assistente social.", "na constatação de que assistentes sociais sofrem igualmente as consequências da precarização do trabalho e, do mesmo modo, ficam imobilizados para projetos mais amplos.", "na condição de assistentes sociais que estão diante das demandas diferenciadas, complexas e volumosas e lidam, cotidianamente, com a contradição entre a teoria e a prática.", "no fato de que mesmo com todos os recursos teórico-metodológicos o Serviço Social ainda lida com “o problema social”."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: na suposição de que aquilo que é de fato o seu objeto passa a ser considerado um obstáculo na prática do assistente social..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Assistente Social','Num serviço de referência na atenção de média complexidade na rede pública, o assistente social atende uma mulher jovem, faxineira-diarista, residente em área distante, com o seguinte histórico: Encaminhada pelo posto de saúde para esclarecimento acerca de alterações no seu preventivo ginecológico. Na primeira consulta, estava muito nervosa, a médica repetiu o exame, tranquilizou-a informando que se tratava de uma “pequena infecção” e que retornasse em 3 meses. Julgou que estava fora de risco, priorizou o trabalho e ao retornar com 3 meses de atraso recebeu diagnóstico de carcinoma. Na perspectiva do projeto ético-político do Serviço Social, a assistente social deve constatar que','','','["a usuária não priorizou a sua saúde; isso mostra a importância de os serviços de saúde desenvolverem programas de educação para o autocuidado.", "apesar do cuidado da médica em reduzir a tensão, a usuária não aderiu ao acompanhamento.", "a função educativa da atenção à saúde, no caso, a informação não possibilitou à usuária uma decisão a partir da compreensão das razões médicas e dos seus reais riscos.", "a médica deveria ter encaminhado a usuária para o Serviço Social realizar trabalho educativo para prevenir abandono."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: a função educativa da atenção à saúde, no caso, a informação não possibilitou à usuária uma decisão a partir da compreensão das razões médicas e dos seus reais riscos..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Assistente Social','Num hospital da rede pública, o assistente social realiza grupos com os usuários de primeira vez nos ambulatórios. Seus relatórios mostram uma prevalência de doenças resultantes da ausência de prevenção em usuários da mesma área programática de saúde. O assistente social deve encaminhar esses resultados, considerando os desafios da Reforma Sanitária, através','','','["da divulgação dos resultados e debater propostas de mudança junto à equipe do hospital, às coordenações de saúde da Secretaria de Saúde, aos conselhos de saúde, envolvendo os usuários nesse processo.", "da criação de um programa educativo específico para prevenção e diminuição das chances de reincidência.", "do contato com as equipes de Serviço Social dos postos de saúde da área programática e propor programas de práticas preventivas.", "da notificação do gestor do hospital para que ele encaminhe o problema junto às autoridades de saúde do município."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa A. Resposta indicada no gabarito: da divulgação dos resultados e debater propostas de mudança junto à equipe do hospital, às coordenações de saúde da Secretaria de Saúde, aos conselhos de saúde, envolvendo os usuários nesse processo..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Assistente Social','Assiste-se, na última quadra do século XX, em razão de processos econômicos, políticos e sociais variados, a ascensão da hegemonia neoliberal. Com relação à questão social não é objetivo central do ideário neoliberal:','','','["remercantilizar os bens sociais.", "reduzir o gasto social.", "universalizar os benefícios sociais.", "suprimir a noção de direitos sociais."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa C. Resposta indicada no gabarito: universalizar os benefícios sociais.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Assistente Social','Segundo Marx, o modo de produção capitalista, ao mesmo tempo que aumenta o controle do homem sobre a natureza, intensifica o processo de alienação, na medida em que o trabalhador não detém o controle sobre o seu trabalho e sobre o produto deste. Assim , na produção capitalista a relação entre as pessoas aparece como relação entre','','','["poderes.", "coisas.", "classes.", "sujeitos."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Assistente Social: alternativa B. Resposta indicada no gabarito: coisas..' from public.exams where slug='pmerj-2010-assistente-social' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-enfermagem-terapia-intensiva-de-adulto','PMERJ 2010 — Oficial — Enfermagem Terapia Intensiva De Adulto','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Enfermagem Terapia Intensiva De Adulto','Homem de 72 anos é internado devido à sepse secundária a pielonefrite. No final da segunda semana de tratamento hospitalar com Ciprofloxacino, ressurge a febre e a investigação revela hemocultura positiva para Candida albicans. Seu exame físico é inexpressivo, o hemograma revela discreta anemia normocítica e normocrômica e a sorologia anti HIV é negativa (EIA). O cateter de veia profunda puncionado na internação é removido e inicia-se Fluconazol intravenoso. Que exame de investigação você solicitaria a seguir?','','','["Ecocardiograma transtorácico.", "Exame de fundo de olho.", "Repetir hemoculturas.", "Tomografia computadorizada de abdome."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: Exame de fundo de olho..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Enfermagem Terapia Intensiva De Adulto','Uma mulher de 56 anos portadora de prótese de valva mitral inicia quadro de febre e calafrios duas semanas após extração dentária. O exame físico revela aumento da intensidade do sopro habitual, o ecocardiograma evidencia uma vegetação de 1 cm na válvula protética e as hemoculturas revelam crescimento de Haemophilus parainfluenza. A melhor conduta no caso é:','','','["Penicilina cristalina associada a Gentami- cina por quatro semanas.", "Ceftriaxone por duas semanas antes da troca da válvula.", "Indicar troca imediata da válvula protética.", "Ceftriaxone por seis semanas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: Ceftriaxone por seis semanas..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Enfermagem Terapia Intensiva De Adulto','Leia o enunciado e as alternativas da questão 3 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q03-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Enfermagem Terapia Intensiva De Adulto','Qual das medicações abaixo reduz a mortalidade per e pós-operatória em pacientes submetidos à cirurgia não cardíaca?','','','["Beta-bloqueador.", "Nitrato.", "Bloqueador de canal de cálcio.", "Agonista α2."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: Beta-bloqueador..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Enfermagem Terapia Intensiva De Adulto','Homem de 32 anos, com história de esplenectomia e radioterapia há um ano para tratamento de doença de Hodgkin, dá entrada na emergência com quadro de febre e calafrios iniciados há 12 horas. Está desorientado, com PA 85 X 20 mmHg e PR 140 bpm. Além das medidas de suporte para o tratamento da sepse, a paciente deverá imediatamente iniciar','','','["Vancomicina.", "Piperacilina-Tazobactam.", "Ceftriaxone.", "Anfotericina B."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: Ceftriaxone..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Enfermagem Terapia Intensiva De Adulto','Leia o enunciado e as alternativas da questão 6 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q06-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Enfermagem Terapia Intensiva De Adulto','Homem de 37 anos com história de diabetes me regular dá entrada no setor de emergência com história d com irradiação para a mandíbula e dorso, associada a ná cedeu com analgésicos comuns. Na emergência, foi im sublingual, oxigenioterapia e analgesia com morfina hemodinamicamente estável. Realizado ECG e solicitados Troponina , CK total Considerando os achados do eletrocardiograma, vo','','["/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q07-1-v3.png"]','["indica imediatamente trombólise intravenosa.", "propõe cinecoronariografia de urgência.", "solicita ecocardiograma bidimensional.", "solicita angiotomografia de tórax."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: solicita ecocardiograma bidimensional..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Enfermagem Terapia Intensiva De Adulto','Homem de 68 anos, internado devido a choque mecânica e em uso de noradrenalina. Repentinamente o FC 192 bpm e SAT O2 88% e o traçado do ECG apresen Sua conduta é','','["/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q08-1-v3.png", "/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q08-2-v3.png"]','["cardioversão imediata: três choques (200J bi do tórax do paciente, caso o ritmo não imediatamente a massagem cardíaca caso o choque.", "cardioversão imediata: um choque (200J b massagem cardíaca externa por dois minutos,", "dose de ataque de Amiodarona 300mg em ve minutos e cardioversão posterior: um choque", "dose de ataque de Adrenalina 1mg em veia minutos, seguida de cardioversão: três choq retirar as pás do tórax do paciente, caso o ritm ellitus tipo 2 e hipertensão arterial em acompanhamento de dor torácica anterior de caráter opressivo e intermitente, áuseas, iniciada há aproximadamente seis horas e que não mediatamente monitorado e prescreveu-se AAS, Nitrato a obtendo rápida melhora sintomática e mantendo-se e CKMB. ocê séptico de origem pulmonar, encontra-se em ventilação acionamento do alarme do monitor revela PAM 20mmHg, nta o padrão abaixo. ifásico ou 360J monofásico) sucessivos sem retirar as pás reverta no primeiro ou segundo choque. Reassumir o ritmo não tenha sido re-estabelecido, após o terceiro bifásico ou 360J monofásico) seguido imediatamente de antes de nova checagem de pulso e ritmo. eia central seguida de massagem cardíaca externa por dois (200J bifásico ou 360J monofásico). a central seguida de massagem cardíaca externa por 3-5 ques (200J bifásico ou 360J monofásico) sucessivos sem mo não reverta no primeiro ou segundo choque."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: cardioversão imediata: um choque (200J b massagem cardíaca externa por dois minutos,.' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Enfermagem Terapia Intensiva De Adulto','Dentre as medicações utilizadas em procedi- mentos na terapia intensiva, aquela que pode acarretar insuficiência suprarrenal aguda é','','','["Quetamina.", "Propofol.", "Fentanil.", "Etomidato."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: Etomidato..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Enfermagem Terapia Intensiva De Adulto','Um homem de 60 anos com cirrose hepática Child C evoluindo com febre e tosse há um mês é internado devido à febre e à insuficiência respiratória com necessidade de ventilação mecânica. A radiografia de tórax revela opacidade heterogênea em lobo superior direito e o lavado bronco-alveolar evidencia positividade para BAAR. O esquema de tratamento a ser prescrito é','','','["Etambutol – Etionamida – Pirazinamida.", "Rifampicina – Isoniazida – Pirazinamida.", "Etambutol – Estreptomicina – Ofloxacina.", "Rifampicina – Etambutol – Isoniazida."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: Etambutol – Estreptomicina – Ofloxacina..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Enfermagem Terapia Intensiva De Adulto','Dentre os patógenos causadores de pneumonia comunitária, o que está mais frequentemente associado à hiponatremia é','','','["Legionella pneumophila.", "Streptococcus pneumoniae.", "Chlamydophila pneumoniae.", "Haemophilus Influenzae."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: Legionella pneumophila..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Enfermagem Terapia Intensiva De Adulto','Mulher de 20 anos previamente saudável é atendida com quadro de febre, icterícia e confusão mental. Ao exame físico, está desorientada, sem sinal neurológico focal, ictérica e com exantema petequial predominando em membros inferiores. Os exames laboratoriais evidenciam: Ht 27%, leucócitos 12.000cels/mm3) (0/0/0/0/12/56/24/8), plaquetas 13.000 cels/mm3, bilirrubina 5mg/dL, bilirrubina direta 0,6mg/dL, ureia 80 mg/dL e creatinina 2,5mg/dL, LDH 1430 mg/dL. O esfregaço de sangue periférico demonstrou hemácias fragmentadas e nucleadas. Os tempos de protrombina e tromboplastina parcial estavam normais. A terapêutica mais efetiva neste caso é','','','["anticoagulação com heparina.", "plasmaferese.", "fator VII recombinante.", "hemofiltração de altos volumes."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: plasmaferese..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Enfermagem Terapia Intensiva De Adulto','A antibioticoterapia empírica para o tratamento de peritonite bacteriana espontânea está indicada quando a análise do líquido ascítico de um paciente cirrótico revelar','','','["aumento dos níveis de adenosina D- aminase (ADA).", "contagem de polimorfonucleares ≥ 250 cels/mm3.", "relação proteína do líquido/proteinemia > 1.", "glicose < 50 mg%."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: contagem de polimorfonucleares ≥ 250 cels/mm3..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Enfermagem Terapia Intensiva De Adulto','Paciente de 32 anos, sabidamente soropositivo para HIV e sem tratamento antiretroviral, apresenta quadro de diarreia há duas semanas, com episódios intermitentes de perda sanguínea fecal, associada a dor abdominal, urgência fecal e astenia. O exame parasitológico de fezes (incluindo pesquisa de Cryptosporidium e Isospora) e a pesquisa de toxina para C. difficile foram negativos. A coprocultura revelou crescimento de microbiota habitual e Candida sp. Um tratamento empírico com ciprofloxacina não obteve melhora do quadro. Realizada a seguir uma colonoscopia que evidenciou lesões ulceradas na mucosa pancolônica e o exame histopatológico revelou enterócitos aumentados de volume com inclusões granulares hipercromáticas, intracitoplasmáticas e intranucleares. O tratamento a ser prescrito é','','','["Fluconazol 200mg IV 2 x dia.", "Metronidazol 750 mg IV 3 x dia.", "Ganciclovir 5mg Kg IV 2 x dia.", "Sulfasalazina 2 g VO 3 x dia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: Ganciclovir 5mg Kg IV 2 x dia..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Enfermagem Terapia Intensiva De Adulto','A fonte mais comum de infecção bacteriana associada a cateteres venosos provém de contaminação','','','["proveniente de foco a distancia através de bacteremia.", "no momento da administração de medicações no canhão (hub).", "através do sítio de inserção do cateter na pele.", "das infusões contínuas administradas diuturnamente."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: através do sítio de inserção do cateter na pele..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Enfermagem Terapia Intensiva De Adulto','Necrose cutânea está ocasionalmente associada à instituição de tratamento com anticoagulantes orais (warfarina) em pacientes com deficiência de','','','["fator VIII.", "antitrombina.", "plasminogênio.", "proteína C."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: proteína C..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Enfermagem Terapia Intensiva De Adulto','Homem de 58 anos, com história de etilismo e hipertensão arterial em uso irregular de alfametildopa é trazida ao Serviço de Emergência, após ser encontrado em casa desacordado. PA 180 x 100mmHg PR 120bpm SAT O2 94 % ar ambiente Tax 39ºC Pupilas 4mm fotorreagentes, reflexos córneo palpebral e óculo cefálico normais, discutível rigidez de nuca. Solicitada TC de crânio: normal. Realizada punção lombar: pressão 24cmH2O, 1600 cels/mm3 (76% PMN), glicose: 32 mg%, proteínas: 96 mg%, Gram e pesquisa de antígenos em andamento. Ainda na emergência deve ser iniciado o seguinte esquema terapêutico:','','','["Ceftriaxone + Ampicilina .", "Cefepime + Claritromicina.", "Aciclovir.", "Penicilina cristalina + Azitromicina."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: Ceftriaxone + Ampicilina ..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Enfermagem Terapia Intensiva De Adulto','Homem de 38 anos, com história de febre e dispneia iniciadas trinta dias após cirurgia para substituição de valva mitral reumática. Seu exame físico revela ritmo cardíaco tríplice, irregular por fibrilação atrial e SS ++++/6 em foco mitral com irradiação dorsal. Há turgência jugular patológica e estertoração crepitante bibasal pulmonar. Na suspeita de endocardite infecciosa, o esquema terapêutico empírico, após a coleta de culturas, deverá ser','','','["Anfotericina B + Imipenem + Vancomicina.", "Imipenem + Fluconazol + Rifampicina.", "Oxacilina + Gentamicina + Fluconazol.", "Rifampicina + Vancomicina + Gentamicina."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: Rifampicina + Vancomicina + Gentamicina..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Enfermagem Terapia Intensiva De Adulto','Podemos afirmar, quanto à sensibilidade da Candida aos antifúngicos, que','','','["Candida glabrata é intrinsecamente sensível ao Fluconazol.", "Candida lusitaniae é intrinsecamente sensível à Anfotericina B.", "Candida krusei é intrinsecamente resistente ao Fluconazol.", "Candida guillermondi é intrinsecamente resistente à Caspofungina."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: Candida krusei é intrinsecamente resistente ao Fluconazol..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Enfermagem Terapia Intensiva De Adulto','Quanto à peritonite bacteriana espontânea (PBE) do paciente cirrótico, podemos afirmar que','','','["trata-se de complicação do paciente ascítico que apresenta bom prognóstico se tratada precocemente com antibióticos.", "a administração de albumina como parte da terapia diminui a incidência de insuficiência renal.", "em torno de 30% dos casos, encontra-se mais de um agente microbiano nas cultura do líquido ascítico.", "Pseudomonas aeruginosa e Bacteroides fragilis são os agentes mais frequentes da PBE."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: a administração de albumina como parte da terapia diminui a incidência de insuficiência renal..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Enfermagem Terapia Intensiva De Adulto','São indicadores de mau prognóstico na pancreatite aguda:','','','["Pancreatite pós-operatória, febre > 39oC, calcemia menor que 8mg/dL nas primeiras 48 horas.", "Idade maior que 55 anos, leucometria acima de 16000 cels/mm3 na admissão, lipase > 50mg/dL na admissão.", "Obesidade, presença de sinal de Cullen, glicemia maior que 200mg% na admissão.", "Sexo masculino, amilase > 1000mg/dL na admissão, sequestro de volume maior que 6L nas primeiras 48 horas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: Obesidade, presença de sinal de Cullen, glicemia maior que 200mg% na admissão..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Enfermagem Terapia Intensiva De Adulto','Assinale a afirmação correta quanto ao suporte nutricional em pacientes hepatopatas críticos.','','','["Nos pacientes com encefalopatia hepática aguda, o planejamento nutricional inicial deverá conter 0,6-0,8 g/Kg de proteína por dia.", "Quando comparadas com as soluções padrão de aminoácidos (AA), as soluções parenterais enriquecidas com AA de cadeia ramificada melhoram o prognóstico dos pacientes em insuficiência hepática.", "Deve-se manter uma oferta de 15-20 Kcal/não proteicas/dia em pacientes com insuficiência hepática crônica agudizada devido ao seu hipometabolismo.", "A utilização de lipídios por via intravenosa está contraindicada para os pacientes com encefalopatia hepática devido à alta frequência de esteatose hepática nesta população."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: Nos pacientes com encefalopatia hepática aguda, o planejamento nutricional inicial deverá conter 0,6-0,8 g/Kg de proteína por dia..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Enfermagem Terapia Intensiva De Adulto','Homem de 23 anos, com história de sinusite de repetição evoluiu com febre (até 39oC) e poliartralgia iniciados dez dias antes da internação hospitalar. Na véspera, desenvolveu tosse inicialmente seca e posteriormente hemoptise, dando entrada no setor de emergência por insuficiência respiratória com necessidade de ventilação mecânica. Os exames revelaram Hb 9.8g/dL, leucócitos 12000 cels/mm3 (0/1/0/0/19/60/15/5), plaquetas 160000cels/mm3, ureia 98mg/dL, creatinina 2.2 mg/dL. A radiografia de tórax apresenta infiltrados nodulares bilaterais sendo que um dos nódulos no lobo superior direito apresenta cavitação. Face à patologia do paciente, podemos inferir que','','','["plasma fresco e vitamina K devem ser prescritos para conter a hemorragia.", "deverá ser tratado empiricamente com rifampicina, isoniazida e pirazinamida.", "o tratamento com plasmaferese deverá ser instituído imediatamente.", "a pesquisa de anticorpos anticitoplasma de neutrófilos será positiva."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: a pesquisa de anticorpos anticitoplasma de neutrófilos será positiva..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Enfermagem Terapia Intensiva De Adulto','Quanto ao tratamento sistêmico para embolia pulmonar (TEP) com drogas trombolíticas, podemos afirmar que','','','["podem ser usados em casos em que há contraindicação a anticoagulação sistêmica.", "diminuem a mortalidade no TEP maciço.", "aceleram a resolução da disfunção ventricular direita.", "são os agentes de escolha no TEP associado à gravidez."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: aceleram a resolução da disfunção ventricular direita..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Enfermagem Terapia Intensiva De Adulto','Homem de 40 anos, sabidamente cirrótico por HCV é internado devido à hemorragia digestiva alta, tratada com sucesso com escleroterapia endoscópica para varizes esofagianas. Ao dar entrada no CTI, encontrava-se hipotenso atingindo estabilidade hemodinâmica após 2000mL de Solução Salina 0.9% e duas unidades de Concentrado de Hemácias. Nos quatro dias subsequentes, apesar de manter-se estável hemodinamicamente, seu volume urinário vem progressivamente diminuindo sendo que, nas últimas 12h, urinou 150 mL. Os exames laboratoriais atuais revelam: sódio 140 mEq/L, creatinina 4.0 mg/dL (quando era 1.1 mg/dL na admissão), EAS: densidade 1010 - hemácias 5 pc - leucócitos 10 pc - raros cilindros granulares, sódio urinário 50 mEq/L e creatinina urinária 35 mg/dL. Qual é a causa mais provável da insuficiência renal deste paciente?','','','["Necrose tubular aguda.", "Glomerulonefrite pelo HCV.", "Síndrome hepato-renal.", "Azotemia pré-renal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: Necrose tubular aguda..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Enfermagem Terapia Intensiva De Adulto','Paciente de 27 anos, vítima de acidente de motocicleta, dá entrada no setor de emergência do hospital lúcido, ausculta pulmonar com redução do murmúrio vesicular à direita e hipertimpanismo, hemodinamicamente estável, hematoma periorbitário bilateral e retroauricular. Encaminhado à tomografia computadorizada, evoluiu em insuficiência respiratória aguda. Realizada imediatamente descompressão do hemitórax direito, porém mantém dificuldade respiratória. O acesso da via aérea que deve ser EVITADO neste caso é a intubação','','','["retrógrada.", "orotraqueal.", "por broncoscopia.", "nasotraqueal."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: nasotraqueal..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Enfermagem Terapia Intensiva De Adulto','No momento em que se decide a necessidade de um acesso venoso profundo, assinale abaixo a assertativa em que a indicação do procedimento corresponde à primeira opção de via de punção.','','','["Hemodiálise – veia femoral direita ou veia femoral esquerda.", "Nutrição parenteral – veia subclávia direita ou veia subclávia esquerda.", "Parada cardiorrespiratória – veia jugular interna direita ou veia subclávia esquerda.", "Cateter de artéria pulmonar – veia jugular interna esquerda ou veia subclávia esquerda."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: Nutrição parenteral – veia subclávia direita ou veia subclávia esquerda..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Enfermagem Terapia Intensiva De Adulto','O manuseio da dor em pacientes críticos pode ser um desafio. Assinale, dentre as opções abaixo, a razão da ineficácia que ocorre no cuidado da dor com o uso de opioides na terapia intensiva.','','','["Via de administração equivocada.", "Efeitos colaterais graves.", "Manuseio incorreto pelo médico.", "Propriedades analgésicas inadequadas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: Manuseio incorreto pelo médico..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Enfermagem Terapia Intensiva De Adulto','Em relação aos bloqueadores neuromusculares, podemos afirmar que é','','','["a forma de interação com acetilcolina que difere os BNM despolarizantes dos não despolarizantes.", "indicada e segura a sua associação com corticoesteroides nos casos de asma grave.", "utilizada no estado de mal epiléptico devido à ação no controle da atividade convulsiva cerebral.", "a primeira droga a ser utilizada no controle da hipertensão intracraniana grave."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: a forma de interação com acetilcolina que difere os BNM despolarizantes dos não despolarizantes..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Enfermagem Terapia Intensiva De Adulto','Em qual das opções abaixo o mecanismo de insuficiência respiratória aguda é a hipoventilação alveolar?','','','["Coma mixedematoso.", "Crise asmática.", "Embolismo pulmonar.", "Doença intersticial pulmonar."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: Coma mixedematoso..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Enfermagem Terapia Intensiva De Adulto','Em relação à injúria pulmonar aguda (IPA) e à síndrome de angústia respiratória aguda (SARA) podemos afirmar que','','','["a injúria pulmonar aguda (IPA) e a síndrome de angústia respiratória aguda (SARA) correspondem a graus diferentes de gravidade da mesma patologia.", "a síndrome de angústia respiratória aguda (SARA) é, por definição, o acometimento secundário pulmonar de processos patológicos a distância.", "a pressão expiratória positiva ao final da expiração (PEEP) é critério de avaliação da síndrome de angústia respiratória aguda (SARA).", "a fase tardia da síndrome de angústia respiratória aguda (SARA) é caracterizada por necrose epitelial e endotelial, sequestro de neutrófilos, trombos plaquetários, edema intersticial e exsudato nos espaços aéreos."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: a injúria pulmonar aguda (IPA) e a síndrome de angústia respiratória aguda (SARA) correspondem a graus diferentes de gravidade da mesma patologia..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Enfermagem Terapia Intensiva De Adulto','Paciente de 37 anos, asmático, inicia quadro de dificuldade respiratória com expiração prolongada, tosse seca, ortopneia, que, apesar do uso da bomba de beta2-agonista, não melhora. À ausculta pulmonar, apresenta broncospasmo difuso. Gasometria arterial: pH = 7,35 pO2 = 70, pCO2 = 47, HCO3 = 20 SO2 = 95%. A principal droga indicada, nesse momento, é','','','["metilxantina venosa.", "antiinflamatório não-esteroide IM.", "corticosteroide sistêmico.", "brometo de ipatrópio inalatório."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: corticosteroide sistêmico..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Enfermagem Terapia Intensiva De Adulto','Paciente de 52 anos, vítima de atropelamento dá entrada na emergência com fratura de diáfise de fêmur direita e choque. Lavado peritoneal evidenciou sangramento intra-abdominal e o paciente é imediatamente levado ao centro cirúrgico e submetido à laparotomia exploradora para correção de lesão hepática. Evoluiu com estabilidade hemodinâmica e encaminhado ao CTI. Em 48 horas desenvolve confusão mental, hipoxemia com insuficiência respiratória aguda tendo sido intubado e acoplado à prótese ventilatória. Dímero D = 1.000. O tratamento em relação ao quadro respiratório é','','','["trombolítico.", "heparina não fracionada.", "heparina de baixo peso molecular.", "suportivo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: suportivo..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Enfermagem Terapia Intensiva De Adulto','Atualmente, na ventilação mecânica invasiva nos casos de injúria pulmonar aguda e/ou SARA, a preocupação com a lesão pulmonar induzida pelo próprio método é uma realidade. Na estratégia de proteger um pulmão já previamente lesado, utilizamos o seguinte parâmetro como objetivo, dentro do possível:','','','["PEEP < 5 cm H2O.", "Pressão platô < 45mmHg.", "Volume corrente = 8ml/kg de peso atual.", "FiO2 < 0,6."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: FiO2 < 0,6..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Enfermagem Terapia Intensiva De Adulto','Leia o enunciado e as alternativas da questão 35 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q35-1-v3.png", "/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q35-2-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Enfermagem Terapia Intensiva De Adulto','Podemos observar nesta radiografia de tórax a seg','','["/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q36-1-v3.png"]','["hipertensão venocapilar pulmonar.", "infiltrado pulmonar em ápice pulmonar direi", "hiperinsuflação do balonete por traqueomalá", "aumento de área cardíaca."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: hiperinsuflação do balonete por traqueomalá.' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Enfermagem Terapia Intensiva De Adulto','Paciente de 22 anos, politraumatizado, com TCE exposta de úmero direito, drenado o tórax e operado hemácias e 3,5L de cristaloides. É admitido no C noradrenalina e no eletrocardiograma realizado na admi Esse padrão eletrocardiográfico corresponde à:','','["/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q37-1-v3.png"]','["hipotermia acidental.", "hipocalcemia pós-transfusional.", "contusão miocárdica.", "normalidade."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: hipotermia acidental..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Enfermagem Terapia Intensiva De Adulto','Assinale a opção correta na correlação do diurético e o principal sítio de ação.','','','["Furosemida – alça descendente de Henle.", "Espironolactona – ducto coletor.", "Tiazídico – túbulo proximal.", "Manitol – túbulo distal."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: Espironolactona – ducto coletor..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Enfermagem Terapia Intensiva De Adulto','Leia o enunciado e as alternativas da questão 39 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q39-1-v3.png", "/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q39-2-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Enfermagem Terapia Intensiva De Adulto','Mulher de 22 anos, com diagnóstico de miastenia gravis (MG) faz uso de 90 mg de piridostigmina a cada 4 horas e prednisona 40 mg/dia com um bom controle de sua doença. Desenvolve sintomas de fraqueza muscular e insuficiência respiratória aguda após alguns dias de sulfametoxazol/trimetropim, para tratamento de infecção urinária. Diagnosticado crise miastênica. Em relação ao tratamento da paciente em questão, além de trocar o antibiótico para infecção urinária, devemos imediatamente','','','["suspender a prednisona.", "aumentar a dose da piridostigmina oral.", "iniciar plasmaferese.", "proceder à timectomia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa C. Resposta indicada no gabarito: iniciar plasmaferese..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Enfermagem Terapia Intensiva De Adulto','Paciente portador de doença diverticular de cólon esquerdo. É submetido à colectomia esquerda com anastomose. No pós-operatório, apresenta deiscência de anastomose sendo reoperado. Após uma semana sem alimentação, é iniciada nutrição parenteral. Para diagnosticar hiperalimentação, são utilizados os seguintes parâmetros:','','','["hipercalemia, hipomagnesemia, amilase elevada.", "hiperglicemia, hipofosfatemia, TGO elevada.", "hiponatremia, hipercalemia, TGP elevada.", "hipocapnia, hiperfosfatemia, hipomagne- semia."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: hiperglicemia, hipofosfatemia, TGO elevada..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Enfermagem Terapia Intensiva De Adulto','Paciente de 47 anos sofre descarga elétrica com queimadura profunda grave. É operado para desbridamento e curativo e, após 24h, desenvolve febre, dores musculares, mal-estar geral, urina escura e muita sede. Ao exame físico apresenta-se intensamente desidratado, hipotenso, lúcido, anictérico, com urina escura e em pouca quantidade. Exames laboratoriais: Gasometria arterial = acidose metabólica grave não compensada. HT = 48% Leu = 18.000 sem desvio Cr = 3,6 Ureia = 78 Potássio = 7,5 Glicemia = 250 Bilirrubinas totais = 1,2 TGO = 246 TGP = 76 CPK = 10.000 O diagnóstico mais provável é','','','["sepse grave.", "rabdomiólise.", "insuficiência renal por AINEs.", "cetoacidose diabética."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: rabdomiólise..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Enfermagem Terapia Intensiva De Adulto','Paciente de 52 anos procura serviço médico com queixa de disartria, diploplia, disfonia, disfagia e fraqueza muscular simétrica. Informa ter viajado no fim de semana para acampar. O diagnóstico provável é','','','["isquemia vértebro-basilar.", "miastenia gravis.", "síndrome de Guillain-Barré.", "botulismo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: botulismo..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Enfermagem Terapia Intensiva De Adulto','Paciente de 77 anos queixa-se de febre, dor abdominal intensa, difusa, aguda, que não alivia com analgésicos comuns. No exame fisco apresenta palidez cutâneo-mucosa, abdômen flácido e doloroso à palpação, ausência de dor à descompressão e presença de peristalse. Toque retal evidencia sangue vivo na luva. Hemograma = 23.000 leu/mm3 com desvio para esquerda. Gasometria arterial com acidose metabólica. Frente ao quadro descrito acima, o diagnóstico mais provável é','','','["diverticulite perfurada.", "pseudo-obstrução intestinal.", "porfiria aguda intermitente.", "infarto entero-mesentérico."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: infarto entero-mesentérico..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Enfermagem Terapia Intensiva De Adulto','É fator precipitante de megacolon tóxico:','','','["Loperamida.", "Lactulona.", "Ventilação não invasiva.", "Obesidade."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: Loperamida..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Enfermagem Terapia Intensiva De Adulto','Paciente de 35 anos, em tratamento para lesão tumoral do SNC com dexametasona. Desenvolve febre, infiltrado pulmonar, choque, insuficiência respiratória, insuficiência renal e a lesão de pele abaixo: O provável diagnóstico é','','["/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q46-1-v3.png", "/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-de-adulto-q46-2-v3.png"]','["sepse fúngica.", "estrongiloidíase disseminada.", "púrpura trombocitopênica trombótica.", "pneumonia grave com coagulação intravas- cular disseminada."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: estrongiloidíase disseminada..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Enfermagem Terapia Intensiva De Adulto','Na intoxicação aguda por anticolinérgicos, observa-se','','','["diarreia.", "bradicardia.", "miose.", "hipertermia."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: hipertermia..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Enfermagem Terapia Intensiva De Adulto','Na síndrome de abstinência do etanol, a medicação indicada para agitação psicomotora é','','','["Diazepam.", "Haloperidol.", "Prometazina.", "Naloxone."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa A. Resposta indicada no gabarito: Diazepam..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Enfermagem Terapia Intensiva De Adulto','Paciente vítima de lesão por projétil por arma de fogo em tórax. Encaminhado à toracotomia onde foi evidenciada lesão de esôfago. Sabemos que a mediastinite aguda é uma possível complicação. Dentre as opções abaixo, podemos afirmar que','','','["as lesões proximais do esôfago envolvem o espaço pleural esquerdo.", "a taquicardia é um sinal precoce de mediastinite.", "o tratamento é conservador com antibiótico venoso.", "o esofagograma contrastado é contrain- dicado."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa B. Resposta indicada no gabarito: a taquicardia é um sinal precoce de mediastinite..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Enfermagem Terapia Intensiva De Adulto','Identifique a resposta onde aparecem causas de reação anafilática não mediadas por IgE.','','','["Benzocaína, tetracaína, Lidocaína.", "Vacinas, soros, látex.", "Pólen, progesterona, líquido seminal.", "Dextran, relaxante muscular, contraste venosos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva De Adulto: alternativa D. Resposta indicada no gabarito: Dextran, relaxante muscular, contraste venosos..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-de-adulto' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-enfermagem-terapia-intensiva-neonatal','PMERJ 2010 — Oficial — Enfermagem Terapia Intensiva Neonatal','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Enfermagem Terapia Intensiva Neonatal','De acordo com o Manual da ANVISA (Neonatologia: critérios nacionais de infecção relacionada à assistência à saúde, 2008) a provisão de recursos humanos de enfermagem em uma Unidade de Terapia Intensiva Neonatal (UTIN) é referida como um indicador de estrutura diretamente relacionado à qualidade da assistência e ocorrência de infecções. Assim, para uma UTIN de 10 leitos, considerando a relação enfermeiro/técnico de enfermagem, podemos dizer que seriam necessários, minimamente, por plantão (turno de trabalho):','','','["1/3.", "1/5.", "2/3.", "2/5."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa D. Resposta indicada no gabarito: 2/5..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Enfermagem Terapia Intensiva Neonatal','A área adequada para punção de gota de sangue para aferição de glicemia capilar em um recém- nascido prematuro é a','','','["extremidade digital da mão.", "extremidade digital do pé.", "face lateral externa do calcâneo.", "área central do calcâneo."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: face lateral externa do calcâneo..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Enfermagem Terapia Intensiva Neonatal','A onfalocele é uma das malformações da parede abdominal anterior do recém-nascido. Assinale a alternativa correta sobre este defeito congênito.','','','["A conduta imediata da enfermagem é a instalação de uma SNG para administração da alimentação por gavagem.", "Geralmente está associado a outras malformações.", "Normalmente não existe membrana recobrindo as vísceras.", "Existe revestimento músculo-aponeurótico e cutâneo."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: Geralmente está associado a outras malformações..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Enfermagem Terapia Intensiva Neonatal','No capítulo “Intervenções do meio ambiente da UTI neonatal” do Manual de Assistência Humanizada ao recém-nascido baixo peso (MS, 2006), mostrou-se como procedimento eficaz para o manejo comportamental da dor no recém-nascido','','','["o anestésico local em prematuros de 32 semanas durante a punção lombar.", "o enrolamento após punção de calcâneo em pré-termos.", "o uso de carícias suaves anteriores ao estímulo doloroso.", "acariciar cabeça e dorso durante punção de calcâneo em pré-termos."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: o enrolamento após punção de calcâneo em pré-termos..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Enfermagem Terapia Intensiva Neonatal','Assinale a opção que apresenta os cuidados imediatos prestados a um recém-nascido, verticalmente exposto ao HIV(vírus da imunodeficiência humana).','','','["Asseio imediato/ iniciar AZT xarope ou venoso, preferencialmente até a 8ª hora de vida.", "Asseio imediato/ iniciar AZT xarope ou venoso, preferencialmente após a 48ª hora de vida.", "Aspiração vigorosa/ iniciar AZT xarope ou venoso, preferencialmente até a 8ª hora de vida.", "Aspiração vigorosa/ iniciar AZT xarope ou venoso, preferencialmente após a 48ª hora de vida."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: Asseio imediato/ iniciar AZT xarope ou venoso, preferencialmente até a 8ª hora de vida..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Enfermagem Terapia Intensiva Neonatal','Leia o enunciado e as alternativas da questão 6 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-enfermagem-terapia-intensiva-neonatal-q06-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Enfermagem Terapia Intensiva Neonatal','Foi prescrito para um recém-nascido, 95 ml de solução glicosada a 15%, sendo que, na Unidade Neonatal, só dispomos de flaconetes de 10ml de glicose a 50% e frascos de 500ml de soro glicosado a 10%. Assim, para o preparo da solução, deve-se utilizar, aproximadamente,','','','["15 ml de glicose a 50% e 80ml de soro glicosado a 10%.", "12 ml de glicose a 50% e 83ml de soro glicosado a 10%.", "89ml de glicose a 50% e 6ml de soro glicosado a 10%.", "80 ml de glicose a 50% e 15ml de soro glicosado a 10%."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: 12 ml de glicose a 50% e 83ml de soro glicosado a 10%..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Enfermagem Terapia Intensiva Neonatal','No que se refere ao cuidado com a pele do recomenda que','','','["o uso de sabão no banho deve ser feito apenas de uma a duas vezes por semana.", "devemos trocar eletrodos rotineiramente para evitar infecção cutânea.", "de preferência sua higiene deve ser feita com água estéril até a segunda semana de vida.", "deve-se evitar a umidificação das incuba- doras, devido ao risco de contaminação da pele."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: de preferência sua higiene deve ser feita com água estéril até a segunda semana de vida..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Enfermagem Terapia Intensiva Neonatal','Analise as assertivas abaixo sobre o uso da nutrição parenteral neonatal. I. Está indicada, além de outros casos, para pós-operatório em que não será iniciada nutrição enteral por mais de 5 dias. II. Pode ser administrada por cateteres periféricos desde que a concentração de glicose não exceda 12,5% e proteína de 2%. III. A troca dos equipos de infusão deve ser realizada a cada 72 horas. IV. Deve-se monitorar glicemia, pelo menos de 12 a 24 horas. Pode-se dizer que as assertivas corretas são','','','["I, II e III.", "I , II e IV.", "II e III.", "I e IV."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: I , II e IV..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Enfermagem Terapia Intensiva Neonatal','A SAF (Síndrome Alcoólica Fetal) é uma das causas mais conhecidas de retardo mental, sendo a única completamente evitável. Os efeitos duram o resto da vida da criança, que poderá apresentar problemas psicológicos e comportamentais. quadro clínico complexo, que pode ser evidenciado, a partir do exame físico pela(o) enfermeira(o) neonatologista, com a evidência de','','','["hipertrofia de gengiva e prega palmar alterada.", "macrocefalia e pregas epicânticas.", "microcefalia e prega palmar alterada.", "hipoplasia maxilar e pregas epicânticas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa D. Resposta indicada no gabarito: hipoplasia maxilar e pregas epicânticas..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Enfermagem Terapia Intensiva Neonatal','A indometacina tem sua indicação bem estabelecida após o aparecimento de sinais clínicos de PCA (persistência de canal arterial) com repercussão hemodinâmica; porém, antes do estabelecimento do quadro de insuficiência cardíaca. Seu uso está indicado graças ao seu efeito','','','["anti-inflamatório.", "antipirético.", "anti-hipertensivo.", "anticolinérgico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: anti-inflamatório..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Enfermagem Terapia Intensiva Neonatal','As infecções relacionadas ao uso de dispositivos intravasculares centrais em Neonatologia continuam sendo a principal causa de infecções primárias da corrente sanguínea (IPCS), podendo levar à sepsis nesta clientela. O Manual da ANVISA (Neonatologia: Critérios nacionais de infecção relacionada à assistência à saúde, 2008) apresenta estratégias fortemente recomendadas para implementação nas Unidades Neonatais, a fim de que as IPCS possam ser evitadas e controladas. I. Usar cateter epicutâneo (PICC) sempre que a terapia intravenosa for programada com tempo superior a 6 dias. II. Usar filtros intravasculares de rotina para prevenir infecções. III. Trocar o cateter central de rotina, sempre que ultrapassar o prazo de 10 dias. IV. Não realizar cultura da ponta de cateter de rotina. Estão corretas as seguintes assertivas:','','','["I, II e IV.", "I e III.", "II, III e IV.", "I e IV."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa D. Resposta indicada no gabarito: I e IV..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Enfermagem Terapia Intensiva Neonatal','A sondagem gástrica é um procedimento muito utilizado na Terapia Intensiva Neonatal, seja para descompressão gástrica, alimentação ou administração de medicamentos no recém-nascido. A(o) enfermeira(o) neonatologista deve estar atenta(o) a sinais clínicos que possam evidenciar possíveis complicações desta técnica, tais como a ocorrência de','','','["taquicardia e perfuração do trato gastrointestinal.", "hipoglicemia e hipercalemia.", "apneia e perfuração do trato gastrointestinal.", "hipercalemia e apneia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: apneia e perfuração do trato gastrointestinal..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Enfermagem Terapia Intensiva Neonatal','Assinale a opção que NÃO representa a fundamentação adequada, no que tange ao uso de modalidades ventilatórias na clientela neonatal.','','','["Um dos maiores objetivos da ventilação de alta frequência é reduzir o barotrauma com baixo volume tidal e frequências acima de 60 ciclos/minuto.", "O óxido nítrico vem sendo amplamente utilizado por seu efeito vasodilatador seletivo, o que promove o relaxamento da musculatura lisa vascular pulmonar.", "A ventilação mecânica convencional não está indicada nos casos de PaCO2 > 55mmHg.", "A MAP (pressão média nas vias aéreas) é a média de pressão aplicada aos pulmões durante o ciclo respiratório."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: A ventilação mecânica convencional não está indicada nos casos de PaCO2 > 55mmHg..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Enfermagem Terapia Intensiva Neonatal','Em uma Unidade Neonatal, foi prescrita uma reposição endovenosa para um recém-nascido com quadro de hipocalcemia. Durante a infusão, a(o) enfermeira(o) neonatologista deve ter os seguintes cuidados, a fim de evitar a administração excessiva deste íon:','','','["Observar ocorrência de vômitos e bradicardia.", "Observar ocorrência de cianose e letargia.", "Observar ocorrência de hipoglicemia e cianose.", "Observar ocorrência de hipoglicemia e taquicardia."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: Observar ocorrência de vômitos e bradicardia..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Enfermagem Terapia Intensiva Neonatal','A adrenalina é a droga mais utilizada na reanimação neonatal. Em relação a afirmativa acima, assinale a opção INCORRETA, no que se refere aos efeitos deste fármaco:','','','["Aumenta a contratilidade miocárdica.", "Eleva a pressão arterial.", "Diminui a demanda miocárdica de oxigênio.", "Aumenta a automaticidade, o que é útil na assistolia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: Diminui a demanda miocárdica de oxigênio.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Enfermagem Terapia Intensiva Neonatal','O enfermeiro deve administrar 10 ml de uma solução de glicose a 30% em um recém-nascido, sendo que na Unidade Neonatal só estão disponíveis ampolas de 20 ml de glicose hipertônica a 50%. O volume de glicose a ser aspirado é de','','','["10 ml.", "8 ml.", "6 ml.", "4 ml."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: 6 ml..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Enfermagem Terapia Intensiva Neonatal','Em uma Unidade de Terapia Intensiva Neonatal foram prescritas 200.000 UI de Penicilina Cristalina. O frasco de 5.000.000 UI disponível no setor foi diluído em 5 ml de água destilada. Para executar a prescrição, o volume a ser aspirado será de','','','["0,2 ml.", "0,02 ml.", "2,0 ml.", "5,0 ml."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: 0,2 ml..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Enfermagem Terapia Intensiva Neonatal','De acordo com a Sociedade Brasileira de reanimação neonatal é um procedimento fundamental para a expansão adequada dos pulmões visando o restabelecimento da ventilação pulmonar e reversão de problemas como hipoxemia, acidose e bradicardia.  Mediante esta assertiva, tal conduta na sala de parto deve ser utilizada quando o recém-nascido apresentar uma frequência cardíaca menor que','','','["40 bpm.", "60 bpm.", "80 bpm.", "100 bpm."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa D. Resposta indicada no gabarito: 100 bpm..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Enfermagem Terapia Intensiva Neonatal','Durante uma reanimação neonatal na sala de parto, apesar da utilização de oxigênio a 100%, ventilação com pressão positiva e massagem cardíaca externa efetivas, a frequência cardíaca continuou abaixo de 60 bpm por mais de 30 segundos. Nesse caso é indicada a administração de adrenalina endotraqueal ou endovenosa. De acordo com o Programa de Reanimação medicação deve ter a concentração e o volume, respectivamente, de:','','','["solução de 1:1.000 e 0,1 – 0,5ml/Kg/dose.", "solução de 1:1.000 e 0,3 – 0,5ml/Kg/dose.", "solução de 1:10.000 e 0,1 – 0,3ml/Kg/dose.", "solução de 1:10.000 e 0,3 – 0,5ml/Kg/dose."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: solução de 1:10.000 e 0,1 – 0,3ml/Kg/dose..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Enfermagem Terapia Intensiva Neonatal','A(o) enfermeira(o) neonatologista possui conhecimento sobre a gravidade e a necessidade de assistência ventilatória a recém-nascidos internados devido a aspiração meconial. Nesse sentido, uma série de cuidados de enfermagem são de grande importância na tentativa de prevenir ou minimizar as principais complicações devido a presença do mecônio no trato respiratório. Pode-se dizer que as principais complicações na aspiração meconial são','','','["atelectasia pulmonar e hipoplasia pulmonar.", "pneumotórax e pneumonia.", "pneumotórax e hipoplasia pulmonar.", "pneumonia e hipoplasia pulmonar."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: pneumotórax e pneumonia..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Enfermagem Terapia Intensiva Neonatal','Durante a assistência ao recém-nascido de alto risco, uma das principais preocupações da equipe de enfermagem é quanto à manutenção da temperatura corpórea na zona termoneutra. Neste sentido, várias intervenções podem ser realizadas a fim de se evitar a exposição da criança ao frio e, com isto, a transferência de calor para o gradiente externo (superfície do corpo para o ambiente). Os mecanismos de perda de calor do recém- nascido e suas causas estão relacionados nas colunas abaixo. I. condução III. evaporação II. radiação IV. convecção ( ) Perda de calor através da movimentação do ar pela superfície da pele. ( ) Transferência de calor corporal para superfícies frias no ambiente que não estão em contato com o corpo. ( ) Perda de calor por contato direto de um corpo com outro. ( ) Perda de calor durante a conversão do estado líquido para o gasoso. Correlacione-as e marque a opção que contém a sequência correta.','','','["IV, II, I e III.", "I, II, III e IV.", "IV, III, II e I.", "II, I, IV e III"]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: IV, II, I e III..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Enfermagem Terapia Intensiva Neonatal','intervenções, visando preservar a temperatura corporal do recém-nascido. Assinale que intervenções são utilizadas no dia a dia para diminuir a perda de temperatura por condução.','','','["Manter o recém-nascido em incubadora aquecida com temperatura adequada; manter incubadoras afastadas da parede e manter recém-nascidos menores de 1.500g em incubadoras de parede dupla.", "Administrar oxigênio aquecido; evitar a abertura da incubadora com frequência e proteger prematuros de muito baixo peso e extremo baixo peso que estejam em berço aquecido com cobertura de plástico transparente.", "Ao banhar o recém-nascido, fazê-lo por partes, secando em seguida; evitar deixar a criança com a fralda molhada e realizar higiene corporal na incubadora quando o recém-nascido for menor que 1.500g.", "Aquecer o estetoscópio antes de examinar o recém-nascido; lavar as mãos com água aquecida antes de tocar o paciente e forrar a balança antes de pesar a criança."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa D. Resposta indicada no gabarito: Aquecer o estetoscópio antes de examinar o recém-nascido; lavar as mãos com água aquecida antes de tocar o paciente e forrar a balança antes de pesar a criança..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Enfermagem Terapia Intensiva Neonatal','A Síndrome da Angústia Respiratória (SAR) é observada com maior frequência em recém-nascidos prematuros, sendo também considerada uma das principais causas de morbimortalidade neonatal. Baseado nestas afirmativas, é de fundamental importância que a(o) enfermeira(o) neonatologista conheça a fisiopatologia da SAR, normalmente caracterizada por','','','["hipoventilação, diminuição de pCO2, aumento do pO2 e vasoconstricção pulmonar.", "hiperventilação, aumento de pCO2, diminuição de pO2 e vasodilatação pulmonar.", "hipoventilação, aumento do pCO2, diminuição do pO2 e vasoconstricção pulmonar.", "hiperventilação, diminuição de pCO2, diminuição do pO2 e vasodilatação pulmonar."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: hipoventilação, aumento do pCO2, diminuição do pO2 e vasoconstricção pulmonar..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Enfermagem Terapia Intensiva Neonatal','Em relação à taquipneia transitória do recém- -nascido, coloque “V” para a afirmativa Verdadeira e “F” para a afirmativa Falsa, em seguida, marque a opção cuja sequência está correta. ( ) Tem como principal fator predisponente o retardamento da eliminação do fluido pulmonar. ( ) A administração de surfactante pulmonar é a terapêutica de escolha para taquipneia transitória. ( ) Um dos fatores predisponentes são os filhos de mães submetidas ao parto cesáreo eletivo. ( ) A evolução clínica é grave, sendo a ventilação mecânica normalmente empregada.','','','["V, F, V, F.", "F, V, V, F.", "V, F, V, V.", "F, V, F, V."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: V, F, V, F..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Enfermagem Terapia Intensiva Neonatal','Em relação à retinopatia da prematuridade e à displasia broncopulmonar, coloque “V” para a afirmativa Verdadeira e “F” para a afirmativa Falsa, em seguida, marque a opção cuja sequência está correta. ( ) A retinopatia da prematuridade e a displasia broncopulmonar têm como um dos fatores predisponentes a oxigenioterapia em altas concentrações por tempo prolongado. ( ) Somente a displasia broncopulmonar tem como fator predisponente a oxigenioterapia em altas concentrações por tempo prolongado e a retinopatia da prematuridade é consequência do tratamento pela fototerapia. ( ) A administração de corticóide na gestante em ameaça de parto prematuro tem contribuído para um melhor prognóstico nos recém-nascidos com retinopatia da prematuridade e displasia broncopulmonar. ( ) A avaliação periódica através da gasometria é de fundamental importância na prevenção da displasia broncopulmonar e o controle da bilirrubina para a prevenção da retinopatia da prematuridade.','','','["V, F, V, F.", "F, V, V, F.", "V, F, F, V.", "F, V, V, V."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: V, F, V, F..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Enfermagem Terapia Intensiva Neonatal','A “CONSTANT POSITIVE AIRWAY PRESSURE” (CPAP) Nasal é uma modalidade de oxigenioterapia com pressão positiva contínua, que tem por finalidade','','','["aumentar a capacidade funcional residual pulmonar e aumentar a resistência vascular pulmonar.", "aumentar a capacidade funcional residual pulmonar e reduzir a resistência vascular pulmonar.", "diminuir a capacidade funcional residual pulmonar e reduzir a resistência vascular pulmonar.", "diminuir a capacidade funcional residual pulmonar e aumentar a resistência vascular pulmonar."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: aumentar a capacidade funcional residual pulmonar e reduzir a resistência vascular pulmonar..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Enfermagem Terapia Intensiva Neonatal','A avaliação frequente do recém-nascido na sala de parto é imprescindível para a tomada de decisões sobre o que deverá ser realizado para a reanimação do mesmo. Quanto a este aspecto, o Programa de Reanimação Neonatal cita três pontos que devem ser rigorosamente avaliados. Pode-se dizer que, em ordem de prioridade, a sequência recomendada é:','','','["respiração, frequência cardíaca e cor.", "cor, respiração e frequência cardíaca.", "frequência cardíaca, cor e respiração.", "cor, frequência cardíaca e respiração."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: respiração, frequência cardíaca e cor..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Enfermagem Terapia Intensiva Neonatal','Tratam-se de sinais preditivos para o diagnóstico de atresia esofágica no recém-nascido:','','','["oligodramnia materna/ vômito bilioso.", "polidramnia materna/ salivação espumosa.", "polidramnia materna/acolia fecal.", "hidramnia/ vômito bilioso."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: polidramnia materna/ salivação espumosa..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Enfermagem Terapia Intensiva Neonatal','Segundo Silva e Nogueira (2004), a remoção do cateter epicutâneo em um recém-nascido requer o seguinte cuidado pelo(a) enfermeiro(a):','','','["Se houver resistência, pode-se utilizar compressas frias locais, a fim de se promover vasoespasmo e facilitar a saída do mesmo.", "Fazer movimentos de rotação do membro para diminuir a contratura muscular e facilitar a retirada do cateter.", "Remover de forma asséptica, delicadamente, a fim de evitar o risco de embolia gasosa ou rompimento do corpo do cateter.", "Aplicar antisséptico no local e compressas mornas de rotina para se evitar a formação de abscessos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: Remover de forma asséptica, delicadamente, a fim de evitar o risco de embolia gasosa ou rompimento do corpo do cateter..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Enfermagem Terapia Intensiva Neonatal','Podemos afirmar que, no preparo de drogas e soluções para infusão intravenosa em recém-nascido, as afirmativas abaixo estão corretas, EXCETO:','','','["Todos os materiais utilizados - agulhas, equipos e circuitos - devem ser mantidos com tampa antes e após o uso.", "O conteúdo restante de ampolas deve ser mantido em seringas na geladeira, devidamente identificados.", "As unidades neonatais devem possuir área exclusiva de preparo, caso as drogas não sejam manipuladas pelo serviço de Farmácia.", "Devem-se usar agulhas de pequeno calibre na aspiração e diluição de frascos com tampa de borracha."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: O conteúdo restante de ampolas deve ser mantido em seringas na geladeira, devidamente identificados.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Enfermagem Terapia Intensiva Neonatal','A determinação da idade gestacional do neonato pode ser realizada avaliando-se algumas de suas características físicas externas e neurológicas. Para a realização desta avaliação, o sistema empregado é o de','','','["Apgar.", "Moro.", "Ballard.", "Cachecol."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: Ballard..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Enfermagem Terapia Intensiva Neonatal','Sobre o surfactante pulmonar, a(o) enfermeira(o) neonatologista deve saber que I. é uma mistura de fosfolipídios e proteínas. II. sua administração tem por objetivo diminuir a complacência pulmonar. III. a sua deficiência está condicionada a qualidade da circulação capilar pulmonar. IV. o surfactante exógeno pode ser administrado de forma profilática nos recém-nascidos prematuros. Estão corretas as seguintes assertivas:','','','["I, III e IV.", "I, II e III.", "I e III.", "III e IV."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: I, III e IV..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Enfermagem Terapia Intensiva Neonatal','A equipe de enfermagem que atua na Unidade de Terapia Intensiva Neonatal desempenha papel de fundamental importância na identificação dos sinais clínicos sugestivos de enterocolite necrosante que são','','','["abdome escavado, angústia respiratória e intolerância alimentar.", "alças intestinais visíveis, retardo do esvaziamento gástrico e presença de sangue nas fezes.", "abdome escavado, ausência de sangue nas fezes e intolerância alimentar.", "intolerância alimentar, ausência de ar nas alças intestinais e alças intestinais visíveis."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: alças intestinais visíveis, retardo do esvaziamento gástrico e presença de sangue nas fezes..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Enfermagem Terapia Intensiva Neonatal','O diagnóstico e o tratamento precoces da hiperbilirrubinemia têm como objetivo principal evitar complicações do sistema','','','["digestivo.", "circulatório.", "nervoso central.", "imunlógico."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: nervoso central..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Enfermagem Terapia Intensiva Neonatal','A exsanguineotransfusão é uma modalidade terapêutica empregada para o tratamento da hiperbilirrubinemia neonatal.  Considerando os objetivos dessa terapia, coloque (V) para as afirmativas Verdadeiras e (F) para as Falsas. ( ) remover os hemácias sensibilizadas da circulação. ( ) diminuir o nível sérico de bilirrubina para prevenir a obstrução intestinal. ( ) corrigir a anemia. ( ) evitar a insuficiência cardíaca. Marque a sequência correta.','','','["V, F, V, V.", "F, V, F, V.", "V, V, F, F.", "V, F, V, F."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: V, F, V, V..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Enfermagem Terapia Intensiva Neonatal','A alimentação por gavagem é muito utilizada para alimentar recém-nascidos prematuros. Para a realização desse procedimento, devemos saber que I. ele visa avaliar a ingesta adequada de líquidos e a capacidade gástrica da criança. II. a via oral para a instalação da sonda tem sido mais indicada que a via nasal. III. o decúbito lateral esquerdo é a posição de escolha para prevenir os episódios de regurgitação e aspiração. IV o resíduo gástrico deve ser desprezado quando for maior que 50% do volume prescrito para a dieta. Marque a opção correta.','','','["Apenas I e II estão corretas.", "Apenas II e III estão corretas.", "Apenas II e IV estão corretas.", "Apenas I e IV estão corretas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: Apenas I e II estão corretas..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Enfermagem Terapia Intensiva Neonatal','A sucção é a melhor forma de um recém- nascido ser alimentado, porém esta só deve ser incentivada quando a criança, dentre outras condições, consegue coordenar sucção-deglutição e respiração. Na maioria dos neonatos, esse mecanismo de coordenação encontra-se desenvolvido a partir da','','','["20a semana de gestação.", "28a semana de gestação.", "34a semana de gestação.", "40a semana de gestação."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: 34a semana de gestação..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Enfermagem Terapia Intensiva Neonatal','translactação tem por finalidade','','','["estimular a sucção durante a administração da dieta por gavagem intermitente.", "oferecer leite complementando a dieta oferecida por gavagem.", "iniciar a alimentação com dieta enteral mínima.", "fazer a transição da alimentação por gavagem para a sucção ao seio."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa D. Resposta indicada no gabarito: fazer a transição da alimentação por gavagem para a sucção ao seio..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Enfermagem Terapia Intensiva Neonatal','A policitemia é um achado clínico que pode aparecer no recém-nascido devido a diversos fatores etiológicos. Quando está associada a manifestações clínicas, a exsanguineotransfusão parcial pode ser indicada com o objetivo de','','','["aumentar o hematócrito e diminuir a viscosidade sanguínea.", "diminuir o hematócrito e aumentar a viscosidade sanguínea.", "aumentar o hematócrito e aumentar a viscosidade sanguínea.", "diminuir o hematócrito e diminuir a viscosidade sanguínea."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa D. Resposta indicada no gabarito: diminuir o hematócrito e diminuir a viscosidade sanguínea..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Enfermagem Terapia Intensiva Neonatal','considera-se recém-nascido baixo peso aquele que apresenta a(s) seguinte(s) característica(s):','','','["peso inferior a 2.500g e idade gestacional menor que 37 semanas.", "peso inferior a 1.500g, independente da idade gestacional.", "peso inferior a 2.500g, independente da idade gestacional.", "peso inferior a 1.500g e idade gestacional menor que 37 semanas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: peso inferior a 2.500g, independente da idade gestacional..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Enfermagem Terapia Intensiva Neonatal','Na assistência imediata ao recém-nascido a termo, em boas condições de vitalidade e que recebeu os primeiros cuidados de forma adequada, ocorrem significativas mudanças adaptativas nos sistemas cardiocirculatório e pulmonar, que são','','','["fechamento do canal arterial, abertura do forame oval, fechamento do ducto venoso e vasodilatação da circulação pulmonar.", "fechamento do canal arterial, fechamento do forame oval, fechamento do ducto venoso e vasodilatação da circulação pulmonar.", "fechamento do canal arterial, fechamento do forame oval, abertura do ducto venoso e vasoconstricção da circulação pulmonar.", "fechamento do canal arterial, fechamento do forame oval, fechamento do ducto venoso e vasoconstricção da circulação pulmonar."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: fechamento do canal arterial, fechamento do forame oval, fechamento do ducto venoso e vasodilatação da circulação pulmonar..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Enfermagem Terapia Intensiva Neonatal','Considere as afirmativas abaixo, referentes ao exame físico do recém-nascido, e marque a opção correta. I. O sinal de Macewen é um dos achados que pode ser observado no recém-nascido portador de hidrocefalia. II. O caput succedaneum caracteriza-se por um hematoma entre o periósteo e os ossos do crânio. III. Uma perda de peso fisiológica em torno de 10% é esperada nos recém-nascidos a termo. IV. A manobra de Koplik é utilizada para identificar a presença de luxação coxo- -femural.','','','["Apenas I e III estão corretas.", "Apenas II e III estão corretas.", "Apenas II e IV estão corretas.", "Apenas I e IV estão corretas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa A. Resposta indicada no gabarito: Apenas I e III estão corretas..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Enfermagem Terapia Intensiva Neonatal','Ao avaliar o resultado dos dados gasométricos: pH =7.25; pO2 = 40 mmHg; pCO2 = 80 mmHg; HCO3 = 25 e Excesso de base = -2, a(o) enfermeira(o) neonatologista sabe que esse recém-nascido, em oxigenioterapia, está em','','','["alcalose respiratória.", "alcalose metabólica.", "acidose respiratória.", "acidose metabólica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: acidose respiratória..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Enfermagem Terapia Intensiva Neonatal','Ao aferir a glicemia capilar de um recém- nascido prematuro internado na Unidade Neonatal, que está mantido em dieta zero, sonda orogástrica em sifonagem e hidratação venosa em veia periferia, verifica-se que o valor encontrado é de 60mg/dl. A partir desse resultado, a conduta deverá ser','','','["comunicar ao médico, pois a criança está apresentando hipoglicemia.", "só registrar o valor no prontuário da criança, pois o valor encontrado está situado na faixa de normalidade.", "aumentar o volume de infusão para correção da glicemia.", "administrar glicose a 25% pela sonda orogástrica e realizar nova glicemia capilar."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: só registrar o valor no prontuário da criança, pois o valor encontrado está situado na faixa de normalidade..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Enfermagem Terapia Intensiva Neonatal','A(o) enfermeira(o) neonatologista intensivista deve considerar que os barotraumas têm aumentado significativamente o tempo de permanência dos tubos endotraqueais em recém-nascidos. Para evitar essas complicações, quando da aspiração do tubo traqueal, são necessários alguns cuidados, tais como','','','["esvaziar o balonete durante o procedimento para evitar lesão por compressão da traqueia.", "mobilizar o tubo para permitir melhor aspiração dos brônquios principais direito e esquerdo.", "não avançar a sonda além da ponta do tubo, evitando o broncoespasmo.", "aplicar pressão de aspiração elevada que é necessária para a remoção mais rápida da secreção."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: não avançar a sonda além da ponta do tubo, evitando o broncoespasmo..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Enfermagem Terapia Intensiva Neonatal','Na assistência dispensada ao recém-nascido normal e, principalmente, ao de risco, é de fundamental importância que sejam implementadas estratégias de prevenção e redução do  desenvolvimento da hipertensão pulmonar persistente que está relacionada a múltiplos fatores etiológicos e é caracterizada por','','','["resistência vascular pulmonar menor que a resistência vascular sistêmica com desvio do fluxo sanguíneo do lado direito para o esquerdo do coração.", "resistência vascular pulmonar maior que a resistência vascular sistêmica com desvio do fluxo sanguíneo do lado direito para o esquerdo do coração.", "resistência vascular pulmonar menor que a resistência vascular sistêmica com desvio do fluxo sanguíneo do lado esquerdo para o direito do coração.", "resistência vascular pulmonar maior que a resistência vascular sistêmica com desvio do fluxo sanguíneo do lado esquerdo para o direito do coração."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: resistência vascular pulmonar maior que a resistência vascular sistêmica com desvio do fluxo sanguíneo do lado direito para o esquerdo do coração..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Enfermagem Terapia Intensiva Neonatal','A tetralogia de Fallot é uma das cardiopatias congênitas cianóticas diagnosticadas durante a primeira semana de vida da criança e é caracterizada pelas seguintes alterações cardíacas:','','','["persistência do canal arterial, comunicação interatrial, estenose pulmonar e estenose aórtica.", "persistência do canal arterial, comunicação interventricular, dextroposição da aorta e hipertrofia do ventrículo esquerdo.", "estenose pulmonar, comunicação interventricular, dextroposição da aorta e hipertrofia do ventrículo direito.", "comunicação interatrial, comunicação interventricular, hipertrofia do ventrículo direito e hipertrofia do ventrículo esquerdo."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa C. Resposta indicada no gabarito: estenose pulmonar, comunicação interventricular, dextroposição da aorta e hipertrofia do ventrículo direito..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Enfermagem Terapia Intensiva Neonatal','A trissomia do 21 (síndrome de Down) é, dentre as síndromes cromossomias, a de maior incidência entre os recém-nascidos e pode estar associada, mais comumente, com a seguinte malformação estrutural:','','','["mielocele ou meningomielocele.", "cardiopatia congênita.", "fenda alatina e lábio leporino.", "onfalocele."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa B. Resposta indicada no gabarito: cardiopatia congênita..' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Enfermagem Terapia Intensiva Neonatal','O filho de mãe diabética necessita de vigilância constante da equipe de enfermagem, pois são altamente predispostos a apresentar','','','["hiponatremia.", "hipomagnesemia.", "hipopotassemia.", "hipoglicemia,"]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Enfermagem Terapia Intensiva Neonatal: alternativa D. Resposta indicada no gabarito: hipoglicemia,.' from public.exams where slug='pmerj-2010-enfermagem-terapia-intensiva-neonatal' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-urologia','PMERJ 2010 — Oficial — Médico Urologia','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Urologia','Em relação à infecção urinária, NÃO é correto afirmar que','','','["o tratamento da candidíase urinária é geralmente realizado com Anfotericina B.", "as infecções por fungos se tornaram mais frequentes com o aparecimento da AIDS e a imunosupressão dos transplantes.", "obstrução e cálculo favorecem o aparecimento de infecção.", "as infecções urinárias são a segunda forma de infecção mais comum em nosso organismo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: as infecções urinárias são a segunda forma de infecção mais comum em nosso organismo.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Urologia','Em relação à duplicidade ureteropélvica completa, é INCORRETO afirmar:','','','["O ureter da unidade superior é mais predisposto à obstrução.", "O ureter da unidade inferior é mais lateral.", "O ureter da unidade superior está associado à ectopia.", "O ureter da unidade superior é mais predisposto a refluxo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: O ureter da unidade superior é mais predisposto a refluxo..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Urologia','Em relação à litíase urinária, é correto afirmar:','','','["Os cálculos de cistina são mais frequentes no sexo masculino.", "Os cálculos urinários são mais frequentes no sexo masculino.", "O cálculo de ácido úrico se forma em urina alcalina.", "Os diuréticos tiazidicos não são usados na litíase urinária."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: Os cálculos urinários são mais frequentes no sexo masculino..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Urologia','Em relação à difusão erétil, NÃO é correto afirmar:','','','["Após infecção e extrusão de uma prótese, a colocação de uma nova prótese somente deve ser realizada após um ano.", "A papaverina foi a primeira substância usada para induzir ereção.", "Os inibidores da 5-fosfo-diesterase são as drogas orais mais usadas.", "A doença de Peyronie é caracterizada por placa fibrosa peniana + dor à ereção e encurtamento peniano."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: Após infecção e extrusão de uma prótese, a colocação de uma nova prótese somente deve ser realizada após um ano.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Urologia','Em relação à tuberculose urinária, é correto afirmar:','','','["A TB genitourinária incide de maneira igual em todos os níveis sociais.", "Pode ser transmitida por vetores.", "Uma prova tuberculínica positiva (PPD) sempre firma diagnóstico da doença em atividade.", "O foco inicial da TB genito-urinária é na maioria dos casos o rim."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: O foco inicial da TB genito-urinária é na maioria dos casos o rim..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Urologia','Em relação à HPB, é correto afirmar:','','','["A ultrassonografia transretal deve sempre ser realizada para medir volume da próstata.", "O questionário IPSS é recomendado para a avaliação dos sintomas do paciente, porém não é utilizado para fechar o diagnóstico de hiperplasia prostática benigna.", "Cerca de 30% dos pacientes com sintomas do trato urinário inferior (LUTS) tem bexiga hiperativa.", "Cerca de 10% dos pacientes, após tratamento cirúrgico da HPB, mantêm queixas urinárias baixas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: O questionário IPSS é recomendado para a avaliação dos sintomas do paciente, porém não é utilizado para fechar o diagnóstico de hiperplasia prostática benigna..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Urologia','Sobre o refluxo vesico-ureteral, é INCORRETA afirmar:','','','["O diagnóstico clássico é feito através da uretrocistrografia miccional.", "O tratamento cirúrgico é reservado para refluxo grau IV e V.", "A utilização de tratamento com antibióticos em dose diária só deve ocorrer em caso de refluxo grau I.", "O refluxo vesico-ureteral deve ser investigado em crianças com infecção urinária de repetição."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: A utilização de tratamento com antibióticos em dose diária só deve ocorrer em caso de refluxo grau I.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Urologia','Sobre o HPV, é INCORRETO afirmar:','','','["É obrigatória a realização da peniscopia em todo homem com parceira com diagnóstico de HPV.", "Alguns tipos de HPV estão associados ao câncer de pênis.", "É a DST viral mais frequente.", "O acometimento uretral mais comum é o meato uretral externo."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: É obrigatória a realização da peniscopia em todo homem com parceira com diagnóstico de HPV..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Urologia','A respeito do câncer de rim, é correto afirmar:','','','["Predomina no sexo feminino.", "Cerca de 10 a 20% das massas renais sólidas, captantes de contraste, são benignas à patologia após remoção cirúrgica.", "O risco de malignidade em Cistos Renais Bosniak IV é de 60%.", "A I.R.C. e diálise crônica não favorecem seu aparecimento."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: Cerca de 10 a 20% das massas renais sólidas, captantes de contraste, são benignas à patologia após remoção cirúrgica..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Urologia','Em relação ao calibre “French” (Fr) das sondas uretrais, assinale a alternativa correta.','','','["Um French é aproximadamente igual a um milímetro.", "A escala French que define o calibre do cateter refere-se ao número de milímetros na circunferência interna na luz da sonda.", "A escala French que define o calibre do cateter é igual a 0,66 mm.", "A escala French que define o calibre do cateter refere-se ao número de milímetros na circunferência externa da sonda."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: A escala French que define o calibre do cateter refere-se ao número de milímetros na circunferência externa da sonda..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Urologia','Em relação ao agente causal mais frequente nas epididimites agudas, podemos afirmar que em homens','','','["com menos de 35 anos o agente causal mais comum é Neisseria gonorrhoeae.", "com menos de 35 anos o agente causal mais comum é a Chlamidia trachomatis.", "com menos de 35 anos o agente causal mais comum é a Escherichia coli.", "com mais de 35 anos o agente causal mais comum é a Chlamidia trachomatis."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: com menos de 35 anos o agente causal mais comum é a Chlamidia trachomatis..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Urologia','Assinalar a melhor técnica cirúrgica em lesões iatrogênicas completas de ureter inferior.','','','["Transuretero-ureterostomia.", "Anastomose témino-terminal.", "Reimplante ureterovesical com bexiga psoica.", "Passagem de cateter duplo jota."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: Reimplante ureterovesical com bexiga psoica..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Urologia','Um homem de 25 anos sofreu um ferimento escarranchado, depois de cair de um andaime e aterrissar em uma divisória de concreto. Na manhã seguinte, ele acordou com uma ereção parcial de 75% que persistiu por 2 semanas. A ereção não era dolorosa. Qual é a causa mais provável?','','','["Ferimento do nervo cavernoso.", "Ruptura da artéria cavernosa.", "Fístula persistente entre o corpo cavernoso e o corpo esponjoso.", "Disfunção autônoma."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: Fístula persistente entre o corpo cavernoso e o corpo esponjoso..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Urologia','O istmo do rim em ferradura é “preso” por qual das seguintes estruturas, durante a ascensão?','','','["Artéria mesentérica inferior.", "Artéria mesentérica superior.", "Artéria celíaca.", "Artéria ilíaca comum."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: Artéria mesentérica inferior..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Urologia','O úraco involui para tornar-se o','','','["verumontano.", "ligamento umbilical mediano.", "apêndice dos testículos.", "epoóforo."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: ligamento umbilical mediano..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Urologia','Quanto ao ureter retrocava, é INCORRETO afirmar que','','','["ocorre devido à permanência da veia supra- cardinal.", "o diagnóstico pode ser feito pela ureterografia retrógrada.", "o melhor exame diagnóstico é a ressonância magnética.", "a forma em que o ureter muda seu curso ao nível de L3 geralmente está associado à obstrução."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: ocorre devido à permanência da veia supra- cardinal..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Urologia','Os cálculos denominados de estruvita são constituídos de','','','["oxalato de cálcio.", "fosfato de cálcio.", "fosfato amoníaco-magnesiano.", "ácido úrico."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: fosfato amoníaco-magnesiano..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Urologia','A presença da úlcera de Hunner na cistoscopia está associada à(ao)','','','["tuberculose.", "esquistossomose.", "câncer de bexiga.", "cistite intersticial."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: cistite intersticial..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Urologia','Indivíduo com prostatite classificada na Categoria IV apresenta os seguintes sintomas:','','','["assintomático, com biópsia prostática demonstrando prostatite.", "febre, calafrios, dor perineal e disúria.", "dor perineal, sem febre e disúria leve.", "síndrome dolorosa pélvica, com leucócitos na urina pós-massagem prostática."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: assintomático, com biópsia prostática demonstrando prostatite..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Urologia','Indivíduo de 40 anos, com piúria estéril no EAS (com cultura) e urografia mostrando estenose ureteral do terço inferior esquerdo associado à bexiga contraída. O método diagnóstico mais importante para o quadro acima é','','','["cultura de urina no meio de Thayer-Martin.", "cultura de urina no meio de Lowenstein- -Jensen.", "citologia urinária.", "bacterioscopia urinária pela coloração de Ziehl-Neelsen."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: cultura de urina no meio de Lowenstein- -Jensen..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Urologia','Indivíduo no toque retal apresenta nódulo endurecido em lobo direito e biópsia prostática mostra adenocarcinoma de próstata bilateral, Gleason 3+3. O paciente deve ser classsificado clinicamente e em relação à diferenciação do tumor em','','','["T1c indiferenciado.", "T2a bem diferenciado.", "T3 moderadamente diferenciado.", "T2b moderadamente diferenciado."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: T2b moderadamente diferenciado..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Urologia','A complicação que pode ocorrer com o uso associado do sildenafil com o nitrato é','','','["distúrbios visuais.", "hipotensão arterial.", "vômitos.", "priapismo."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: hipotensão arterial..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Urologia','O melhor exame para o diagnóstico de torção testicular é','','','["cintilografia.", "ecodoppler colorido.", "tomografia computadorizada.", "exame físico."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: ecodoppler colorido..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Urologia','No transplante renal deve ser retirado, preferencialmente, o rim esquerdo do doador vivo. A razão para esse procedimento é','','','["o rim esquerdo ser maior que o direito.", "o rim esquerdo estar numa posição mais alta que o direito.", "a veia renal ser mais longa no rim esquerdo.", "a artéria renal ser quase sempre única, à esquerda."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: a veia renal ser mais longa no rim esquerdo..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Urologia','A causa mais comum de hipertensão reno- vascular é','','','["displasia fibromuscular.", "poliarterite nodosa.", "coartação da aorta.", "aterosclerose."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: aterosclerose..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Urologia','O trato urinário inferior recebe inervações aferentes e eferentes tanto do sistema autonômico como do somático. Assinale abaixo a afirmativa correta.','','','["A inervação simpática origina-se de L1 a L3.", "A inervação somática para o esfíncter externo origina-se entre T10-L2 e caminha através do nervo pudendo.", "A inervação parassimpática origina-se entre o segundo e o quarto segmentos sacrais.", "O nervo pélvico não carrega fibras motoras para a inervação esfincteriana externa."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: A inervação parassimpática origina-se entre o segundo e o quarto segmentos sacrais..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Urologia','A disreflexia autonômica pode ser uma apresentação comum em pacientes com traumatismo raquimedular. Assinale a afirmativa abaixo que melhor caracteriza este fenômeno.','','','["Ocorre em lesões medulares mais baixas, principalmente na região lombar e caracteriza-se por uma diminuição da atividade detrussora.", "Ocorre em lesões torácicas altas e cervicais e caracteriza-se por um quadro clínico de hipertensão, bradicardia, dor de cabeça e piloereção associada à distensão vesical ou retal.", "Ocorre em lesões torácicas altas e cervicais e caracteriza-se por um quadro clínico de hipotensão severa, taquicardia, dor de cabeça e piloereção associada à distensão vesical ou retal.", "Ocorre em lesões medulares, principalmente na região lombar e caracteriza-se por uma diminuição da atividade detrussora."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: Ocorre em lesões torácicas altas e cervicais e caracteriza-se por um quadro clínico de hipertensão, bradicardia, dor de cabeça e piloereção associada à distensão vesical ou retal..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Urologia','Podemos definir a urge-incontinência (UI) como a perda involuntária de urina acompanhada ou imediatamente precedida pela sensação de urgência. Assinale a afirmativa correta.','','','["O principal fator relacionado a UI é a instabilidade esfincteriana.", "O termo bexiga hiperativa que substituiu o termo bexiga instável é clinicamente defi- nido pelos sintomas de urgência, frequência e noctúria, associada ou não à UI.", "A hiperplasia prostática benigna não é uma causa comum de bexiga hiperativa em homens.", "Da mesma forma que a incontinência urinária por esforço, a UI tem no tratamento cirúrgico a sua opção mais comum."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: O termo bexiga hiperativa que substituiu o termo bexiga instável é clinicamente defi- nido pelos sintomas de urgência, frequência e noctúria, associada ou não à UI..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Urologia','Sobre a falência na função de reservatório vesical e seu tratamento, assinale a alternativa INCORRETA.','','','["Os agentes anticolinérgicos são amplamente utilizados nesta situações e agem bloqueando a ação da dopamina nos receptores muscarínico.", "Os agentes anticolinérgicos são amplamente utilizados nestas situações levando ao aumento da capacidade vesical e à inibição de contrações involuntárias.", "A toxina butolínica e a neuroestimulação são opções à falha do tratamento medicamentoso.", "A soliferacina é um anticolinérgico seletivo para receptores M3."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: Os agentes anticolinérgicos são amplamente utilizados nesta situações e agem bloqueando a ação da dopamina nos receptores muscarínico.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Urologia','Assinale a afirmativa INCORRETA sobre as complicações presentes em pacientes com trauma raqui-medular e bexiga neurogênica.','','','["As principais complicações em portadores de bexiga neurogênica são: infecção urinária recorrente, hidronefrose secundária ao refluxo vésico-ureteral e formação de cálculos.", "A amiloidose renal secundária é uma causa comum de morte em pacientes com bexiga neurogênica.", "Pacientes com trauma raquimedular tendem a preservar a ejaculação ( reflexo coordenado em nível medular) apesar das alterações sobre a qualidade da ereção.", "A pielonefroite e epidimite são complicações ocasionais associadas às infecções recorrentes do trato urinário."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: Pacientes com trauma raquimedular tendem a preservar a ejaculação ( reflexo coordenado em nível medular) apesar das alterações sobre a qualidade da ereção.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Urologia','Sobre a fisiologia da micção, é correto afirmar:','','','["O fluxo urinário normal, com a bexiga repleta, varia de 25 a 30 ml/s em homens e 20-25 ml/s em mulheres. Estas variações estão diretamente associadas ao volume urinado e idade.", "Devemos suspeitar de obstrução infra- vesical em pacientes com fluxo menor do que 18 ml/s.", "A presença de um fluxo alto, acima dos valores esperados para o sexo, deve sempre ser investigada como possibilidade de alterações patológicas.", "Fluxo urinário abaixo de 10ml/s é considerado uma evidência definitiva da existência de um fator obstrutivo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: Fluxo urinário abaixo de 10ml/s é considerado uma evidência definitiva da existência de um fator obstrutivo..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Urologia','Os fatores básicos na função vesical normal são: capacidade, acomodação, sensação, contratilidade, controle voluntário e resposta às drogas. Assinale a alternativa correta.','','','["As sensações de enchimento vesical são inicialmente percebidas aos 50 ml, e o desejo de micção ocorre após os 400 ml.", "A bexiga é um órgão complacente e desta forma as variações de volume estão associadas a um rápido aumento nas pressões vesicais.", "Quando utilizamos o betanecol na avaliação da função vesical, notamos que a ausência de resposta está associada à presença de lesão miogênica e à resposta exacerbada à lesão do neurônio motor inferior.", "A inibição consciente da contração detrussora é inexistente."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: Quando utilizamos o betanecol na avaliação da função vesical, notamos que a ausência de resposta está associada à presença de lesão miogênica e à resposta exacerbada à lesão do neurônio motor inferior..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Urologia','Assinale a alternativa que apresente apenas causas de redução da capacidade vesical.','','','["Enurese, incontinência, tuberculose, lesão do neurônio motor superior.", "Cistite intersticial, tuberculose, lesões do neurônio motor inferior, infecção urinária.", "Lesão do neurônio motor superior, obstrução infravesical crônica, enurese e incontinência.", "Lesão do neurônio motor inferior, enurese, incontinência e tuberculose."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: Enurese, incontinência, tuberculose, lesão do neurônio motor superior..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Urologia','Como definimos a presença de uma dissinergia vésico-esfincteriana?','','','["Presença de uma aumento da pressão de fechamento uretral durante a contração detrussora. É uma situação comum em pacientes com lesão supraespinhal.", "Presença de uma diminuição da pressão de fechamento uretral durante a contração detrussora. É uma situação comum em pacientes com lesão supraespinhal.", "Presença de uma aumento da pressão de fechamento uretral durante a contração detrussora. É uma situação incomum em pacientes com lesão supraespinhal.", "Presença de uma diminuição da pressão de fechamento uretral durante a contração detrussora. É uma situação incomum em pacientes com lesão supraespinhal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: Presença de uma aumento da pressão de fechamento uretral durante a contração detrussora. É uma situação comum em pacientes com lesão supraespinhal..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Urologia','Assinale a alternativa correta quanto à relação entre varicocele e infertilidade masculina.','','','["A incidência de varicocele à esquerda em homens subférteis é de 80%.", "A varicocele é comumente diagnosticada em garotos com idade inferior a 10 anos, podendo estar associada à atrofia testicular.", "A incidência de varicocele bilateral é de 60% dos homens subférteis.", "A incidência de varicocele à esquerda em homens subférteis é de 40%."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: A incidência de varicocele à esquerda em homens subférteis é de 40%..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Urologia','Na presença de um homem azoospérmico com as seguintes características clínicas: ginecomastia, atrofia testicular e história de atraso na maturação sexual, devemos suspeitar de','','','["sindrome de Klinefelter, em que 50% desses homens têm cariótipo 47XXY.", "sindrome XYX, onde o cariótipo característico é 47XYX.", "distrofia Mitótica.", "sindrome de Klinefelter, em que 90% desses homens têm cariótipo 47XXY."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: sindrome de Klinefelter, em que 90% desses homens têm cariótipo 47XXY..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Urologia','A pesquisa de microdeleções do cromossono Y deve ser realizada em qual situação clínica?','','','["Todos os homens com alterações na motilidade.", "Todos os homens com história de infertilidade conjugal.", "Todos os homens com oligoespermia severa.", "Todos os homens com alterações de forma e motilidade associadas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: Todos os homens com oligoespermia severa..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Urologia','Quanto à reposição hormonal para o tratamento da DAEM (Disfunção Androgênica do Envelhecimento Maculino), é correto afirmar:','','','["A administração oral apresentam maior risco de hepatotoxicidade.", "A administração IM profunda a cada 2-3 semanas previne a existência de picos supra-fisiológicos.", "A administração com patchs não está associada a complicações cutâneas.", "A reposição hormonal deve ser realizada mesmo em pacientes sem alterações bioquímicas confirmadas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: A administração oral apresentam maior risco de hepatotoxicidade..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Urologia','Selecione a alternativa correta quanto à relação entre hormônios e função sexual.','','','["A testosterona regula a secreção de gonadotrofina e a maturação sexual.", "A dehidrotestosterona regula o desenvolvi- mento muscular.", "A deficiência androgênica tem pouco impacto sobre a libido no adulto.", "A dehidrotestosterona regula a maturação sexual."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: A dehidrotestosterona regula a maturação sexual..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Urologia','São complicações comuns da administração de prostaglandina E1 como medicação intracavernosas, EXCETO','','','["priapismo.", "fibrose corpos cavernoso.", "dor no local da injeção.", "elevação de enzimas hepáticas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: elevação de enzimas hepáticas.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Urologia','Paciente de 21 anos é vítima de um acidente automobilístico. É atendido com quadro de hipotensão, inicialmente estabilizado com reposição volêmica apenas. Ao exame físico, notamos a presença de hematoma em região lombar à esquerda, ausência de sinais de irritação peritoneal e, após o cateterismo vesical, notamos hematúria macroscópica. Paciente é submetido a uma tomografia abdominal que nota uma lesão renal esquerda isolada Grau IV. Com base no cenário clínico apresentado acima, marque a alternativa correta.','','','["A exploração cirúrgica deve ser obrigatoriamente indicada pela gravidade da lesão e presença de hipotensão na admissão hospitalar.", "A intensidade da hematúria tem relação direta com a gravidade da lesão.", "A presença de extravazamento de contraste na tomografia é uma indicação relativa de exploração cirúrgica.", "A lesão Grau IV é caracterizada pela presença de lesão parenquimatosa que atinge o sistema coletor ou lesão completa do pedículo renal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: A presença de extravazamento de contraste na tomografia é uma indicação relativa de exploração cirúrgica..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Urologia','Assinale a alternativa correta quanto aos métodos diagnóstico na avaliação do trauma renal.','','','["A ultrassonografia é um método adequado na avaliação inicial do trauma renal, principalmente no estadiamento de lesões maiores.", "A urografia excretora permite a adequada avaliação das lesões renais, apresentando vantagens em pacientes hemodinâmica- mente instáveis.", "Mesmo com o crescimento na utilização da tomografia computadorizada, a arteriografia renal ainda é um método obrigatório para a avaliação de lesões vasculares renais.", "A tomografia computadorizada permite além da avaliação de lesões do parênquima e pedículo renal a avaliação de lesões intra- -abdominais associadas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: A tomografia computadorizada permite além da avaliação de lesões do parênquima e pedículo renal a avaliação de lesões intra- -abdominais associadas..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Urologia','Na suspeita de uma lesão ureteral por projétil de arma de fogo, é correto afirmar que','','','["a porção distal do ureter é a mais comumente afetada.", "a tomografia abdominal com contraste ou a urografia excretora são os métodos mais adequados para o diagnóstico e dificilmente levam a resultados falso- negativos.", "o diagnóstico é comumente realizado no transoperatório da laparotomia exploradora, devendo o cirurgião estar atendo, principal-mente em lesões com trajeto retroperitoneal.", "a hematúria macroscópica está presente na quase totalidade dos casos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa C. Resposta indicada no gabarito: o diagnóstico é comumente realizado no transoperatório da laparotomia exploradora, devendo o cirurgião estar atendo, principal-mente em lesões com trajeto retroperitoneal..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Urologia','Paciente é admitido no pronto-socorro, vítima de um acidente automobilístico, com diagnóstico de fratura pélvica e não notamos, ao exame físico, a presença de uretrorragia. Sobre esse caso, assinale a alternativa INCORRETA.','','','["A realização de uma uretrografia retrógrada é obrigatória em virtude da possibilidade da presença de uma lesão  uretral que pode ser agravada pelo cateterismo.", "Podemos realizar uma tentativa de cateterismo uretral cuidadosa e, na presença de dificuldade, realizar uma uretrografia.", "A ausência de uretrorragia não exclui a possibilidade de lesão uretral associada.", "Na presença de hematúria após o cateterismo vesical, devemos realizar uma cistografia."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: A realização de uma uretrografia retrógrada é obrigatória em virtude da possibilidade da presença de uma lesão  uretral que pode ser agravada pelo cateterismo.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Urologia','Paciente de 22 anos é vítima de uma escrotal durante a atividade esportiva; ao exame físico, notamos aumento do volume escrotal unilateral com testículo não palpável. Sobre esse caso, é correto afirmar:','','','["A Ressonância nuclear magnética é o exame de escolha neste caso.", "Na suspeita de uma ruptura testicular, a exploração cirúrgica deve ser realizada.", "O tratamento conservador deve sempre ser tentado.", "Pelas características da inervação testicular, os traumatismos não são acompanhados de dor."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa B. Resposta indicada no gabarito: Na suspeita de uma ruptura testicular, a exploração cirúrgica deve ser realizada..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Urologia','Assinale a alternativa correta quanto às opções de tratamento no trauma de uretra posterior.','','','["O tratamento primário da lesões apresenta as melhores taxas de preservação da potência e da incontinência.", "A realização de uma cistostomia apenas está associada à taxa de estenose tardia de 50%, e essa taxa não é reduzida pela realização de realinhamento primário.", "A reconstrução uretral tardia deve ser realizada cerca de 1 mês após o trauma.", "A impotência está mais relacionada ao trauma do que ao procedimento de reconstrução uretral."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: A impotência está mais relacionada ao trauma do que ao procedimento de reconstrução uretral..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Urologia','Sobre a interpretação dos valores do pH apresentados no exame de urina, é INCORRETO afirmar:','','','["Pacientes com infecção por Proteus sp tende a ter pH inferior a 7.", "Pacientes com cálculos por ácido úrico raramente têm pH acima de 6.5.", "A urina coletada logo após uma refeição ou que é deixada à temperatura ambiente por algumas horas tende a ser alcalina.", "Pacientes com cálculos de cálcio ou nefrocalcinose podem apresentar acidose tubular renal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa A. Resposta indicada no gabarito: Pacientes com infecção por Proteus sp tende a ter pH inferior a 7..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Urologia','A ultrassonografia é um método de diagnóstico comumente utilizado na prática urológica. Avalie as questões abaixo e marque a alternativa correta.','','','["A ultrassonografia não é um método efetivo na caracterização de cistos renais benignos.", "Massas renais ecogênicas são, em geral, bem definidas ao ultrassom e não há a necessidade da utilização de uma nova modalidade de imagem para a sua confirmação.", "A ultrassonografia com color Doppler é um método de pouco utilização na avaliação de complicações pós-transplante renal.", "Doença renal parenquimatosa crônica está associada à presença de diminuição do volume e aumento da ecogenicidade renal ao exame ultrassonográfico."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: Doença renal parenquimatosa crônica está associada à presença de diminuição do volume e aumento da ecogenicidade renal ao exame ultrassonográfico..' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Urologia','Assinale a alternativa INCORRETA quanto aos efeitos adversos da administração intravenosa de contrastes em exames urológicos.','','','["A incidência total de complicações é de 5%, sendo essas, na maioria das vezes, menores como náuseas, vômitos e rash cutâneo.", "Não há métodos de pré-teste que possam afastar a possibilidade de reações adversas.", "A fisiopatologia da nefrotoxicidade, associada ao uso de contrastes, inclui isquemia medular e lesão tubular direta.", "Agentes não iônicos apresentam alta osmolaridade quando comparadas a agentes iônicos e podem estar associadas a menor risco de complicações."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Resposta indicada no gabarito: Agentes não iônicos apresentam alta osmolaridade quando comparadas a agentes iônicos e podem estar associadas a menor risco de complicações.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Urologia','Leia o enunciado e as alternativas da questão 50 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-urologia-q50-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Urologia: alternativa D. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-urologia' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-dermatologia','PMERJ 2010 — Oficial — Médico Dermatologia','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Dermatologia','Em relação à embriologia da pele, é correto afirmar que','','','["os nervos são amielínicos inicialmente, possuindo diversas origens como crista neural (células de Schwann), medula e gânglios posteriores (axônios).", "os pelos, as unhas e os melanócitos derivam do mesoderma, enquanto a derme e a hipoderme derivam do ectoderma.", "apenas os nervos derivam do neuroectoderma.", "a pele do feto humano é rica em colágeno tipo I, enquanto a pele do adulto é rica em colágeno tipo III."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa A. Resposta indicada no gabarito: os nervos são amielínicos inicialmente, possuindo diversas origens como crista neural (células de Schwann), medula e gânglios posteriores (axônios)..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Dermatologia','Corpúsculos nervosos são estruturas sensoriais organizadas. Leia as afirmativas abaixo e, em seguida, assinale a opção correta. 1. As sensações de calor são percebidas através dos corpúsculos de Vater Paccini. 2. As sensações de frio são percebidas através dos corpúsculos de Ruffini. 3. As sensações táteis são percebidas através dos corpúsculos de Krause.','','','["F, V, V.", "V, F, F.", "F, F, F.", "F, V, F."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: F, F, F..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Dermatologia','Leia o enunciado e as alternativas da questão 3 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-dermatologia-q03-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Dermatologia','Em relação aos tumores ungueais, marque a alternativa correta.','','','["O tumor de Koenen desenvolve-se em 50% dos casos de pacientes que possuem doença de Pringle-Bourneville sofrendo maligniza-ção na terceira década.", "Tumor glômico apresenta a tríade: dor paroxística noturna, sensibilidade local e hipersensibilidade ao calor intenso.", "O carcinoma espinocelular subungueal é uma entidade frequentemente subdiagnos- ticada porque se confunde com outras doenças ungueais; pode ser confundido com onicomicose e verruga periungueal.", "A dermatoscopia, quando feita por profissionais treinados, faz o diagnóstico de melanoma do aparelho ungueal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: O carcinoma espinocelular subungueal é uma entidade frequentemente subdiagnos- ticada porque se confunde com outras doenças ungueais; pode ser confundido com onicomicose e verruga periungueal..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Dermatologia','Sobre as neoplasias malignas da mucosa oral, assinale a afirmativa INCORRETA.','','','["O carcinoma de células escamosas corresponde a cerca de 30% das neoplasias malignas da boca.", "O câncer dos lábios envolve mais a região exposta do lábio inferior do que a região exposta do lábio superior.", "A radioterapia do carcinoma verrucoso promove a aceleração do seu crescimento.", "Na papilomatose oral florida, o uso de acitretina é indicado para reduzir o volume da lesão."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa A. Resposta indicada no gabarito: O carcinoma de células escamosas corresponde a cerca de 30% das neoplasias malignas da boca.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Dermatologia','Sobre a síndrome de Netherton, marque a afirmativa correta.','','','["Está associada à atopia, alteração óssea e alteração dos pelos.", "Ocorrem pústulas foliculares e alteração dos pelos vistas como trichorrexis invaginata.", "É autossômica dominante.", "A ictiose linear cincunflexa faz parte da síndrome."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa D. Resposta indicada no gabarito: A ictiose linear cincunflexa faz parte da síndrome..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Dermatologia','Sobre os diferentes tipos de lentigo, assinale a afirmativa correta.','','','["O lentigo simples está relacionado com a exposição crônica ao sol, estando o seu número aumentado em áreas fotoexpostas.", "O potencial maligno dos lentigos simples obriga ao acompanhamento dos seus portadores.", "Os lentigos surgidos em pacientes submetidos a fotoquimioterapia (PUVA) não são dose dependente e estão relacionados ao surgimento de melanoma.", "No lentigo simples ocorre um aumento do número de melanócitos na junção dermo- epidérmica, sem evidente proliferação de melanócitos em direção à derme."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa D. Resposta indicada no gabarito: No lentigo simples ocorre um aumento do número de melanócitos na junção dermo- epidérmica, sem evidente proliferação de melanócitos em direção à derme..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Dermatologia','Sobre a púrpura pigmentar progressiva, marque a alternativa correta.','','','["A pigmentação nesta entidade é devido à presença de hemossiderina, seguida de intensa alteração da epiderme.", "As lesões ocorrem frequentemente nos membros inferiores sendo mais comuns em homens de qualquer idade.", "A dermatose púrpurica pigmentar progressiva tem em comum com a púrpura eczematide-símile o intenso e persistente prurido.", "A progressão da doença leva à ulceração e dor pela presença de trombose nos pequenos vasos."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: As lesões ocorrem frequentemente nos membros inferiores sendo mais comuns em homens de qualquer idade..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Dermatologia','Em relação às buloses, assinale a alternativa correta.','','','["O pênfigo paraneoplásico possui como características: estomatite dolorosa, erupção cutânea polimórfica e imunofluorescência indireta negativa.", "A doença de Sneddon Wilkinson ou dermatose pustular subcórnea é uma dermatose neutrofílica onde ocorre o depósito de IgA na junção dermoepidérmica.", "No penfigoide bolhoso, as bolhas são subpidérmicas. Acomete pele e mucosa do adulto jovem, podendo haver associação com líquen plano.", "O penfigoide gestacional pode surgir no segundo ou terceiro trimestre de gravidez e apresenta depósito de C3 na junção dermoepidérmica."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa D. Resposta indicada no gabarito: O penfigoide gestacional pode surgir no segundo ou terceiro trimestre de gravidez e apresenta depósito de C3 na junção dermoepidérmica..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Dermatologia','Assinale a alternativa correta em relação às fases do eczema atópico. I. Fase infantil - possui curso flutuante que varia devido a fatores como dentição, infecções respiratórias, alterações emocionais e climáticas. II. Fase pré-puberal – a presença de vesiculação aguda generalizada ou localizada sugere a possibilidade de infecção secundária viral ou bacteriana. III. Fase adulta - a distribuição na face, braços e dorso superior pode correlacionar-se com áreas de sudorese ou sensibilidade à Malassezia.','','','["I, II.", "I, II, III.", "II, III.", "I, III."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: I, II, III..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Dermatologia','Marque a alternativa correta em relação às paniculites.','','','["Histopatologicamente o eritema nodoso é uma paniculite septal com vasculite ocorrendo nos vasos lobulares da hipoderme.", "A paniculite por deficiência de alfa 1 antiripsina pode ser causada por traumatismo, ocorrendo principalmente em idosos, após a sétima década.", "Necrose da gordura subcutânea afeta 2-3% de todos os pacientes com doenças do pâncreas, onde apenas uma das três enzimas pancreáticas (amilase) é necessária para induzir esta necrose.", "paniculite lúpica está associada à lesão de lúpus cutâneo crônico em aproximadamente 20% dos casos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa D. Resposta indicada no gabarito: paniculite lúpica está associada à lesão de lúpus cutâneo crônico em aproximadamente 20% dos casos..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Dermatologia','Correlacione as colunas e marque a opção correta em relação a vasculites. 1. Púrpura de Henoch-Schönlein 2. Granulomatose de Wegener 3. Síndrome de Churg-Strauss 4. Poliangeite microscópica ( ) 50% P-ANCA anti-mieloperoxidase positi- vo e 30% com C-ANCA PR3 positivo ( ) Asma, eosinofilia e granuloma extravascular  ( ) C-ANCA 80% ( ) Complexo imune com IgA','','','["4, 3, 2, 1.", "2, 3, 4, 1.", "1, 3, 2, 4.", "4, 3, 1, 2 ."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa A. Resposta indicada no gabarito: 4, 3, 2, 1..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Dermatologia','Considere as alternativas abaixo sobre a Atrofodermia de Pasini e Pierini. 1. O dorso está quase sempre envolvido, o tórax e abdômen frequentemente, e as regiões proximais dos membros ocasionalmente. 2. As placas estendem-se muito rapidamente em poucos meses, em seguida persistem inalteradas. 3. Na atrofodermia, histologicamente, a esclerose pode ser intensa. 4. Testes sorológicos para Borrelia burgdorferi são negativos. Está correto o que se afirma em','','','["F, F, F, F.", "V, F, F, V.", "V, V, F, V.", "F, F, V, V."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: V, F, F, V..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Dermatologia','Relacione a primeira coluna com a segunda e marque a opção cuja sequência está correta. 1. Micose cutânea e superficial 2. Micose subcutânea 3. Micose sistêmica ( ) Micetoma ( ) Pitiríase versicolor ( ) Criptococose ( ) Esporotricose ( ) Pedra branca ( ) Rinosporidose ( ) Histoplasmose ( ) Infecção por Scytalidium ( ) Blastomicose','','','["2, 1, 2, 2, 1, 3, 1, 3, 3.", "2, 1, 3, 2, 1, 2, 3, 1, 3.", "3, 1, 2, 1, 1, 2, 3, 2, 3.", "1, 1, 3, 2, 1, 3, 2, 2, 3."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: 2, 1, 3, 2, 1, 2, 3, 1, 3..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Dermatologia','Tinea capitis é infecção da haste do pelo por fungo dermatófito, predominante em criança, podendo ocasionalmente ocorrer no adulto. Sobre os tipos distintos de invasão, é correto afirmar que','','','["a invasão pelo Microsporum é do tipo endothrix e ectothrix.", "a invasão pelo Trichophyton é do tipo ectothrix e do tipo favus.", "a invasão pelo Microsporum é do tipo endothrix apenas.", "a invasão pelo Trichophyton é do tipo endothrix, ectothrix e do tipo favus."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa D. Resposta indicada no gabarito: a invasão pelo Trichophyton é do tipo endothrix, ectothrix e do tipo favus..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Dermatologia','Paciente masculino, 38 anos, pescador, domiciliado no estado do Pará, apresenta no membro inferior esquerdo lesão queloideana, de 10 cm, bem delimitada e bem localizada há 5 anos, sem interferência no estado geral. Foi realizada biópsia e o material enviado para cultura onde não foi isolado fungo. Ao exame histopatológico, observou-se presença de inúmeras células fúngicas arredondadas, com espessa parede celular, em forma de limão. Qual o diagnóstico mais provável?','','','["Cromoblastomicose.", "Blastomicose.", "Lobomicose.", "Zigomicose."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: Lobomicose..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Dermatologia','Paciente do sexo feminino, 37 anos, profissional do sexo, referindo proteção adequada, apresenta queixa de corrimento vaginal. Qual a medida a ser tomada?','','','["Realizar coleta de material para microscopia, descartar candidíase, tratar vaginose, aconselhar, oferecer sorologia para HIV, VDRL, hepatite B e C, notificar.", "Tratar gonorréia e clamídia, aconselhar, oferecer sorologia para HIV, VDRL, hepatite B e C, notificar.", "Realizar coleta de material para microscopia, descartar candidíase e vaginose, tratar tricomoníase, aconselhar, oferecer sorologia para HIV, VDRL, hepatite B e C, notificar.", "Tratar clamídia, aconselhar, oferecer sorologia para HIV, VDRL, hepatite B e C, notificar."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: Tratar gonorréia e clamídia, aconselhar, oferecer sorologia para HIV, VDRL, hepatite B e C, notificar..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Dermatologia','Assinale a alternativa INCORRETA no que diz respeito à correlação da sífilis com o HIV.','','','["As lesões genitais ulceradas aumentam o risco de contrair e transmitir o vírus.", "Já no início da infecção adquirida pelo HIV, a clínica se apresenta de forma incomum, não usual.", "A maioria dos testes sorológicos nos pacientes com infecção adquirida pelo HIV, está dentro dos padrões encontrados nos pacientes não infectados.", "São frequentes nos pacientes HIV positivos o acometimento ocular e oral e a alteração neurológica precoce."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: Já no início da infecção adquirida pelo HIV, a clínica se apresenta de forma incomum, não usual.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Dermatologia','Relacione a primeira coluna com a segunda no que se refere às várias formas de acne ocupacional. Em seguida, marque a opção correta quanto a essa relação. 1. Cloracne 2. Acne tropical 3. Foliculite por óleo A. Lesões císticas e nódulos no dorso e região glútea B. Pápulas e pústulas nos braços e coxas C. Comedões e lesões císticas na região malar e mandibular','','','["1-C, 2-A, 3-B.", "1-B, 2-A, 3-C.", "1-A, 2-B, 3-C.", "1-A, 2-C, 3-B."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa A. Resposta indicada no gabarito: 1-C, 2-A, 3-B..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Dermatologia','Em relação à situação epidemiológica da leishmaniose no Brasil, assinale a opção correta.','','','["A leishmaniose tegumentar americana ocorre em ambos os sexos e todas as faixas etárias; entretanto, na média do país, predominam nos maiores de 5 anos, representando 90% dos casos e o sexo feminino, 74%.", "Em 2004, o maior coeficiente de detecção foi localizado no Estado do Acre, 41/100.000 habitantes, destacando-se os estados de Minas Gerais e Espírito Santo com o menor coeficiente de detecção, 0,03/100.000 habitantes.", "A leishmaniose tegumentar constitui um problema de saúde pública em 88 países, distribuídos em quatro continentes (Américas, Europa, África e Ásia), com registro anual de 500 mil casos.", "No Brasil, a leishmaniose tegumentar americana não é mais considerada uma doença ocupacional, apresentando ampla distribuição com registro de casos em todas as regiões brasileiras."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: Em 2004, o maior coeficiente de detecção foi localizado no Estado do Acre, 41/100.000 habitantes, destacando-se os estados de Minas Gerais e Espírito Santo com o menor coeficiente de detecção, 0,03/100.000 habitantes..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Dermatologia','Em relação à forma cutânea da leishmaniose, considere a opção verdadeira.','','','["Forma cutânea localizada - representa o acometimento primário da pele. A lesão é geralmente do tipo úlcera sem evolução à cura espontânea, porém apresenta boa resposta ao tratamento.", "Forma cutânea disseminada - é uma expressão comum que pode ser observada em até 20% dos casos. O número de lesões pode alcançar as centenas, provavelmente por disseminação do parasito por via hemática ou via linfática, causando lesões distantes do local da picada. Em 2004, o maior coeficiente de detecção foi localizado no Estado do Acre, 41/100.000 habitantes, destacando-se os estados de Minas Gerais e Espírito Santo com o menor coeficiente de detecção, 0,03/100.000 habitantes.", "Forma recidiva cutis - caracteriza-se por evoluir com cicatrização espontânea ou medicamentosa da úlcera, com reativação localizada geralmente na borda da lesão. A resposta à terapêutica é pobre ou ausente.", "Forma cutânea difusa – é rara e grave, ocorre em pacientes com anergia e deficiência específica na resposta imune humoral a antígenos de leishmania. Inicia- se de maneira insidiosa, com lesão única e boa resposta ao tratamento."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: Forma recidiva cutis - caracteriza-se por evoluir com cicatrização espontânea ou medicamentosa da úlcera, com reativação localizada geralmente na borda da lesão. A resposta à terapêutica é pobre ou ausente..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Dermatologia','Considera-se que o paciente com hanseníase recebeu alta por cura após completar o esquema de tratamento PQT nos seguintes prazos:','','','["Esquema Paucibacilar (PB) - 12 doses mensais supervisionadas de rifampicina, em até 18 meses; mais a sulfona autoadministrada. Esquema Multibacilar (MB) - 18 doses mensais supervisionadas de rifampicina, em até 24 meses, mais a sulfona autoadministrada e a clofazimina autoadministrada e supervisionada.", "Esquema Paucibacilar (PB) - 6 doses mensais supervisionadas de rifampicina, em até 9 meses; mais a sulfona autoadministrada. Esquema Multibacilar (MB) - 12 doses mensais supervisionadas de rifampicina, em até 18 meses, mais a sulfona autoadministrada e a clofazimina autoadministrada e supervisionada.", "Esquema Paucibacilar (PB) - 6 doses mensais supervisionadas de rifampicina, em até 12 meses; mais a sulfona autoadministrada. Esquema Multibacilar (MB) - 12 doses mensais supervisionadas de rifampicina, em até 24 meses, mais a sulfona autoadministrada e a clofazimina autoadministrada e supervisionada.", "Esquema Paucibacilar (PB) - 3 doses mensais supervisionadas de rifampicina, em até 6 meses; mais a sulfona autoadministrada. Esquema Multibacilar (MB) - 6 doses mensais supervisionadas de rifampicina, em até 9 meses, mais a sulfona autoadministrada e a clofazimina autoadministrada e supervisionada."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: Esquema Paucibacilar (PB) - 6 doses mensais supervisionadas de rifampicina, em até 9 meses; mais a sulfona autoadministrada. Esquema Multibacilar (MB) - 12 doses mensais supervisionadas de rifampicina, em até 18 meses, mais a sulfona autoadministrada e a clofazimina autoadministrada e supervisionada..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Dermatologia','Marque a alternativa correta no que se refere à recidiva e reação na hanseníase.','','','["A reação reversa ocorre muito tempo após a quimioterapia, geralmente após o intervalo de um ano.", "A recidiva é de surgimento súbito e inesperado, a reação reversa surge lentamente.", "Na reação reversa, há má resposta aos corticosteróides sistêmicos, já na recidiva há uma resposta excelente.", "Na reação reversa, é comum ocorrer ulceração de algumas lesões, enquanto recidiva isso é raro."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa D. Resposta indicada no gabarito: Na reação reversa, é comum ocorrer ulceração de algumas lesões, enquanto recidiva isso é raro..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Dermatologia','Em relação às variantes da acne, correlacione as duas colunas. Em seguida, assinale a opção cuja sequência está correta. 1. Acne fulminans 2. Acne mecânica 3. Acne induzida por drogas 4. Acne neonatal 5. Acne infantil ( ) Pápulas nas bochechas e dorso nasal ( ) Associa-se a manifestações sistêmicas ( ) Alterações hormonais intrínsecas ( ) Abrupta, monomórfica (pápulas e pústulas) ( ) Predomínio de lesões tipo comedões','','','["4, 3, 5, 1, 2.", "5, 1, 4, 3, 2.", "5, 1, 2, 3, 4.", "4, 1, 5, 3, 2."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa D. Resposta indicada no gabarito: 4, 1, 5, 3, 2..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Dermatologia','Paciente negra, 35 anos, chega ao setor de internação da dermatologia com erupção cutânea do tipo eritrodermia, edema de membros inferiores, áreas de descolamento cutâneo nos braços. Clinicamente também apresentava linfadenopatia generalizada, febre, artralgia, acompanhando-se de alterações laboratoriais com eosinofilia periférica e leucocitose de 21.000/mm³. Refere há um mês episódio de convulsão e início de tratamento com carbamazepina prescrito por seu neurologista. Esse quadro é compatível com qual das erupções abaixo produzida por drogas?','','','["NET.", "Doença do soro.", "DRESS.", "Eritrodermia esfoliativa."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: DRESS..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Dermatologia','Em relação ao uso da cloroquina, marque corretamente quais as alterações que podem ser observadas.','','','["Fotossensibilidade, urticária, alteração na retina e discrasias sanguíneas.", "Urticária, síndrome do homem vermelho, vasculite e eritema nodoso.", "Urticária, fotoalergia, erupções liquenóides e eritema nodoso.", "Púrpura, vasculite, estomatite e alterações renais."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa A. Resposta indicada no gabarito: Fotossensibilidade, urticária, alteração na retina e discrasias sanguíneas..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Dermatologia','Paciente feminina, 54 anos, apresenta há dez meses lesão única, em placa, com bordas policíclicas e área de ulceração central, localizada na região frontal. Relata progressão periférica e o surgimento recente de linfoadenite regional. À diascopia da lesão cutânea, observam-se os chamados “nódulos de geleia de maçã”. Quanto à hipótese diagnóstica, há dois diagnós- ticos diferenciais e dois exames complementares significativos que são, respectivamente,','','','["hanseníase / sarcoidose, lupus discoide / baciloscopia, teste de Mitsuda.", "lúpus vulgar / hanseníase, sarcoidose / PPD, PCR.", "sarcoidose / sífilis terciária, hanseníase / teste de kvein, enzima conversora de angiotensina (ECA).", "sífilis terciária / hanseníase, lúpus vulgar / FTA ABS IgM, biópsia cutânea"]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: lúpus vulgar / hanseníase, sarcoidose / PPD, PCR..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Dermatologia','O bacilo Calmette-Guérin é uma cepa atenuada de M. bovis que é empregado na vacinação obrigatória contra a tuberculose em todo o planeta. Assinale a opção correta quanto a esse bacilo.','','','["Atua bloqueando a disseminação linfática primária da microbactéria.", "Pode ser usado em várias situações clínicas, inclusive no tratamento de câncer.", "A conversão tuberculínica surge após 18 semanas da vacinação.", "No local da injeção, após uma semana, surge pústula que evolui para ulceração; o quadro dermatológico acompanha-se de febre alta."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: Pode ser usado em várias situações clínicas, inclusive no tratamento de câncer..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Dermatologia','Em relação ao carbúnculo, marque a alternativa INCORRETA.','','','["É comum que esta infecção ocorra em pacientes diabéticos.", "Abscessos fazem parte do diagnóstico diferencial, também flutuam, porém não se relacionam com unidades pilossebáceas.", "Tem, como consequência, nodosidade com apenas um orifício de drenagem que elimina pus.", "O tratamento inclui a antibioticoterapia sistêmica contra S. aureus, além da intervenção cirúrgica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: Tem, como consequência, nodosidade com apenas um orifício de drenagem que elimina pus.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Dermatologia','Qual das alterações paraneoplásicas abaixo está mais comumente relacionada à neoplasia pancreática?','','','["Palma em tripa.", "Erythema Gyratum Repens.", "Tromboflebite migratória superficial.", "Pênfigo paraneoplásico."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: Tromboflebite migratória superficial..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Dermatologia','Anorexia nervosa é vista como fobia sobre o peso corporal. Consequências nutricionais são frequentes e muitas são as alterações dermatológicas. Assinale, em ordem de frequência, as alterações mais comumente vistas.','','','["Xerose cutânea, alterações dos cabelos, deformidades ungueais, queilite.", "Alterações dos cabelos, deformidades ungueais, queilite, xerose cutânea.", "Deformidades ungueais, alterações dos cabelos, queilite, xerose cutânea.", "Queilite, alterações dos cabelos, deformidades ungueais, xerose cutânea."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa A. Resposta indicada no gabarito: Xerose cutânea, alterações dos cabelos, deformidades ungueais, queilite..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Dermatologia','Mononucleose infecciosa é caracterizada por febre, dor de garganta com faringotonsilite exsudativa e linfadenopatia. Considere os itens abaixo: I. Um exantema maculopapuloso no tronco, região superior dos braços e face ocorre em cerca de 10% dos casos, geralmente entre o quarto e sexto dias. II. Em mais de 90% dos casos uma erupção mobiliforme maculopapular extensa ocorre se a ampicilina é tomada durante o curso da doença. III. Púrpura trombocitopênica é comum, mas plaquetas abaixo 1000/mm ³ são raras. Está(ão) cooreto(s):','','','["I.", "I, II.", "I, II, III.", "I, III."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: I, II, III..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Dermatologia','Segundo os itens abaixo, relacione a malignidade cutânea com a mais provável infecção pelo HPV e, em seguida, assinale a opção correta. 1. Carcinoma das cavidades nasais 2. Adenocarcinoma do cérvix 3. Ceratoacantoma ( ) HPV 11 ( ) HPV 25 ( ) HPV 18','','','["3, 2, 1.", "1, 3, 2.", "2, 1, 3.", "2, 3, 1."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: 1, 3, 2..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Dermatologia','Em relação aos distúrbios glandulares cutâneos, assinale a alternativa INCORRETA.','','','["Em pacientes recebendo quimioterapia autiroaplásica, a excreção de componentes tóxicos no suor écrino é sugerida como tendo um papel estabelecido na produção de hidradenite neutrofílica écrina.", "Miliária é desencadeada pela alta temperatura e sudorese excessiva, sem haver qualquer interferência das bactérias residentes.", "O suor apócrino, uma vez secretado, é estéril e inodoro. A decomposição bacteriana na superfície da pele modifica as substâncias secretadas produzindo odor chamado bromidrose.", "Cromidrose apócrina extrínseca ou pseudo- extrínseca resulta de coloração do suor por bactéria, especialmente Corynebacterium spp."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: Miliária é desencadeada pela alta temperatura e sudorese excessiva, sem haver qualquer interferência das bactérias residentes.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Dermatologia','Em relação à glândula sebácea, assinale a opção cuja afirmativa está correta.','','','["Folículos sebáceos são ricos em microorganismos incluindo Malassezia spp., Staphylococcus epidermidis, Staphylo-coccus aureus e Propionibacterium spp.", "Ceratinização anormal é o primeiro sinal detectável da acne. O aumento da proliferação e retenção de corneócitos no infundíbulo resulta no microcomedão; sendo assim, o fluxo do sebo é totalmente bloqueado.", "No aparelho infundibular ocorre o favorecimento do crescimento dos seguintes microorganismos: P. acnes e S. epidermidis.", "O sebo nas glândulas sebáceas e dentro dos ductos não é estéril e possui grandes quantidades de ácidos graxos livres, favorecendo, assim, o crescimento de microorganismos nestas regiões."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: No aparelho infundibular ocorre o favorecimento do crescimento dos seguintes microorganismos: P. acnes e S. epidermidis..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Dermatologia','De 20 a 35% dos pacientes com sarcoidose sistêmica possuem lesões na pele, entretanto a sarcoidose cutânea pode surgir sem necessariamente haver comprometimento sistêmico. Assinale a alternativa correta.','','','["A extensão de qualquer lesão cutânea se correlaciona diretamente com a extensão da doença sistêmica.", "A sarcoidose subcutânea é rara, são nódulos persistentes macios ou dolorosos, sem envolvimento sistêmico, ocorrendo principalmente nas extremidades de pacientes jovens.", "O envolvimento ungueal e da mucosa na sarcoidose não possuem associação com o lúpus pérnio.", "Nível sérico elevado da enzima conversora de angiotensina (ECA) não possui valor como auxílio no diagnóstico de sarcoidose; ele é útil para monitorar a atividade da doença."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa D. Resposta indicada no gabarito: Nível sérico elevado da enzima conversora de angiotensina (ECA) não possui valor como auxílio no diagnóstico de sarcoidose; ele é útil para monitorar a atividade da doença..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Dermatologia','Em relação à histopatologia do granuloma anular, assinale a opção cuja sequência V (verdadeira) e F (falsa) está respectivamente correlacionada às três alternativas feitas. 1. Sua maior característica histológica é o granuloma necrobiótico, havendo um único padrão histológico: granuloma necrobiótico “em paliçada”.  2. Os granulomas necrobióticos são caracterizadas por focos de necrobiose rodeados por histiócitos, linfócitos e células gigantes multinucleadas na zona periférica. 3. Os granulomas situam-se na derme superficial e média, as alterações epidérmicas são mínimas exceto na forma perfurante do granuloma anular.','','','["V, F, F.", "F, V, V.", "V, V, F.", "F, F, V."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: F, V, V.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Dermatologia','Em relação à psoríase, correlacione as colunas e, em seguida, marque a sequência correta. 1. Características fundamentais da lesão de psoríase vulgar na pele 2. Psoríase ungueal 3. Psoríase eritrodérmica instável 4. Psoríase guttata 5. Psoríase nas crianças ( ) Acomete preferencialmente crianças e adultos jovens após infecções estreptococicas agudas. ( ) Pode ser desencadeada por infecções e antimaláricos, estar associada à psoríase artropática e apresentar prurido intenso. ( ) Acomete frequentemente a face, couro cabeludo e estar associada à psoríase interdigital. ( ) Hiperproliferação epidérmica, dilatação e proliferação dos vasos sanguíneos dérmicos e acúmulo de células inflamatórias. ( ) Associação com artropatia psoriática e espécies de Candida são frequentemente vistas como contaminante.','','','["5, 3, 4, 1, 2.", "4, 2, 5, 1, 3.", "4, 3, 5, 1, 2.", "5, 4, 2, 1, 3."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: 4, 3, 5, 1, 2..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Dermatologia','A síndrome de Reiter é caracterizada pela tríade: uretrite inespecífica, artrite e conjuntivite. Em relação ao seu acometimento articular, assinale a opção correta.','','','["É poliarticular, simétrica e de pequenas articulações.", "É monoarticular, atinge grandes articulações e não é supurativa.", "Não é supurativa, atinge grandes articulações podendo ocorrer sacroileíte.", "É poliarticular, assimétrica e supurativa."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: Não é supurativa, atinge grandes articulações podendo ocorrer sacroileíte..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Dermatologia','Sobre o acometimento cutâneo nas amiloidoses, é correto afirmar que','','','["lesões cutâneas ocorrem em 60 a 80% dos casos sistêmicos primários.", "macroglossia é sugestiva de amiloidose e ocorre em 20% dos casos.", "equimoses e petéquias nas regiões de mucosas são as manifestações mucocutâneas mais frequentes da amiloidose.", "na amiloidose sistêmica secundária frequentemente ocorrem lesões cutâneas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: macroglossia é sugestiva de amiloidose e ocorre em 20% dos casos..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Dermatologia','Uma variedade de erupções dermatológicas pode ocorrer tanto com a colite ulcerativa quanto com a doença de Crohn. Nesse contexto, assinale a alternativa correta.','','','["Eritema nodoso, dermatoses neutrofílicas, ulcerações aftosas.", "Eritema multiforme, ulcerações aftosas, piodermites.", "Angioedema, calcinose cutânea, cútis laxa.", "Dermatoses neutrofílicas, eritema multi- forme, calcinose cutânea."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa A. Resposta indicada no gabarito: Eritema nodoso, dermatoses neutrofílicas, ulcerações aftosas..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Dermatologia','A arquitetura do infiltrado inflamatório nas diver-sas doenças liquenoides tem características diferentes. Assinale a alternativa correta.','','','["Líquen plano - infiltrado polimorfonuclear em faixa (liquenóide) na derme superficial.", "Líquen nítido - infiltrado mononuclear em faixa (liquenóide) na derme superficial.", "Líquen espinuloso - infiltrado inflamatório circunscrito na derme papilar onde a epiderme adjacente parece envolver esse infiltrado.", "Líquen nítido - infiltrado inflamatório cir- cunscrito na derme papilar onde a epiderme adjacente parece envolver esse infiltrado."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa D. Resposta indicada no gabarito: Líquen nítido - infiltrado inflamatório cir- cunscrito na derme papilar onde a epiderme adjacente parece envolver esse infiltrado..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Dermatologia','A Epidemólise Bolhosa (EB) Simplex das mãos e pés (Weber-Cockayne) é o tipo mais comum. Assinale qual alternativa NÃO corresponde a essa patologia.','','','["A condição piora com a temperatura elevada.", "As bolhas se curam sem cicatrizes significativas.", "É comum haver bolhas em outros sítios como cintura, pescoço e ombros.", "É comum haver calos plantares."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: É comum haver bolhas em outros sítios como cintura, pescoço e ombros.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Dermatologia','A esclerodermia pode ser classificada clinicamente como esclerodermia localizada e esclerose sistêmica; seu diagnóstico é feito pela apresentação clínica e exames complementares. Em relação a isso, marque a alternativa correta:','','','["Anticorpo Anti Scl 70 é muito específico para doença pulmonar intersticial e vasculites, comuns na esclerose sistêmica.", "Anticorpo anticentrômero é indicador de doença limitada à pele.", "Anticorpo anti DNA Topoisomerase I torna-se positivo em manifestações tardias da esclerose sistêmica e demonstra um prognóstico reservado.", "A morfeia generalizada em placas é uma forma de esclerose sistêmica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: Anticorpo anti DNA Topoisomerase I torna-se positivo em manifestações tardias da esclerose sistêmica e demonstra um prognóstico reservado..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Dermatologia','Para uma lesão pigmentada ser considerada melanocítica pela dermatoscopia, deve apresentar um dos seguintes critérios dermatoscópicos. Assinale-o.','','','["Estruturas em folha.", "Lagos vermelho-enegrecidos.", "Glóbulos agregados.", "Pseudocistos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: Glóbulos agregados..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Dermatologia','Paciente com laudo histológico de melanoma, espessura de um milímetro. Marque a alternativa correta em relação a esse quadro clínico.','','','["Não necessita ser submetidos a biópsia do linfonodo sentinela.", "Deve haver biópsia do linfonodo sentinela e cortes sequenciais com imuno- histoquímica, se positivo, retirar todo o linfonodo acometido.", "Recentemente está sendo usada a técnica de reação de transcriptase reversa associada à reação em cadeia da polimerase, RT-PCR, para detecção de micrometástases no linfonodo sentinela, com maior sensibilidade em relação a imuno- -histoquímicas e histopatologia.", "O linfonodo sentinela é a principal ferramenta de estagiamento do melanoma, sua detecção e o esvaziamento ganglionar estão associados a aumento da sobrevida desses pacientes."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa C. Resposta indicada no gabarito: Recentemente está sendo usada a técnica de reação de transcriptase reversa associada à reação em cadeia da polimerase, RT-PCR, para detecção de micrometástases no linfonodo sentinela, com maior sensibilidade em relação a imuno- -histoquímicas e histopatologia..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Dermatologia','Drogas capazes de modificar respostas biológicas recebem o nome genérico de “biológicos”. Os agentes biológicos foram desenhados para agir segundo diferentes estratégias. Assinale qual das propostas estratégicas abaixo está INCORRETA.','','','["Bloqueio das citocinas inflamatórias, entre elas o TNF-α.", "Bloqueio das citocinas inflamatórias, entre elas o interferon.", "Depleção das células T e subconjuntos das células T.", "Desvio imune das células T e modificação do equilíbrio Th1/Th2."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: Bloqueio das citocinas inflamatórias, entre elas o interferon.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Dermatologia','O agente anestésico local ideal deverá ser: não tóxico, com pouca dor no momento da injeção, de início rápido, altamente efetivo e com baixo risco de sensibilização. Sobre anestesia local, assinale a opção correta.','','','["Dentre os anestésicos locais do tipo amido, está a procaína.", "Dentre os anestésicos locais do tipo amido, está a bupivacaína.", "Anestésicos locais do tipo éster são os mais usados nas cirurgias dermatológicas.", "A epinefrina adicionada a soluções anestésicas prolonga a duração da anestesia, porém não reduz o risco de toxicidade sistêmica da lidocaína."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa B. Resposta indicada no gabarito: Dentre os anestésicos locais do tipo amido, está a bupivacaína..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Dermatologia','Nitrogênio líquido é o agente crioterápico mais amplamente utilizado. É um método fácil de uso, barato e amplamente disponível. Em relação à crioterapia por nitrogênio líquido, é correto afirmar que','','','["a extensão da injúria é determinada apenas pelo tempo de congelamento.", "temperaturas teciduais alcançadas durante a crioterapia necessitam ser mensuradas  para avaliar a eficácia desta proposta terapêutica.", "repetidos ciclos de congelamento/desconge-lamento não produzem maior dano tecidual que congelamento simples.", "dano máximo é produzido por rápido congelamento e descongelamento lento."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa D. Resposta indicada no gabarito: dano máximo é produzido por rápido congelamento e descongelamento lento..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Dermatologia','A exposição aos raios ultravioleta (RUV) causa alguns efeitos na pele normal, que se dividem em efeitos precoces e efeitos tardios. Correlacione as colunas e, em seguida, marque a alternativa correta. 1. Efeitos precoces 2. Efeitos tardios ( ) Hiperplasia ( ) Fotocarcinogenese ( ) Bronzeamento imediato ( ) Foto-onicólise ( ) Pseudoporfiria ( ) Bronzeamento tardio','','','["1, 2, 1, 1, 2, 1.", "2, 2, 1, 1, 2, 2.", "2, 2, 1, 1, 2, 1.", "1, 1, 1, 1, 2, 1."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Dermatologia: alternativa A. Resposta indicada no gabarito: 1, 2, 1, 1, 2, 1..' from public.exams where slug='pmerj-2010-medico-dermatologia' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-endocrinologia','PMERJ 2010 — Oficial — Médico Endocrinologia','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Endocrinologia','Paciente do sexo feminino, 30 anos, foi ao endocrinologista com história de amenorreia há 18 meses. Já possui os seguintes resultados de exames: FSH = 88UI/L; LH = 41 UI/L; estradiol = 12 pg/mL; prolactina = 110 µg/L (VR até 23) e 105 µg/L (após precipitação do soro com polietileno glicol) e ressonância magnética de sela túrcica com um adenoma hipofisário medindo 06 mm de diâmetro. Frente a esse caso, podemos dizer que','','','["a paciente possui um adenoma hipofisário produtor de gonadotrofinas e que esse é a causa da sua amenorreia.", "a paciente está com amenorreia em virtude de uma falência ovariana primária.", "a amenorreia provém de um hipogonadismo secundário à hiperprolactinemia.", "a redução da prolactina sérica com agonistas dopaminérgicos muito provavelmente restaurará os ciclos menstruais da paciente."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endocrinologia: alternativa B. Resposta indicada no gabarito: a paciente está com amenorreia em virtude de uma falência ovariana primária..' from public.exams where slug='pmerj-2010-medico-endocrinologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Endocrinologia','Dentre as complicações associadas ao uso de bomba de infusão subcutânea de insulina, não inclui','','','["risco aumentado de cetoacidose.", "infecção no local de inserção do cateter.", "aumento da amplitude média das excursões glicêmicas, quando comparado à terapia intensiva por múltiplas picadas.", "aumento da frequência de hipoglicemias graves, quando comparado à terapia intensiva por múltiplas picadas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endocrinologia: alternativa C. Resposta indicada no gabarito: aumento da amplitude média das excursões glicêmicas, quando comparado à terapia intensiva por múltiplas picadas..' from public.exams where slug='pmerj-2010-medico-endocrinologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Endocrinologia','Em relação às insulinas de ação ultra rápida, marque a alternativa INCORRETA.','','','["A afinidade da insulina lispro pelo receptor de insulina é semelhante ao da insulina regular.", "Pelo risco aumentado de carcinogênese em ratos, a insulina lispro não pode ser utilizada em gestantes.", "Em relação à insulina glulisina, existe uma fosforilação preferencial do IRS-1 em detrimento do IRS-2.", "Devido ao rápido início de ação dessas insulinas, elas podem ser aplicadas após as refeições."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endocrinologia: alternativa B. Resposta indicada no gabarito: Pelo risco aumentado de carcinogênese em ratos, a insulina lispro não pode ser utilizada em gestantes.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-endocrinologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Endocrinologia','Em relação a diabetes tipo MODY, marque a alternativa correta.','','','["A necessidade de insulinoterapia no MODY tipo 3 é superior a 60%.", "O defeito no MODY tipo 1 está no gene da Glucoquinase.", "As complicações microvasculares no MODY tipo 2 são raras.", "Normalmente a idade de diagnóstico do MODY tipo 2 ocorre por volta dos 20 anos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endocrinologia: alternativa C. Resposta indicada no gabarito: As complicações microvasculares no MODY tipo 2 são raras..' from public.exams where slug='pmerj-2010-medico-endocrinologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Endocrinologia','Dentre as drogas abaixo, marque aquela que não é causa de hiperprolactinemia.','','','["Metoclopramida.", "Estrogênio.", "Verapamil.", "Diltiazem."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endocrinologia: alternativa D. Resposta indicada no gabarito: Diltiazem.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-endocrinologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Endocrinologia','Em uma paciente com hiperparatireoidismo primário, é indicação de tratamento cirúrgico:','','','["nefrolitíase de repetição.", "osteopenia.", "calcificações subcutâneas.", "hipocalciúria."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endocrinologia: alternativa A. Resposta indicada no gabarito: nefrolitíase de repetição..' from public.exams where slug='pmerj-2010-medico-endocrinologia' on conflict(exam_id,number) do nothing;
