insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Odontologia Endodontia','Em geral, os instrumentos endodônticos são produzidos em ligas de aço inoxidável','','','["martensítico.", "austenítico.", "ferrítico.", "martensita / austenita."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: austenítico..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Odontologia Endodontia','A elasticidade de um material é quantificada pelo seu módulo de elasticidade. Em vista disso, pode-se afirmar que','','','["quanto maior o módulo de elasticidade, maior será a elasticidade do material.", "quanto menor o módulo de elasticidade, menor será a elasticidade do material.", "quanto menor o módulo de elasticidade, maior será a elasticidade do material.", "quanto menor o módulo de elasticidade, maior será a intensidade de atração entre os átomos do material."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: quanto menor o módulo de elasticidade, maior será a elasticidade do material..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Odontologia Endodontia','Num instrumento endodôntico, a passagem da base de ponta para a aresta de corte (hélice) da haste helicoidal pode formar um ângulo obtuso denominado ângulo de transição. A presença deste ângulo pode','','','["induzir a fratura por torção do instrumento.", "induzir a fratura por fadiga do instrumento.", "provocar defeitos na parede dentinária interna de um canal radicular curvo.", "provocar o arrombamento do forame apical."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: induzir a fratura por torção do instrumento..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Odontologia Endodontia','Para instrumentos endodônticos, o número de hélices presentes na haste helicoidal cônica será','','','["maior, quanto maior o diâmetro e maior o ângulo de inclinação das hélices.", "maior, quanto maior o diâmetro e menor o ângulo de inclinação das hélices.", "maior, quanto menor o diâmetro e menor o ângulo de inclinação das hélices.", "maior, quanto menor o diâmetro e maior o ângulo de inclinação das hélices."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: maior, quanto menor o diâmetro e maior o ângulo de inclinação das hélices..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Odontologia Endodontia','Segundo Cohen e Hargreaves, a constrição apical foi localizada coronalmente ao término do canal, a uma dstância de','','','["0,3 a 0,7 mm.", "0,5 a 0,9 mm.", "0,5 a 1,0 mm.", "0,5 a 0,7 mm."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: 0,5 a 0,7 mm..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Odontologia Endodontia','A capacidade de corte de um instrumento endodôntico, ao realizar o movimento de alargamento, depende','','','["do ângulo agudo de inclinação da hélice. Quanto menor, maior a eficiência de corte.", "do ângulo da aresta lateral de corte. Quanto maior, maior será a eficiência de corte.", "da dureza do instrumento e do material a ser cortado. Quanto maior a dureza do instrumento em relação à dentina, menor será a eficiência de corte.", "do vértice da aresta de corte. Vértice arredondado é mais eficiente do que vértice agudo."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: do ângulo agudo de inclinação da hélice. Quanto menor, maior a eficiência de corte..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Odontologia Endodontia','Na fratura de um instrumento endodôntico por torção, pode-se afirmar que','','','["o ângulo de torção máxima até a fratura representa a soma da sua rotação na região elástica e na região plástica.", "o ângulo de torção máxima até a fratura representa a sua rotação na região elástica.", "o ângulo de torção máxima até a fratura é quantificado em Newton.", "o ângulo de torção máxima até a fratura é quantificado em Newton. mm."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: o ângulo de torção máxima até a fratura representa a soma da sua rotação na região elástica e na região plástica..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Odontologia Endodontia','Na fratura por flexão rotativa (fadiga) de um instrumento endodôntico de NiTi, assinale a condição em que a vida útil do instrumento será maior.','','','["Quanto menor o raio de curvatura do canal e maior o diâmetro do instrumento empregado.", "Quanto menor o raio de curvatura do canal e menor o diâmetro do instrumento empregado.", "Quanto maior o raio de curvatura do canal e menor o diâmetro do instrumento empregado.", "Quanto maior o raio de curvatura do canal e maior o diâmetro do instrumento empregado."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: Quanto maior o raio de curvatura do canal e menor o diâmetro do instrumento empregado..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Odontologia Endodontia','Durante a instrumentação de um canal radicular curvo, podem-se detectar três áreas onde pode ocorrer desgaste acentuado das paredes dentinárias. São elas:','','','["área apical, parede côncava do canal; área média, parede convexa do canal; área cervical, parede côncava do canal.", "área apical, parede convexa do canal; área média, parede côncava do canal; área cervical, parede convexa do canal.", "área apical, parede côncava do canal; área média, parede côncava do canal; área cervical, parede côncava do canal.", "área apical, parede côncava do canal; área média, parede côncava do canal; área cervical, parede convexa do canal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: área apical, parede côncava do canal; área média, parede convexa do canal; área cervical, parede côncava do canal..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Odontologia Endodontia','Segundo o glossário da American Association of Endodontics, pode-se definir Zip como o(a)','','','["transporte apical interno que ocorre no preparo de canais radiculares curvos.", "transporte apical externo que ocorre no preparo de canais radiculares curvos.", "formação de um falso canal.", "arrombamento do forame apical."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: transporte apical externo que ocorre no preparo de canais radiculares curvos..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Odontologia Endodontia','No preparo apical de um canal radicular, NÃO deve ser empregado o movimento de','','','["alargamento.", "cateterismo.", "remoção.", "limagem."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: limagem..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Odontologia Endodontia','A remoção de um fragmento metálico de um instrumento fraturado no interior de um canal radicular curvo é provável de ocorrer','','','["quando a seção reta transversal do canal é circular.", "nos canais de menores raios de curvaturas.", "quando a seção reta transversal do canal é achatada.", "quando a fratura ocorrer por torção."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: quando a seção reta transversal do canal é achatada..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Odontologia Endodontia','A remoção de um fragmento metálico de broca Gates Glidden no interior de um canal não apresenta grande dificuldade','','','["porque o canal helicoidal da broca é raso.", "quando a fratura ocorre por torção.", "quando o ângulo de ataque do instrumento é positivo.", "porque o passo da hélice da lâmina ativa do instrumento é incompleto."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: porque o passo da hélice da lâmina ativa do instrumento é incompleto..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Odontologia Endodontia','Em relação à solução de Dakin, pode-se afirmar que ela é uma solução de','','','["hipoclorito de sódio a 0,4% neutralizada com ácido bórico.", "hipoclorito de sódio a 0,5%.", "hipoclorito de sódio a 0,5% neutralizada com cloreto de sódio.", "hipoclorito de sódio a 0,5% neutralizada com ácido bórico."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: hipoclorito de sódio a 0,5% neutralizada com ácido bórico..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Odontologia Endodontia','Estrela afirma que, nos hipocloritos de sódio não dissociados, encontramos','','','["maior concentração de hidróxido de sódio e menor de acido hipocloroso.", "menor concentração de hidróxido de sódio e maior de acido hipocloroso.", "maior concentração de íon clorato.", "maior concentração de íon hipoclorito e menor de hidróxido de sódio."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: maior concentração de hidróxido de sódio e menor de acido hipocloroso..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Odontologia Endodontia','Para Lopes e Siqueira, a ação desinfectante do hipoclorito de sódio torna-se pronunciada','','','["quando o pH da solução aumenta (pH básico).", "quando o pH da solução diminui (pH ácido).", "quando o pH da solução é neutro.", "quando o ácido hipocloroso é ionizado."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: quando o pH da solução diminui (pH ácido)..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Odontologia Endodontia','São componentes da solução MTAD:','','','["doxiciclina, ácido acético e um detergente neutro de superfície.", "clorociclina, ácido cítrico e um tensoativo.", "doxiciclina, ácido abiético e tartarato de sódio.", "doxiciclina, ácido cítrico e Tween 80."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: doxiciclina, ácido cítrico e Tween 80..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Odontologia Endodontia','Segundo Lopes e Siqueira, durante a irrigação / aspiração, a extremidade da cânula irrigadora deve ficar aquém do ápice, a uma distância de','','','["3 mm.", "2 mm.", "4 mm.", "1 mm."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: 3 mm..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Odontologia Endodontia','Nos dentes com rizogênese incompleta, quando a polpa vital é exposta acidentalmente, o procedimento de escolha deverá permitir','','','["apicificação.", "revascularização pulpar.", "apexificação.", "apecigênese."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: apecigênese..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Odontologia Endodontia','Nos dentes com rizogênese incompleta, as paredes vestíbulo-palatina, em relação às mesio- distais, apresentam-se','','','["mais curtas.", "mais longas.", "de iguais comprimentos.", "com forame circular."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: mais curtas..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Odontologia Endodontia','Os dentes com rizogênese incompleta oferecem pouca resistência à ação dos instrumentos endodônticos. Sendo assim, recomenda-se','','','["uma instrumentação com movimento de alargamento contínuo.", "uma instrumentação com movimento de limagem e alargamento.", "uma instrumentação com movimento de limagem circunferencial.", "uma instrumentação escalonada no sentido coroa-ápice."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: uma instrumentação com movimento de limagem circunferencial..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Odontologia Endodontia','Na reabsorção radicular interna, a polpa dentária está','','','["totalmente necrosada.", "com vitalidade e fibrosada.", "com o tecido pulpar coronário com vitalidade, junto ao tecido de granulação.", "com o tecido pulpar coronário necrosado, junto ao tecido de granulação."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: com o tecido pulpar coronário necrosado, junto ao tecido de granulação..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Odontologia Endodontia','O agregado de trióxido mineral (MTA), tem-se mostrado promissor como agente de capeamento pulpar. Antes de ele tomar presa, seu pH é','','','["baixo.", "alto.", "neutro.", "ácido."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: alto..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Odontologia Endodontia','Para reduzir ou mesmo evitar o extravasamento do cimento MTA para os tecidos perirradiculares durante o selamento de uma perfuração radicular, é utilizada uma barreira extrarradicular reabsorvível de','','','["sulfato de bário.", "carbonato de zinco.", "sulfato de cálcio.", "carbonato de cálcio."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: sulfato de cálcio..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Odontologia Endodontia','Para Cohen e Hargreaves, nos casos de apicificação, sendo o diâmetro apical maior que o diâmetro coronário, a técnica de obturação do canal radicular indicada é a de','','','["plastificação da guta-percha.", "compactação lateral da guta-percha.", "cone único.", "pressão hidráulica."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: plastificação da guta-percha..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Odontologia Endodontia','A smear layer apresenta em sua composição componentes orgânicos e inorgânicos. Consequente- mente, para a remoção dos componentes orgânicos, a solução química indicada é','','','["EDTA.", "hipoclorito de sódio.", "clorexidina.", "água ionizada."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: hipoclorito de sódio..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Odontologia Endodontia','É lícito afirmar que, quanto menor a tensão superficial de uma solução irrigante,','','','["maior será sua capacidade de umectação.", "menor será sua capilaridade.", "menor será sua capacidade de penetração em reentrâncias ou ramificações de um canal radicular.", "maior será a sua viscosidade."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: maior será sua capacidade de umectação..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Odontologia Endodontia','Para Lopes e Siqueira, a condição que deve ser observada para o instrumento que realizará o cateterismo de um canal atresiado é','','','["ser previamente pré-curvado.", "ser de maior resistência a flambagem.", "ser de níquel-titânio.", "ser do tipo Hedstroem."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: ser de maior resistência a flambagem..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Odontologia Endodontia','Para Estrela, a zona de menor diâmetro de um canal radicular encontra-se no','','','["segmento apical.", "segmento intermediário.", "início do segmento cervical.", "forame apical."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: início do segmento cervical..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Odontologia Endodontia','A solução de hipoclorito de sódio a 0,5% com bicarbonato de sódio é denominada','','','["Dakin.", "Labarraque.", "Milton.", "Dausfrene."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: Dausfrene..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Odontologia Endodontia','Na escolha da solução anestésica para o tratamento endodôntico, é importante observar:','','','["Entre os principais vasoconstritores utilizados em odontologia, a fenilefrina é o mais potente e um dos mais empregados.", "A adrenalina na concentração de 1.100.000 é atualmente o vasoconstritor mais indicado para uso em pacientes gestantes.", "A Mepivacaína é indicada em pacientes gestantes por possuir velocidade de metabolização no feto semelhante à lidocaína.", "A Prilocaína é o sal anestésico que apresenta maior percentual de ligação proteica"]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: A adrenalina na concentração de 1.100.000 é atualmente o vasoconstritor mais indicado para uso em pacientes gestantes..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Odontologia Endodontia','A polpa dentária é um tecido conjuntivo frouxo especializado, ricamente vascularizado e inervado. Em relação à histologia pulpar, é correto afirmar que','','','["as células ectomesenquimais localizadas na zona rica em células da polpa podem se diferenciar em odontoblastos.", "os odontoblastos são as células mais numerosas da polpa.", "as fibras elásticas se distribuem em grande quantidade no tecido pulpar.", "as fibras nervosas tipo A são amielinizadas e são responsáveis por estímulos de condução lenta."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: as células ectomesenquimais localizadas na zona rica em células da polpa podem se diferenciar em odontoblastos..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Odontologia Endodontia','Um dente com aumento na espessura do espaço do ligamento periodontal apical, com teste de vitalidade negativo, sensação de dente crescido, dor localizada e espontânea e com dor na percussão vertical apresenta a seguinte condição patológica:','','','["periodontite apical aguda.", "granuloma periapical.", "cisto radicular.", "pulpite irreversível."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: periodontite apical aguda..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Odontologia Endodontia','Sobre as alterações pulpares frente às agressões que causam injúria tecidual, pode-se afirmar que','','','["em um dente com necrose pulpar, o teste térmico ao frio não é confiável para determinar o diagnóstico.", "segundo Lopes e Siqueira, o tratamento de uma pulpite irreversível consiste na remoção do tecido pulpar, total ou parcial.", "a periodontite apical supurativa geralmente apresenta dor contínua e localizada.", "uma polpa dentária com leve alteração inflamatória, em fase inicial, submetida ao teste térmico pelo calor, pode responder com uma dor aguda e imediata, característica das fibras nervosas do tipo C."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: segundo Lopes e Siqueira, o tratamento de uma pulpite irreversível consiste na remoção do tecido pulpar, total ou parcial..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Odontologia Endodontia','A radiologia é uma especialidade em que a endodontia se relaciona direta e diariamente.  Em relação à Técnica Radiográfica de Clark aplicada sobre um primeiro pré-molar superior, é correto afirmar que','','','["em uma incidência mesiorradial, a raiz palatina aparece deslocada para mesial.", "em uma incidência mesiorradial, a raiz vestibular aparece deslocada para mesial.", "em uma incidência distorradial, a raiz palatina aparece deslocada para mesial.", "em uma incidência distorradial, a raiz vestibular aparece deslocada para distal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: em uma incidência mesiorradial, a raiz palatina aparece deslocada para mesial..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Odontologia Endodontia','Um paciente cardiopata necessita de alguns cuidados especiais, ao submeter-se a um tratamento endodôntico. Dentre eles, pode-se citar:','','','["Deve-se utilizar sempre um anestéscio sem vasoconstritor.", "Empregar vasoconstritor em concentração de 1:50.000.", "Adotar o período mínimo de 3 meses após o infarto do miocárdio ou acidente vascular cerebral para realizar o tratamento.", "Não empregar noradrenalina em pacientes que utilizam o propanolol."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: Não empregar noradrenalina em pacientes que utilizam o propanolol..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Odontologia Endodontia','Embora até o momento não tenha sido possível definir o papel de um micro-organismo específico das alterações perirradiculares, evidências sugerem um grupo de espécies bacterianas envolvidas nos diferentes tipos de infecção. Dentre as de maior percentual de incidência, podem-se citar:','','','["prevotella denticola, eubacterium nadatum e streptococcus.", "fusubacterium nucleatum, prevotella oralis e eubacterium nadatum.", "veillonela parvulla, bacteroides e actinomyces.", "fusobacterium nucleatum, streptococcus sp e bacteroides sp."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: fusobacterium nucleatum, streptococcus sp e bacteroides sp..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Odontologia Endodontia','Métodos moleculares têm permitido a identificação de micro-organismos jamais detectados em canais radiculares pelo método de cultura. Dentre eles podem-se citar:','','','["compylobacter e treponema dentícola.", "mitsuokella dentalis e tannerella forsythia.", "treponema vincentii e dialister pneumosintes.", "actinomyces e selenomonas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: treponema vincentii e dialister pneumosintes..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Odontologia Endodontia','O hidróxido de cálcio tem sido a substância química mais empregada como medicação intracanal durante o tratamento endodôntico. Acredita-se que seu representativo destaque expressa-se devido a importantes propriedades e características, dentre as quais se pode destacar:','','','["Quando associado ao veículo viscoso sua dissociação torna-se extremamente rápida.", "A colofônia confere à pasta de hidróxido de cálcio uma diminuição de sua permeabilidade em contato com os líquidos teciduais.", "A associação ao polietilenoglicol influencia significativamente as propriedades antimicrobianas do hidróxido de cálcio.", "Os veículos oleosos conferem à pasta de hidróxido de cálcio aumento da solubilidade e difusão junto aos tecidos."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: A colofônia confere à pasta de hidróxido de cálcio uma diminuição de sua permeabilidade em contato com os líquidos teciduais..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Odontologia Endodontia','Segundo Lopes e Siqueira, um canal necrosado totalmente instrumentado, antes de ser obturado, deve receber uma medicação intracanal. A alternativa correta nesse caso é','','','["medicação com hiploclorito de sódio.", "medicação com otosporim.", "medicação com pasta de hidróxido de cálcio, glicerina e paramonoclorofenol canforado.", "medicação com hidróxido de cálcio e iodofórmio."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: medicação com pasta de hidróxido de cálcio, glicerina e paramonoclorofenol canforado..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Odontologia Endodontia','A obtenção de um selamento compacto é o objetivo principal do tratamento endodôntico. Em relação à fase de obturação do sistema de canais radiculares, pode-se afirmar:','','','["Estudos atuais recomendam que o preparo e obturação do canal radicular em dentes polpados deve situar-se no nível do ápice radiográfico.", "As vantagens significantes dos cimentos de ionômero de vidro no selamento do canal são adesividade dentinária e atividade antimicrobiana.", "Quando o canal não consegue ser seco, sua obturação deve ser obrigatoriamente com cimento à base de óxido de zinco eugenol, pela sua efetiva ação antimicrobiana.", "Durante a seleção do cone principal, deve- se introduzi-lo no canal inundado de solução irrigadora."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: Durante a seleção do cone principal, deve- se introduzi-lo no canal inundado de solução irrigadora..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Odontologia Endodontia','Em relação aos materiais obturadores do sistema de canais radiculares, é importante observar que','','','["a pasta LC, graças à sua composição e propriedades, tem revelado resultados positivos quando empregada como cimento obturador.", "a guta-percha, cuja temperatura de fusão é de 560 , na forma alfa-cristalina, é estável e flexível à temperatura ambiente.", "a clorexidina pode ser usada de forma eficaz na descontaminação dos cones de guta- -percha.", "os cones de guta-percha, quando em contato com os tecidos perirradiculares, nunca são reabsorvido e estimulam a formação de uma cápsula fibrosa."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa A. Resposta indicada no gabarito: a pasta LC, graças à sua composição e propriedades, tem revelado resultados positivos quando empregada como cimento obturador..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Odontologia Endodontia','Quando se faz referência a dentes tratados endodonticamente, uma questão que deve ser observada é o fortalecimento do elemento dentário com o pino intrarradicular. Quanto ao retentor intrarradicular, é correto afirmar:','','','["Para a maioria dos autores, devem-se manter 2 mm de obturação no segmento apical do canal radicular.", "Na remoção do material obturador, devem- -se empregar instrumentos endodônticos associados a solventes orgânicos.", "Os pinos rosqueados são indicados em situações clínicas, em que o canal radicular se apresenta com pouca profundidade.", "Uma vantagem dos pinos de fibra de carbono é sua ótima união adesiva com o núcleo de preenchimento em compósito."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: Os pinos rosqueados são indicados em situações clínicas, em que o canal radicular se apresenta com pouca profundidade..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Odontologia Endodontia','Para o esvaziamento do canal radicular com finalidade de retratamento, empregam-se vários instrumentos e substâncias. Em relação a esse procedimento, é lícito afirmar:','','','["O clorofórmio é o solvente mais empregado na remoção da guta-percha.", "O óleo de terebintina é o solvente mais eficiente da guta-percha.", "O halotano, além de solvente, tem efetividade antimicrobiana.", "O eucaliptol é um solvente muito efetivo na desobstrução dos canais obturados com óxido de zinco-eugenol."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: O halotano, além de solvente, tem efetividade antimicrobiana..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Odontologia Endodontia','Um paciente procura um atendimento de urgência queixando-se de dor espontânea, pulsátil à mastigação no dente 22, que se encontra com mobilidade. Foi diagnosticado um abscesso perirradicular agudo em evolução. Havia edema consistente não flutuante e febre intermitente. Assinale o procedimento NÃO indicado para o tratamento do caso em questão.','','','["Drenagem da coleção purulenta pelo canal.", "Se o edema se encontra intraoral, optamos pela incisão da mucosa.", "Na presença de edema extraoral, optamos por não incisar, prescrevendo a aplicação de calor intraoral.", "Se não houver drenagem de pus pelo canal, amplia-se o forame até a lima tipo K n 25 e deixa o canal aberto."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: Se não houver drenagem de pus pelo canal, amplia-se o forame até a lima tipo K n 25 e deixa o canal aberto..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Odontologia Endodontia','Os traumatismos dentários ocorrem desde as fraturas coronárias até as avulsões dentárias. Dentre os vários fatores que envolvem o prognóstico de dentes traumatizados, podemos citar:','','','["As células ligamentares começam um processo degenerativo 60 minutos após a lesão num dente avulsionado.", "O fator mais importante no sucesso do reimplante é o meio de conservação do dente avulsionado.", "Os meios de conservação sugeridos em ordem de preferência são: saliva, leite, água, soro fisiológico.", "Uma contenção semirrígida por 7 a 10 dias é recomendada no reimplante de um dente avulsionado."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa D. Resposta indicada no gabarito: Uma contenção semirrígida por 7 a 10 dias é recomendada no reimplante de um dente avulsionado..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Odontologia Endodontia','O uso de antibióticos em odontologia tem sido cada vez mais restrito e há atualmente uma grande  preocupação quanto ao uso errôneo e abusivo dessa droga. Assinale a única afirmativa correta quanto ao uso de antibiótico em endodontia, segundo Lopes e Siqueira.','','','["O metronidazol, na dosagem habitual, por um período de 7 dias, é o antibiótico de eleição nos casos de reimplante de dentes avulsionados.", "Antibióticos, quando bem indicados, são eficazes no tratamento de doenças crônicas, como no caso de lesões perirradiculares.", "A maioria dos antibióticos empregados na cavidade oral possui meia-vida inferior a 3 horas.", "Pacientes infectados por HIV e que necessi-tam de tratamento endodôntico apresentam maiores riscos de complicação infecciosa e necessitam de profilaxia antibiótica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: A maioria dos antibióticos empregados na cavidade oral possui meia-vida inferior a 3 horas..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Odontologia Endodontia','Em relação ao tratamento endodôntico em dentes decíduos, pode-se afirmar que','','','["o teste elétrico pulpar é relevante no diagnóstico de inflamação pulpar em dentes decíduos.", "os testes térmicos geralmente não são confiáveis para se determinar o estado de polpa em dentição decídua.", "a pulpotomia em dente decíduo, utilizando o formocresol, é indicada quando a hemorragia não é controlada depois da amputação da polpa coronária.", "em polpas expostas pela cárie recomenda- se o capeamento pulpar utilizando o hidróxido de cálcio."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: os testes térmicos geralmente não são confiáveis para se determinar o estado de polpa em dentição decídua..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Odontologia Endodontia','O processo de reparação ou cicatrização é uma sequência de eventos que ocorrem após a remoção de agentes desencadeantes de uma reação básica de defesa do organismo. Assinale a afirmativa INCORRETA sobre os eventos que correspondem ao processo de reparo após o tratamento endodôntico.','','','["O reparo das lesões pode ocorrer por dois processos: regeneração e cicatrização.", "A regeneração é caracterizada pela formação de um tecido com predomínio do conjuntivo de origem fibroblástica.", "A adenosina trifosfato possui papel fundamental na geração de energia para o reparo.", "A reparação da lesão perirradicular depende da influência de fatores sistêmicos e locais."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa B. Resposta indicada no gabarito: A regeneração é caracterizada pela formação de um tecido com predomínio do conjuntivo de origem fibroblástica.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Odontologia Endodontia','O tampão apical é utilizado com objetivos mecânicos e biológicos. Dentre os materiais utilizados para esse procedimento, podem-se citar:','','','["pasta LC e sulfato de bário.", "MTA e Ketac-endo.", "pasta LC e MTA.", "HPG e Dycal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Endodontia: alternativa C. Resposta indicada no gabarito: pasta LC e MTA..' from public.exams where slug='pmerj-2010-odontologia-endodontia' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-endoscopia-digestiva','PMERJ 2010 — Oficial — Médico Endoscopia Digestiva','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Endoscopia Digestiva','Avalie as afirmativas abaixo em relação ao processamento de aparelhos e marque a opção correta. I. A limpeza é a etapa mais importante uma vez que pode reduzir em até 6,2 log o número de micro-organismos, assim como o material orgânico. II. A importância das micobactérias se dá pelos relatos de transmissão por endoscopia digestiva e a sua elevada prevalência em nosso meio. III. A erradicação das micobactérias só não é mais difícil que os esporos, por isso é utilizada como marcador de erradicação de todos os micro-organismos de interesse clínico, exceto o Prion. IV. Devemos realizar uma anamnese dirigida com objetivo de identificar pacientes portadores de HIV, HBV e HCV, realizando um tratamento especial no aparelho após o exame.','','','["As afirmativas I e II estão corretas.", "As afirmativas I e III estão corretas.", "As afirmativas II e IV estão corretas.", "As afirmativas III e IV estão corretas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: As afirmativas I e III estão corretas.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Endoscopia Digestiva','Em relação aos saneantes utilizados no processamento de aparelhos, marque a resposta correta.','','','["Tanto o glutaraldeído, quanto o ácido peracético e o orthophtalaldeído produzem dano no meio ambiente.", "O ácido peracético tem a vantagem sobre o glutaraldeído por não fixar proteínas.", "Tanto o ácido peracético quanto o glutaraldeído não precisam ser inativados antes de serem desprezados no meio ambiente.", "O ácido peracético e o orthophtalaldeído, assim como o glutaraldeído, requerem sistema de exaustão."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: O ácido peracético tem a vantagem sobre o glutaraldeído por não fixar proteínas..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Endoscopia Digestiva','Avalie as afirmativas abaixo em relação à sedoanalgesia no exame endoscópico e assinale a resposta INCORRETA.','','','["Em pacientes que relatarem reação adversa à lidocaína, poderemos, simplesmente, realizar o procedimento sem anestesia tópica.", "O diazepam tem como vantagem sobre o midazolam o menor custo, enquanto o midazolam tem menor meia vida, maior potência e maior efeito amnésico.", "A resposta imediata ao flumazenil utilizada em paciente que apresente depressão respiratória associada ao uso de midazolam significa a garantia de uma recuperação completa, uma vez que a meia vida do flumazenil é maior do que a do midazolam.", "O curto período de ação do propofol e a consequente recuperação rápida nos permitem afirmar que é uma droga mais segura do que os benzodiazepínicos, após o despertar do paciente."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: A resposta imediata ao flumazenil utilizada em paciente que apresente depressão respiratória associada ao uso de midazolam significa a garantia de uma recuperação completa, uma vez que a meia vida do flumazenil é maior do que a do midazolam.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Endoscopia Digestiva','Um paciente estava sendo submetido a uma colonoscopia sob sedoanalgesia com petidina e midazolam quando, após nova infusão de midazolam, apresentou esforço respiratório, sinal de obstrução de vias aéreas superiores e redução da saturação de O2 para 85%. Qual a conduta médica adequada?','','','["Reverter imediatamente o midazolam, utilizando flumazenil, uma vez que o fato ocorreu logo após a sua infusão.", "Reverter não somente o benzodiazepínico como também o opioide, utilizando naloxone, uma vez que eles apresentam ação sinérgica.", "Realizar intubação orotraqueal imediatamente.", "Tracionar a mandíbula e suplementar oxigênio, revertendo o benzodiazepínico apenas se essas medidas não forem suficientes."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: Tracionar a mandíbula e suplementar oxigênio, revertendo o benzodiazepínico apenas se essas medidas não forem suficientes..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Endoscopia Digestiva','Avalie as afirmativas abaixo sobre o preparo de cólon. Assinale a afirmativa INCORRETA.','','','["O sulfato de sódio pode ser utilizado com segurança em paciente com suboclusão intestinal, uma vez que é necessária a ingestão de pequeno volume.", "O polietilenoglicol tem a vantagem de determinar menor troca osmótica e a desvantagem de exigir a ingestão de grande volume.", "A metabolização do manitol pelas bactérias produz hidrogênio e metano, o que pode causar explosão do cólon durante a utilização de corrente elétrica.", "O sulfato de sódio, por poder determinar grande distúrbio hidroeletrolítico e piora da função renal, deve ser usado com cautela ou mesmo contraindicado em paciente que tenham comprometimento prévio da função renal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: O sulfato de sódio pode ser utilizado com segurança em paciente com suboclusão intestinal, uma vez que é necessária a ingestão de pequeno volume.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Endoscopia Digestiva','Assinale a associação em que a profilaxia antibiótica NÃO deve ser realizada.','','','["Paciente com prolapso de válvula mitral com regurgitação, submetido à endoscopia digestiva alta ou colonoscopia diagnóstica.", "Paciente cirrótico admitido com hemorragia digestiva alta varicosa, submetido a tratamento endoscópico pela técnica de escleroterapia.", "Paciente com endocardite bacteriana prévia e estenose esofagiana, submetido à dilatação endoscópica.", "Paciente com obstrução do ducto biliar que será submetido a tratamento endoscópico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: Paciente com prolapso de válvula mitral com regurgitação, submetido à endoscopia digestiva alta ou colonoscopia diagnóstica..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Endoscopia Digestiva','Em relação ao manejo de pacientes com alteração da coagulação ou sob uso de anticoagulantes ou antiagregantes plaquetários, é correto afirmar que','','','["o uso de aspirina contraindica a realização de polipectomia endoscópica.", "antes de procedimentos endoscópicos como a CPRE, devemos solicitar exames como TAP, PTT e plaquetas de pacientes com co-morbidade ou história clínica que estejam associadas a distúrbio de coagulação, para que possa ser realizada a correção necessária.", "o uso de aspirina contraindica a realização de gastrostomia endoscópica.", "a retirada temporária de anticoagulante ou antiagregante plaquetário, independente do risco de fenômeno tromboembólico do paciente, deve ser feita sempre, uma vez que procedimento adicional pode ser necessário."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: antes de procedimentos endoscópicos como a CPRE, devemos solicitar exames como TAP, PTT e plaquetas de pacientes com co-morbidade ou história clínica que estejam associadas a distúrbio de coagulação, para que possa ser realizada a correção necessária..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Endoscopia Digestiva','Em relação às complicações associadas a procedimentos endoscópicos, assinale a resposta correta?','','','["As perfurações esofagianas decorrentes de procedimentos endoscópicos têm as mesmas implicações prognósticas e terapêuticas, independente se ocorridas no esôfago cervical, torácico ou abdominal, devendo sempre ser operadas.", "O sepultamento de um cateter de gastros- tomia significa sempre a sua perda em definitivo, devendo ser feito um novo procedimento após a cicatrização.", "O tratamento para uma fístula gastroco- locutânea que surja como complicação de uma gastrostomia se dá pela retirada do cateter, reservando-se o tratamento cirúrgico apenas para os casos em que não houver fechamento da fístula.", "O tratamento cirúrgico é imediatamente realizado quando ocorre uma perfuração para o retroperitônio após a papilotomia endoscópica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: O tratamento para uma fístula gastroco- locutânea que surja como complicação de uma gastrostomia se dá pela retirada do cateter, reservando-se o tratamento cirúrgico apenas para os casos em que não houver fechamento da fístula..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Endoscopia Digestiva','A endoscopia digestiva é instrumento importante na avaliação da esofagite por refluxo. Analise as afirmativas abaixo e marque a opção correta. I. A endoscopia tem sensibilidade baixa para o diagnóstico de doença do refluxo gastroesofagiano. II. As classificações endoscópicas têm excelente correlação com os sintomas e com a pHmetria. III. As biópsias endoscópicas do esôfago devem ser sempre realizadas nos casos em que não houver alteração macroscópica, uma vez que irão sempre definir o diagnóstico de doença do refluxo não erosiva. IV. A endoscopia estratifica a doença do refluxo e oferece informações importantes para a decisão do tratamento.','','','["As afirmativas I e II estão corretas.", "As afirmativas II e III estão corretas.", "As afirmativas III e IV estão corretas", "As afirmativas I e IV estão corretas"]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: As afirmativas I e IV estão corretas.' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Endoscopia Digestiva','Analise as seguintes condições em relação ao esôfago de Barrett e assinale a resposta correta.','','','["A presença de processo inflamatório não altera a avaliação da displasia, portanto não se faz necessário novo exame com biópsias para avaliação histológica após o tratamento adequado da doença do refluxo.", "Quando houver displasia de alto grau associada a intenso processo inflamatório macroscópico, devemos indicar a esofagectomia.", "Na ausência de displasia, devemos realizar novo exame em dois a três anos.", "A ablação do epitélio metaplásico com plasma de argônio está bem estabelecida como forma de tratamento."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: Na ausência de displasia, devemos realizar novo exame em dois a três anos..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Endoscopia Digestiva','A endoscopia é excelente instrumento na avaliação de um paciente submetido à fundoplicatura para o tratamento da doença do refluxo. Assinale a alternativa correta.','','','["A presença de estase líquida ou mesmo de grande volume de saliva no corpo eso- fagiano deve ser valorizada, especialmente se houver disfagia.", "A presença de disfagia, um mês após o procedimento, determinará a realização de dilatação, independente dos achados endoscópicos.", "A presença de resistência ao ultrapassarmos a junção esofagogástrica, o “rolamento da mucosa” com a mobilização do aparelho, visualizado em manobra em “U”, indicam uma fundoplicatura competente.", "A visualização de segmento de mucosa gástrica acima da junção esofagogástrica indica que houve deslizamento da fundoplicatura ou esta foi realizada sobre o estômago, devendo-se indicar nova cirurgia, independente dos sintomas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: A presença de estase líquida ou mesmo de grande volume de saliva no corpo eso- fagiano deve ser valorizada, especialmente se houver disfagia..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Endoscopia Digestiva','Um homem jovem se apresenta para realização de exame endoscópico com história de impactações esofagianas. Analise as afirmativas e marque a opção correta. I. Na presença de endoscopia normal, não se deve realizar nenhum procedimento adicional, uma vez que o diagnóstico será definido pela manometria esofagiana. II. A presença de sulcos longitudinais, pontilhados brancos e ondulações transversais é altamente sugestiva de esofagite eosinofilica. III. Na hipótese diagnóstica de esofagite eosinofílica, deveremos realizar, pelo menos, quinze biópsias no corpo esofagiano, especialmente próximo da junção esofagogástrica. IV. Na hipótese de esofagite eosinofílica, a presença de sinais endoscópicos caracterís- ticos de esofagite por refluxo não a exclui, uma vez que podem coexistir.','','','["As afirmativas I e II estão corretas.", "As afirmativas II e III estão corretas.", "As afirmativas III e IV estão corretas.", "As afirmativas II e IV estão corretas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: As afirmativas II e IV estão corretas..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Endoscopia Digestiva','Um paciente com síndrome da imunodeficiência adquirida é submetido à endoscopia digestiva. Assinale a resposta correta.','','','["A presença de placas brancas no corpo esofagiano é sugestiva de infecção por cândida. Nessa situação, a biópsia é imperativa e o tratamento só será realizado após a confirmação.", "Pequenas ulcerações rasas, por vezes lembrando a forma de um vulcão, são sugestivas de lesões por herpes simples vírus. Nesse caso, a biópsia deverá envolver obrigatoriamente o fundo das lesões.", "Úlceras mais profundas, por vezes grandes e com bordas bem marcadas, são sugestivas de lesões por CMV, achado que orienta as biópsias para fundo das lesões. A  não identificação das alterações citopáticas no estudo histopatológico inclui as úlceras esofagianas idiopáticas no diagnóstico diferencial.", "Em pacientes com doença avançada, cujo exame demonstre a mucosa esofagiana normal, devemos realizar biópsias seriadas do corpo esofagiano para identificação de germes oportunistas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: Úlceras mais profundas, por vezes grandes e com bordas bem marcadas, são sugestivas de lesões por CMV, achado que orienta as biópsias para fundo das lesões. A  não identificação das alterações citopáticas no estudo histopatológico inclui as úlceras esofagianas idiopáticas no diagnóstico diferencial..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Endoscopia Digestiva','Analise as afirmativas abaixo em relação à conduta na lesão esofagiana após a ingestão de substância cáustica e assinale a resposta correta.','','','["A avaliação endoscópica inicial não deverá ser realizada nas primeiras 48 horas, uma vez que não haverá tempo necessário para o desenvolvimento das lesões.", "O procedimento de dilatação está contraindicado até um mês após, uma vez que está associado a grande risco de perfuração.", "Na fase aguda dos casos graves, está contraindicada a passagem de cateter gástrico, uma vez que o risco de perfuração é maior que o benefício.", "Após reavaliação endoscópica, a dilatação cuidadosa pode ser iniciada na segunda semana."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: Após reavaliação endoscópica, a dilatação cuidadosa pode ser iniciada na segunda semana..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Endoscopia Digestiva','Um paciente com bom estado geral, em sua 5ª década de vida, com diagnóstico de megaesôfago grau II por acalasia idiopática, é submetido à cardiomiotomia com fundoplicatura frouxa, sem resultado efetivo. Nesse caso: I. A endoscopia deve ser realizada para afastar estenose na miotomia ou fundoplicatura apertada. II. A manometria esofagiana estará indicada para avaliação da pressão do esfíncter, se não houver alteração endoscópica que justifique a clínica. III. A dilatação pneumática está proscrita uma vez que envolve grande risco de perfuração após a miotomia. IV. A aplicação de toxina botulínica tem excelente resultado, uma vez que há ação sinérgica com a cirurgia. Assinale a opção correta.','','','["As afirmativas I e II estão corretas.", "As afirmativas I e III estão corretas.", "As afirmativas I e IV estão corretas.", "As afirmativas III e IV estão corretas"]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: As afirmativas I e II estão corretas..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Endoscopia Digestiva','Um paciente do sexo masculino, emagrecido, mas ainda com bom estado geral, apresenta-se com disfagia por um carcinoma epidermoide que se inicia a 2 cm do cricofaríngeo, estende-se por 5 cm e permite a passagem do endoscópio com grande dificuldade. Estadiamento demonstrou acometimento transmural e de linfonodos cervicais e mediastinais. A melhor conduta seria','','','["aplicar prótese esofagiana, uma vez que já há metástase a distância e a localização do tumor é a mais adequada para esse procedimento.", "indicar radioterapia, uma vez que tem bom resultado nesse tipo histológico e o paciente ainda apresenta bom estado geral.", "indicar esofagectomia, pois o paciente tem apenas lesão local avançada e acometimento linfonodal.", "tunelizar da lesão com plasma de argônio, pois tem excelente resultado na paliação de lesões grandes."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: indicar radioterapia, uma vez que tem bom resultado nesse tipo histológico e o paciente ainda apresenta bom estado geral..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Endoscopia Digestiva','Assinale a alternativa correta em relação a lesões neoplásicas esofagianas.','','','["A lesão neoplásica de aspecto polipoide é a de melhor prognóstico para tratamento endoscópico, uma vez que está associada à fácil ressecção e tem a base livre de infiltração.", "A ressecção endoscópica de um carcinoma superficial que envolva sm1 é curativa, porque é desprezível a possibilidade de metástase linfonodal.", "A ressecção endoscópica de um carcinoma superficial deve ser realizada apenas após o estadiamento com ecoendoscopia.", "As restrições para ressecção do carcinoma epidermoide são o acometimento até a lâmina própria (m2) e extensão superior a 3 cm."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: As restrições para ressecção do carcinoma epidermoide são o acometimento até a lâmina própria (m2) e extensão superior a 3 cm..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Endoscopia Digestiva','Em relação à diverticulotomia endoscópica para o tratamento dos divertículos faringoesofágicos, é correto afirmar que','','','["a perfuração envolve alta mortalidade, mesmo se identificada logo após o procedimento e tratada adequadamente.", "a intubação traqueal com ventilação assistida é condição obrigatória para o procedimento, uma vez que perfuração e hemorragia são complicações que podem determinar insuficiência respiratória.", "os divertículos menores são mais propensos a complicações.", "a recidiva tardia da disfagia significa obrigatoriamente a realização de tratamento cirúrgico."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: os divertículos menores são mais propensos a complicações..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Endoscopia Digestiva','Um paciente é submetido a uma endoscopia digestiva que demonstra úlcera duodenal. Analise as afirmativas abaixo e marque a opção correta. I. Independente do resultado histopatológico, devemos erradicar o Helicobacter pylori por ser este o único fator associado à úlcera duodenal. II. No exame histológico, a presença de atividade intensa, representada pelo infiltrado polimorfonuclear, é altamente indicativa da existência da bactéria. III. Se o paciente tiver feito uso recente de AINH e apresentar alterações estruturais representadas pela deformidade duodenal, a bactéria deve ser pesquisada e erradicada, se presente. IV. Para o tratamento, mesmo que o teste de urease seja positivo, devemos aguardar o resultado do estudo histopatológico, considerando o percentual elevado de teste falso positivo.','','','["As afirmativas I e II estão corretas.", "As afirmativas II e III estão corretas.", "As afirmativas II e IV estão corretas.", "As afirmativas III e IV estão corretas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: As afirmativas II e III estão corretas..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Endoscopia Digestiva','O estudo histopatológico na gastrite avalia os infiltrados polimorfonuclear e mononuclear, a presença do Helicobacter pylori, a atrofia e a metaplasia. O endoscopista, ao interpretar os resultados, deve entender que','','','["a presença de infiltrado mononuclear caracterizando gastrite crônica em material de exame realizado seis meses após o tratamento para erradicação da bactéria indica que esta deve estar presente, mas em densidade muito baixa para ser identificada.", "no fragmento com presença acentuada de metaplasia intestinal a identificação da bactéria é mais difícil, não podendo ser excluída.", "um exame controle realizado dois meses depois da erradicação certamente demonstrará a ausência do infiltrado de polimorfonucleares e mononucleares.", "um exame controle realizado três meses depois da erradicação certamente demonstrará regressão da atrofia e da metaplasia intestinal."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: no fragmento com presença acentuada de metaplasia intestinal a identificação da bactéria é mais difícil, não podendo ser excluída..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Endoscopia Digestiva','Em relação às indicações e contraindicações para uso do balão intragástrico para tratamento da obesidade, assinale a reposta em que as duas afirmativas, indicação e contraindicação, estão corretas.','','','["O balão está indicado como teste pré- -operatório para candidatos à cirurgia eminentemente restritiva; está contra-  indicado em paciente com fundoplicatura prévia.", "O balão está indicado em pacientes com IMC maior que 40 que apresentem contraindicação para cirurgia ou a recusem; está contraindicado em pacientes que apresentem cicatriz de úlcera gástrica.", "O balão está indicado em pacientes com IMC maior que 50, como pré-operatório, com o objetivo de diminuir a morbidade e mortalidade; está contraindicado na presença de gastrite enantematosa cujo histopatológico demonstre gastrite associada ao H. pylori com atividade intensa.", "O balão está indicado em pacientes com IMC entre 30 e 35 com objetivo de apenas auxiliar o tratamento clínico; está contraindicado na presença de hérnia hiatal volumosa."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: O balão está indicado como teste pré- -operatório para candidatos à cirurgia eminentemente restritiva; está contra-  indicado em paciente com fundoplicatura prévia..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Endoscopia Digestiva','O médico endoscopista deve conhecer os aspectos endoscópicos e as possíveis complicações das principais cirurgias bariátricas. Assinale a alternativa correta.','','','["Na cirurgia de Scopinaro, a fístula para o estômago excluso é uma complicação possível.", "Na cirurgia de Fobi-Capella, a migração do anel pode causar fenômeno obstrutivo.", "Na gastroplastia vertical com banda, é impossível a avaliação do fundo gástrico, exceto se houver formação de fístula ao longo da linha de sutura.", "Uma das complicações observadas na derivação biliopancreática com switch duodenal é a erosão da banda."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: Na cirurgia de Fobi-Capella, a migração do anel pode causar fenômeno obstrutivo..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Endoscopia Digestiva','Relacione os achados endoscópicos com as respectivas cirurgias e, em seguida, marque a opção correta. 1. Cirurgia de Fobi-Capella. 2. Derivação gastrojejunal com anastomose em Y de Roux. 3. Operação de Scopinaro. 4. Derivação biliopancreática com Switch duodenal. ( ) Gastrectomia vertical com preservação do piloro, observando-se anastomose duodenojejunal. ( ) Pequeno reservatório gástrico com anastomose gastrojejunal com diâmetro entre 10 e 15 mm. ( ) Pequeno reservatório gástrico com área de estreitamento anelar, representado pelo anel e pela anastomose gastrojejunal. ( ) Gastrectomia distal com gastroenteroanas- tomose.','','','["4, 1, 3, 2.", "3, 4, 1, 3.", "4, 2, 1, 3.", "3, 2, 1, 4."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: 4, 2, 1, 3..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Endoscopia Digestiva','Assinale a resposta correta em relação à CPRE.','','','["Independente da clínica apresentada, um paciente com amilase aumentada 3 vezes o valor de referência no dia seguinte ao procedimento deve ter sua internação prorrogada, uma vez que houve pancreatite como complicação.", "A dilatação da papila é uma alternativa à papilotomia em pacientes com distúrbio da coagulação, porém envolve maior risco de pancreatite.", "Os fatores de risco, associados ao desenvolvimento de pancreatite, são o sexo masculino, colédoco dilatado, idade avançada e a presença de cálculo impactado na papila.", "A perfuração é uma complicação incomum, mas geralmente provocada pelo próprio aparelho que, por ter visão lateral, é difícil de ser posicionado na segunda porção duodenal."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: A dilatação da papila é uma alternativa à papilotomia em pacientes com distúrbio da coagulação, porém envolve maior risco de pancreatite..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Endoscopia Digestiva','Um paciente com colelitíase é internado com quadro agudo de cólica biliar. Considerando a possibilidade de coledocolitíase associada, avalie as afirmativas e assinale conduta correta,  fundamentando- -se na relação custo-benefício.','','','["Independente dos exames laboratoriais e dos dados do US, realizar logo a colecistectomia, deixando a via biliar drenada, se houver cálculo coledociano.", "Realizar CPRE de imediato, se houver pancreatite aguda biliar associada.", "Sempre realizar primeiro colangiografia por ressonância magnética, independente dos achados clínicos e laboratoriais.", "Realizar CPRE pré-operatória, se houver dilatação da via biliar ao US, aumento das aminotransferases e bilirrubina direta."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: Realizar CPRE pré-operatória, se houver dilatação da via biliar ao US, aumento das aminotransferases e bilirrubina direta..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Endoscopia Digestiva','Estenoses e fístulas são complicações associadas à cirurgia nas vias biliares que podem ter resolução endoscópica. Analise as afirmativas abaixo e assinale a INCORRETA.','','','["Estenoses acima da bifurcação dos hepáticos, segmentos longos de estenoses e tempo pós-cirúrgico maior que três meses estão associados a falhas terapêuticas por endoscopia.", "Em um paciente com estenose da via biliar principal, é realizada papilotomia, dilatação hidrostática da estenose e aplicação de uma prótese de 10 French. Se no exame seguinte, realizado dois meses após, ainda observarmos estenose, deveremos indicar cirurgia.", "Na presença de uma fístula de baixo débito, a papilotomia simples ou a aplicação de prótese única sem papilotomia pode ser suficiente para a resolução.", "A presença de cálculo residual distal é fator associado à formação ou à perpetuação da fístula."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: Em um paciente com estenose da via biliar principal, é realizada papilotomia, dilatação hidrostática da estenose e aplicação de uma prótese de 10 French. Se no exame seguinte, realizado dois meses após, ainda observarmos estenose, deveremos indicar cirurgia.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Endoscopia Digestiva','São fatores preditivos da ruptura de varizes de esôfago no paciente cirrótico:','','','["esofagite erosiva, pressão da veia porta, sinais da cor vermelha na superfície da variz.", "classificação de Child, sinais da cor vermelha na superfície da variz, esofagite erosiva.", "pressão intravaricosa, pressão na veia porta, tamanho das varizes e sinais da cor vermelha na superfície da variz.", "classificação de Child, tamanho das varizes e número de cordões varicosos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: pressão intravaricosa, pressão na veia porta, tamanho das varizes e sinais da cor vermelha na superfície da variz..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Endoscopia Digestiva','O tratamento de escolha para a erradicação das varizes de fundo gástrico que sangraram é','','','["injeção de cianoacrilato + lipiodol.", "ligadura elástica.", "injeção de oleato de etanolamina a 5% ou polidocanol a 1%.", "injeção de álcool absoluto."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: injeção de cianoacrilato + lipiodol..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Endoscopia Digestiva','É contraindicação para o uso da cápsula endoscópica:','','','["sangramento oculto.", "estenose intestinal.", "investigação de doença de Crohn.", "estase gástrica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: estenose intestinal..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Endoscopia Digestiva','Têm indicação de ressecção endoscópica os seguintes tumores gástricos precoces:','','','["carcinoma intramucoso menor que 1.0cm associado à cicatriz de úlcera.", "lesão do tipo IIa, menor do que 2.0cm, restrita à mucosa, sem ulceração, independente do grau de diferenciação histológica.", "lesão do tipo IIc, maior do que 1.0cm, restrita à mucosa, sem ulceração.", "lesão do tipo IIa ou IIb, menor do que 2.0cm, restrita à mucosa, sem ulceração e bem diferenciada."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: lesão do tipo IIa ou IIb, menor do que 2.0cm, restrita à mucosa, sem ulceração e bem diferenciada..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Endoscopia Digestiva','Paciente do sexo feminino, 54 anos, realizou uma endoscopia digestiva alta por síndrome dispéptica.  O exame revelou inúmeros pólipos de glândulas fúndicas. A recomendação ao paciente deve ser a seguinte:','','','["revisão endoscópica bianual, apesar de pólipos hiperplásicos, pelo risco aumentado de tumor carcinoide.", "não precisa de acompanhamento por se tratar de pólipos hiperplásicos.", "retirada de todos os pólipos antes do acompanhamento endoscópico.", "revisão endoscópica anual pela sua associação com a FAP (polipose adenomatosa familiar)."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: não precisa de acompanhamento por se tratar de pólipos hiperplásicos..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Endoscopia Digestiva','O endoscopista deve procurar tumor carcinoide nas seguintes situações, EXCETO em','','','["gastrite atrófica.", "anemia perniciosa.", "antrectomia prévia.", "síndrome de Zollinger-Ellison."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: antrectomia prévia.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Endoscopia Digestiva','A linite plástica encontrada no tumor maligno avançado do estômago é um tipo de Borrmann:','','','["I.", "II.", "III.", "IV."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: IV..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Endoscopia Digestiva','Paciente realizou gastrostomia endoscópica percutânea que complicou com fístula gastrocólica. O achado clínico mais comum para essa complicação é','','','["diarreia.", "obstrução intestinal.", "peritonite.", "dor abdominal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: diarreia..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Endoscopia Digestiva','Para a realização da gastrostomia endoscópica percutânea na técnica de “pull”, os melhores parâmetros para o sucesso do procedimento são','','','["boa transiluminação do aparelho na parede abdominal e punção localizada na região subcostal esquerda.", "impressão digital representada por indentação bem definida na parede anterior gástrica e ausência de hérnia de hiato.", "boa transiluminação do aparelho na parede abdominal e punção gástrica localizada na parede anterior do corpo.", "boa transiluminação do aparelho na parede abdominal e impressão digital representada por indentação bem definida na parede anterior gástrica."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: boa transiluminação do aparelho na parede abdominal e impressão digital representada por indentação bem definida na parede anterior gástrica..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Endoscopia Digestiva','Na doença inflamatória intestinal, os aspectos endoscópicos que podem sugerir o diagnóstico de doença de Crohn são','','','["assimetria, pedras de calçamento, úlceras aftosas.", "pedras de calçamento, reto sempre comprometido, inflamação contínua.", "úlceras aftosas, mucosa doente ao redor das úlceras, friabilidade.", "úlceras rasas, distribuição contínua, fístulas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: assimetria, pedras de calçamento, úlceras aftosas..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Endoscopia Digestiva','Assinale a opção INCORRETA em relação às doenças inflamatórias intestinais.','','','["A vigilância endoscópica para o câncer de cólon deve ser realizada na pancolite com mais de 8 anos de evolução e na colite esquerda com mais de 15 anos.", "O diagnóstico confirmado de DALM preconiza a colectomia total.", "O achado duvidoso de displasia deve resultar em novo exame endoscópico em 3 a 6 meses para nova biópsia e confirmação da presença da displasia.", "Pacientes com colangite esclerosante devem realizar a vigilância endoscópica para o câncer de cólon a cada 4 anos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: Pacientes com colangite esclerosante devem realizar a vigilância endoscópica para o câncer de cólon a cada 4 anos.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Endoscopia Digestiva','O melhor tratamento endoscópico para a proctite actínica com sangramento recorrente é','','','["injeção de esclerosantes.", "plasma de argônio.", "injeção de formalina.", "terapia hiperbárica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: plasma de argônio..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Endoscopia Digestiva','Paciente do sexo masculino, 63 anos, revascularizado há 8 anos, em uso de AAS. Apresentou cólica abdominal súbita e enterorragia sem repercussão hemodinâmica. Foi internado e realizou uma colonoscopia. O diagnóstico mais provável é','','','["úlceras do cólon relacionadas ao uso do AAS.", "retocolite ulcerativa idiopática.", "colite isquêmica.", "câncer coloretal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: colite isquêmica..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Endoscopia Digestiva','Paciente do sexo masculino, 62 anos, evoluiu após transplante renal com parada de eliminação de gazes e fezes e distensão abdominal. A melhor conduta para esse caso é','','','["conduta conservadora, corrigindo a doença de base.", "conduta cirúrgica, a partir de 48h de distensão abdominal.", "descompressão colônica por colonoscopia, independente do diâmetro do ceco.", "descompressão colônica por colonoscopia, se o diâmetro do ceco for maior do que 12cm."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: descompressão colônica por colonoscopia, se o diâmetro do ceco for maior do que 12cm..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Endoscopia Digestiva','Criança de 4 anos engoliu, há 1 hora, uma bateria de um brinquedo. A melhor opção é','','','["a retirada cirúrgica, independente da localização.", "monitorar a localização da bateria e só retirá-la por endoscopia, caso ela não seja eliminada espontaneamente.", "a retirada endoscópica, se a bateria estiver no esôfago, para evitar a possibilidade de formação de fístula.", "a retirada cirúrgica, se a bateria estiver no intestino delgado, independente do tempo de ingestão."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: a retirada endoscópica, se a bateria estiver no esôfago, para evitar a possibilidade de formação de fístula..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Endoscopia Digestiva','Em relação à enteroscopia de duplo balão, marque a resposta INCORRETA.','','','["O overtube tem a função de impedir a formação de alça e manter o eixo do intestino delgado retificado.", "As principais indicações para esse exame são: hemorragia digestiva de origem obscura, doença inflamatória intestinal, neoplasia e enteropatia droga induzida.", "Na abordagem por ambas as vias, anterógrada e retrógrada, devemos fazê-las no mesmo dia, evitando a injeção de naquim e o uso da fluoroscopia.", "A enteroscopia está indicada na avaliação do estômago excluso da cirurgia bariátrica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: Na abordagem por ambas as vias, anterógrada e retrógrada, devemos fazê-las no mesmo dia, evitando a injeção de naquim e o uso da fluoroscopia.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Endoscopia Digestiva','Em relação ao sangramento pós-polipectomia, é correto afirmar que','','','["laçar novamente o pedículo remanescente e aguardar por 5 a 10 minutos é o suficiente para a hemostasia na maioria dos casos.", "é preciso evitar o sangramento, injetando adrenalina no pedículo antes da ressecção.", "a interrupção espontânea do sangramento volumoso acontece na maioria dos casos.", "é necessário seccionar o pedículo remanescente para realizar, em seguida, a hemostasia com método de injeção ou térmico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: laçar novamente o pedículo remanescente e aguardar por 5 a 10 minutos é o suficiente para a hemostasia na maioria dos casos..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Endoscopia Digestiva','Na colonoscopia com magnificação e aplicação de corantes, podemos visualizar o padrão das criptas e classificar as lesões polipoides. Segundo a classificação de Kudo, os adenomas vilosos correspondem a lesões do tipo:','','','["IIIs.", "III L.", "IV.", "V."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: IV..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Endoscopia Digestiva','Nas doenças do cólon de pacientes com SIDA, a colonoscopia é um exame importante para o diagnóstico etiológico das lesões ulceradas, principalmente após a biópsia endoscópica. Marque a opção correta.','','','["A biópsia endoscópica deve ser realizada nas bordas e, principalmente, na base das úlceras, onde são evidenciadas células endoteliais nas colites por CMV.", "A biópsia endoscópica deve ser realizada na base das úlceras para a identificação de inclusões intranuclerares do herpes.", "A biópsia endoscópica no sarkoma de Kaposi não é diagnóstica por ser esta uma lesão da submucosa.", "A colite por CMV tem aspecto endoscópico único e característico, representado por úlceras ovalares, de bordas planas, distribuídas difusamente no cólon."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: A biópsia endoscópica deve ser realizada nas bordas e, principalmente, na base das úlceras, onde são evidenciadas células endoteliais nas colites por CMV..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Endoscopia Digestiva','Em relação à lesão de Dieulafoy, podemos dizer que','','','["representa dilatação de vasos submucosos com sangramento resultante de erosões puntiformes da mucosa e da parede vascular.", "a localização mais frequente é no intestino delgado.", "o tratamento é cirúrgico, pois as tentativas de hemostasia endoscópica raramente são eficazes.", "o sangramento geralmente é de baixo débito, levando à anemia crônica como sintoma principal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: representa dilatação de vasos submucosos com sangramento resultante de erosões puntiformes da mucosa e da parede vascular..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Endoscopia Digestiva','Para paciente com enterorragia e com repercussão hemodinâmica, o primeiro exame diagnóstico deve ser','','','["arteriografia.", "endoscopia digestiva alta.", "colonoscopia.", "cintigrafia com hemácias marcadas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa B. Resposta indicada no gabarito: endoscopia digestiva alta..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Endoscopia Digestiva','Na hemorragia digestiva alta não varicosa, podemos afirmar que','','','["a retirada do coágulo sobre a lesão deve ser realizada rotineiramente para avaliar a presença de vaso visível.", "não se deve retirar o coágulo sobre a lesão antes de injetar adrenalina.", "se deve deixar o coágulo sobre a lesão porque ele não precisa de tratamento endoscópico e pela chance de ressangramento após a sua retirada.", "se deve retirar o coágulo sobre a lesão apenas se houver sangramento tipo “lençol” na base da úlcera."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa A. Resposta indicada no gabarito: a retirada do coágulo sobre a lesão deve ser realizada rotineiramente para avaliar a presença de vaso visível..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Endoscopia Digestiva','A hemostasia endoscópica com injeção de adrenalina nas úlceras sangrantes preconizada por Soehendra é obtida, principalmente, por','','','["vasoconstricção e ulceração.", "destruição tissular, vasoconstricção e trombose.", "ação química de irritação, trombose e vasoconstricção.", "compressão do vaso da submucosa, vasoconstricção e agregação plaquetária."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa D. Resposta indicada no gabarito: compressão do vaso da submucosa, vasoconstricção e agregação plaquetária..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Endoscopia Digestiva','Paciente realizou endoscopia digestiva alta para investigação de anemia ferropriva. O achado endoscópico que corrobora o diagnóstico de úlceras de Cameron é','','','["fundoplicatura.", "úlcera na parede posterior do bulbo duodenal.", "hérnia de hiato por deslizamento.", "volvo gástrico."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Endoscopia Digestiva: alternativa C. Resposta indicada no gabarito: hérnia de hiato por deslizamento..' from public.exams where slug='pmerj-2010-medico-endoscopia-digestiva' on conflict(exam_id,number) do nothing;
