insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Farmácia Bioquímica','No controle do tratamento da osteoporose, utiliza-se como monitorização a dosagem dos níveis sanguíneos de','','','["calcitonina.", "fosfatase alcalina.", "osteocalcina.", "PTH- Paratormônio."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Farmácia Bioquímica: alternativa C. Resposta indicada no gabarito: osteocalcina..' from public.exams where slug='pmerj-2010-farmacia-bioquimica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Farmácia Bioquímica','A faixa terapêutica ideal para o Lítio no tratamento do distúrbio bipolar é','','','["0,1 a 0,5 mEq/L.", "0,75 a 1,5 mEq/L.", "1,5 a 2,5 mEq/L.", "2,5 a 3,5 mEq/L."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Farmácia Bioquímica: alternativa B. Resposta indicada no gabarito: 0,75 a 1,5 mEq/L..' from public.exams where slug='pmerj-2010-farmacia-bioquimica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Farmácia Bioquímica','O constituinte bioquímico presente no sangue capaz de reduzir o íon cúprico à cuproso in vitro e a quente é','','','["amilase.", "colesterol.", "glicose.", "ureia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Farmácia Bioquímica: alternativa C. Resposta indicada no gabarito: glicose..' from public.exams where slug='pmerj-2010-farmacia-bioquimica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Farmácia Bioquímica','A alfafetoproteína aumentada em carcinoma hepatocelular é verificada pelo aumento na fração eletroforética de','','','["Alfa 1.", "Alfa 2", "Beta.", "Gama."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Farmácia Bioquímica: alternativa A. Resposta indicada no gabarito: Alfa 1..' from public.exams where slug='pmerj-2010-farmacia-bioquimica' on conflict(exam_id,number) do nothing;
