insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Fisiatria','A Medida de Independência Funcional (MIF) avalia 18 atividades básicas da vida diária, agrupadas em áreas funcionais. Identifique abaixo as categorias funcionais contempladas pela MIF.','','','["Cuidados pessoais, controle esfincteriano, transferências, locomoção, comunicação e cognição social.", "Cuidados pessoais, controle esfincteriano, locomoção, comunicação e cognição social.", "Cuidados pessoais, controle vesical, transferências, locomoção, comunicação e cognição social.", "Cuidados pessoais, controle esfincteriano, transferências, marcha, comunicação e cognição social."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa A. Resposta indicada no gabarito: Cuidados pessoais, controle esfincteriano, transferências, locomoção, comunicação e cognição social..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Fisiatria','O sinal de froment é positivo quando se realiza o movimento de pinça (segurando um pedaço de papel por exemplo) e ocorre a flexão da falange terminal do polegar. Esse sinal está presente na lesão do nervo','','','["mediano.", "ulnar.", "interósseo posterior.", "radial."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa B. Resposta indicada no gabarito: ulnar..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Fisiatria','Nas radiculopatias, é comum a ocorrência do seguinte achado eletroneuromiográfico:','','','["alteração da condução sensitiva.", "alteração da condução motora.", "fasciculações.", "sinais de desnervação."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa D. Resposta indicada no gabarito: sinais de desnervação..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Fisiatria','Leia o enunciado e as alternativas da questão 4 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-fisiatria-q04-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa A. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Fisiatria','Assinale os tipos possíveis de contração muscular durante o exercício.','','','["Contração concêntrica, isotônica e isométrica.", "Contração concêntrica, isocêntrica e isométrica.", "Contração isométrica, excêntrica e isotônica.", "Contração concêntrica, excêntrica e isométrica."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa D. Resposta indicada no gabarito: Contração concêntrica, excêntrica e isométrica..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Fisiatria','Existe contraindicação absoluta de calor terapêutico na presença de','','','["implantes metálicos.", "fraturas.", "marca-passos.", "anestesia térmica."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa D. Resposta indicada no gabarito: anestesia térmica..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Fisiatria','Identifique fontes de calor superficial e profundo respectivamente.','','','["Ultrassom / diatermia de ondas curtas.", "Infravermelho / microondas.", "Banho de parafina / forno de bier.", "Ultrassom / infravermelho."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa B. Resposta indicada no gabarito: Infravermelho / microondas..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Fisiatria','Atividade, segundo a Classificação Internacional de Funcionalidade, Incapacidade e Saúde, é a execução de uma tarefa ou ação por um indivíduo. Identifique, na lista abaixo, um exemplo de atividade.','','','["Percepção visual.", "Mastigar.", "Andar.", "Detectar som."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa C. Resposta indicada no gabarito: Andar..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Fisiatria','Ao prescrevermos uma órtese, devemos sempre levar em consideração o seguinte:','','','["imobilização, estética e alinhamento.", "imobilização versus mobilidade, conforto e alinhamento.", "mobilidade, sensibilidade álgica e alinhamento.", "imobilização, sensibilidade térmica e estética."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa B. Resposta indicada no gabarito: imobilização versus mobilidade, conforto e alinhamento..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Fisiatria','A presença de edema e hiperemia em membro inferior de um paciente com paraplegia por sequela de traumatismo raquimedular NÃO nos leva a pensar em','','','["fratura.", "trombose venosa profunda.", "ossificação heterotópica.", "disreflexia autonômica."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa D. Resposta indicada no gabarito: disreflexia autonômica..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Fisiatria','Podemos considerar leve um traumatismo crânioencefálico quando a pontuação na escala de Coma de Glasgow for ≥ 13, e quando','','','["a perda da consciência for menor que 30 minutos, não houver déficits neurológicos focais e não houver alterações nos exames de imagem.", "a perda da consciência for menor que 30 minutos e não houver déficits neurológicos focais.", "não houver déficits neurológicos focais e não houver alterações nos exames de imagem.", "a perda da consciência for menor que 60 minutos, não houver déficits neurológicos focais e não houver alterações nos exames de imagem."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa A. Resposta indicada no gabarito: a perda da consciência for menor que 30 minutos, não houver déficits neurológicos focais e não houver alterações nos exames de imagem..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Fisiatria','Assinale a afirmativa correta em relação à afasia.','','','["A afasia de broca é fluente, com diminuição da capacidade de repetição e boa compreensão.", "A afasia de Wernicke é não fluente, com diminuição da capacidade de repetição e diminuição da compreensão.", "A afasia de broca é não fluente, com diminuição da capacidade de repetição e boa compreensão.", "A afasia de Wernicke é fluente, com boa capacidade de repetição e diminuição da compreensão."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa C. Resposta indicada no gabarito: A afasia de broca é não fluente, com diminuição da capacidade de repetição e boa compreensão..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Fisiatria','Os tipos clínicos possíveis da encefalopatia crônica da infância são','','','["espástica, discinética, atáxica ou mista.", "espástica, cerebelar, apráxica ou mista.", "espástica, apráxica, atáxica ou mista.", "espástica, acinética, atáxica ou mista."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa A. Resposta indicada no gabarito: espástica, discinética, atáxica ou mista..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Fisiatria','Assinale a afirmativa correta em relação às síndromes clínicas encontradas na Esclerose Lateral Amiotrófica (ELA).','','','["Ocorre a associação das síndromes de Neurônio Motor Superior-NMS: (frontais e do tracto corticoespinhal) e Neurônio Motor Inferior-NMI (da medula espinhal).", "Ocorre a associação das síndromes de NMS (frontais e do tracto corticoespinhal) e NMI (do tronco cerebral).", "Ocorre a associação das síndromes de NMS (frontais e do tracto corticoespinhal) e NMI (do tronco cerebral e da medula espinhal).", "Ocorre a associação das síndromes de NMS (frontais, do tracto corticoespinhal e espinocerebelar) e NMI (da medula espinhal)."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa C. Resposta indicada no gabarito: Ocorre a associação das síndromes de NMS (frontais e do tracto corticoespinhal) e NMI (do tronco cerebral e da medula espinhal)..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
