insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Fisiatria','Quando comparamos os portadores de poliomielite com síndrome pós-pólio com aqueles sem esses sintomas, qual das seguintes afirmativas é verdadeira?','','','["A recuperação da força após exercício físico extenuante é pouco diferente entre os dois grupos.", "Os indivíduos sintomáticos têm maior força muscular.", "Os indivíduos sintomáticos têm uma história de maior comprometimento na época da doença inicial.", "Os achados eletromiográficos permitem a diferenciação clara entre os dois grupos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa C. Resposta indicada no gabarito: Os indivíduos sintomáticos têm uma história de maior comprometimento na época da doença inicial..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Fisiatria','Ao avaliar um paciente tetraplégico com nível C5, o que poderia ser considerada, respectivamente, uma alteração de estrutura, de atividade e de participação de acordo com a CIF (Classificação Internacional de Funcionalidade)?','','','["Acidente vascular encefálico, hemiplegia, uso de adaptações para AVDs.", "Mielite transversa, dor neuropática, bexiga neurogênica.", "Hérnia de disco cervical, hemiplegia, dor neuropática.", "Lesão medular traumática, alteração da marcha, adaptação para o transporte."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Fisiatria: alternativa D. Resposta indicada no gabarito: Lesão medular traumática, alteração da marcha, adaptação para o transporte..' from public.exams where slug='pmerj-2010-medico-fisiatria' on conflict(exam_id,number) do nothing;
