insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Ginecologia','Em paciente com suspeita clínica de doença inflamatória pélvica, a bacterioscopia corada pelo Gram não evidencia a presença de dipolococos gram- -negativos intracelulares. O agente etiológico presuntivo é','','','["Chlamydia trachomatis.", "Gardnerella vaginalis.", "Neisseria gonorrhoeae.", "Peptoestreptococos."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Ginecologia: alternativa A. Resposta indicada no gabarito: Chlamydia trachomatis..' from public.exams where slug='pmerj-2010-medico-ginecologia' on conflict(exam_id,number) do nothing;
