insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Hematologia','Em paciente com macroglobulinemia de Waldenström e síndrome de hiperviscosidade, é contraindicado o uso de','','','["agentes alquilantes.", "concentrado de hemácias.", "análogos das purinas.", "anticorpo monoclonal anti CD 20."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hematologia: alternativa B. Resposta indicada no gabarito: concentrado de hemácias..' from public.exams where slug='pmerj-2010-medico-hematologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Hematologia','Sobre a apresentação e evolução da Doença de Hodgkin, é correto afirmar:','','','["O comprometimento do fígado raramente ocorre sem comprometimento prévio do baço.", "O envolvimento dos linfonodos hílares ocorre previamente ao envolvimento do mediastino.", "Fibrose e infiltração da medula óssea são frequentes ao diagnóstico.", "Apresentação extranodal ocorre em 1/4 dos casos."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hematologia: alternativa A. Resposta indicada no gabarito: O comprometimento do fígado raramente ocorre sem comprometimento prévio do baço..' from public.exams where slug='pmerj-2010-medico-hematologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Hematologia','Na apresentação clínica habitual dos linfomas foliculares observa(m)-se','','','["esplenomegalia isolada.", "envolvimento primário de sítios extranodais.", "infiltração da medula óssea em cerca de metade dos casos.", "sintomas constitucionais frequentemente."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hematologia: alternativa C. Resposta indicada no gabarito: infiltração da medula óssea em cerca de metade dos casos..' from public.exams where slug='pmerj-2010-medico-hematologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Hematologia','São marcadores de mau prognóstico na leucemia linfoide crônica:','','','["ZAP 70 positiva e status mutado da cadeia pesada da imunoglobulina (IgVH).", "deleção 17 p e ZAP 70 negativa.", "status não mutado da IgVH e deleção 17 p.", "ZAP 70 negativa e status mutado da IgVH."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hematologia: alternativa C. Resposta indicada no gabarito: status não mutado da IgVH e deleção 17 p..' from public.exams where slug='pmerj-2010-medico-hematologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Hematologia','O exame de imunofixação nas gamopatias monoclonais está indicado para','','','["quantificar a imunoglobulina monoclonal.", "monitorizar a recaída de mieloma múltiplo.", "avaliação do prognóstico.", "dosar a concentração de cadeias leves no soro."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hematologia: alternativa B. Resposta indicada no gabarito: monitorizar a recaída de mieloma múltiplo..' from public.exams where slug='pmerj-2010-medico-hematologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Hematologia','O valor da Beta 2 microglobulina no mieloma múltiplo','','','["eleva-se com a piora da função renal.", "tem relação inversa com a massa tumoral.", "não tem correlação com a evolução do transplante autólogo de medula óssea.", "é um fator de mau prognóstico apenas para pacientes com função renal comprometida."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hematologia: alternativa A. Resposta indicada no gabarito: eleva-se com a piora da função renal..' from public.exams where slug='pmerj-2010-medico-hematologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Hematologia','O anticorpo monoclonal anti CD20, Rituximab, em associação com poliquimioterapia','','','["pode ser reutilizado nas recaídas de linfomas, pois não ocorre resistência.", "aumenta a sobrevida global dos pacientes com Linfoma de grandes células B difuso.", "induz apoptose apenas nas células malignas que expressam CD 20.", "aumenta o percentual de cura dos pacientes com Linfoma folicular."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hematologia: alternativa B. Resposta indicada no gabarito: aumenta a sobrevida global dos pacientes com Linfoma de grandes células B difuso..' from public.exams where slug='pmerj-2010-medico-hematologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Hematologia','Sobre os quimioterápicos antraciclínicos, é correto afirmar:','','','["Não há indicação de redução de doses se houver lesão hepática.", "São menos cardiotóxicos do que a Mitoxantrona.", "A cardiotoxicidade é uma reação idiossincrásica.", "Tem como mecanismo de ação a inibição da Topoisomerase II."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hematologia: alternativa D. Resposta indicada no gabarito: Tem como mecanismo de ação a inibição da Topoisomerase II..' from public.exams where slug='pmerj-2010-medico-hematologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Hematologia','A ausência de expressão de uma cadeia leve de imunoglobulina, kappa ou lambda, em sangue ou medula óssea, na citometria de fluxo, sugere a presença de doença','','','["inflamatória crônica.", "maligna de origem linfoide B.", "autoimune.", "maligna de origem linfoide T."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hematologia: alternativa B. Resposta indicada no gabarito: maligna de origem linfoide B..' from public.exams where slug='pmerj-2010-medico-hematologia' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-hemodinamica','PMERJ 2010 — Oficial — Médico Hemodinâmica','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Hemodinâmica','Em relação aos efeitos biológicos dos raios X, assinale a assertiva INCORRETA.','','','["Os efeitos estocásticos são os produzidos por danos irreparáveis ao DNA celular.", "O coeficiente de risco para indução de câncer em operadores e pacientes é de 5% a 10% por Sv da dose efetiva.", "Constituem danos determinísticos, descamação e câncer de pele, eritemas, atrofia dérmica e leucemias.", "Os efeitos determinísticos ocorrem quando um número significativo de células sofre danos suficientes para causar alterações observáveis."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: Constituem danos determinísticos, descamação e câncer de pele, eritemas, atrofia dérmica e leucemias.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Hemodinâmica','De acordo com os critérios do Academic Research Consortium, assinale a melhor definição para trombose de stent, respectivamente, quanto ao período de tempo após o implante e às categorias de evidência.','','','["Trombose aguda entre 0 e 24 horas - provável (qualquer óbito não explicado após 30 dias do implante).", "Trombose subaguda antes de 30 dias - provável (qualquer óbito não explicado nos primeiros 30 dias, sem confirmação angiográfica).", "Trombose tardia após 30 dias e até 1 ano - possível (qualquer óbito não explicado após 30 dias do implante).", "Trombose tardia após 1 ano - possível (qualquer infarto do miocárdio no território relacionado ao vaso tratado, sem confirmação angiográfica)."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: Trombose tardia após 30 dias e até 1 ano - possível (qualquer óbito não explicado após 30 dias do implante)..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Hemodinâmica','Na realização de arteriografia pulmonar em paciente com suspeita de tromboembolismo pulmonar, que conduta NÃO está indicada?','','','["Medir pressões no átrio, no ventrículo direito e na artéria pulmonar e, se a pressão sistólica da artéria for igual ou superior a 60 mmHg, suspender o exame.", "Utilizar contraste de baixa osmolaridade.", "Realizar duas injeções seletivas em cada artéria pulmonar, nas projeções PA e 45° (ipsilateral).", "Realizar punção da veia femoral, cateterismo cardíaco direito e arteriografia pulmonar com cateter pig tail."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: Medir pressões no átrio, no ventrículo direito e na artéria pulmonar e, se a pressão sistólica da artéria for igual ou superior a 60 mmHg, suspender o exame..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Hemodinâmica','Portador de insuficiência mitral apresentou, à ventriculografia, volumes diastólico e sistólico finais de 197 ml e 42 ml, respectivamente. O volume sistólico quantificado pelo método de Fick foi de 58 ml. Sobre o caso, assinale a assertiva INCORRETA.','','','["O volume de regurgitação por batimento é calculado pela equação (197 - 42) - 58.", "A fração de regurgitação é calculada pela divisão 58 ÷ 197.", "O volume sistólico quantificado pelo método de Fick é valor médio, enquanto o angiográfico é valor absoluto de um determinado ciclo cardíaco.", "Insuficiência mitral grau II, quantificada por angiografia, corresponde a uma fração de regurgitação entre 20% e 40%."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa B. Resposta indicada no gabarito: A fração de regurgitação é calculada pela divisão 58 ÷ 197.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Hemodinâmica','Em relação à hemostasia do acesso arterial femoral, assinale a assertiva correta.','','','["Em paciente com tempo de coagulação ativado inferior a 150 segundos, o introdutor arterial femoral pode ser retirado e a hemostasia, feita por compressão manual.", "A utilização de dispositivos percutâneos de hemostasia vascular reduz a taxa de ocorrência de pseudoaneurisma, porém não altera o risco de desenvolvimento de fístula arteriovenosa.", "O uso crônico de anticoagulantes orais contraindica o acesso femoral, mesmo quando há disponibilidade de dispositivos percutâneos de hemostasia vascular.", "Após hemostasia femoral por compressão manual, deve ser prescrito repouso no leito por 6 horas, independentemente do diâmetro do introdutor arterial."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: Em paciente com tempo de coagulação ativado inferior a 150 segundos, o introdutor arterial femoral pode ser retirado e a hemostasia, feita por compressão manual..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Hemodinâmica','As projeções axiais utilizadas em estudos angiográficos têm grande importância para a visualização de lesões em segmentos específicos das coronárias. Assim sendo, assinale a assertiva INCORRETA.','','','["A projeção OAD cranial não favorece a visualização das porções distais da coronária direita, dos ramos descendente posterior e ventricular(es) posterior(es).", "A projeção OAD cranial é adequada para avaliar as porções média e distal da descendente anterior porque evita a sobreposição de imagens dos ramos septais e diagonais.", "A projeção OAE cranial não é a mais indicada para visualizar a origem e as porções proximais da descendente anterior.", "A projeção OAE caudal é utilizada para visualizar adequadamente o tronco da coronária esquerda e as porções proximais da circunflexa."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: A projeção OAD cranial não favorece a visualização das porções distais da coronária direita, dos ramos descendente posterior e ventricular(es) posterior(es).. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Hemodinâmica','Homem de 64 anos apresentou angina de início recente. À angiografia, observou-se placa ateromatosa concêntrica e severa localizada no terço médio da artéria descendente anterior. O paciente foi submetido à angioplastia com implante de stent convencional 4,0 mm x 12 mm. Qual a probabilidade de nova revascularização da lesão nos próximos 4 anos?','','','["Igual ou inferior a 5%.", "Igual a 10%.", "Entre 15% e 20%.", "Superior a 20%."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: Igual ou inferior a 5%..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Hemodinâmica','Na hemorragia retroperitoneal pós- procedimento percutâneo, NÃO ocorre','','','["queda do volume globular.", "dor no flanco abdominal.", "dor ao fletir a coxa.", "rápida estabilização hemodinâmica com infusão de volume."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: rápida estabilização hemodinâmica com infusão de volume..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Hemodinâmica','Em relação às complicações do cateterismo cardíaco diagnóstico, considere as assertivas abaixo. I. As mais frequentes estão relacionadas ao local da introdução do cateter e são as principais responsáveis pela morbidade decorrente do procedimento. II. Trombose da artéria femoral ocorre, com mais frequência, nos portadores de pequeno lúmen arterial (mulheres, diabéticos e portadores de doença arterial periférica) e, especialmente, em procedimentos e compressões prolongados. III. O sangramento retroperitoneal está frequentemente associado à punção acima do ligamento inguinal. Quais são corretas?','','','["Apenas I.", "Apenas II.", "Apenas III.", "I, II e III."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: I, II e III..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Hemodinâmica','As imagens abaixo são de um paciente com diagnóstico anatômico de origem anômala independente das artérias descendente anterior (DA) e circunflexa (Cx) em torno do óstio da coronária direita tópica. Assinale a alternativa que preenche correta e respectivamente as lacunas da frase abaixo. Para atingir o septo interventricular anterior, a DA cursa o trajeto .........., e, para atingir o sulco atrioventricular esquerdo, a Cx cursa o trajeto .......... .','','["/pmerj-arquivo/pmerj-2010-medico-hemodinamica-q10-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-hemodinamica-q10-2-v3.png"]','["posterior à aorta - entre a aorta e a via de saída do ventrículo direito.", "entre a aorta e a via de saída do ventrículo direito - posterior à aorta.", "pelo septo interventricular - posterior à aorta.", "pelo septo interventricular - entre a aorta e a via de saída do ventrículo direito."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: pelo septo interventricular - posterior à aorta..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Hemodinâmica','Mulher de 65 anos procurou a emergência com quadro de dor precordial e sudorese profusa, iniciado há aproximadamente 6 horas. O eletrocardiograma evidenciou corrente de lesão subepicárdica de V1 a V5. A coronariografia foi normal. A ventriculografia, em diástole e sístole, revelou as imagens abaixo. Sobre o diagnóstico que o quadro e as imagens permitem estabelecer, assinale a assertiva INCORRETA.','','["/pmerj-arquivo/pmerj-2010-medico-hemodinamica-q11-1-v3.png"]','["Acomete preferencialmente mulheres (90%).", "Apresenta prognóstico reservado com mortalidade superior a 20%.", "Essa disfunção ventricular pode requerer o uso de balão de contrapulsação aórtica.", "Um dos critérios para o diagnóstico é ausência de aterosclerose coronariana obstrutiva à angiografia."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa B. Resposta indicada no gabarito: Apresenta prognóstico reservado com mortalidade superior a 20%.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Hemodinâmica','Assinale a assertiva INCORRETA acerca da trombose muito tardia (após 1 ano) decorrente do implante de stent farmacológico.','','','["Pode estar associada à inflamação crônica da parede.", "Pode ocorrer por uma reação de hipersensibilidade.", "Será evitada quando se prescrever antiagregante.", "Apresenta-se com altas taxas de morbidade e mortalidade."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: Será evitada quando se prescrever antiagregante.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Hemodinâmica','Com base em ensaios clínicos que compararam os stents convencionais com os farmacológicos, considere os fatores abaixo: I. Mortalidade II. Reestenose III. Necessidade de nova revascularização Qual (Quais) deles foi (foram) reduzido(s) significativamente pelos stents farmacológicos?','','','["Apenas I.", "Apenas II.", "Apenas III.", "Apenas II e III."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: Apenas II e III..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Hemodinâmica','Paciente foi internado com diagnóstico de infarto agudo do miocárdio com supradesnivelamento do segmento ST na parede anterior. À admissão, 32 horas após o início dos sintomas, encontrava-se sem dor precordial, razão pela qual se optou por tratamento conservador. Transcorridas 36 horas da hospitalização, apresentou piora rápida com hipotensão arterial sistêmica grave. A monitorização invasiva mostrou pressão capilar pulmonar de 32 mmHg e saturação de oxigênio na artéria pulmonar de 91%. Com base no quadro descrito, assinale a assertiva correta.','','','["O quadro clínico apresentado sugere a possibilidade de cirurgia de urgência, cuja indicação pode ser confirmada pelos achados angiográficos.", "A realização de ventriculografia esquerda durante o procedimento diagnóstico está contraindicada, pois não contribui para o esclarecimento diagnóstico.", "Para evitar demora no tratamento, deve-se iniciar a cateterização da coronária esquerda. Caso a artéria descendente anterior esteja ocluída, deve ser prontamente realizada a angioplastia.", "O quadro clínico descrito representa uma contraindicação relativa ao uso de balão intra-aórtico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: O quadro clínico apresentado sugere a possibilidade de cirurgia de urgência, cuja indicação pode ser confirmada pelos achados angiográficos..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Hemodinâmica','Em relação ao infarto agudo do miocárdio (IAM) do ventrículo direito tratado por intervenção coronariana percutânea, considere as assertivas abaixo: I. Não é um fator de risco independente para aumento da mortalidade. II. Apresenta taxa de mortalidade hospitalar aos 30 dias e aos 6 meses maior do que a do IAM da parede anterior. III. A reperfusão completa da coronária direita e do ramo marginal direito deve ser um dos objetivos da angioplastia transluminal coronariana primária, pois se associa com melhora da função contrátil do ventrículo direito, com diminuição da mortalidade aos 30 dias.  Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "II e III apenas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: II e III apenas.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Hemodinâmica','Homem de 62 anos, com diagnóstico prévio de doença coronariana de 2 vasos e angina estável classe III, foi encaminhado para angioplastia coronariana eletiva. Após a inserção do introdutor arterial, recebeu 5.000 unidades de heparina por via intravenosa seguida da administração de tirofibano em bolo e em infusão contínua. O tempo de coagulação ativada era de 320 segundos. Após a pré-dilatação inicial da coronária descendente anterior (DA), observou-se extensa dissecção retrógrada espiral do vaso até o tronco da coronária esquerda, comprometendo significativamente o fluxo anterógrado da DA. O paciente tornou-se hipotenso e passou a apresentar supradesnivelamento do segmento ST na parede anterior. Sobre esse caso, assinale a assertiva correta.','','','["A administração de fluidos por via intravenosa é suficiente para reverter o quadro clínico.", "Deve-se administrar protamina para reverter os efeitos da heparina.", "Cirurgia de revascularização não constitui boa alternativa frente à administração de antagonista dos receptores da glicoproteína IIb/IIIa pelo risco de hemorragia.", "Se não houver ocorrido perfuração coronariana e o fio-guia estiver no lúmen arterial verdadeiro, devem ser tomadas medidas na tentativa de recuperar o fluxo arterial através do implante de stents, visando a selar a dissecção."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: Se não houver ocorrido perfuração coronariana e o fio-guia estiver no lúmen arterial verdadeiro, devem ser tomadas medidas na tentativa de recuperar o fluxo arterial através do implante de stents, visando a selar a dissecção..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Hemodinâmica','Em relação ao uso de clopidogrel em pacientes submetidos a implante de stent coronariano, assinale a assertiva correta.','','','["O tratamento com 300 mg, pelo menos 6 horas antes do procedimento, não apresenta vantagens quando comparado à administração da mesma dose no momento do procedimento, exceto em pacientes com síndrome coronariana aguda.", "Não há evidência de benefício em estender seu uso por 9 meses, exceto em caso de implante de stents farmacológicos.", "A dose de ataque com 600 mg administrada no momento do procedimento é uma boa alternativa para pacientes que não receberam pré-tratamento com 300 mg.", "O risco de trombose tardia dos stents farmacológicos é semelhante ao dos stents convencionais, e, portanto, o uso de clopidogrel deve ser mantido por 3 meses."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: A dose de ataque com 600 mg administrada no momento do procedimento é uma boa alternativa para pacientes que não receberam pré-tratamento com 300 mg..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Hemodinâmica','Considere as assertivas abaixo: I. A infusão de acetilcolina em uma artéria coronária com função endotelial normal produz vasodilatação. II. A infusão de nitroprussiato de sódio em uma artéria coronária com disfunção endotelial produz vasodilatação. III. A infusão de nitroglicerina em uma artéria coronária com disfunção endotelial produz vasodilatação. Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "I, II e III."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: I, II e III..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Hemodinâmica','Quanto à anticoagulação com enoxaparina em angioplastias de pacientes não previamente anticoagulados, considere as assertivas abaixo: I. A administração de 1 mg/kg, por via subcutânea, a cada 12 horas, permite que se realize a angioplastia coronariana dentro das primeiras 12 horas, após a última dose. II Na angioplastia eletiva, a dose de 0,5 mg/kg, por via intravenosa, mostrou-se efetiva e segura. III. Na angioplastia primária, a dose de 0,5 mg/kg, por via intravenosa, é adequada para a realização do procedimento com segurança.  Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "II e III apenas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: II e III apenas..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Hemodinâmica','Em relação aos efeitos dos raios X na prática médica, assinale a assertiva correta.','','','["A dose máxima de radiação tolerada para profissionais que trabalham em laboratório de hemodinâmica é de 75 Sv/ano.", "A dose máxima de radiação recomendada para o cristalino, pelo risco do desenvolvimento de catarata, é de 10 rem/ano.", "Efeitos determinísticos da radiação ionizante são dose-dependentes e incluem supressão da medula óssea (hematopoiese); efeitos não determinísticos provocam dano direto ao DNA celular e englobam diversos tipos de neoplasias.", "No que diz respeito à absorção de radiação, não há diferença entre as diversas projeções ortogonais; a radiação emitida depende unicamente do tempo de fluoroscopia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: Efeitos determinísticos da radiação ionizante são dose-dependentes e incluem supressão da medula óssea (hematopoiese); efeitos não determinísticos provocam dano direto ao DNA celular e englobam diversos tipos de neoplasias..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Hemodinâmica','Em qual das posições abaixo a glândula tireoide do operador receberá maior quantidade de irradiação?','','','["OAD 15º e caudal 25º.", "OAE 90º.", "OAD 40º e cranial 10º.", "OAE 30º."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa B. Resposta indicada no gabarito: OAE 90º..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Hemodinâmica','A curva pressórica abaixo foi obtida durante estudo hemodinâmico. Qual a provável patologia do paciente? LV: ventrículo esquerdo. FA: artéria femoral.','','["/pmerj-arquivo/pmerj-2010-medico-hemodinamica-q22-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-hemodinamica-q22-2-v3.png"]','["Pericardite constritiva com repercussão hemodinâmica significativa.", "Miocardiopatia hipertrófica obstrutiva.", "Traçado pressórico normal com provável interferência negativa decorrente da presença de contraste no cateter.", "Estenose valvar aórtica moderada a importante."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa B. Resposta indicada no gabarito: Miocardiopatia hipertrófica obstrutiva..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Hemodinâmica','Considere os dados angiográficos abaixo: • Diâmetro de referência do vaso = 3,0 mm. • Diâmetro luminal mínimo pré-intervenção = 1,2 mm. • Diâmetro luminal mínimo pós-intervenção = 2,0 mm. • Diâmetro luminal mínimo no reestudo angiográfico após 9 meses = 1,6 mm. O índice de perda tardia (late loss index) é de','','','["0,13.", "0,4.", "0,5.", "0,8."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: 0,5..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Hemodinâmica','A complicação mais frequentemente relacionada à punção da artéria femoral, distal à sua bifurcação, após a remoção da bainha, é','','','["formação de pseudoaneurisma.", "fístula arteriovenosa.", "hematoma retroperitoneal.", "choque hipovolêmico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: formação de pseudoaneurisma..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Hemodinâmica','Sobre as anomalias das artérias coronárias, assinale a assertiva INCORRETA.','','','["A origem de todas as artérias coronárias de um único seio de Valsalva compromete a perfusão miocárdica.", "A origem da coronária esquerda do seio de Valsalva direito pode comprometer a perfusão miocárdica.", "A origem anterior alta da artéria coronária direita não compromete a perfusão miocárdica.", "A origem da artéria circunflexa do seio de Valsalva direito não compromete a perfusão miocárdica."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: A origem de todas as artérias coronárias de um único seio de Valsalva compromete a perfusão miocárdica.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Hemodinâmica','A respeito das malformações congênitas que acometem o trato de saída do ventrículo esquerdo, considere as assertivas abaixo: I. Valva aórtica bicúspide é uma malformação congênita pouco frequente. II. Anormalidades da valva aórtica podem ser associadas com malformações do aparelho valvar mitral, do ventrículo esquerdo e do arco aórtico. III. A estenose aórtica em túnel está relacionada com a síndrome de Williams. Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "I e II apenas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa B. Resposta indicada no gabarito: II apenas..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Hemodinâmica','Em relação ao tratamento endovascular dos aneurismas da aorta abdominal, considere as assertivas abaixo: I. Deve ser reservado para pacientes de baixo risco cirúrgico e boa anatomia. II. Apresenta melhores resultados do que o tratamento cirúrgico mesmo nos seguimentos de longo prazo. III. Vazamento (endoleak) dos tipos I ou III é de mau prognóstico e deve ser corrigido. Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "I e II apenas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: III apenas..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Hemodinâmica','Em relação às propriedades físico-químicas das substâncias contrastantes e a seus efeitos clínicos, assinale a assertiva correta.','','','["Os contrastes iônicos com alta osmolaridade têm menor potencial de trombogenicidade.", "Os contrastes iônicos de baixa osmolaridade são menos nefrotóxicos que os isosmolares.", "Os contrastes não iônicos de baixa osmolaridade são os mais nefrotóxicos.", "Os contrastes não iônicos e isosmolares têm menor potencial de trombogenicidade."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: Os contrastes iônicos com alta osmolaridade têm menor potencial de trombogenicidade..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Hemodinâmica','Em relação à oferta e ao consumo de oxigênio pelo miocárdio, assinale a assertiva correta.','','','["O aumento da extração de oxigênio pelo miocárdio exerce papel pouco relevante para compensar a redução do fluxo coronariano.", "Na doença coronariana, o fluxo miocárdico é influenciado pela redução do calibre da artéria coronária, mas não é afetado pelo comprimento da lesão.", "A reserva de fluxo coronariano não é afetada pelo consumo basal de oxigênio pelo miocárdio.", "O fluxo miocárdico normal é predominantemente diastólico e semelhante nas artérias coronárias esquerda e direita."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: O aumento da extração de oxigênio pelo miocárdio exerce papel pouco relevante para compensar a redução do fluxo coronariano..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Hemodinâmica','Sobre o ciclo cardíaco normal, considere as assertivas abaixo: I. Na fase de contração isovolumétrica, o volume e o formato da câmara ventricular esquerda são constantes, tendo em vista que as valvas atrioventriculares e semilumares estão fechadas. II. O fluxo aórtico máximo ocorre aproximadamente 100 ms após o início da sístole ventricular esquerda, coincidindo com o pico máximo da pressão sistólica aórtica. III. Estudos com fluxômetros eletromagnéticos confirmam que, na fase de relaxamento isovolumétrico, ocorre pequeno acréscimo no volume ventricular esquerdo, demonstrando reversão do fluxo aórtico no momento do fechamento dessa valva. Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "I e III apenas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: III apenas..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Hemodinâmica','Considere as assertivas abaixo sobre avaliação da função endotelial no Laboratório de Hemodinâmica: I. A resposta fisiológica normal ao aumento da demanda miocárdica é o aumento do fluxo coronariano, que é alcançado por vasodilatação dos vasos epicárdicos mediada por mecanismo não dependente do endotélio e dos vasos de resistência mediada por mecanismo dependente do endotélio. II. Disfunção endotelial pode se manifestar por aumento não significativo, ausência de alteração ou mesmo redução do fluxo sanguíneo coronariano. III. Acetilcolina é comumente utilizada para avaliar a regulação do tono vasomotor dependente do endotélio. A estimulação de seus receptores produz dilatação uniforme dependente do endotélio nos vasos coronários de todos os calibres. Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "II e III apenas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: II e III apenas..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Hemodinâmica','Constituem contraindicações para valvoplastia mitral percutânea:','','','["trombose do átrio esquerdo (septo), ecoescore superior a 9 pontos e distúrbios da coagulação.", "calcificação bicomissural importante, insuficiência mitral importante e trombose do átrio esquerdo (septo).", "distúrbios da coagulação, doença coronariana grave associada que necessite de revascularização cirúrgica e insuficiência aórtica leve.", "insuficiência mitral leve a moderada, trombose do átrio esquerdo e ecoescore superior a 12 pontos."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa B. Resposta indicada no gabarito: calcificação bicomissural importante, insuficiência mitral importante e trombose do átrio esquerdo (septo)..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Hemodinâmica','Abaixo estão reproduzidas imagens de valvoplastia mitral percutânea (VMP) para serem analisadas. Assinale a assertiva que NÃO se correlaciona com a técnica utilizada.','','["/pmerj-arquivo/pmerj-2010-medico-hemodinamica-q33-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-hemodinamica-q33-2-v3.png"]','["A ocorrência de perfuração do ventrículo esquerdo é equivalente nas técnicas de VMP com duplo-balão e com balão de Inoue.", "As modificações incorporadas no desenho dos cateteres-balão utilizados representam um avanço tecnológico que facilita a execução da VMP com duplo-balão.", "A ocorrência ou o aumento do grau de insuficiência mitral é maior na VMP com balão de Inoue.", "O ganho médio de aumento na área valvar é equivalente nas séries de pacientes tratados com VMP com duplo-balão e com balão de Inoue."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: A ocorrência de perfuração do ventrículo esquerdo é equivalente nas técnicas de VMP com duplo-balão e com balão de Inoue..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Hemodinâmica','Acerca dos aneurismas da aorta abdominal (AAAs), assinale a assertiva correta.','','','["Considera-se AAA quando o diâmetro ultrapassar 5,5 cm.", "São mais prevalentes em pacientes com doença pulmonar crônica e o ritmo de crescimento é mais acelerado naqueles em uso de corticosteroides.", "Homens com mais de 60 anos devem ser submetidos a avaliação ultrassonográfica anual para detecção de dilatação da aorta infrarrenal.", "AAAs com menos de 4,0 cm de diâmetro devem ser avaliados anualmente com ultrassonografia abdominal."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa B. Resposta indicada no gabarito: São mais prevalentes em pacientes com doença pulmonar crônica e o ritmo de crescimento é mais acelerado naqueles em uso de corticosteroides..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Hemodinâmica','Analise a imagem ultrassonográfica intracorona- riana abaixo e assinale a assertiva correta.','','["/pmerj-arquivo/pmerj-2010-medico-hemodinamica-q35-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-hemodinamica-q35-2-v3.png"]','["A imagem mostra placa aterosclerótica com características de alto risco de ruptura.", "Os achados são compatíveis com discreta a moderada hiperplasia neointimal intra- stent.", "Há evidência de dissecção intimal, sem comprometimento significativo do lúmen.", "A imagem é tipicamente encontrada em segmentos de referência, com angiografia normal ou quase normal."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: A imagem é tipicamente encontrada em segmentos de referência, com angiografia normal ou quase normal..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Hemodinâmica','Em pacientes portadores de oclusão crônica submetidos à tentativa de recanalização, qual dos fatores abaixo é o maior preditor de mortalidade a longo prazo?','','','["Insuficiência renal crônica.", "Diabetes melito.", "Doença multiarterial.", "Insucesso no procedimento."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: Insucesso no procedimento..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Hemodinâmica','Assinale a assertiva correta em relação ao uso de dispositivo de proteção distal durante intervenções coronarianas percutâneas envolvendo pontes de safena, discutido no estudo SAFER.','','','["O índice de eventos cardíacos adversos maiores foi menor no grupo controle do que no grupo que utilizou o dispositivo de proteção distal.", "Não houve diferença nos objetivos primários do estudo em relação aos dois grupos comparados.", "A utilização de inibidores da glicoproteína IIb/IIIa não teve influência no resultado final do estudo.", "O índice de complicações decorrentes do procedimento foi maior no grupo que utilizou o dispositivo de proteção distal do que no grupo controle."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: A utilização de inibidores da glicoproteína IIb/IIIa não teve influência no resultado final do estudo..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Hemodinâmica','Quanto aos dispositivos de proteção distal para revascularização percutânea de enxertos de veia safena e artéria coronária nativa, assinale a assertiva correta.','','','["Os dispositivos que promovem a oclusão distal transitória por balão apresentam segurança e eficácia semelhantes às dos filtros.", "Podem evitar a elevação de marcadores de necrose miocárdica, como a creatinoqui- nase, e reduzir consideravelmente a mortalidade nesse subgrupo de pacientes, independentemente da idade do enxerto.", "Os dispositivos filtros não apresentam risco de embolização durante o cruzamento da lesão-alvo.", "Os dispositivos oclusores geralmente apresentam perfil mais alto do que os filtros, o que pode dificultar sua aplicação."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: Os dispositivos que promovem a oclusão distal transitória por balão apresentam segurança e eficácia semelhantes às dos filtros..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Hemodinâmica','Em relação ao diagnóstico hemodinâmico de pericardite constritiva, considere as assertivas abaixo. I. Normalmente há equalização das pressões diastólicas observadas nos ventrículos esquerdo e direito. II. As pressões, no átrio direito, habitualmente se situam nos limites normais. III. O débito cardíaco está sempre reduzido, mesmo em estados hiperdinâmicos. Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "I, II e III."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: I apenas..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Hemodinâmica','Acerca do tratamento endovascular das estenoses arteriais dos membros inferiores, considere as assertivas abaixo. I. Deve ser aplicado para pacientes assintomáticos com estenose grave como profilaxia de eventos futuros. II. Deve ser indicado para as lesões TASC (TransAtlantic Inter-Society Consensus) A, B e C. III. As estenoses das artérias ilíacas com boa anatomia podem ser tratadas com implante de stent ou angioplastia convencional com stent provisional. Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "I, II e III."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: III apenas..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Hemodinâmica','Considere as indicações para realização de ultrassonografia intravascular propostas abaixo: I. Verificação das características da lesão e das dimensões da artéria para selecionar o melhor dispositivo, visando à intervenção percutânea. II. Verificação de resultado subótimo após intervenção coronariana percutânea. III. Avaliação do grau de obstrução coronariana em local de difícil visualização à angiografia em paciente sintomático. Assinale a opção que corresponde a indicações classe IIa.','','','["I apenas.", "II apenas.", "III apenas.", "II e III apenas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: II e III apenas..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Hemodinâmica','Considere os eventos abaixo: I. Acentuada queda no gradiente sistólico basal ou induzido na via de saída do ventrículo esquerdo, com manutenção dos resultados obtidos com o procedimento, tanto na evolução imediata como na tardia. II. Aumento do VO2 máx, da pressão de perfusão coronariana e do relaxamento ventricular. III. Desenvolvimento de infarto de parede anterior por refluxo de álcool para a artéria descendente anterior como complicação de maior prevalência. Qual (Quais) deles pode(m) ocorrer no tratamento eficaz da miocardiopatia hipertrófica obstrutiva por ablação percutânea com álcool?','','','["Apenas I.", "Apenas II.", "Apenas III.", "Apenas I e II."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: Apenas I e II..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Hemodinâmica','Assinale a assertiva INCORRETA com relação ao fenômeno de no-reflow.','','','["A administração intracoronariana de vasodilatadores da microcirculação, tais como adenosina, verapamil e nitroprussiato de sódio, pode resultar em melhora do fluxo sem que isso se traduza em aumento da sobrevida do paciente.", "A ocorrência de no-reflow é particularmente elevada em procedimentos realizados em pontes de safena ou infarto agudo do miocárdio.", "Por tratar-se de espasmo da microcirculação, o uso de dispositivos de proteção distal não resulta em benefício clínico, a despeito de uma melhora angiográfica do fluxo anterógrado.", "O emprego rotineiro de dispositivos de aspiração de trombos não está indicado para o infarto agudo do miocárdio com vistas à redução da ocorrência de no- reflow."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: Por tratar-se de espasmo da microcirculação, o uso de dispositivos de proteção distal não resulta em benefício clínico, a despeito de uma melhora angiográfica do fluxo anterógrado.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Hemodinâmica','Acerca das complicações da angioplastia coronariana, considere as assertivas abaixo: I. É pouco frequente a ocorrência de infarto do miocárdio devido à oclusão aguda da artéria ou perda de ramo importante que esteja no interior da lesão ou próximo a ela pelo efeito snowplow. II. Nas perfurações coronarianas, o paciente deve ser imediatamente submetido a tratamento cirúrgico. III. Não é mais recomendável o implante rotineiro de marca-passo endocárdico temporário nas angioplastias transluminais da coronária direita pela baixa incidência  de bradiarritmias severas (< 1%) e pela possibilidade de tamponamento cardíaco por perfuração do ventrículo direito. Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "I e III apenas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: I e III apenas.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Hemodinâmica','Qual dos fatores abaixo NÃO pode ser considerado preditor de oclusão aguda após intervenção coronariana percutânea?','','','["Ponte de veia safena degenerada.", "Lesão reestenótica proliferativa.", "Trombo intraluminal.", "Angina instável."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa B. Resposta indicada no gabarito: Lesão reestenótica proliferativa..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Hemodinâmica','Considere as variáveis abaixo: I. Idade inferior a 1 ano II. Obstrução significativa do tronco da artéria coronária esquerda III. Disfunção ventricular esquerda com fração de ejeção inferior a 50%. Assinale a alternativa que apresenta variáveis independentes para aumento da mortalidade em pacientes submetidos a cateterismo cardíaco.','','','["I apenas.", "II apenas.", "III apenas.", "I e II apenas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa D. Resposta indicada no gabarito: I e II apenas..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Hemodinâmica','Considere as assertivas abaixo em relação ao espasmo coronariano durante procedimento hemodinâmico invasivo: I. Deve-se administrar, por via intracorona- riana, dose inicial de 1 mg de nitroglicerina. II. Nos espasmos acompanhados de hipotensão e bradicardia, mas sem sinais de isquemia miocárdica, deve-se administrar atropina. III. O uso intracoronariano de antagonistas do cálcio, como verapamil, para o tratamento do espasmo deve ser sempre acompanhado do implante de marca-passo endocárdico temporário. Está correto o que se afirma em','','','["I apenas.", "II apenas.", "III apenas.", "I e II apenas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa B. Resposta indicada no gabarito: II apenas..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Hemodinâmica','Em relação ao tratamento percutâneo de lesões em pontes de safena, assinale a assertiva correta.','','','["A taxa de reestenose de stents convencionais não difere significativamente daquela obtida com angioplastia com balão.", "O uso de antagonistas dos receptores IIb/IIIa pode reduzir significativamente a probabilidade de ocorrência de no-reflow.", "Os dispositivos de proteção embólica, apesar de reduzirem a ocorrência de no- reflow, não diminuem a taxa de complicações como infarto do miocárdio e/ou mortalidade pós-implante de stents.", "A ocorrência do fenômeno de no-reflow é semelhante, em termos de incidência, àquela encontrada em casos de infarto agudo do miocárdio."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa A. Resposta indicada no gabarito: A taxa de reestenose de stents convencionais não difere significativamente daquela obtida com angioplastia com balão..' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Hemodinâmica','Qual a causa mais comum de insucesso na recanalização de uma oclusão crônica?','','','["Entrada da corda-guia metálica em plano de dissecção subintimal.", "Impossibilidade de dilatar a lesão com balão.", "Impossibilidade de ultrapassar o segmento ocluído", "Impossibilidade de implante de stent."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa C. Resposta indicada no gabarito: Impossibilidade de ultrapassar o segmento ocluído.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Hemodinâmica','Leia o enunciado e as alternativas da questão 50 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-hemodinamica-q50-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemodinâmica: alternativa B. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-hemodinamica' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-hemoterapia','PMERJ 2010 — Oficial — Médico Hemoterapia','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Hemoterapia','De acordo com a RDC 153 de 14 de junho de 2004, o sangue total e seus componentes não podem ser transfundidos antes da obtenção de resultados finais não reagentes, nos testes de detecção para','','','["hepatites B e C; HIV-1 e HIV-2; HTLV-I e HTLV-II; CMV; Trypanosoma cruzi.", "hepatites B e C; HIV-1 e HIV-2; HTLV-I e HTLV-II; Trypanosoma cruzi; Treponema pallidum.", "hepatites B e C; HIV-1 e HIV-2; HTLV-I e HTLV-II; CMV; Parvoviridae linear.", "hepatites B e C; HIV-1 e HIV-2; HTLV-I e HTLV-II; HPV-8; Trypanosoma cruzi."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa B. Resposta indicada no gabarito: hepatites B e C; HIV-1 e HIV-2; HTLV-I e HTLV-II; Trypanosoma cruzi; Treponema pallidum..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Hemoterapia','Para prevenir a doença enxerto versus hospedeiro secundária à transfusão sanguínea, o hemocomponente deverá sofrer','','','["leucorredução.", "lavagem.", "tratamento com violeta de genciana.", "irradiação."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: irradiação..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Hemoterapia','A globulina anti-humana do tipo poliespecífica para uso de rotina deve conter obrigatoriamente','','','["anti-IgG e anti-C3a.", "anti-IgM e anti-C3b.", "anti-IgG e anti-C3c.", "anti-IgG e anti-C3d."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: anti-IgG e anti-C3d..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Hemoterapia','Em relação aos antígenos do sistema de histogrupo sanguíneo ABO no ser humano, é correto afirmar que','','','["os antígenos ABO estão presentes nas hemácias do embrião a partir da nona- décima semana de gestação, apresentando expressão eritrocitária máxima a partir dos dois anos de vida.", "os antígenos ABO estão presentes nas hemácias do embrião a partir da quinta- sexta semana de gestação, apresentando expressão eritrocitária máxima a partir do nascimento.", "os antígenos ABO estão presentes nas hemácias do embrião a partir da quinta- sexta semana de gestação, apresentando expressão eritrocitária máxima a partir dos dezoito meses de vida.", "os antígenos ABO estão presentes nas hemácias do embrião a partir da nona- décima semana de gestação, apresentando expressão eritrocitária máxima a partir dos seis meses de vida."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: os antígenos ABO estão presentes nas hemácias do embrião a partir da quinta- sexta semana de gestação, apresentando expressão eritrocitária máxima a partir dos dezoito meses de vida..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Hemoterapia','Em relação à transfusão autóloga pré-operatória, NÃO é correto afirmar:','','','["São contraindicações absolutas a insuficiência cardíaca descompensada, a angina pectoris instável e a presença de infecção ativa ou tratamento antimicrobiano.", "Não há limites de idade para as doações autólogas.", "O intervalo entre cada doação autóloga pode ser inferior a sete dias.", "No sangue autólogo, obtido de um doador- -paciente, devem ser realizadas a detecção de anticorpos irregulares e as provas para doenças transmissíveis. O doador-paciente e o seu médico devem ser notificados sobre qualquer anormalidade."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: O intervalo entre cada doação autóloga pode ser inferior a sete dias.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Hemoterapia','Assinale a afirmativa INCORRETA.','','','["É obrigatória a investigação de hemoglobina S e de outras hemoglobinas anormais nos doadores de sangue. Os componentes eritrocitários de doadores com pesquisa de hemoglobina S positiva devem conter esta informação no seu rótulo, mas não precisam ser descartados. Esses componentes não devem ser deleucocitados.", "O sangue total e o concentrado de hemácias irradiado podem ser utilizados até, no máximo, 28 dias após a data da irradiação, desde que a validade original do componente seja respeitada. Os concentrados de plaquetas e os concentrados de granulócitos irradiados mantêm as suas datas de validade original.", "Quanto ao tipo, a transfusão pode ser classificada em: \"Programada\", para determinado dia e hora; \"Não urgente\", a se realizar dentro das 24 horas; \"Urgente\", a realizar dentro das 3 horas ou \"De extrema urgência\", quando o retardo na administração da transfusão pode acarretar risco para a vida do paciente.", "A liberação de sangue total ou concentrado de hemácias sem provas de compatibilidade pode ser feita, desde que o quadro clínico do paciente justifique a extrema urgência, isto é, quando o retardo no início da transfusão puder levar o paciente ao óbito. Nesse caso, as provas pré-transfusionais não necessitam ser realizadas até o final, se a transfusão já tiver sido completada."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: A liberação de sangue total ou concentrado de hemácias sem provas de compatibilidade pode ser feita, desde que o quadro clínico do paciente justifique a extrema urgência, isto é, quando o retardo no início da transfusão puder levar o paciente ao óbito. Nesse caso, as provas pré-transfusionais não necessitam ser realizadas até o final, se a transfusão já tiver sido completada.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Hemoterapia','Em relação ao sistema de grupo sanguíneo Lewis entre europeus e seus descendentes, NÃO é correto afirmar:','','','["Indivíduos não secretores de ABH são portadores do fenótipo eritrocitário Le(a+b-).", "Indivíduos secretores de ABH são portadores do fenótipo eritrocitário Le(a-b+).", "O fenótipo eritrocitário Le(a-b-) tanto pode ser encontrado em indivíduos secretores como não secretores de ABH.", "O fenótipo eritrocitário Le(a-b-) é observado apenas em indivíduos não secretores de ABH."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: O fenótipo eritrocitário Le(a-b-) é observado apenas em indivíduos não secretores de ABH.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Hemoterapia','A triagem sorológica dos hemocomponentes diminui o risco de acidentes transfusionais. Em relação aos procedimentos empregados, assinale a afirmativa correta.','','','["O hemocomponente que apresentar reatividade para anti-HbcAg da classe IgG associado à reatividade do anti-HbsAg poderá ser liberado para uso transfusional.", "Os testes de triagem sorológica devem ser realizados em duplicata. Caso reagente, o teste deverá ser repetido.", "A técnica de hibridização é mandatória para confirmação de reatividade para anti- HCV.", "Os testes sorológicos para detecção de agentes infecciosos devem possuir as características de elevada sensibilidade e especificidade, produzindo resultados rápidos e seguros."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: Os testes sorológicos para detecção de agentes infecciosos devem possuir as características de elevada sensibilidade e especificidade, produzindo resultados rápidos e seguros..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Hemoterapia','Qual o fenótipo ABO do indivíduo que apresenta os seguintes resultados? Classificação Classificação direta reversa Saliva Reagentes anti- Hemácias -A -B -A,B -A1 -H A1 A2 B O secretor 4 0 4 2 3 0 0 4 0 de A e H 0, ausência de aglutinação; 2-4, diferentes intensidades de aglutinação positiva.','','','["Ay.", "Ax.", "Aint.", "Am."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: Aint..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Hemoterapia','A principal causa de perda de consciência associada à bradicardia durante a doação de sangue é','','','["arritmia sinusal.", "efeito vasovagal.", "hipotensão arterial.", "taquicardia supraventricular."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa B. Resposta indicada no gabarito: efeito vasovagal..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Hemoterapia','O fenótipo eritrocitário Fy(a-b-) na maior parte dos indivíduos está implicado com','','','["ausência de glicoproteína Duffy em todas as células do organismo.", "incidência aumentada de malária pós- -transfusional.", "mutação em ponto na região promotora do alelo FY*B que impede a transcrição do gene em células eritroides.", "mutação em ponto no alelo FY*B (C265T→Arg89Cys) que condiciona um enfraquecimento do antígeno eritrocitário Fyb."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: mutação em ponto na região promotora do alelo FY*B que impede a transcrição do gene em células eritroides..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Hemoterapia','Baseando-se na RDC 153/2004, assinale a afirmativa INCORRETA.','','','["Em cirurgias eletivas, o procedimento preferencial é a transfusão autóloga e as bolsas de sangue coletadas poderão conter o nome completo do paciente.", "A presença de anticorpos irregulares em um concentrado de hemácias não impede que essa unidade seja liberada para uso transfusional.", "A técnica de PCR (“polymerase chain reaction”) é empregada de rotina nos Serviços de Hemoterapia para diagnóstico de agentes infecciosos transmissíveis pelo sangue.", "Concentrados de hemácias com hemoglobina S presente devem ser evitados para transfusão em pacientes portadores de hemoglobinopatias, pacientes com acidose grave, em recém- nascidos ou intrauterina."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: A técnica de PCR (“polymerase chain reaction”) é empregada de rotina nos Serviços de Hemoterapia para diagnóstico de agentes infecciosos transmissíveis pelo sangue.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Hemoterapia','Em relação à validade dos diferentes componentes sanguíneos, NÃO é correto afirmar que','','','["o sangue total e o concentrado de hemácias irradiado podem ser utilizados até, no máximo, 21 dias após a data da irradiação, desde que a validade original do componente seja respeitada.", "a data de vencimento para as hemácias congeladas à temperatura de -65 ºC ou inferior é de 10 anos, a partir da data da flebotomia. Após o descongelamento, as hemácias podem ser usadas em até 24 horas.", "a validade de um concentrado de hemácias lavadas expira 24 horas depois de sua obtenção.", "a validade de um concentrado de hemácias pobre em leucócitos é a mesma do sangue total que lhe deu origem, quando preparado em circuito fechado. Se o sistema for aberto, a validade expira 24 horas depois de aberto o sistema."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa A. Resposta indicada no gabarito: o sangue total e o concentrado de hemácias irradiado podem ser utilizados até, no máximo, 21 dias após a data da irradiação, desde que a validade original do componente seja respeitada.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Hemoterapia','Quando um paciente apresenta anticorpo(s) irregular(es) clinicamente significativo(s) ou apresenta uma história prévia de presença de anticorpo(s) irregular(es), as hemácias a serem transfundidas devem','','','["obrigatoriamente ser compatíveis.", "não possuir o(s) antígeno(s) para o(s) qual(is) o paciente apresenta anticorpos circulantes.", "ser compatíveis e carecer dos antígenos correspondentes.", "ser compatíveis, independente da presença do(s) antígeno(s) correspondente(s)."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: ser compatíveis e carecer dos antígenos correspondentes..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Hemoterapia','Constitui contraindicação definitiva para doação de sangue o uso de','','','["hormônio de crescimento de origem humana.", "anti-inflamatórios e ácido acetil salicílico.", "inibidores de enzima conversora de angioten- sina.", "vasodilatadores e antiarrítmicos."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa A. Resposta indicada no gabarito: hormônio de crescimento de origem humana..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Hemoterapia','Em relação ao transporte de sangue, é INCORRETO afirmar que','','','["o envio de hemocomponentes para outra instituição deve ser regido pela obediência às normas de biossegurança e às exigências técnicas relacionadas à sua conservação.", "todo hemocomponente deverá ser transportado em temperaturas que sejam adequadas para a manutenção das suas características.", "os hemocomponentes devem ser transportados por pessoal convenientemente instruído.", "o envio de hemocomponentes deve ser acompanhado de um documento contendo o número de identificação e as iniciais do doador."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: o envio de hemocomponentes deve ser acompanhado de um documento contendo o número de identificação e as iniciais do doador..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Hemoterapia','Em relação ao sistema de grupo sanguíneo Diego, NÃO é correto afirmar que','','','["os antígenos do sistema Diego encontram-se localizados na glicoproteína eritrocitária banda 3, também denominada transportador aniônico 1 (AE1) ou CD233.", "o antígeno Dib é um marcador antropológico, devido à sua prevalência em populações mongoloides.", "o antitético do antígeno Wrb apresenta baixa frequência na população.", "os antígenos do sistema Diego encontram-se localizados na glicoproteína eritrocitária banda 3, também denominada transportador aniônico 1 (AE1) ou CD223."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: os antígenos do sistema Diego encontram-se localizados na glicoproteína eritrocitária banda 3, também denominada transportador aniônico 1 (AE1) ou CD223.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Hemoterapia','Em relação à transfusão em recém-natos com até quatro meses e vida, é INCORRETO afirmar:','','','["Na amostra inicial (anterior à primeira transfusão), o grupo sanguíneo ABO deverá ser determinado pela classificação direta, sem necessitar realizar a classificação reversa. O antígeno Rh(D) deve ser determinado, empregando reagente anti-D em paralelo com soro- controle Rh do mesmo fabricante. Se a reação for negativa para a presença do antígeno D, deve ser efetuada técnica para a exclusão de RhD fraco.", "Se as hemácias selecionadas para transfusão não são do grupo O, deve ser investigada, no soro ou plasma do neonato, a presença de anti-A ou anti-B, com métodos que incluam a fase de antiglobulina humana. Este teste não precisa ser realizado se houver disponibilidade de uma amostra do sangue da mãe para tipificação ABO e Rh e se o grupo ABO da mãe for o mesmo do recém- -nascido. Se ocorrer detecção da presença de anti-A ou anti-B, devem ser transfundidos glóbulos vermelhos do grupo O até que o anticorpo deixe de ser demonstrável no soro do neonato. Essas unidades não necessitam ser compatibilizadas.", "Na amostra inicial (anterior a primeira transfusão), deve ser realizada a pesquisa de anticorpos irregulares. O método para detecção do(s) anticorpo(s) irregular(es) no soro ou plasma deve ser capaz de detectar anticorpos clinicamente significativos. Deve ser empregado soro do neonato ou da mãe.", "Se a pesquisa de anticorpos irregulares for negativa, não será necessário compatibilizar as hemácias para a primeira transfusão nem para as transfusões subsequentes dentro do período neonatal, desde que as hemácias sejam do grupo \"O\". Se a pesquisa de anticorpos irregulares demonstrar a presença de anticorpos clinicamente significativos, a transfusão deve ser feita com unidades que não contenham os antígenos correspon- dentes. Essas unidades não necessitam ser compatibilizadas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: Se a pesquisa de anticorpos irregulares for negativa, não será necessário compatibilizar as hemácias para a primeira transfusão nem para as transfusões subsequentes dentro do período neonatal, desde que as hemácias sejam do grupo "O". Se a pesquisa de anticorpos irregulares demonstrar a presença de anticorpos clinicamente significativos, a transfusão deve ser feita com unidades que não contenham os antígenos correspon- dentes. Essas unidades não necessitam ser compatibilizadas..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Hemoterapia','Em relação ao sistema HLA, é correto afirmar:','','','["Anticorpos HLA estão implicados com doença hemolítica do recém-nato.", "HLA de classe A, B, C e DR estão presentes nos eritrócitos circulantes.", "Em indivíduos normais, os eritrócitos não apresentam elevada expressão de HLA.", "A27 e B8 são os antígenos do sistema HLA mais frequentes nos eritrócitos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: Em indivíduos normais, os eritrócitos não apresentam elevada expressão de HLA..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Hemoterapia','Em relação ao sistema de grupo sanguíneo RH, é INCORRETO afirmar que','','','["os fenótipos RHD fracos, na maior parte das vezes, estão associados com mutações do tipo em ponto no gene RH*D que codificam substituições de aminoácidos localizados na região citoplasmática ou transmembranal do polipeptídeo RHD.", "os fenótipos RHD parciais, na maior parte das vezes, estão associados com mutações no gene RH*D que codificam substituições de aminoácidos localizados nas alças extracelulares do polipeptídeo RHD.", "o antígeno RHD é exclusivo dos eritrócitos, não sendo encontrado em secreções ou em qualquer outro tecido no organismo humano.", "Os genes RH*D e RH*CE contêm 12 éxons cada e apresentam uma organização bastante similar (93,8% de homologia)."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: Os genes RH*D e RH*CE contêm 12 éxons cada e apresentam uma organização bastante similar (93,8% de homologia)..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Hemoterapia','Em qual condição abaixo, a plasmaferese terapêutica NÃO está indicada?','','','["Transplante de medula óssea ABO incompatível.", "Síndrome de Guillain-Barré.", "Doença hemolítica autoimune por anticorpo quente.", "Púrpura trombocitopênica trombótica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: Doença hemolítica autoimune por anticorpo quente..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Hemoterapia','Os hemocomponentes devem ser infundidos, no máximo, em','','','["2 (duas) horas.", "4 (quatro) horas.", "6 (seis) horas.", "8 (oito) horas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa B. Resposta indicada no gabarito: 4 (quatro) horas..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Hemoterapia','O fenótipo Ror é composto pelos antígenos:','','','["D / C / e.", "D / C / E.", "D / c / e.", "D / C / E / e."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: D / c / e..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Hemoterapia','A conduta a ser tomada nos casos de reação febril com elevação da temperatura corporal acima de 1oC é','','','["usar antitérmico e suspender a transfusão se a temperatura não abaixar em 30 minutos.", "interromper a transfusão imediatamente e não mais reinfundir o hemocomponente.", "interromper a transfusão, retornando à infusão após cessar a febre.", "não interromper a transfusão."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa B. Resposta indicada no gabarito: interromper a transfusão imediatamente e não mais reinfundir o hemocomponente..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Hemoterapia','Em relação às imunoglobulinas envolvidas nas reações antígeno-anticorpo em doença hemolítica autoimune (DHAI), podemos afirmar:','','','["A imunoglobulina A raramente está associada com DHAI, justificando a inexistência de anti-IgA nos reagentes antiglobulina humana.", "A resposta primária na DHAI é constituída por anticorpos da classe IgM e, após cinco dias, ocorre o aparecimento da IgG.", "Grande parte das reações entre antígeno e anticorpo na DHAI resulta da fixação de complemento, principalmente quando essa reação envolve a IgG.", "As afirmativas A e C estão corretas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: Grande parte das reações entre antígeno e anticorpo na DHAI resulta da fixação de complemento, principalmente quando essa reação envolve a IgG..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Hemoterapia','Em relação à técnica de depleção do número de leucócitos em concentrado de hemácias, é INCORRETO afirmar que','','','["o concentrado pobre em leucócitos deve ser preparado por um método que reduza o número de leucócitos no componente final a menos de 5x1010.", "o concentrado de hemácias desleucocitado ou leucorreduzido deve conter menos do que 5x106 leucócitos residuais no componente final.", "os concentrados de hemácias pobre em leucócitos e o desleucocitado/leucorre- duzido, quando são preparados em sistema aberto, têm validade de 24h.", "os concentrados de hemácias desleuco- citados/leucorreduzidos são concentrados de hemácias dos quais foram retirados pelo menos 99,9% dos leucócitos originalmente presentes nos componentes."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa A. Resposta indicada no gabarito: o concentrado pobre em leucócitos deve ser preparado por um método que reduza o número de leucócitos no componente final a menos de 5x1010..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Hemoterapia','Em relação ao controle de qualidade sistemático obrigatório em todo Serviço de Hemoterapia, é correto afirmar que','','','["devem ser submetidos obrigatoriamente ao controle de qualidade somente os seguintes hemocomponentes: concentrado de hemácias; plasma fresco congelado e concentrado de plaquetas.", "os parâmetros obrigatórios avaliados nos concentrados de hemácias são os seguintes: volume, hemoglobina, hematócrito, grau de hemólise e esterilidade.", "todos os parâmetros avaliados nos hemocomponentes, pelo controle de qualidade, devem apresentar percentual de conformidade de pelo menos 75 %.", "a quantidade de concentrados de hemácias e concentrados de plaquetas a serem submetidos ao controle de qualidade deve ser no mínimo de 4 unidades produzidas por mês."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa B. Resposta indicada no gabarito: os parâmetros obrigatórios avaliados nos concentrados de hemácias são os seguintes: volume, hemoglobina, hematócrito, grau de hemólise e esterilidade..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Hemoterapia','A coleta de sangue total realizada nos Serviços de Hemoterapia só NÃO deve seguir uma das diretrizes abaixo. Assinale-a.','','','["O sangue total coletado deve ser armazenado imediatamente após a coleta à temperatura de 20C a 60C, exceto se for usado como fonte de plaquetas.", "A área escolhida para a punção venosa deve ser submetida à limpeza rigorosa em 1 tempo, conhecida como antissepsia.", "Uma bolsa de sangue com volume total inferior a 300 ml, pode ser utilizada para fins transfusionais, se a quantidade de anticoagulante foi ajustada proporcional- mente ao volume coletado.", "A punção venosa deve ser preferencialmente na veia cubital mediana."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa B. Resposta indicada no gabarito: A área escolhida para a punção venosa deve ser submetida à limpeza rigorosa em 1 tempo, conhecida como antissepsia..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Hemoterapia','Assinale a alternativa abaixo que contém causas de inaptidão TEMPORÁRIA para a doação de sangue, segundo a RDC 153.','','','["Hepatite viral após os 10 anos de idade/diabetes tipo I/uso de hormônio do crescimento recombinante.", "Uso de analgésicos/diuréticos/insulina.", "Diabetes tipo II não controlada/acupuntura com material descartável/alergias.", "Uso de hormônio feminino/uso de inibidores da enzima conversora da angiotensina/uso de bloqueadores de canais de cálcio."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: Diabetes tipo II não controlada/acupuntura com material descartável/alergias..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Hemoterapia','Em relação aos exames de qualificação no sangue do doador é correto afirmar que','','','["os registros dos resultados dos exames realizados assim como as interpretações e disposições finais devem ser arquivados por no mínimo 10 anos.", "o Serviço de Hemoterapia deve obrigatoriamente convocar o doador e firmar o diagnóstico da doença.", "a plasmateca deverá ser conservada em temperatura igual ou inferior a -20ºC.", "quando os exames são realizados em instituição diferente daquela em que ocorreu a doação, a transmissão dos resultados pode se dar por via telefônica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: a plasmateca deverá ser conservada em temperatura igual ou inferior a -20ºC..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Hemoterapia','Nos pacientes portadores de hemofilia A, quando se infunde concentrado de Fator VIII, a meia- vida do fator infundido é de','','','["2h a 4h.", "4h a 6h.", "9h a 14h.", "18h a 24h."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: 9h a 14h..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Hemoterapia','Quando uma coleta de plaquetas por aférese – plaquetaférese - é realizada, o volume de sangue que fica retido no “bowl” ao final de cada procedimento deve ser monitorado e registrado. Assinale a alternativa que completa corretamente essa afirmação.','','','["Quando o volume cumulativo atingir 9 ml/kg do doador, a doação de sangue total subsequente só poderá ser realizada dentro de 2 meses, para doadores do sexo masculino.", "Quando o volume cumulativo atingir 9 ml/kg do doador, a doação de sangue total subsequente só poderá ser realizada dentro de 3 meses, para doadoras do sexo feminino.", "Quando o volume cumulativo atingir 8 ml/kg do doador, a doação de sangue total subsequente só poderá ser realizada dentro de 3 meses, para doadores do sexo masculino.", "Quando o volume cumulativo atingir 9 ml/kg do doador, a doação de sangue total subsequente só poderá ser realizada dentro de 2 meses, para doadores do sexo feminino."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa A. Resposta indicada no gabarito: Quando o volume cumulativo atingir 9 ml/kg do doador, a doação de sangue total subsequente só poderá ser realizada dentro de 2 meses, para doadores do sexo masculino..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Hemoterapia','Em relação aos componentes plasmáticos, é correto afirmar que','','','["o plasma fresco congelado é o plasma separado de uma unidade de sangue total por centrifugação e totalmente congelado em até 6 horas depois da coleta.", "o plasma fresco congelado tem a validade de 24 (vinte e quatro) meses, se for mantido em temperatura de conservação entre –20ºC e –30°C.", "o plasma comum ou plasma normal, quando necessário, pode ser utilizado em transfusão.", "o plasma comum, quando é obtido a partir de um plasma fresco congelado, cuja validade tenha expirado, tem a validade máxima de 4 anos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: o plasma comum, quando é obtido a partir de um plasma fresco congelado, cuja validade tenha expirado, tem a validade máxima de 4 anos..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Hemoterapia','Assinale a alternativa correta em relação à decisão a ser tomada em caso do seguinte resultado sorológico, observado em uma doação de sangue: 1º ELISA para HIV: Positivo; repetição em duplicata na mesma amostra: Negativo; 2º ELISA para HIV:  Negativo; repetição em duplicata na mesma amostra: Negativo.','','','["A bolsa de sangue doada por este doador deve ser descartada e o mesmo deve ser convocado para consulta, por ser soropositivo para HIV.", "A bolsa de sangue doada por este doador pode ser utilizada normalmente, já que se trata de soroconversão para HIV.", "A bolsa de sangue doada por este doador deve ser descartada, para se seguir o princípio da precaução, e o doador não precisa ser convocado.", "A bolsa de sangue doada por este doador pode ser utilizada normalmente e o doador não precisa ser convocado."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: A bolsa de sangue doada por este doador pode ser utilizada normalmente e o doador não precisa ser convocado..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Hemoterapia','Em um doador de sangue em que se encontrou um teste ELISA para HBsAg repetidamente positivo, a confirmação deste resultado deve ser feita com','','','["teste de neutralização.", "sorologia para anti-HBsAg e anti-HBeAg.", "sorologia (ELISA) para HBeAg e anti-HBc IgM.", "anamnese e exame clínico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa A. Resposta indicada no gabarito: teste de neutralização..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Hemoterapia','Em paciente com antecedentes de reações transfusionais alérgicas, assinale a opção INCORRETA em relação às alternativas para a prevenção dessa complicação, quando estiver indicada nova transfusão.','','','["Uso de concentrado de hemácias lavadas.", "Pré-medicação com anti-histamínicos.", "Uso de concentrado de plaquetas lavadas.", "Pré-medicação com ácido acetil salicílico."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: Pré-medicação com ácido acetil salicílico.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Hemoterapia','A transfusão é denominada maciça quando o volume transfundido em 24 h é equivalente ao volume sanguíneo total do paciente. Assinale a alternativa abaixo que NÃO pode estar associada à transfusão maciça.','','','["Desvio para a esquerda na curva de dissociação do oxigênio devido ao fato de as hemácias estocadas terem um menor teor de 2,3-DPG.", "Trombocitopenia dilucional.", "Toxicidade pelo citrato, assim como alterações no pH plasmático do paciente.", "Estabilidade ou elevação da temperatura corporal do paciente."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: Estabilidade ou elevação da temperatura corporal do paciente..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Hemoterapia','Assinale a alternativa que NÃO corresponde aos sinais e sintomas de reações transfusionais febris em lactentes.','','','["Calafrios.", "Elevação de temperatura.", "Palidez cutânea.", "Taquicardia."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa A. Resposta indicada no gabarito: Calafrios.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Hemoterapia','A púrpura pós-transfusional é uma reação adversa tardia a transfusão sanguínea. Nessa síndrome, encontramos','','','["trombocitopenia que se desenvolve 1 semana após a transfusão e está relacionada com a presença de alo- -anticorpos plaquetários.", "número de plaquetas normal e efusão hemorrágica na pele devido à hemodiluição de fatores da coagulação pós-transfusão.", "trombociptopenia devido à hemodiluição de plaquetas pós-transfusão.", "trombocitopenia que se desenvolve 1 mês após a transfusão e está relacionada com a presença de anticorpos anti-HLA."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa A. Resposta indicada no gabarito: trombocitopenia que se desenvolve 1 semana após a transfusão e está relacionada com a presença de alo- -anticorpos plaquetários..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Hemoterapia','Em pacientes com doença de Von Willebrand tipo I, leve ou moderada, o tratamento de escolha para os episódios hemorrágicos agudos é','','','["concentrado de fator VII ativado recombinante.", "complexo protrombínico parcialmente ativado.", "DDAVP intravenoso.", "concentrado de fator VIII de altíssima pureza."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: DDAVP intravenoso..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Hemoterapia','Em relação à transfusão de concentrados de plaquetas, assinale a alternativa INCORRETA.','','','["A compatibilidade ABO entre as plaquetas e o paciente precisa ser estritamente respeitada.", "Sepse, febre, CIVD (coagulação intra- vascular disseminada) aumentam o consumo de plaquetas e consequentemente influenciam no sangramento de pacientes trombocitopênicos.", "Os componentes plaquetários podem ser agrupados em “pool” que deverão ser preparados em capela de fluxo laminar tipo II.", "Em relação aos concentrados de plaquetas obtidos a partir do sangue total, os concentrados de plaquetas obtidos por aférese têm a vantagem de expor os pacientes a um menor número de doadores."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa A. Resposta indicada no gabarito: A compatibilidade ABO entre as plaquetas e o paciente precisa ser estritamente respeitada.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Hemoterapia','Em relação ao concentrado de complexo protrombínico, é INCORRETO afirmar que','','','["contém fatores vitamina K dependentes.", "contém os seguintes fatores: II, V, IX e X.", "são trombogênicos.", "pode substituir o concentrado de fator IX, na falta desses, na terapia para pacientes hemofílicos B."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa B. Resposta indicada no gabarito: contém os seguintes fatores: II, V, IX e X..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Hemoterapia','Em relação à exsanguíneotransfusão, terapêutica que pode ser utilizada na Doença Hemolítica Perinatal, assinale a afirmativa INCORRETA.','','','["Deve ser realizada com sangue total colhido há menos de 5 dias.", "Deve ser realizada com plasma compatível com as hemácias do paciente.", "Deve ser realizada com hemácias compatíveis com o soro da mãe e que não possuam os antígenos contra os quais a mãe está imunizada, nos casos de incompatibilidade pelo sistema Rh.", "Deve ser realizada com sangue total reconstituído: concentrado de hemácias O Negativo e plasma O Negativo, qualquer que seja o grupo sanguíneo do recém- -nascido."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: Deve ser realizada com sangue total reconstituído: concentrado de hemácias O Negativo e plasma O Negativo, qualquer que seja o grupo sanguíneo do recém- -nascido.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Hemoterapia','Quanto ao regulamento técnico para procedimentos em hemoterapia, é INCORRETO afirmar que','','','["ao médico responsável técnico por Serviços de Hemoterapia cabe a responsabilidade final por todas as atividades médicas, técnicas e administrativas.", "a instituição de saúde que realize intervenções cirúrgicas de grande porte ou que efetue mais de 60(sessenta) transfusões /mês deve contar com uma agência transfusional dentro de suas instalações.", "é facultado aos Serviços de Saúde que tenham atendimento de emergência, ou de obstetrícia, ou que realizem cirurgias de médio porte, não possuir uma agência transfusional dentro de suas instalações.", "o Serviço de Saúde deve constituir um Comitê Transfusional formado apenas por profissionais do Serviço de Hemoterapia, que terá como função o monitoramento da prática hemoterápica na instituição."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: o Serviço de Saúde deve constituir um Comitê Transfusional formado apenas por profissionais do Serviço de Hemoterapia, que terá como função o monitoramento da prática hemoterápica na instituição..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Hemoterapia','Os Serviços de Hemoterapia que distribuem sangue e seus componentes devem formalizar, por escrito, com o serviço receptor, um contrato, convênio ou termo de compromisso. Desse documento devem constar, obrigatoriamente, os seguintes dados:','','','["Penalidades para a não execução das obrigações.", "Obrigatoriedade do Serviço receptor, no sentido de enviar doadores de sangue em número igual ou maior do que o de bolsas disponibilizadas pelo Serviço fornecedor.", "Adequação e responsabilidade pelo transporte do sangue e seus componentes.", "Nomes e dados jurídicos das instituições envolvidas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa B. Resposta indicada no gabarito: Obrigatoriedade do Serviço receptor, no sentido de enviar doadores de sangue em número igual ou maior do que o de bolsas disponibilizadas pelo Serviço fornecedor..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Hemoterapia','Dá-se o nome de equipamentos da cadeia do frio aos refrigeradores e congeladores específicos para conservação de componentes sanguíneos. Em relação a esses equipamentos, é correto afirmar que','','','["a verificação e o registro de temperatura desses equipamentos devem ser realizados, ao menos, a cada seis horas, para os equipamentos que não dispõem de registrador gráfico contínuo.", "todos esses equipamentos devem ser equipados com sistema de alarme sonoro e visual.", "os componentes liberados e os componentes não liberados para uso podem ser armazenados no mesmo refrigerador ou congelador desde que estejam em prateleiras diferentes e identificados.", "os alarmes devem ser periodicamente testados (no mínimo a cada 6 meses) e deve haver um procedimento escrito com relação ao armazenamento dos hemocomponentes em caso de pane do equipamento."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa B. Resposta indicada no gabarito: todos esses equipamentos devem ser equipados com sistema de alarme sonoro e visual..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Hemoterapia','Em relação à liberação de sangue para a transfusão, é INCORRETO afirmar:','','','["Todo hemocomponente deve ser inspecionado quanto ao seu aspecto e rótulo, antes da liberação para a transfusão.", "Os componentes eritrocitários liberados para a transfusão, mas não utilizados, não podem em hipótese alguma ser reintegrados ao estoque.", "Uma amostra de sangue da bolsa e uma amostra de soro ou plasma do receptor devem ser conservadas entre 2º C a 6º C durante pelo menos 3 dias após a transfusão.", "Fazem parte da identificação do hemocomponente a ser transfundido: nome, sobrenome, leito e a identificação do local do receptor, identificação numérica ou alfanumérica e o grupo ABO e fator Rh(D) do receptor, o número de identificação da unidade, grupo ABO e fator Rh(D), a conclusão da prova cruzada e a data do envio para transfusão."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa B. Resposta indicada no gabarito: Os componentes eritrocitários liberados para a transfusão, mas não utilizados, não podem em hipótese alguma ser reintegrados ao estoque..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Hemoterapia','Os critérios que inabilitam a doação de sangue em relação à malária são estabelecidos a partir da incidência da doença no local de doação e é usado como referência o Índice Parasitário Anual – IPA, fornecido por órgão oficial. Assinale a afirmativa INCORRETA.','','','["Em áreas endêmicas, ficam excluídos os candidatos que tenham tido malária nos 12 meses que antecedem a doação.", "Em áreas não endêmicas, ficam excluídos os candidatos que, nos últimos 6 (seis) meses, estiveram em área endêmica com transmissão ativa.", "Em área endêmica, são aceitos os candidatos que residem em área de médio e baixo risco pelo IPA e deverão ser submetidos a teste parasitológico.", "Em áreas endêmicas e não endêmicas, são excluídos definitivamente candidatos à doação que já tiveram infecção por plasmodium falciparum (febre terçã)."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Resposta indicada no gabarito: Em áreas endêmicas e não endêmicas, são excluídos definitivamente candidatos à doação que já tiveram infecção por plasmodium falciparum (febre terçã).. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Hemoterapia','Diz-se que há soroconversão de um doador, quando os testes de triagem forem reagentes em um doador de sangue que, em doações prévias, apresentava sorologia não reagente. Assinale a resposta abaixo que está em DESACORDO com a RESOLUÇÃO – RDC ANVISA Nº 153, DE 14 DE JUNHO DE 2004.','','','["Encaminhar a amostra de sangue da última doação em que foi identificada a soroconversão para a realização de testes confirmatórios.", "Se os testes confirmatórios forem reagentes, deve-se verificar o destino de todos os hemocomponentes da doação anterior.", "Caso a unidade de plasma oriunda da última doação tenha sido enviada para o fracionamento industrial, não há obrigação de comunicação à indústria que o recebeu, pois essa realiza os testes de amplificação e de detecção de ácidos nucleicos (NAT) para todos os marcadores sorológicos obrigató-rios pela legislação brasileira.", "Caso a unidade de plasma oriunda da última doação esteja armazenada em qualquer Serviço de Hemoterapia, essa poderá ser encaminhada para a produção de reagentes (painéis, controles)."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa C. Resposta indicada no gabarito: Caso a unidade de plasma oriunda da última doação tenha sido enviada para o fracionamento industrial, não há obrigação de comunicação à indústria que o recebeu, pois essa realiza os testes de amplificação e de detecção de ácidos nucleicos (NAT) para todos os marcadores sorológicos obrigató-rios pela legislação brasileira..' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Hemoterapia','Leia o enunciado e as alternativas da questão 50 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-hemoterapia-q50-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Hemoterapia: alternativa D. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-hemoterapia' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-infectologia','PMERJ 2010 — Oficial — Médico Infectologia','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Infectologia','As causas de morte de pacientes infectados pelo HIV, obtidas por um levantamento nacional conduzido na França em 2005, foram comparadas com aquelas obtidas por um levantamento similar realizado em 2000. Entre 1042 mortes reportadas em 2005, 344 (34%) foram relacionadas a câncer. Em 2000, das 934 mortes relatadas, 269 (29%) foram por câncer. A proporção de cânceres relacionados às hepatites (6% em 2000 vs. 11% em 2005) e de cânceres não relacionados a Aids nem às hepatites (38% em 2000 vs 50% em 2005) aumentaram significativamente de 2000 para 2005 (P = 0,03 e P = 0,01, respectivamente). Fonte: Clin Infect Dis 2009; 48:633–9 Considerando que a forma do levantamento, as definições de câncer e os métodos de detecção de câncer não modificaram significativamente entre 2000 e 2005, em relação à metodologia e aos resultados do estudo, é correto afirmar que, entre os indivíduos infectados pelo HIV na França,','','','["a incidência de cânceres não relacionados à infecção pelo HIV e às hepatites aumentou significativamente.", "a prevalência de cânceres não relacionados à infecção pelo HIV e às hepatites aumentou significativamente.", "a mortalidade por cânceres não relacionados à infecção pelo HIV e às hepatites aumentou significativamente.", "a letalidade por cânceres não relacionados à infecção pelo HIV e às hepatites aumentou significativamente."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: a mortalidade por cânceres não relacionados à infecção pelo HIV e às hepatites aumentou significativamente..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Infectologia','Dos agentes infecciosos listados abaixo, o que NÃO é passível de nenhuma forma de transmissão inter-humana é','','','["Toxoplasmose gondii.", "Rickettsia sp.", "Plamodium vivax.", "Leishmania chagasi."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: Rickettsia sp.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Infectologia','Assinale a única opção em que somente foram listados vetores de doenças infecciosas e parasitárias.','','','["Aedes aegypti, Wuchereria bancrofti, Amblyomma cajennense, Triatoma infestans, Simulium metallicum.", "Haemagogus sp, Culex pipiens, Pediculus humanus, Ixodes scapularis, Rhodnius prolixus.", "Anopheles darlingi, Lutzomyia longipalpis, Biomphalaria Tenagophila, Panstrongylus megistus, Culex quinquefasciatus.", "Anopheles aquasalis, Glossina palpalis, Xenopsilla cheopis, Ratus norvergicus, Sarcoptes scabei."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: Haemagogus sp, Culex pipiens, Pediculus humanus, Ixodes scapularis, Rhodnius prolixus..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Infectologia','Os profissionais de saúde no exercício da profissão, bem como os responsáveis por organizações e estabelecimentos públicos e particulares de saúde e ensino são obrigados a comunicar aos gestores do Sistema Único de Saúde – SUS a ocorrência de','','','["todos os casos suspeitos ou confirmados de doença de Chagas.", "todos os casos suspeitos ou confirmados de sífilis.", "toda evidência laboratorial de influenza.", "toda evidência laboratorial de sarampo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: toda evidência laboratorial de sarampo..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Infectologia','Assinale a única opção que contém somente doenças e agravos de notificação compulsória imediata.','','','["Cólera, febre amarela, meningite por Haemophilus influenzae, hantavirose.", "Malária, raiva humana, poliomielite, caso confirmado de tétano neonatal.", "Sarampo, síndrome de rubéola congênita, paralisia flácida aguda, botulismo.", "Febre do Nilo Ocidental, varíola, influenza humana por novo subtipo, peste."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: Febre do Nilo Ocidental, varíola, influenza humana por novo subtipo, peste..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Infectologia','Durante uma tarde de plantão em uma Clínica de Imunização, três indivíduos com situações incomuns ao cotidiano procuram atendimento: uma gestante no primeiro trimestre, suscetível à rubéola, requisitando administração da vacina tríplice viral para seu filho com 12 meses; um profissional de saúde que, após duas séries de três doses da vacina para hepatite B, ainda não havia obtido níveis séricos protetores de Anti-HBs; um adolescente portador de neoplasia hematológica em quimioterapia, sem história de varicela, que teve contato significativo com criança com varicela em ambiente hospitalar, há 36 horas. As condutas mais adequadas para cada situação são, respectivamente,','','','["adiar a vacinação na criança até o segundo trimestre da gestação da mãe, repetir o esquema de vacinação do profissional de saúde e administrar imunoglobulina específica no adolescente.", "aplicar a vacina requisitada na criança imediatamente, administrar imunoglobulina específica para o profissional de saúde e administrar imunoglobulina específica no adolescente.", "contraindicar a administração da vacina na criança, orientar o profissional de saúde a considerar-se imunizado numa eventual exposição e vacinar o adolescente para varicela.", "aplicar a vacina requisitada na criança imediatamente, orientar o profissional de saúde a considerar-se suscetível numa eventual exposição e administrar imunoglobulina específica no adolescente."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: aplicar a vacina requisitada na criança imediatamente, orientar o profissional de saúde a considerar-se suscetível numa eventual exposição e administrar imunoglobulina específica no adolescente..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Infectologia','O antimicrobiano primariamente bactericida que atua na membrana citoplasmática é a','','','["bacitracina.", "polimixina B.", "cefepima.", "fosfomicina."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: polimixina B..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Infectologia','Para se determinar se uma bactéria Klebsiella pneumonia isolada em amostras de hemocultura é produtora de beta-lactamase espectro estendido (ESBL), é necessário documentar','','','["que o MIC para ceftazidima, astreonam, cefotaxima ou ceftriaxone é superior a 1µg/ml em teste de triagem e que há aumento do MIC para ceftaxime ou ceftazidima quando essas drogas são testadas associadas ao ácido clavulânico.", "que o MIC para ceftazidima, astreonam, cefotaxima ou ceftriaxone é inferior a 1µg/ml em teste de triagem e que há aumento do MIC para ceftaxime ou ceftazidima quando essas drogas são testadas associadas ao ácido clavulânico.", "que o MIC para ceftazidima, astreonam, cefotaxima ou ceftriaxone é superior a 1µg/ml em teste de triagem e que há redução do MIC para ceftaxime ou ceftazidima quando essas drogas são testadas associadas ao ácido clavulânico.", "que o MIC para ceftazidima, astreonam, cefotaxima ou ceftriaxone é inferior a 1µg/ml em teste de triagem e que há redução do MIC para ceftaxime ou ceftazidima quando essas drogas são testadas associadas ao ácido clavulânico."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: que o MIC para ceftazidima, astreonam, cefotaxima ou ceftriaxone é superior a 1µg/ml em teste de triagem e que há redução do MIC para ceftaxime ou ceftazidima quando essas drogas são testadas associadas ao ácido clavulânico..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Infectologia','Paciente do sexo feminino apresenta diarreia aquosa, de moderada intensidade, em uma área onde está havendo um surto epidêmico de cólera. Considere que o diagnóstico pelo vibrião colérico foi comprovado e que a paciente está grávida de 12 semanas. Além da reidratação adequada, o tratamento antimicrobiano deverá ser feito preferencialmente com','','','["ampicilina.", "fosfato de tetraciclina.", "ciprofloxacino.", "trimetoprim + sulfametoxazol."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: ampicilina..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Infectologia','Numa terapêutica antifúngica prolongada, o aparecimento de ginecomastia relaciona-se habitual- mente ao uso de','','','["anfotericina B.", "cetoconazol.", "itraconazol.", "fluconazol."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: cetoconazol..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Infectologia','Paciente de 45 anos apresenta prolapso de válvula mitral com regurgitação e será submetido a endoscopia digestiva alta para esclarecer dor epigástrica de 2 meses. Além dos cuidados técnicos inerentes ao procedimento, a melhor conduta em relação à profilaxia antibiótica é','','','["nenhum antibiótico.", "cefalotina ou cefazolina.", "amoxicilina + clavulanato.", "clindamicina + gentamicina."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: nenhum antibiótico..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Infectologia','Em maio de 2006, 21 indivíduos, moradores de Mojuí dos Campos (PA), apresentaram quadro febril agudo, acompanhado de cefaleia, mialgia, astenia, artralgia e epigastralgia, evoluindo com edema de membros inferiores, dispneia aos esforços e sinais clínicos de insuficiência cardíaca congestiva. Cinco pacientes apresentaram alterações de repolarização no ECG, 1 apresentou bloqueio completo de ramo direito, 3 apresentaram derrame pericárdico e 1 paciente evoluiu para óbito por miocardite aguda. Os casos distribuíram-se em 6 núcleos familiares e ocorreram cerca de 15 dias da ingestão de suco de bacaba de fonte comum. Fonte: Rev Soc Bras Med Trop Vol 40: Supl I, 2007. A droga indicada para tratamento dos pacientes do surto de Mojuí dos Campos é','','','["anfotericina B.", "cloranfenicol.", "benznidazol.", "estreptomicina."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: benznidazol..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Infectologia','A maioria dos casos de febre prolongada de origem obscura (febre de origem obscura clássica), no grupo das neoplasias sólidas e hematológicas, é causada por','','','["linfomas.", "neoplasias do tubo digestivo.", "leucoses.", "neoplasias do aparelho gênito-urinário."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: linfomas..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Infectologia','Um paciente do sexo masculino procura atendimento médico referindo febre baixa, mal-estar, cefaleia e mialgias concomitantes ao surgimento de pápulas eritematosas e vesículas agrupadas na genitália externa, com dor, queimação e prurido locais, além de linfadenopatia inguinal e femoral. Nos dias que seguiram, houve aparecimento de novas lesões e as existentes progrediram para pústulas, que coaleceram e ulceraram. Cerca de 7 dias antes do início dos sintomas, participou de sexo grupal sem uso de preservativos. Nega episódios semelhantes no passado. Foram então solicitados exames complementares que evidenciaram: Teste de Tzanck, obtido da base de lesão genital ulcerada, positivo; Imunofluorescência direta para HSV-2 no material de lesão genital, negativa; sorologia para HSV-1 + HSV- 2 IgG não reativo; sorologia para HSV-1 + HSV-2 IgM reativo. Com os dados disponíveis, o diagnóstico mais provável para o quadro apresentado é','','','["episódio de recorrência de herpes genital por HSV-2.", "infecção primária genital por HSV-1.", "infecção primária genital por HSV-2.", "infecção primária genital por HSV-2 em paciente portador de HSV-1."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: infecção primária genital por HSV-1..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Infectologia','Quando indicado, o tratamento específico dos vírus influenza A e B deve ser feito preferencialmente com','','','["amantadina.", "ribavirina.", "aciclovir.", "oseltamivir."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: oseltamivir..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Infectologia','Entre outras medidas, é necessário vacinar contra a raiva os acidentados por mordeduras de','','','["rato do telhado (Rattus rattus).", "macacos em geral.", "hamster (Mesocricetus auratus).", "coelho (Oryetalogus cuniculus)."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: macacos em geral..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Infectologia','O agente etiológico mais comum de síndrome mononucleose em pacientes com pesquisa de anticorpos heterófilos negativa é o','','','["citomegalovirus.", "Toxoplasma gondii.", "HIV.", "vírus de Epstein-Barr."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: vírus de Epstein-Barr..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Infectologia','Paciente de 16 anos, sexo feminino, procedente de Amargosa – BA, é admitida com história de que há 8 dias iniciou quadro de dor em região lombar com irradiação para membros inferiores associado a cefaleia de moderada intensidade, constipação intestinal e incontinência urinária, evoluindo com parestesia e paraparesia flácida bilateral e simétrica após 4 dias. Ao exame físico da admissão, paciente em bom estado geral, afebril, normotensa, redução de força muscular em membros inferiores, arreflexia bilateral, sensibilidade térmica, tátil e dolorosa ausentes abaixo dos joelhos e face interna das coxas. Líquor obtido por punção lombar revela: 337 cél/mm3, predomínio mononuclear e 20% de eosinófilos, glicorraquia de 51 mg%, proteínas 130 mg%. A RNM de coluna lombossacra mostra espessamento da porção distal da medula e do cone medular e realce de raízes nervosas após a infusão venosa do meio de contraste. Foi medicada com praziquantel e prednisona com regressão dos sintomas neurológicos na primeira semana de tratamento, recuperando controles esfincterianos, mas mantendo arreflexia. Fonte: Rev Soc Bras Med Trop vol 38: Supl I, 2005. A provável etiologia para o caso relatado é','','','["neurocisticercose.", "hidatidose.", "esquistossomose mansoni.", "fasciolíase."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: esquistossomose mansoni..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Infectologia','Paciente do sexo feminino, 45 anos, natural da Bahia, doadora inapta do Instituto de Hematologia, por diagnóstico de doença de Chagas e infecção pelo HIV. Exames posteriores documentaram estar na forma indiferenciada de Chagas (IFI = 1/160, HA = 1/1280, ELISA = 1/1280, exames de rastreamento normais), com contagem de CD4 de 310 cél/mm3 e carga viral de 5.000 cópias/ml (3,7 log/ml). Foi recomendado o início da terapia antirretroviral, mas optou-se por esperar. Dois anos após, a paciente foi internada com febre, cefaleia, vômitos, taquicardia, hipotensão postural, dor abdominal e rigidez de nuca. As pesquisas de tripomastigotas em gota espessa corada de sangue periférico e por xenodiagnóstico foram ambas positivas. Os eletrocardiogramas seriados e o ecocardiograma foram compatíveis com miocardite. Entre as condutas tomadas pelo médico assistente, aquela que NÃO está adequada ao momento atual da evolução clínica da paciente é','','','["notificar a paciente ao Ministério da Saúde.", "administrar benznidazol por 60 dias.", "iniciar profilaxia primária para outras infecções oportunistas.", "realizar exame de imagem em sistema nervoso central."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: notificar a paciente ao Ministério da Saúde..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Infectologia','Para que se rompa a cadeia de transmissão das DST, é fundamental que os contatos sexuais dos indivíduos infectados sejam adequadamente tratados. Segundo o Ministério da Saúde, são considerados parceiros, para fins de comunicação ou convocação, os indivíduos com quem o cliente se relacionou sexualmente','','','["nos últimos 30 dias se o cliente apresenta corrimento uretral.", "nos últimos 60 dias se o cliente apresenta candidose vaginal.", "nos últimos 90 dias se o cliente apresenta úlceras genitais.", "nos últimos 120 dias se o cliente apresenta sífilis secundária."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: nos últimos 90 dias se o cliente apresenta úlceras genitais..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Infectologia','Na difteria, o uso de corticoides está melhor indicado em casos complicados com','','','["miocardite.", "obstrução respiratória alta.", "polineurite.", "plaquetopenia."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: obstrução respiratória alta..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Infectologia','Em novembro de 2004, a Secretaria de Saúde do Estado da Bahia notificou quatro óbitos em Cedro de Vespertina, zona rural do município de Riacho de Santana. Caso 1 – feminino, 21 anos, falecida sem assistência médica 14 horas após o início dos sintomas; Caso 2 – feminino, 12 anos, prima do caso 1, falecida 130 horas após o início dos sintomas; Caso 3 – masculino, 28 anos, irmão do caso 1, falecido 21 horas após início dos sintomas; Caso 4 – masculino, 59 anos, pai dos casos 1 e 3, falecido 23 horas após o início dos sintomas. Todos os casos evoluíram com cefaleia frontal, tonteira, sonolência, distúrbio visual, ptose palpebral bilateral, midríase, disartria, disfagia, fraqueza muscular, dificuldade para caminhar sozinho, preservação da consciência e ausência de febre. Todos os casos sofreram exposições múltiplas a carne suína  conservada em gordura encontrada em panelas e em uma cabaça na residência do caso 1. Fonte: Rev Soc Bras Med Trop vol 38: Supl I, 2005. O provável agente etiológico envolvido no surto notificado é','','','["Clostridium botulinum.", "Bacillus cereus.", "Campylobacter jejuni.", "Clostridium perfringens."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: Clostridium botulinum..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Infectologia','Um aumento significativo dos casos de pneumonia estafilocócica tem sido descrito em epidemias causadas por','','','["adenovirus.", "rinovirus.", "parainfluenza.", "influenza."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: influenza..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Infectologia','As meningites agudas após trauma fechado de crânio são mais comumente produzidas por','','','["Staphylococcus aureus.", "Neisseria meningitidis.", "Streptococcus pneumoniae.", "Haemophilus influenzae."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: Streptococcus pneumoniae..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Infectologia','A maioria dos pacientes com Doença de Chagas, após 20 anos de infecção, apresenta-se com','','','["forma indiferenciada.", "megaesôfago.", "megacólon.", "cardiopatia."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: forma indiferenciada..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Infectologia','Das formas graves de malária pelo Plasmodium falciparum a mais frequente é a','','','["miocárdica.", "colérica.", "hemoglobinúrica.", "cerebral."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: cerebral..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Infectologia','A maioria dos casos de artrite séptica em articulações nativas é causada por','','','["Staphylococcus epidermidis.", "Staphylococcus aureus.", "Streptococcus pyogenes.", "Neisseria gonorrhoeae."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: Staphylococcus aureus..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Infectologia','Nas endocardites infecciosas causadas pelas bactérias do grupo HACEK, o tratamento antimicrobiano melhor indicado é com','','','["ampicilina + gentamicina.", "vancomicina + rifampicina.", "ceftriaxona.", "oxacilina + gentamicina."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: ceftriaxona..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Infectologia','O uso de corticoides antes do esquema antimicrobiano adequado parece melhor indicado na meningite causada por','','','["Streptococcus pneumoniae.", "Neisseria meningitidis.", "Herpes simplex.", "Listeria monocytogenes."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: Streptococcus pneumoniae..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Infectologia','Ruptura de tendões e tendinite têm sido relacionadas ao uso de','','','["clindamicina.", "levofloxacino.", "tetraciclina.", "aztreonam."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: levofloxacino..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Infectologia','Paciente do sexo feminino, 40 anos, está há 2 dias com febre alta, dor lombar, disúria e queda do estado geral. Última menstruação há 7 dias, com características normais. Nenhuma patologia de importância para o caso na história. A ultrassonografia renal e abdominal nada mostrou de significativo. A bacterioscopia pelo Gram da urina não centrifugada mostrou a presença de bastonetes gram negativos, 2 a  3 por campo de imersão. Foi coletada a urina para realização de urinocultura, contagem de colônias e teste de sensibilidade, além de hemoculturas. Foi decidido internar a doente, iniciar o tratamento empírico, após a coleta dos exames, enquanto se aguardam os resultados. A melhor opção para esse caso será a prescrição de','','','["ceftriaxona.", "nitrofurantoína.", "moxifloxacino.", "norfloxacino."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: ceftriaxona..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Infectologia','Paciente do sexo feminino, 25 anos, relata início do quadro há 3 semanas com o aparecimento de lesão ulcerada em dorso do polegar esquerdo, atribuído à infecção de arranhadura por seu gato de estimação. Passou inúmeras pomadas no local sem melhora. Há duas semanas vem notando o aparecimento de nódulos subcutâneos ao longo do antebraço, alguns dolorosos e sem fistulização. Nega febre ou sintomas sistêmicos. A conduta que mais provavelmente levará ao diagnóstico etiológico do quadro é realizar','','','["raspado da lesão cutânea e microscopia do material por Ziehl-Neelsen, KOH, e tinta nanquim.", "biópsia do nódulo subcutâneo com coloração por impregnação pela prata (Warthin-Starry).", "biópsia da borda da úlcera cutânea com cultura do material em meio NNN e Lovenstein-Jansen.", "biópsia da lesão cutânea e nódulos subcutâneos com cultura do material em meio de sabourraud."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: biópsia da lesão cutânea e nódulos subcutâneos com cultura do material em meio de sabourraud..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Infectologia','Paciente do sexo feminino, 35 anos, acaba de se descobrir infectada pelo HIV após o diagnóstico de tuberculose. Apresenta emagrecimento de 7 quilos nos últimos quatro meses e tosse persistente com eventuais escarros hemoptoicos. A pesquisa de BAAR foi positiva. A radiografia de tórax mostra imagem cavitária em lobo superior de pulmão direito. Sem outras alterações no exame físico. A abordagem terapêutica mais adequada para essa paciente deverá ser','','','["adiar o tratamento da tuberculose até que se avalie a contagem de linfócitos CD4 e a carga viral plasmática.", "iniciar o tratamento da tuberculose com drogas que não interajam com os inibidores da protease da terapia antirretroviral.", "adiar o início da terapia antirretroviral até o final do tratamento da tuberculose pulmonar.", "iniciar o tratamento da tuberculose e reavaliar início da terapia antirretroviral com contagem de linfócitos CD4 após 30 dias."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: iniciar o tratamento da tuberculose e reavaliar início da terapia antirretroviral com contagem de linfócitos CD4 após 30 dias..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Infectologia','Dois irmãos de 30 e 25 anos, ambos do sexo masculino, pardos, lavradores e residentes em Palmeiras do Piauí foram internados em Teresina, em 29/11/99 e 7/12/99, respectivamente. O mais velho apresentava quadro febril acompanhado de tosse, inicialmente seca e posteriormente produtiva, dor torácica, anorexia, astenia, perda ponderal (5Kg), dispneia leve e discreta icterícia. O mais novo apresentou febre, tosse seca e anorexia. Ambos apresentaram RX de tórax com condensações mistas difusas nos pulmões com predomínio em campos inferiores. As TC de tórax mostraram múltiplas opacidades intraparenquimatosas de tamanhos e formatos variáveis, contornos lobulados difusamente distribuídos nos pulmões. Outro paciente de 36 anos, sexo masculino, pardo, agricultor, residente em Alvorada do Gurgueia, foi atendido no ambulatório com sintomas de febre e dor torácica iniciados em 21/11/99. TC de tórax revelou micronódulos esparsamente distribuídos em ambos os pulmões. Evoluiu com desaparecimento espontâneo dos sintomas e achados radiográficos sem terapia específica. Os três pacientes haviam participado de oito caçadas a tatus no período de 27/10/99 a 11/11/99, no município de Palmeiras, situado em região semiárida, no sul do estado do Piauí. Essa série de casos do final da década de 90 resultou na descrição, como doença emergente no Brasil, da','','','["histoplasmose.", "coccidioidomicose.", "hantavirose.", "paragomíase."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: coccidioidomicose..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Infectologia','Paciente masculino, 26 anos, solteiro, açougueiro, acompanhado em ambulatório de Infectologia com diagnóstico de AIDS desde 1992, já tendo apresentado toxoplasmose de SNC, pneumonia por P. jirovecii e diarreia crônica como manifestações associadas, apresenta lesões violáceas na região do antebraço direito acompanhadas de dor, diminuição de sensibilidade e espessamento do nervo cubital. O anatomopatológico das lesões foi compatível com hanseníase dimorfa, com  Zihel-Neelsen demonstrando BAAR (poucas globias) e MITSUDA negativo. Na ocasião do diagnóstico, o CD4 do paciente era de 150 cel/mm3. Paciente portador de Anti-HCV reativo. Em uso de anticonvulsivantes em virtude de crises convulsivas subentrantes como sequela da toxoplasmose. Entre as drogas habitualmente utilizadas nos tratamento das comorbidades desse paciente, haverá prováveis interações medicamentosas, que impedem seu uso concomitante, entre','','','["difenilhidantoína e inibidores da protease.", "ribavirina e inibidores da transcriptase reversa não análogos de nucleosídeos.", "interferon peguilado e poliquimioterapia.", "poliquimioterapia e inibidores da transcriptase reversa análogos de nucleosídeos."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: difenilhidantoína e inibidores da protease..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Infectologia','A situação em que NÃO é indicado o uso de profilaxia para pneumocistose em indivíduos com infecção por HIV e que não iniciaram terapia antirretroviral é','','','["presença de candidose esofagiana.", "história recente de pneumonia por Pneumocystis jirovecii.", "carga viral do HIV recente superior a 100.000 cópias/ml.", "contagem de linfócitos CD4+ de 100 células/mm3."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: carga viral do HIV recente superior a 100.000 cópias/ml.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Infectologia','De acordo com as orientações do Ministério da Saúde do Brasil, indivíduos com infecção por HIV NÃO têm indicação de quimioprofilaxia para tuberculose com isoniazida na existência de','','','["contacto intradomicilar com indivíduo com baciloscopia sabidamente positiva (BAAR+).", "imagem calcificada em ápice pulmonar sem história de tratamento específico para tuberculose.", "reação intradérmica (PPD) de 8 mm, contagem de CD4+ de 650/mm3 e uso de zidovudina, lamivudina e efavirenz.", "reação intradérmica (PPD) de 12 mm e passado de tratamento com esquema contendo rifampicina, isoniazida e pirazinamida 2 anos antes."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: reação intradérmica (PPD) de 12 mm e passado de tratamento com esquema contendo rifampicina, isoniazida e pirazinamida 2 anos antes..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Infectologia','Indivíduo com infecção pelo HIV apresenta carga viral detectável após 2 anos de terapia com o primeiro esquema antirretroviral. A genotipagem realizada com o paciente em uso deste esquema apresenta apenas a mutação K103N. A droga que não deve ser incluída no novo esquema antirretroviral é','','','["atazanavir.", "etravirina.", "nevirapina.", "tenofovir."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: nevirapina..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Infectologia','O antibiótico que NÃO é opção para tratamento de situações clínicas em que há forte suspeita de participação de Pseudomonas aeruginosa é','','','["cefepima.", "ertapenem.", "piperacilina + tazobactam.", "ceftazidima."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: ertapenem.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Infectologia','O agente etiológico mais frequentemente implicado em quadros de sepse em indivíduos adultos esplenectomizados é','','','["Streptococus pneumoniae.", "Staphylococcus aureus.", "Salmonella entérica.", "Haemophilus influenzae."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: Streptococus pneumoniae..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Infectologia','Paciente do sexo masculino, de 45 anos, em tratamento quimioterápico de linfoma de Hodgkin apresenta quadro de febre em vigência de neutropenia (neutrófilos totais de 80/mm3). No sétimo dia de evolução da febre apresenta ainda 2 picos febris diários (39º C). Está em uso de cefepime (há 6 dias) e vancomicina (há 3 dias) e apresenta 300 granulócitos/mm3. As hemoculturas iniciais estão negativas. A melhor conduta é','','','["substituir o esquema antimicrobiano por meropenem e vancomicina.", "interromper o esquema antimicrobiano e tentar isolamento de agente etiológico com coleta de novas hemoculturas.", "associar amicacina ao esquema antimicrobiano em uso.", "associar caspofungina ao esquema antimicrobiano em uso."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa D. Resposta indicada no gabarito: associar caspofungina ao esquema antimicrobiano em uso..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Infectologia','A internação em quarto individual com precauções respiratórias de aerossol NÃO está indicada na ocorrência de','','','["lesão radiológica sugestiva de tuberculose em indivíduo com infecção por HIV.", "suspeita de angina diftérica em criança.", "varicela em indivíduo imunodeprimido por quimioterapia.", "suspeita de síndrome respiratória aguda grave (SARS) em viajante."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: suspeita de angina diftérica em criança..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Infectologia','Paciente do sexo masculino que desenvolve arritmia grave durante tratamento de calazar com antimoniais deverá ter seu tratamento reiniciado, após a resolução da arritmia, com','','','["ganciclovir.", "anfotericina B.", "caspofungina.", "benznidazol."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: anfotericina B..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Infectologia','O tratamento de malária transfusional por Plasmodium vivax deverá ser feito com','','','["clindamicina e mefloquina.", "cloroquina e primaquina.", "cloroquina.", "mefloquina e primaquina."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: cloroquina..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Infectologia','Você atende um técnico de laboratório que relata acidente perfurocortante com agulha com lúmen que havia sido usada imediatamente antes em cultura de Trypnassoma cruzi. A conduta recomendada para profilaxia de infecção por esse agente é','','','["realizar de reação de amplificação de ácidos nucleicos para T.cruzi em amostra de sangue do profissional 48-72 h após o acidente e iniciar quimioprofilaxia se o resultado for positivo.", "fazer apenas acompanhamento sorológico por 6 meses com orientação para restrição de doação de órgãos e sangue.", "início imediato de benznidazol com orientação para restrição de doação de órgãos e sangue.", "início imediato de benznidazol e realização de reação de amplificação de ácidos nucleicos para T.cruzi em amostra de sangue do profissional 7 dias após, e interromper a medicação se o resultado for negativo."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: início imediato de benznidazol com orientação para restrição de doação de órgãos e sangue..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Infectologia','O tratamento de quadro de meningoencefalite diagnosticada 72 h após intervenção cirúrgica em indivíduo com histórico de epilepsia grave e insuficiência renal em que é isolado em material de líquor Klebsiella pneumoniae, produtora de beta- -lactamase de espectro estendido, com sensibilidade em vitro a piperacilina-tazobactam, meropenem, imipenem e amicacina, deve ser feito preferencialmente com o uso intravenoso de','','','["meropenem.", "imipenem.", "piperacilina-tazobactam.", "polimixina b."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: meropenem..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Infectologia','Num recente levantamento sobre a frequência das principais parasitoses intestinais de duas comunidades da periferia de Aracaju (SE), foram examinadas amostras de fezes de 5.000 habitantes (3 amostras de cada indivíduo), aproximadamente 2.500 de cada comunidade. As técnicas realizadas foram os métodos de Lutz, Faust e Baerman-Morais. Foram encontrados os seguintes resultados: Comunidad Comunidad Parasitoses p-valor e A (%) e B (%) Ascaris lumbricoides 30 29 0,44 Ancilostomídeos 28 12 < 0,001 Trichurus trichiura 25 26 0,42 Schistosoma mansoni 0 0 - Strongyloides 15 2 < 0,001 stercoralis Enterobius 6 7 0,15 vermicularis Taenia sp 4 3 0,06 Entamoeba 3 12 < 0,001 histolytica/dispar Giardia lamblia 5 8 < 0,001 Iodamoeba butschlii 1 0 - Entamoeba coli 1 2 < 0,01 * p<0,05 = diferença estatisticamente significante Comparando-se as prevalências das enteroparasi-toses nas duas comunidades, é provável que','','','["a comunidade B tenha melhor rede de saneamento básico que a comunidade A.", "a comunidade A tenha menor utilização de calçados que a comunidade B.", "ambas as comunidades tenham pouca exposição a banhos em águas naturais.", "nenhuma inferência possa ser realizada."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa B. Resposta indicada no gabarito: a comunidade A tenha menor utilização de calçados que a comunidade B..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Infectologia','Na caracterização etiológica dos acidentes por animais peçonhentos, os sinais e sintomas de aparecimento precoce esperados são','','','["dor, edema e surgimento de bolhas como manifestações locais e diarreia, cólicas abdominais, bradicardia e escurecimento da visão como manifestações sistêmicas, nos acidentes pelas serpentes do gênero Bothrops.", "dor imediata intensa, edema, eritema e parestesias como manifestações locais e sudorese profusa, sialorreia, priapismo, hemorragias e hemoglobinúria como manifestações sistêmicas nos acidentes por aranhas do gênero Phoneutria.", "dor imediata intensa e parestesias como manifestação locais e sudorese profusa, vômitos incoercíveis, salivação excessiva, arritmia e convulsões como manifestações sistêmicas, nos acidentes por escorpiões do gênero Tityus.", "discreta dor local e parestesias como manifestações locais e ptose palpebral bilateral, oftalmoplegia, paralisia velopa- latina e mioglobinúria como manifestações sistêmicas nos acidentes por serpentes do gênero Micrurus."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: dor imediata intensa e parestesias como manifestação locais e sudorese profusa, vômitos incoercíveis, salivação excessiva, arritmia e convulsões como manifestações sistêmicas, nos acidentes por escorpiões do gênero Tityus..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Infectologia','Das medidas abaixo, aquela que NÃO é recomendada para a profilaxia de infecções do trato urinário em paciente que deverá ficar com a via urinária cateterizada por aproximadamente 2 semanas é','','','["profilaxia antimicrobiana com nitrofuran- toina.", "utilização de sistema coletor fechado.", "manutenção do saco coletor abaixo do nível da bexiga.", "inserção do cateter com luvas estéreis."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa A. Resposta indicada no gabarito: profilaxia antimicrobiana com nitrofuran- toina.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Infectologia','Um paciente de 56 anos, internado por acidente vascular cerebral há 10 dias, apresentou há 48 h febre de 38,5 oC. Ele se encontrava normotenso, normocardíaco e sem alterações evolutivas significativas no exame físico. Na inspeção do sítio de inserção do cateter vascular central, foi visto hiperemia. O médico responsável coletou hemoculturas, retirou o cateter, enviou a ponta do cateter para cultura e iniciou vancomicina com cefepime; 48 h após o início dos antibióticos, o paciente ficou apirético. Houve crescimento de Staphylococcus aureus, sensível à oxacilina, cefalotina, vancomicina, cefepima, linezolida em 1 das 3 amostras de hemoculturas coletadas e também na ponta do cateter. Ecocardiograma transtorácico realizado nesse momento não detectou alterações em válvulas cardíacas. A conduta adequada em relação à antibioticoterapia nesse momento é','','','["interromper o esquema antibiótico devido a resolução do quadro febril.", "manter o esquema antibiótico em uso até completar 14 dias.", "trocar o esquema antibiótico em uso para oxacilina IV e completar 14 dias.", "interromper a cefepima e manter a vancomicina até completar 14 dias."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Infectologia: alternativa C. Resposta indicada no gabarito: trocar o esquema antibiótico em uso para oxacilina IV e completar 14 dias..' from public.exams where slug='pmerj-2010-medico-infectologia' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-mastologia','PMERJ 2010 — Oficial — Médico Mastologia','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Mastologia','Os linfonodos de Rotter estão localizados','','','["inferiormente à borda do músculo pequeno peitoral.", "posteriormente ao músculo pequeno peitoral.", "anteriormente ao músculo grande peitoral.", "entre o músculo pequeno e grande peitoral."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa D. Resposta indicada no gabarito: entre o músculo pequeno e grande peitoral..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Mastologia','O nervo torácico longo ou “Nervo de Bell”, origina-se na face posterior dos ramos vertebrais de C5, C6 e C7 e está localizado ao longo do gradeado costal. Sua lesão resulta na paralisia do músculo','','','["pequeno peitoral.", "grande peitoral.", "serrátil anterior.", "grande dorsal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: serrátil anterior..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Mastologia','A Doença de Zuskas, ou abscesso retroareolar, apresenta-se como infecção crônica e recidivante da região retroareolar, podendo evoluir com formação de fístula, e é mais frequente em mulheres','','','["entre 20 e 29 anos, sempre após a 1ª gestação.", "entre 30 e 39 anos, usuárias de anticoncepcionais orais.", "entre 40 e 49 anos, com hábito de fumar.", "entre 20 e 29 anos, tabagistas e usuárias de anticoncepcionais orais."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: entre 40 e 49 anos, com hábito de fumar..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Mastologia','Assinale a opção cujas características NÃO são de maior importância patológica para os derrames papilares.','','','["Espontâneo / unilateral.", "Provocado / ductos múltiplos.", "Ducto único / serossanguinolento.", "Unilateral / água de rocha ."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: Provocado / ductos múltiplos..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Mastologia','Qual o microorganismo mais frequentemente encontrado durante o período da lactação, determinando os abscessos mamários puerperais?','','','["Streptococcus.", "Pseudomonas.", "Staphylococcus aureus.", "Proteus."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: Staphylococcus aureus..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Mastologia','Sobre o sistema BI-RADS, é correto afirmar que','','','["“0” significa avaliação incompleta e há necessidade de estudo adicional para conclusão diagnóstica.", "“1” significa mamografia negativa e mesmo que alguma anormalidade seja palpada no exame clínico não deve ser biopsiada.", "“2” significa achado suspeito.", "“3” não apresenta necessidade de acompanhamento com intervalos menores."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: “0” significa avaliação incompleta e há necessidade de estudo adicional para conclusão diagnóstica..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Mastologia','Lesões não palpáveis mamograficamente suspeitas, que exigem biópsia cirúrgica, devem ser localizadas pré-operatoriamente, permitindo ao cirurgião uma remoção adequada. Na técnica denominada “ROLL”, utiliza-se como marcador da lesão suspeita:','','','["agulha de Kopans.", "azul patente.", "isótopo radioativo.", "carvão estéril."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: isótopo radioativo..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Mastologia','Em uma paciente idosa e portadora de mamas volumosas e ptosadas, durante a palpação, foi observado cordão dololoroso na mama esquerda, compatível com a doença de Mondor. Tal afecção é causada por','','','["carcinoma metastático.", "embolia gordurosa.", "mastite por anaeróbio.", "tromboflebite venosa."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa D. Resposta indicada no gabarito: tromboflebite venosa..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Mastologia','No processo da amamentação, a produção de leite ocorre nos ácinos sob a influência da prolactina, enquanto a ocitocina estimula as células mamárias do tipo','','','["alveolares.", "conjuntivas.", "mioepiteliais.", "ductais."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: mioepiteliais..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Mastologia','As mamas são originadas durante o desenvolvimento embrionário dos folhetos ectodérmico e mesodérmico. Entre a 5ª e a 6ª semanas de vida intrauterina, ocorre a formação de','','','["crista mamária.", "mamilos primitivos.", "complexo areolopapilar.", "ductos lactíferos."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: crista mamária..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Mastologia','Paciente com 56 anos, pós-menopausada, observou surgimento de nódulo doloroso de 2 cm, endurecido, sem sinais flogísticos, localizado em região que havia sido traumatizada há dois meses. A mais provável hipótese diagnóstica para esse caso é','','','["adenocarcinoma.", "abscesso recidivante.", "esteatonecrose.", "lipoma reacional."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: esteatonecrose..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Mastologia','A hormonioterapia adjuvante com tamoxifeno por 5 anos é uma conduta bem estabelecida. Contudo, as pacientes devem ser monitorizadas em relação ao endométrio que sofre sua ação de forma expressiva. O achado histológico mais comumente encontrado em biópsias histeroscópicas dessas pacientes é','','','["atrofia glandular cística.", "hiperplasia atípica.", "adenocarcinoma.", "endometrite inespecífica."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: atrofia glandular cística..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Mastologia','A quimioterapia para o câncer de mama avançado é, rotineiramente, feita com associação de drogas que agem em diferentes fases do ciclo celular. Entretanto, quando se avalia a eficácia antiblástica desses medicamentos, a substância que pode ser usada isoladamente é','','','["methotrexate.", "capecitabina.", "ciclofosfamida.", "clorambucil."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: capecitabina..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Mastologia','As faixas fibrosas que representam o meio natural de suporte da mama são denominadas','','','["fáscia superficial de Camper.", "ligamentos de Cooper.", "fáscia de Halsted.", "ligamentos de Spence."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: ligamentos de Cooper..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Mastologia','Conceitualmente, o linfonodo sentinela é','','','["o linfonodo que protege a disseminação linfática do tumor.", "o linfonodo comprometido no câncer de mama.", "o primeiro linfonodo a receber a drenagem de um tumor.", "um linfonodo de mau prognóstico no câncer de mama."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: o primeiro linfonodo a receber a drenagem de um tumor..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Mastologia','Entre as anormalidades mamárias observadas abaixo, qual apresenta como sua causa mais comum os procedimentos iatrogênicos?','','','["Amastia.", "Amazia.", "Hipoplasia.", "Atelia."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: Amazia..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Mastologia','A hormonioterapia tem indicação em pacientes com câncer de mama','','','["receptor de estrogênio positivo e HER 2 positivo.", "receptor de estrogênio negativo e HER 2 positivo.", "receptores de estrogênio e/ou progesterona positivos.", "receptores de estrogênio e/ou progesterona negativos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: receptores de estrogênio e/ou progesterona positivos..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Mastologia','Consideram-se lesões mamárias não proliferativas, com EXCEÇÃO de','','','["cisto simples.", "adenose esclerosante.", "fibroadenomas.", "ectasia ductal."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: adenose esclerosante..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Mastologia','Após realização de mastectomia com linfadenectomia axilar, paciente cursa com parestesia dolorosa na face interna do braço. Tal sintoma traduz lesão de qual nervo?','','','["Toracodorsal.", "Toráxico longo.", "Intercostobraquial.", "Cutâneo lateral."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: Intercostobraquial..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Mastologia','Entre os fármacos abaixo, qual é considerado antiestrogênio puro?','','','["Fulvestranto.", "Tamoxifeno.", "Raloxifeno.", "Formestano."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: Fulvestranto..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Mastologia','A Classificação de Berg, para determinação dos níveis da axila, utiliza como referência anatômica o','','','["feixe toracodorsal.", "músculo peitoral menor.", "músculo peitoral maior.", "processo coracoide e veia cefálica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: músculo peitoral menor..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Mastologia','Mulher de 45 anos apresenta diagnóstico histopatológico de hiperplasia ductal com atipia após realização de biópsia de fragmento (core). A melhor conduta nesse caso é a','','','["biópsia aspirativa a vácuo.", "excisão cirúrgica ampla da área suspeita.", "mastectomia subcutânea.", "quimioprevenção com tamoxifeno."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: excisão cirúrgica ampla da área suspeita..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Mastologia','A atuação da prostaglandina E1 no mecanismo de ação na dor mamária cíclica é reconhecida. Dentre as droga abaixo, qual Não é utilizada em sua terapêutica?','','','["Doxorrubicina.", "Ácido gamalinolênico.", "Vitamina E.", "Tamoxifeno."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: Doxorrubicina.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Mastologia','O derrame papilar sanguinolento, sem tumor palpável, corresponde na maioria das vezes à(a)','','','["ectasia ductal.", "doença de Paget.", "papiloma intraductal.", "carcinoma papilífero."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: papiloma intraductal..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Mastologia','As micrometástases em linfonodos no câncer de mama são definidas como depósitos tumorais que variam','','','["entre 1 e 2 mm.", "entre 2 e 3 mm.", "entre 0,1 e 0,2 mm.", "entre 0,2 e 2 mm."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa D. Resposta indicada no gabarito: entre 0,2 e 2 mm..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Mastologia','Assinale a alternativa que NÃO é um parâmetro avaliado pelo método de Gail para estimativa de risco para câncer de mama.','','','["Idade da menarca.", "Biópsias prévias de mama.", "Número de parentes de primeiro grau com câncer de mama.", "Uso atual de terapia estrogênica (ACO ou TRH)."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa D. Resposta indicada no gabarito: Uso atual de terapia estrogênica (ACO ou TRH).. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Mastologia','Em relação à utilização da ressonância nuclear magnética, em mastologia, assinale a indicação INCORRETA.','','','["No carcinoma oculto da mama.", "Na avaliação de integridade de prótese de silicone .", "Na pesquisa da multifocalidade ou multicentricidade da lesão não pela esclarecida mamografia ou pela ecografia.", "Na avaliação de calcificações pleomórficas visando à detecção de carcinoma in situ."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa D. Resposta indicada no gabarito: Na avaliação de calcificações pleomórficas visando à detecção de carcinoma in situ.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Mastologia','Em relação à mutação dos genes BRCA-1 e do BRCA-2, assinale a opção INCORRETA.','','','["Herdar uma mutação do BRCA-1 e do BRCA-2 determina, durante a vida, um aumento de risco para tumores de mama, do ovário e do cólon.", "Nos casos de câncer da mama no homem BRCA positivos, é mais frequente a ocorrência da mutação BRCA-2.", "A mutação BRCA-2 confere maior risco para câncer de ovário que BRCA-1.", "O risco para câncer de mama em portadoras de BRCA-1 e BRCA-2 é de 85%."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: A mutação BRCA-2 confere maior risco para câncer de ovário que BRCA-1.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Mastologia','Paciente com tumor de mama de 3,5 cm e linfonodos endurecidos e fixos em axila ipsilateral deverá ser incluída no estádio','','','["IIIA.", "IIIB.", "IIIC.", "IV."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: IIIA..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Mastologia','A comparação entre mastectomia de Halsted e quadrantectomia com dissecção axilar completa mais radioterapia sobre a mama residual, para pacientes com idade inferior a 70 anos, T1(< ou =2cm) N0-N1a, se refere ao estudo','','','["Milão I.", "Milão II.", "NSABP-B-06.", "NSABP-B-06 e Milão I."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: Milão I..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Mastologia','A mastalgia pode estar relacionada a alterações funcionais benignas da mama (AFBM) ou a outras causas não hormonais. Em relação a esse assunto, assinale a opção INCORRETA.','','','["Na dor mamária, a orientação verbal pode resolver mais de dois terços dos casos.", "Pacientes portadoras de AFBM têm risco aumentado para câncer de mama.", "A mastalgia pode ser cíclica, não-cíclica e ter causas não-mamárias.", "Danazol e o tamoxifeno podem ser usados no tratamento das mastalgias."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: Pacientes portadoras de AFBM têm risco aumentado para câncer de mama.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Mastologia','Em relação à ginecomastia, assinale a opção INCORRETA.','','','["Enfermidade muito frequente, que incide em 60% a 70% dos meninos púberes, sugerindo tratar-se de um evento fisiológico transitório.", "Pode ser causada por neoplasias, inclusive não testiculares.", "Pode ocorrer por mecanismo idiopático, após traumatismo da parede torácica.", "Pode ser causada por drogas que inibem a ação e(ou) a síntese de testosterona; entre elas, o diazepan e a flutamida."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: Pode ocorrer por mecanismo idiopático, após traumatismo da parede torácica.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Mastologia','No caso de uma paciente com 42 anos de idade que apresenta imagem mamográfica diagnosticada como BI-RADS 2, a melhor conduta é','','','["repetir a mamografia com outras incidências e, caso persistam as imagens, biopsiar.", "sempre biopsiar.", "repetir a mamografia a cada seis meses para melhor acompanhamento da lesão.", "realizar acompanhamento mamográfico anual."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa D. Resposta indicada no gabarito: realizar acompanhamento mamográfico anual..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Mastologia','Em relação ao aspecto histopatológico do carcinoma ductal in situ da mama do tipo comedo, só NÃO podemos afirmar que','','','["apresentam características citológicas de baixa agressividade.", "as figuras de mitose são evidentes e numerosas.", "apresentam extensas áreas de necrose com calcificação.", "apresentam pleomorfismo nuclear."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: apresentam características citológicas de baixa agressividade..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Mastologia','Quanto aos fatores prognósticos do câncer de mama, podemos afirmar que','','','["o tamanho tumoral é uma variável essencial para se estabelecer uma proposta terapêutica.", "não existe uma correlação direta entre o tamanho tumoral e a taxa de recorrência da doença.", "a invasão vascular e linfática peritumoral são variáveis decisórias na opção terapêutica.", "os tumores ductais invasivos têm melhor prognóstico pelo menor comprometimento axilar do que os tumores intraductais."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: o tamanho tumoral é uma variável essencial para se estabelecer uma proposta terapêutica..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Mastologia','Em relação à recidiva local, após mastectomia, podemos afirmar que','','','["aproximadamente 85% das pacientes com recidiva local apresentam recidiva regional concomitante.", "aproximadamente 25% a 30% das recorrências locais apresentam metástases a distância.", "a recidiva local pós-mastectomia não está diretamente relacionada ao aumento de risco de recorrência da doença a distância.", "a recorrência local, geralmente, apresenta- se como uma úlcera na pele ou sob a pele da parede torácica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: aproximadamente 25% a 30% das recorrências locais apresentam metástases a distância..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Mastologia','Durante o exame físico das mamas, a manobra de contração dos músculos peitorais dá ênfase a','','','["edema da pele da mama.", "ulcerações e eczemas no mamilo.", "áreas sutis de retração.", "linfonodos axilares suspeitos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: áreas sutis de retração..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Mastologia','São dois achados mamográficos frequentes no carcinoma ductal in situ da mama:','','','["distensão de grandes e pequenos ductos / calcificações tipo grão de areia.", "calcificações tipo grão de areia / densidade assimétrica com distorção arquitetural.", "papiloma intracístico / nódulo sólido microlobulado.", "calcificações tipo grão de areia / nódulo de papiloma intraductal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: papiloma intracístico / nódulo sólido microlobulado..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Mastologia','Alguns tumores desenvolvem menos metástase e as pacientes possuem maior intervalo livre de doenças. Dentre os abaixo citados, qual NÃO apresenta tal característica?','','','["Carcinoma medular.", "Carcinoma túbulo-lobular.", "Carcinoma papilífero.", "Carcinoma mucinoso."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: Carcinoma papilífero..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Mastologia','As microcalcificações do tipo IV, segundo a classificação de Le Gal, corresponde a','','','["microcalcificações anulares e arredondadas.", "microcalcificações irregulares tipo grão de sal ou areia.", "microcalcificações arredondadas e uniformes.", "microcalcificações punctiformes tipo poeira."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: microcalcificações irregulares tipo grão de sal ou areia..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Mastologia','Em relação ao estudo histopatológico, o achado de metástase em 5 linfonodos axilares, após tratamento cirúrgico do câncer da mama, corresponde a','','','["pN1a.", "pN1b.", "pN2a.", "pN2b."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: pN2a..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Mastologia','Quanto ao carcinoma lobular in situ, podemos afirmar que','','','["somente 5% morrem por doença invasiva em 10 anos.", "seu principal diagnóstico diferencial é com a hiperplasia ductal atípica.", "ocorre com frequência em mulheres idosas.", "se apresenta, frequentemente, como uma lesão clínica palpável, firme e indolor."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: somente 5% morrem por doença invasiva em 10 anos..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Mastologia','São causas de retração da pele durante o exame clínico das mamas, EXCETO:','','','["doença de Paget.", "doença de Mondor.", "doença de Zuskas.", "esteatonecrose."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: doença de Paget.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Mastologia','Observe as afirmativas a seguir, em relação à conduta nas lesões não palpáveis: I. nos casos Categoria 2 (BI-RADS) devem ser realizados exames semestrais.  II. nos casos Categoria 3 (BI-RADS) devem ser realizados dois controles radiológicos com intervalo semestral, seguidos de dois controles com intervalo anual. III. nas lesões Categoria 4 e 5 (BI-RADS) está indicado estudo citológico e histopatológico, que pode ser realizado por meio de PAAF, mamotomia ou biópsia cirúrgica. Está correto apenas o que se firma em','','','["I .", "II .", "I e II .", "II e III ."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa D. Resposta indicada no gabarito: II e III ..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Mastologia','Em relação ao tratamento cirúrgico do câncer de mama, podemos afirmar que','','','["a reconstrução mamária imediata deverá ser descartada ao se indicar uma mastectomia em pacientes com mais de 45 anos, mesmo com boas condições clínicas.", "a biopsia do linfonodo sentinela não deve ser realizada em casos de carcinoma in situ com comedonecrose ou alto grau histológico (GIII).", "a presença de calcificações suspeitas difusas é contraindicação absoluta para realização de cirurgia conservadora de mama.", "o linfonodo sentinela pode ser realizado em pacientes com axila comprometida clinicamente."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: a presença de calcificações suspeitas difusas é contraindicação absoluta para realização de cirurgia conservadora de mama..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Mastologia','Atualmente, existem duas alterações genéticas ligadas ao câncer de mama, denominadas BRCA1 e BRCA2. Elas estão localizadas respectivamente em','','','["17p21 e 13q12-13.", "17q12-21 e 13q12-13.", "17q12-21 e 13p21.", "17p21e 13p21."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: 17q12-21 e 13q12-13..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Mastologia','Qual das seguintes características celulares NÃO é importante na resposta terapêutica à quimioterapia?','','','["O tamanho do tumor.", "A fração de crescimento do tumor.", "O tempo de duplicação do tumor.", "A integridade imunológica do hospedeiro."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa D. Resposta indicada no gabarito: A integridade imunológica do hospedeiro.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Mastologia','Uma das vantagens da técnica do TRAM - pediculado para reconstrução mamária é manter a nutrição dos tecidos através dos vasos','','','["hipogástricos", "epigástricos superiores", "mesentéricos superiores", "mesentéricos inferiores"]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa B. Resposta indicada no gabarito: epigástricos superiores.' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Mastologia','Ao considerarmos a curva de crescimento que os tumores sólidos apresentam, também denominada matematicamente de função Gompertziana, em que momento da curva o tratamento pela quimioterapia é mais eficiente?','','','["Na primeira porção, onde a fração de crescimento é maior.", "Na segunda, onde a taxa de crescimento tumoral é maior.", "Na terceira, onde o volume tumoral é maior.", "A eficiência independe da fase e sim da intensidade de dose e sensibilidade às drogas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa A. Resposta indicada no gabarito: Na primeira porção, onde a fração de crescimento é maior..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Mastologia','A forma mais frequente de sarcoma da mama é','','','["leiomiossarcoma.", "lipossarcoma.", "angiossarcoma.", "fibrossarcoma."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Mastologia: alternativa C. Resposta indicada no gabarito: angiossarcoma..' from public.exams where slug='pmerj-2010-medico-mastologia' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-nefrologia','PMERJ 2010 — Oficial — Médico Nefrologia','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Nefrologia','Sobre o exame de urina simples (tipo I), é correto afirmar:','','','["A presença de nitritos sugere infecção urinária por estreptococos.", "Nas fitas, o método mais comum para detecção da glicose não é enzimático, o que diminui a especificidade da reação.", "Um teste de hemoglobina positivo pode significar hemoglobina livre na urina ou hematúria.", "Pessoas vegetarianas tendem a ter urina mais ácida."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: Um teste de hemoglobina positivo pode significar hemoglobina livre na urina ou hematúria..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Nefrologia','Sobre a avaliação da filtração glomerular, é correto afirmar:','','','["O clearance de creatinina com a urina de 24 horas é uma medida clinicamente aceitável da filtração, sendo mais preciso em pacientes com insuficiência renal avançada.", "A estimativa da filtração glomerular através das fórmulas de Cockroft-Gault e MDRD tem maior precisão na faixa de filtração glomerular superior a 60 ml/min.", "A cistatina é filtrada no glomérulo, porém não é reabsorvida ou secretada no túbulo constituindo uma opção mais precisa para a estimativa da filtração glomerular.", "Nos casos de insuficiência renal avançada, a média dos clearances da ureia e creatinina é uma medida mais precisa da filtração glomerular do que o clearance isolado desses compostos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: Nos casos de insuficiência renal avançada, a média dos clearances da ureia e creatinina é uma medida mais precisa da filtração glomerular do que o clearance isolado desses compostos..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Nefrologia','Em relação aos exames de imagem para avaliação renal, pode-se afirmar:','','','["Na ultrassonografia, em condições normais, as pirâmides renais são hiperecogênicas em relação ao tecido cortical.", "Na cintigrafia, O DTPA é o composto mais usado para determinação de cicatrizes renais.", "O padrão ouro para investigação de urolitíase é a tomografia computadorizada.", "A urografia excretora é o exame mais útil para detecção de refluxo vésico-ureteral."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: O padrão ouro para investigação de urolitíase é a tomografia computadorizada..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Nefrologia','No que concerne aos distúrbios ácidobásicos, assinale a opção INCORRETA.','','','["A dosagem do cloreto urinário em amostra é particularmente útil no diagnóstico diferencial das acidoses metabólicas.", "O valor da pCO2 na alcalose metabólica raramente ultrapassa 55mmHg.", "Bicarbonato de sódio intravenoso, geralmente, não está indicado nos casos de acidose hiperclorêmica onde o pH está maior do que 7,2.", "A acidose láctica, a cetoacidose diabética e a ingestão acidental de metanol constituem causas de acidose metabólica com hiato aniônico aumentado."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa A. Resposta indicada no gabarito: A dosagem do cloreto urinário em amostra é particularmente útil no diagnóstico diferencial das acidoses metabólicas.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Nefrologia','Sobre a hiperpotassemia, assinale a opção INCORRETA.','','','["No eletrocardiograma, podem ser encontrados achatamento de onda P, ondas T apiculadas e simétricas e alargamento do complexo QRS.", "Em situações emergenciais, o gluconato de cálcio deve ser a primeira medicação já que sua administração é prontamente acom- panhada pela redução do K sérico.", "Beta2 miméticos, bicarbonato, glicoinsuli- noterapia, resinas de troca e diálise são opções no manuseio dessa condição.", "Insuficiência renal, aguda ou crônica, é uma desordem subjacente em muitos casos de hipercalemia."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Resposta indicada no gabarito: Em situações emergenciais, o gluconato de cálcio deve ser a primeira medicação já que sua administração é prontamente acom- panhada pela redução do K sérico.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Nefrologia','Sobre a hipocalemia e depleção de potássio, assinale a opção INCORRETA.','','','["Hipocalemia está presente na grande maioria dos casos de hipertensão decorrente de hiperaldosteronismo primário.", "Pode ocorrer hipocalemia na ausência de depleção corporal de potássio.", "Em casos de vômitos intensos e persistentes, a maior perda de potássio ocorre pelos rins.", "Em casos de depleção grave de potássio, o potássio infundido inicialmente deve ser diluído preferencialmente em soro fisiológico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa A. Resposta indicada no gabarito: Hipocalemia está presente na grande maioria dos casos de hipertensão decorrente de hiperaldosteronismo primário.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Nefrologia','Sobre o prognóstico e a gênese da insuficiência renal aguda, assinale a opção INCORRETA.','','','["A forma oligúrica tem mortalidade mais elevada do que a não oligúrica.", "Isquemia renal e nefrotoxinas estão envolvidas na maior parte dos casos, mas, nas unidades de terapia intensiva, a sepse aparece como um fator subjacente frequente.", "A nefrotoxicidade por drogas pode ocorrer por diversos mecanismos, mas o preponderante é a indução de necrose cortical em placas.", "Drogas como a cocaína e o etanol podem causar injúria renal por rabdomiólise."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: A nefrotoxicidade por drogas pode ocorrer por diversos mecanismos, mas o preponderante é a indução de necrose cortical em placas.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Nefrologia','O diagnóstico etiológico da insuficiência renal aguda é um elemento importante ao adequado manuseio dessa condição. Das afirmativas abaixo, assinale a INCORRETA.','','','["Os casos associados à leptospirose cursam com hiperpotassemia frequente devido ao elevado catabolismo desses pacientes.", "A presença de anúria sugere causa obstrutiva.", "A presença de cristais de oxalato na urina e acidose metabólica com hiato aniônico aumentado sugere intoxicação por etilenoglicol.", "Em idosos com insuficiência renal sem causa aparente, mas com história de dor lombar, deve-se suspeitar de mieloma múltiplo."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa A. Resposta indicada no gabarito: Os casos associados à leptospirose cursam com hiperpotassemia frequente devido ao elevado catabolismo desses pacientes.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Nefrologia','Sobre o diagnóstico da insuficiência renal aguda, é correto afirmar:','','','["O exame do sedimento urinário não é contributivo.", "Nos casos pré-renais, a osmolaridade e o sódio urinário encontram-se elevados.", "A presença de uma relação ureia/creatinina no plasma superior a 40 sugere insuficiência renal parenquimatosa.", "A biópsia renal precoce está indicada se há suspeita de glomerulonefrite ou vasculite."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: A biópsia renal precoce está indicada se há suspeita de glomerulonefrite ou vasculite..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Nefrologia','Sobre a nefrotoxicidade por antibiótiocos, assinale a opção INCORRETA.','','','["A incidência inicialmente elevada com a vancomicina foi provavelmente relacionada a impurezas das primeiras preparações desse composto.", "As nefrites intersticiais relacionadas às penicilinas ocorrem com a meticilina e as oxazolil-pencilinas não tendo sido relatadas com a amoxicilina.", "O aztreonam é um antibiótico com espectro semelhante aos aminoglicosídeos que exibe baixa nefrotoxicidade.", "A rifampicina pode causar nefrite intersticial e, também, quadros de vasculite sistêmica associada à glomerulonefrite de crescentes."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Resposta indicada no gabarito: As nefrites intersticiais relacionadas às penicilinas ocorrem com a meticilina e as oxazolil-pencilinas não tendo sido relatadas com a amoxicilina.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Nefrologia','Acerca da nefrotoxicidade por drogas, assinale a afirmativa correta.','','','["O diabetes mellitus e o mieloma múltiplo são os fatores de risco mais importantes injúria renal por contrastes iodados.", "Os anti-inflamatórios não hormonais podem causar nefrite intersticial aguda, síndrome nefrótica, hipertensão arterial, hipocalemia e agravar doença renal crônica pré-existente.", "O uso prolongado de acetazolamida já foi associado à urolitíase.", "Os inibidores da enzima conversão da angiotensina, mas não os bloqueadores do receptor AT-1, podem ocasionar insuficiência renal hemodinâmica em pacientes com estenose bilateral das artérias renais."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: O uso prolongado de acetazolamida já foi associado à urolitíase..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Nefrologia','Sobre o carcinoma de células renais, pode-se afirmar que','','','["constitui cerca de 30% dos tumores malignos do rim em adultos.", "a tríade clássica do hipernefroma (dor, hematúria e massa palpável) ocorre na minoria dos casos.", "a ressonância magnética é o exame de escolha para o seu diagnóstico.", "no caso de tumores bem localizados ou com invasão apenas local, a terapia preferida é a tumorectomia para melhor preservar a função renal."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Resposta indicada no gabarito: a tríade clássica do hipernefroma (dor, hematúria e massa palpável) ocorre na minoria dos casos..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Nefrologia','Em relação à prevalência e história natural da nefropatia diabética, assinale a opção INCORRETA.','','','["É a causa mais comum de ingresso em terapia renal substitutiva nos países desenvolvidos.", "A presença de microalbuminúria (30-300 mg de excreção de albumina/dia) caracteriza a nefropatia diabética incipiente.", "Valores de excreção de albumina acima de 300mg/dia são habitualmente detectáveis pelo teste da fita usado no exame simples de urina, caracterizando a fase de nefropatia diabética clínica ou declarada.", "A frequência de hipertensão arterial é semelhante nas três fases da moléstia."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: A frequência de hipertensão arterial é semelhante nas três fases da moléstia.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Nefrologia','Sobre o tratamento da nefropatia diabética, pode-se afirmar:','','','["Os inibidores do sistema renina angiotensina estão indicados na nefropatia diabética mesmo em indivíduos normotensos.", "Optando-se pelo controle metabólico com antidiabéticos orais, os mais indicados são as drogas da família das glitazonas.", "O emprego de insulina ou análogos está indicado em menos de 10% dos diabéticos com nefropatia avançada.", "O transplante renal não é uma boa opção na nefropatia diabética avançada."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa A. Resposta indicada no gabarito: Os inibidores do sistema renina angiotensina estão indicados na nefropatia diabética mesmo em indivíduos normotensos..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Nefrologia','Sobre o lúpus eritematoso sistêmico (LES), assinale a afirmativa correta.','','','["Segundo o American College of Rheumatology, são necessários pelo menos 3 dos 11 critérios alistados para que um paciente tenha uma chance substancial de ter LES.", "Anticorpos anti-DNA de dupla hélice e complemento baixo estão presentes no lúpus induzido por drogas, mas o que caracteriza essa condição é a positividade para anticorpos anti-histonas.", "Anticorpos anti-Sm são bastante específicos para o diagnóstico do LES estando presentes em mais da metade dos pacientes.", "Gravidez tem sido associada à piora da função renal, mas pacientes sem atividade por pelo menos 6 meses têm evolução mais favorável."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: Gravidez tem sido associada à piora da função renal, mas pacientes sem atividade por pelo menos 6 meses têm evolução mais favorável..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Nefrologia','Acerca das alterações fisiológicas na gravidez, assinale a opção INCORRETA.','','','["A atividade plasmática de renina aumenta em mais de dez vezes.", "As vias excretoras dilatam-se caracterizando a hidronefrose gestacional.", "Há aumento da volemia e diminuição da resistência periférica que resultam em diminuição da pressão arterial.", "O fluxo plasmático renal diminui tornando o rim mais suscetível à isquemia."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: O fluxo plasmático renal diminui tornando o rim mais suscetível à isquemia.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Nefrologia','Sobre a gestose hipertensiva da gravidez, assinale a afirmativa correta.','','','["Afeta mais grandes multíparas.", "Nos casos que evoluem com insuficiência renal aguda, a lesão mais encontrada é a necrose tubular aguda.", "A redução dos níveis séricos de ácido úrico constitui uma indicação precoce de sua instalação.", "Hipertensão prévia e diabetes mellitus, mas não doença renal crônica em estágio 3, constituem fatores de risco para pré- -eclampsia."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Resposta indicada no gabarito: Nos casos que evoluem com insuficiência renal aguda, a lesão mais encontrada é a necrose tubular aguda..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Nefrologia','Sobre as alterações renais no envelhecimento, assinale a afirmativa correta.','','','["A partir dos 40 anos, observa-se redução da taxa de filtração glomerular ao redor de 1ml/ano.", "O fluxo plasmático renal diminui, porém em uma proporção menor do que a observada na filtração glomerular.", "As quedas da filtração glomerular e do fluxo plasmático renal são mais acentuadas no gênero feminino.", "A diluição máxima da urina aumenta pela incapacidade de manter uma urina adequadamente concentrada."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa A. Resposta indicada no gabarito: A partir dos 40 anos, observa-se redução da taxa de filtração glomerular ao redor de 1ml/ano..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Nefrologia','Sobre as glomerulopatias nos idosos, assinale a afirmativa INCORRETA.','','','["Quando a biópsia renal é indicada por síndrome nefrótica, a lesão mais encontrada é a glomerulopatia membranosa.", "No contexto clínico de glomerulonefrite rapidamente progressiva, a lesão mais prevalente é a glomeurlonefrite crescêntica pauci-imune.", "Dependendo da série analisada, a amiloidose renal pode constituir o segundo ou o terceiro achado mais frequente em idosos nefróticos.", "A lesão mínima é rara no idoso acometendo menos do que 10% dos casos biopsiados."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: A lesão mínima é rara no idoso acometendo menos do que 10% dos casos biopsiados.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Nefrologia','Sobre os mecanismos de ação dos diuréticos, assinale a afirmativa correta.','','','["Os tiazídicos inibem o cotransporte de Na e Cl no túbulo proximal.", "O triantereno e a amilorida bloqueiam o canal epitelial de sódio, principalmente, no túbulo coletor cortical.", "A furosemida aumenta a reabsorção de cálcio no segmento ascendente espesso da alça de Henle.", "A furosemida e os tiazídicos diminuem a capacidade de diluir a urina ao máximo."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Resposta indicada no gabarito: O triantereno e a amilorida bloqueiam o canal epitelial de sódio, principalmente, no túbulo coletor cortical..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Nefrologia','Dos esquemas de diálise regular empregados na doença renal crônica terminal, qual deles tem sido associado a um balanço negativo de fósforo demandando, em algumas circunstâncias, reposição desse elemento?','','','["Hemodiálise convencional (4h, 3x/semana).", "Hemodiálise diária de curta duração (2h, 6 a 7x/semana).", "Diálise peritoneal ambulatorial continua com icodextrina.", "Hemodiálise diária noturna de longa duração."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: Hemodiálise diária noturna de longa duração..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Nefrologia','Sobre o acesso vascular em hemodiálise, pode- se afirmar que:','','','["a fístula arteriovenosa é o acesso definitivo de eleição, exceto para diabéticos do tipo II, nos quais o acesso inicial mais indicado é o enxerto vascular.", "complicações relacionadas ao acesso vascular raramente resultam em internação hospitalar.", "o cateter vascular com almofada dupla é uma opção de acesso definitivo para pacientes sem vasos periféricos que permitam confecção de fístula nativa ou colocação de enxerto vascular.", "nos casos em que o emprego de cateteres de duplo lúmen de curta permanência não pode ser evitado, recomenda-se sua troca rotineira a cada duas semanas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: o cateter vascular com almofada dupla é uma opção de acesso definitivo para pacientes sem vasos periféricos que permitam confecção de fístula nativa ou colocação de enxerto vascular..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Nefrologia','Sobre os esquemas de hemodiálise regular, assinale a opção INCORRETA.','','','["O tradicional, de 3 sessões semanais de 4 horas, está associado com maior incidência de complicações ao fim de semana.", "Na hemodiálise com fluxo sanguíneo alto, dialisadores de alta permeabilidade e alto fluxo do banho de diálise, sessões de 2 horas são, em geral, suficientes para diálise adequada.", "Com hemodiálise diária de curta duração, em regime de 6 a 7 sessões de diálise por semana, as sessões são menos sintomáticas do que no esquema tradicional.", "A hemodiálise noturna de longa duração é o esquema que reduz o nível das escórias nitrogenadas para mais próximo dos valores normais."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Resposta indicada no gabarito: Na hemodiálise com fluxo sanguíneo alto, dialisadores de alta permeabilidade e alto fluxo do banho de diálise, sessões de 2 horas são, em geral, suficientes para diálise adequada.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Nefrologia','Adotando o conceito de distribuição unicompartimental de ureia, quantas horas de hemodiálise por semana são necessárias para que um homem de 97 Kg alcance um Kt/V semanal de 3,6 empregando um dialisador com um clearance de ureia in vivo de 250ml/min?','','','["12.", "9,5.", "14.", "10."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: 14..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Nefrologia','Acerca do hiperparatireoidismo secundário à doença renal crônica (DRC), pode-se afirmar:','','','["Não está associado à hiperplasia das glândulas paratireoides.", "É caracterizado por uma doença óssea de baixo remanejamento.", "Acomete menos de 20% dos pacientes em hemodiálise.", "As formas graves estão associadas a risco aumentado de calcificação cardiovascular e mortalidade."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: As formas graves estão associadas a risco aumentado de calcificação cardiovascular e mortalidade..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Nefrologia','Em relação aos distúrbios minerais e ósseos da doença renal crônica e à vitamina D, assinale a opção correta.','','','["Baixos níveis séricos de calcidiol não se associam ao desenvolvimento de hiperparatireoidismo secundário.", "A deficiência de calcidiol é detectada somente em indivíduos que vivem em países com menor radiação solar.", "No tratamento do hiperparatireoidismo secundário, o uso de calcitriol é a melhor forma de controlar a hipercalcemia, independente dos níveis de calcidiol.", "Na presença de hipercalcemia e/ou hiperfosfatemia, o tratamento com calcitriol deve ser instituído com cautela."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: Na presença de hipercalcemia e/ou hiperfosfatemia, o tratamento com calcitriol deve ser instituído com cautela..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Nefrologia','Em relação aos antígenos HLA, que são importantes ao reconhecimento dos tecidos pelo sistema imune, pode-se afirmar que','','','["os antígenos HLA de classe I estão presentes em praticamente todas as células do organismo, incluindo leucócitos, plaquetas e hemácias.", "os antígenos HLA de classe II estão restritos aos linfócitos T e células apresentadoras de antígenos.", "um dos componentes dos antígenos HLA da classe I é a beta 2-microglobulina.", "tanto os antígenos de classe I como os de classe II são codificados na mesma região situada no braço curto do cromossomo 8 humano."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: um dos componentes dos antígenos HLA da classe I é a beta 2-microglobulina..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Nefrologia','O baixo fluxo sanguíneo em capilar glomerular determina','','','["baixa pressão de filtração e diminuição da pressão oncótica em capilar na saída do glomérulo com aumento da reabsorção tubular proximal de sal e água.", "baixa pressão de filtração e diminuição da pressão oncótica em capilar na saída do glomérulo com diminuição da reabsorção tubular proximal de sal e água.", "aumento da pressão oncótica em capilar na saída do glomérulo, refletindo em capilar peritubular com aumento da reabsorção tubular proximal de sal e água.", "aumento da pressão oncótica em capilar na saída do glomérulo, refletindo em capilar peritubular com diminuição da reabsorção tubular proximal de sal e água."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: aumento da pressão oncótica em capilar na saída do glomérulo, refletindo em capilar peritubular com aumento da reabsorção tubular proximal de sal e água..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Nefrologia','A secreção de hidrogênio através dos túbulos se dá principalmente por meio de dois transportadores. São eles:','','','["contratransporte de Na+ e H+ em túbulo proximal e H+-ATPase em ducto coletor.", "cotransporte de H+ e Cl- em ducto coletor e H+-ATPase em túbulo proximal.", "cotransporte Na+ e H+ em túbulo proximal e H+-ATPase em ducto coletor.", "contratransporte Na+ e H+ em túbulo proximal e cotransporte Na+-HCO3- em ducto coletor."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa A. Resposta indicada no gabarito: contratransporte de Na+ e H+ em túbulo proximal e H+-ATPase em ducto coletor..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Nefrologia','O efeito antidiurético da vasopressina é atribuído à sua ligação a receptores V2 em ducto coletor. Esse efeito se dá à custa de','','','["ativação de megalina com pinocitose de gotículas de água.", "estímulo para abertura de canais de água em via paracelular.", "expressão de canais de água em membrana basolateral de células intercaladas.", "inserção de aquaporinas em membrana apical após estímulo de AMP cíclico."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: inserção de aquaporinas em membrana apical após estímulo de AMP cíclico..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Nefrologia','A hiponatremia ocorre em diversas situações clínicas como sinal de agravamento de síndrome nefrótica, insuficiência cardíaca e cirrose hepática. Nessas condições, o mecanismo fisiopatológico mais provável é','','','["secreção inapropriada de hormônio antidiurético.", "diabetes insípidus nefrogênico.", "secreção não osmótica de hormônio antidiurético.", "polidipsia secundária à ativação do eixo renina-angiotensina-aldosterona."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: secreção não osmótica de hormônio antidiurético..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Nefrologia','São características do edema nefrítico, com EXCEÇÃO de','','','["inibição de renina angiotensina aldosterona.", "aumento de pressão hidrostática em microcirculação.", "aumento da volemia", "ativação de renina-angiotensina- aldosterona."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: ativação de renina-angiotensina- aldosterona..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Nefrologia','A injúria renal aguda permanece apresentando significativos índices de mortalidade em todo o mundo. Assinale a causa mais comum de óbito na IRA:','','','["hiperpotassemia.", "edema pulmonar agudo.", "infecção.", "acidose metabólica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: infecção..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Nefrologia','A nefropatia de Berger, também conhecida como nefropatia por IgA, vem sendo uma das causas importantes de glomerulonefrite crônica evoluindo para doença renal crônica. Suas apresentações clínica e histopatológica são bem caracterizadas respectivamente por','','','["síndrome nefrótica cerca de 20 dias após infecção de vias aéreas superiores e proliferação mesangial com depósitos de IgA.", "hematúria micro ou macroscópica concomitante a infecção de vias aéreas superiores e lesão proliferativa mesangial com depósitos de IgA.", "síndrome nefrítica e esclerose glomerular segmentar e focal.", "hematúria micro ou macroscópica 20 dias após infecção de vias aéreas superiores e lesão proliferativa mesangial com depósitos de IgA."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Resposta indicada no gabarito: hematúria micro ou macroscópica concomitante a infecção de vias aéreas superiores e lesão proliferativa mesangial com depósitos de IgA..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Nefrologia','Sobre as vasculites sistêmicas, é correto afirmar:','','','["A presença de mononeuríte múltipla (ou polineuropatia assimétrica) é altamente sugestiva de granulomatose de Wegener e se associa em 50% dos casos de positividade para cANCA.", "Pacientes com granulomatose de Wegener na forma limitada apresentam sinais e sintomas essencialmente respiratórios embora a positividade para cANCA seja encontrada em até 95% dos casos.", "O acometimento renal na síndrome de Churg-Strauss, embora raro, é em geral acompanhado por positividade para cANCA em cerca de 85% e é caracterizado por glomerulonefrite mesangial, raramente acompanhada de lesões necrotizantes.", "A púrpura de Henoch-Scholein é a vasculite mais frequente na população pediátrica, e se caracteriza por púrpura palpável, dor abdominal, artralgia e glomerulonefrite semelhante à encontrada na doença de Berger."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: A púrpura de Henoch-Scholein é a vasculite mais frequente na população pediátrica, e se caracteriza por púrpura palpável, dor abdominal, artralgia e glomerulonefrite semelhante à encontrada na doença de Berger..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Nefrologia','Sobre as vasculites sistêmicas, assinale a opção INCORRETA.','','','["Para o diagnóstico histopatológico de granulomatose de Wegener deve-se preferir a obtenção de biópsia de nasofaringe quando há lesão, tendo em vista ser relativamente pouco invasiva.", "A síndrome de Churg Strauss é caracterizada por quadro respiratório que consiste de asma, eosinofilia e ausência de granulomas, o que a distingue da granulomatose de Wegener.", "A púrpura de Henoch-Scholein é considerada uma vasculite por hipersensibilidade em que depósitos de IgA são encontrados, o que a distingue de outras vasculites.", "A vasculite essencial por crioglobulinemia é, em geral, devido à infecção pelo vírus da hepatite C e acomete capilares, arteríolas e vênulas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Resposta indicada no gabarito: A síndrome de Churg Strauss é caracterizada por quadro respiratório que consiste de asma, eosinofilia e ausência de granulomas, o que a distingue da granulomatose de Wegener.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Nefrologia','Em relação à nefropatia obstrutiva, é correto afirmar:','','','["É caracterizada por hidronefrose do rim acometido, bilateral em obstruções ao nível de bexiga e uretra e, nos casos de obstrução total, evolui para insuficiência renal em cerca de 75% dos casos.", "A lesão renal é difusa com desorganização não inflamatória do parênquima e que reverte após correção cirúrgica do processo obstrutivo.", "Evolui com hidronefrose do rim acometido, o qual apresenta processo de desarranjo fibroso acelular com perda funcional proporcional ao tempo de obstrução.", "Desencadeia quadro intrarrenal inflamatório com nefrite túbulo-intersticial crônica e perda funcional."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: Desencadeia quadro intrarrenal inflamatório com nefrite túbulo-intersticial crônica e perda funcional..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Nefrologia','A glomerulonefrite rapidamente progressiva (GNRP) é importante causa de insuficiência renal em várias faixas etárias e em ambos os sexos. Sobre ela, assinale a opção INCORRETA.','','','["A GNRP tipo III é acompanhada de lesão renal pauci-imune com formação de crescentes fibrocelulares, acometendo indivíduos com vasculites como a granulomatose de Wegener, porém sem positividade para cANCA.", "A GNRP tipo I é caracterizada pela presença de anticorpo antimembrana basal glomerular, o que caracteriza a síndrome de Goodpasture e seu tratamento consiste em imunossupressão e plasmaferese.", "Todos os tipos de GNRP têm como patogênese a ruptura da membrana basal glomerular, extravasamento de células como macrófagos e linfócitos T, fibrinogênio e liberação de citocinas com consequente formação de crescentes.", "A GNRP tipo II ocorre por formação de imunocomplexos e pode incidir em doenças como a glomerulonefrite aguda pós- -estreptocócica, lúpus eritematoso e glomerulonefrite membrano-proliferativa."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa A. Resposta indicada no gabarito: A GNRP tipo III é acompanhada de lesão renal pauci-imune com formação de crescentes fibrocelulares, acometendo indivíduos com vasculites como a granulomatose de Wegener, porém sem positividade para cANCA.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Nefrologia','Paciente do sexo feminino, 23 anos, com quadro de hematúria macroscópica recorrente, creatinina sérica de 2,2 mg/dL, hipertensão arterial em torno de 160/100 mmHg, proteinúria em torno de 5,3 g/24h, discreta rarefação de tecido subcutâneo em dorso e alterações visuais compatíveis com degeneração macular, é um provável caso de','','','["glomerulopatia membranosa lúpica.", "glomerulonefrite por IgA.", "glomerulonefrite por depósitos densos.", "glomerulosclerose segmentar e focal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: glomerulonefrite por depósitos densos..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Nefrologia','Quanto à glomerulonefrite aguda pós- -estreptocócica, assinale a afirmação INCORRETA.','','','["A hematúria em geral desaparece após 3 a 6 meses de doença.", "Corticoterapia é preconizada nas situações de oligúria com hipervolemia grave e insuficiência cardíaca.", "O prognóstico é normalmente benigno, porém há relatos de evolução para insuficiência renal crônica por glomerulosclerose focal até cerca de 40 anos após o episódio agudo.", "O aparecimento do quadro clínico é precedido por período de latência que pode ser mais prolongado após piodermite."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Resposta indicada no gabarito: Corticoterapia é preconizada nas situações de oligúria com hipervolemia grave e insuficiência cardíaca.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Nefrologia','A glomerulopatia membranosa é uma causa comum de síndrome nefrótica primária que se caracteriza por','','','["aspecto de depósitos lineares de IgG e C3 no trajeto da membrana basal à imunofluorescência e depósitos subepiteliais à microscopia eletrônica.", "presença de depósitos subendoteliais de IgG e proliferação de células mesangiais.", "fusão de pedicelos à microscopia eletrônica com múltiplos depósitos subepiteliais.", "presença de espículas caracterizadas por prolongamentos das células epiteliais entre a membrana basal e as células endoteliais."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: fusão de pedicelos à microscopia eletrônica com múltiplos depósitos subepiteliais..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Nefrologia','Assinale a afirmação INCORRETA sobre os cálculos renais.','','','["Cálculos de ácido úrico e fosfato de cálcio podem ser prevenidos com alcalinização da urina.", "Cálculos de fosfato amoníaco magnesiano estão relacionados a infecções.", "Hipocitratúria pode ocorrer por acidose tubular inaparente.", "Dieta pobre em cálcio não deve ser prescrita por não ser benéfica e predispor à osteopenia."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa A. Resposta indicada no gabarito: Cálculos de ácido úrico e fosfato de cálcio podem ser prevenidos com alcalinização da urina.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Nefrologia','Quanto à nefrolitíase, é INCORRETO afirmar que','','','["cálculos de oxalato de cálcio são de difícil tratamento pela litotripsia extracorpórea.", "estratégias dietéticas para a prevenção incluem dieta hipossódica, hipoproteica e incentivo à ingestão de água.", "indivíduos obesos apresentam risco aumentado para cálculos de ácido úrico e oxalato de cálcio.", "no tratamento de cálculos de ácido úrico em indivíduos com hiperuricemia, podem- se empregar alcalinizantes como o bicarbonato de sódio oral."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa A. Resposta indicada no gabarito: cálculos de oxalato de cálcio são de difícil tratamento pela litotripsia extracorpórea..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Nefrologia','Na progressão da doença renal nos casos de doença dos rins policísticos, pode-se afirmar que','','','["o tamanho renal não guarda correlação com o prognóstico da doença.", "o maior determinante de progressão é a esclerose glomerular por causa hemodinâmica.", "a pielonefrite crônica pelos episódios sucessivos de infecção é a causa da perda progressiva da função renal.", "fibrose intersticial e apoptose das células renais ocorrem progressivamente, ainda sem explicações precisas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: fibrose intersticial e apoptose das células renais ocorrem progressivamente, ainda sem explicações precisas..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Nefrologia','Assinale os índices propostos pelas diretrizes da NKF-DOQI para tratamento da anemia em pacientes renais crônicos em hemodiálise para saturação de transferrina, ferritina sérica e hemoglobina, respectivamente:','','','[">40; >400; Entre 11 e 12g/dL.", ">20; >200; Entre 11 e 12g/dL.", ">30; >100; >13g/dL.", ">20; >200; >13g/dL."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Resposta indicada no gabarito: >20; >200; Entre 11 e 12g/dL..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Nefrologia','Em relação à diálise peritoneal (DP), julgue os itens abaixo e, em seguida, assinale a opção correta: I. O único mecanismo de transporte durante a DP é a ultrafiltração; II. A ultrafiltração é induzida pelo gradiente osmótico gerado pela concentração de glicose na solução de diálise; III. A difusão é a maior responsável pelo transporte de solutos. Estão corretos os itens','','','["I, II e III.", "I e II, apenas.", "I e III, apenas.", "II e III, apenas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa D. Resposta indicada no gabarito: II e III, apenas..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Nefrologia','Em relação à diálise peritoneal, assinale a opção INCORRETA.','','','["A função renal residual é importante para a DP apenas em indivíduos com índice de massa corporal acima de 25 kg/m2.", "O PET (Peritoneal Equilibrium Test) é o melhor método para avaliar qual modalidade de DP apresentará melhor resultado.", "O CAPD (Continuous Ambulatorial Peritoneal Dialysis) tem eficácia similar ao APD (Automatized Peritoneal Dialysis), desde que se obedeça à indicação de modalidade pelo PET.", "O PET deve ser repetido quando os parâmetros de adequação forem alterados."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa A. Resposta indicada no gabarito: A função renal residual é importante para a DP apenas em indivíduos com índice de massa corporal acima de 25 kg/m2.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Nefrologia','Leia o enunciado e as alternativas da questão 48 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-nefrologia-q48-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa B. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Nefrologia','Após o transplante renal, especial cuidado deve ser tomado em relação às infecções oportunistas. Dentre essas, a mais comum nos primeiros meses após o transplante é','','','["candida sp.", "cryptococcus neoformans.", "citomegalovirus.", "lysteria monocytogenes."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: citomegalovirus..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Nefrologia','Várias são as glomerulonefrites que recorrem ou se manifestam após o transplante renal. Nas glomerulopatias “de novo”, a de maior prevalência é a','','','["glomerulonefrite membranoproliferativa tipo 1.", "glomerulonefrite membranoproliferativa tipo 2.", "glomerulonefrite membranosa.", "glomeruloesclerose segmentar e focal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Nefrologia: alternativa C. Resposta indicada no gabarito: glomerulonefrite membranosa..' from public.exams where slug='pmerj-2010-medico-nefrologia' on conflict(exam_id,number) do nothing;
