insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Neurocirurgia','Em relação ao hematoma de fossa posterior traumático é correto afirmar que','','','["é melhor diagnosticado por angiografia cerebral.", "quanto melhor a pontuação na escala de coma de Glasgow na entrada, pior o prognóstico final.", "apresenta hidrocefalia em aproximadamente 30% dos pacientes.", "sinais cerebelares e paralisia de nervos cranianos ocorrem na maioria dos pacientes e na fase inicial."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurocirurgia: alternativa C. Resposta indicada no gabarito: apresenta hidrocefalia em aproximadamente 30% dos pacientes..' from public.exams where slug='pmerj-2010-medico-neurocirurgia' on conflict(exam_id,number) do nothing;
