insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Neurocirurgia','Qual a complicação mais frequente pós- -operatória na cirurgia dos craniofaringiomas?','','','["Déficit visual.", "Déficit hormonal e diabetes insípidos.", "Hematoma pós-operatório.", "Coma e óbito."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurocirurgia: alternativa B. Resposta indicada no gabarito: Déficit hormonal e diabetes insípidos..' from public.exams where slug='pmerj-2010-medico-neurocirurgia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Neurocirurgia','Assinale a associação da posição do paciente e a complicação relatada.','','','["Macroglossia (edema severo da língua) – decúbito dorsal.", "Embolia aérea – decúbito ventral.", "Quadriplegia – posição semisentada.", "Paraplegia – posição neutra."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurocirurgia: alternativa C. Resposta indicada no gabarito: Quadriplegia – posição semisentada..' from public.exams where slug='pmerj-2010-medico-neurocirurgia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Neurocirurgia','Quanto ao Tumor Neuroepitelial Disembrioplás- tico (DNET), é correto afirmar:','','','["São tumores considerados de alto grau pela OMS.", "São mais comuns no lobo temporal.", "Não apresentam formação cística.", "Não mostram calcificações."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurocirurgia: alternativa B. Resposta indicada no gabarito: São mais comuns no lobo temporal..' from public.exams where slug='pmerj-2010-medico-neurocirurgia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Neurocirurgia','Tumores cerebrais metastáticos, que podem cursar com hemorragia cerebral como sintoma inicial, são mais frequentes em:','','','["carcinoma de pulmão, carcinoma de mama e carcinoma de cólon.", "melanoma, carcinoma de célula renal e carcinoma prostático.", "carcinoma de célula renal, carcinoma de tireoide e carcinoma de pulmão.", "melanoma, carcinoma de célula renal e carcinoma de tireoide."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurocirurgia: alternativa D. Resposta indicada no gabarito: melanoma, carcinoma de célula renal e carcinoma de tireoide..' from public.exams where slug='pmerj-2010-medico-neurocirurgia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Neurocirurgia','Em relação à localização dos aneurismas cerebrais, é correto afirmar quanto ao risco de ruptura a seguinte frequência:','','','["aneurisma da circulação posterior, aneurisma de artéria comunicante posterior e aneurisma de artéria comunicante anterior.", "aneurisma da artéria comunicante anterior, aneurisma da artéria comunicante posterior, aneurisma da circulação posterior.", "aneurisma da artéria comunicante anterior, aneurisma da circulação posterior e aneurisma da artéria comunicante posterior.", "aneurisma da circulação posterior, aneurisma da artéria comunicante anterior e aneurisma da artéria comunicante posterior."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurocirurgia: alternativa A. Resposta indicada no gabarito: aneurisma da circulação posterior, aneurisma de artéria comunicante posterior e aneurisma de artéria comunicante anterior..' from public.exams where slug='pmerj-2010-medico-neurocirurgia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Neurocirurgia','Vasoespasmo cerebral é mais comum quando o sangramento cerebral é localizado','','','["no espaço subaracnoide.", "intraparenquimatoso.", "ventricular.", "no espaço subdural."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurocirurgia: alternativa A. Resposta indicada no gabarito: no espaço subaracnoide..' from public.exams where slug='pmerj-2010-medico-neurocirurgia' on conflict(exam_id,number) do nothing;
