insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Neurocirurgia','No tratamento da neuralgia do trigêmio, devemos considerar como opções atuais de tratamento:','','','["rizotomia à céu aberto.", "alcoolização do gânglio de Gasser.", "neurotomia periférica.", "microdescompressão vascular ou compres- são por balão."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurocirurgia: alternativa D. Resposta indicada no gabarito: microdescompressão vascular ou compres- são por balão..' from public.exams where slug='pmerj-2010-medico-neurocirurgia' on conflict(exam_id,number) do nothing;
