insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Neurocirurgia','Em relação à anatomia do seio cavernoso, é correto afirmar que','','','["o limite lateral do seio cavernoso é formado pelo nervos oculomotor e nervo troclear.", "dois nervos cursam dentro do seio cavernoso (nervo abducente e nervo simpático).", "o nervo maxilar cursa dentro do seio cavernoso.", "o nervo troclear cursa superior ao nervo ocolumotor."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurocirurgia: alternativa B. Resposta indicada no gabarito: dois nervos cursam dentro do seio cavernoso (nervo abducente e nervo simpático)..' from public.exams where slug='pmerj-2010-medico-neurocirurgia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Neurocirurgia','A estimulação do nervo vago está reservada para determinados pacientes com epilepsia. Por que esse procedimento é executado do lado esquerdo?','','','["Menor chance de paralisia das cordas vocais e rouquidão à esquerda.", "Para evitar lesão do nervo laríngeo recorrente que segue uma via mais tortuosa à direita.", "Para evitar dano ao X, que supre o coração principalmente pela direita.", "Menor chance de paralisa das cordas vocais e rouquidão à direita."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurocirurgia: alternativa C. Resposta indicada no gabarito: Para evitar dano ao X, que supre o coração principalmente pela direita..' from public.exams where slug='pmerj-2010-medico-neurocirurgia' on conflict(exam_id,number) do nothing;
