insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Neurologia','Paciente feminina, 70 anos, refere dor pulsátil em região temporal à esquerda. Apresenta, ainda, claudicação de mandíbula, febre e mialgia. Teve perda ponderal de 5 kg em 2 meses. A principal hipótese diagnóstica para esse caso é','','','["carotidínia.", "arterite temporal.", "dor atípica da face.", "cefaleia hípnica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: arterite temporal..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
