insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Neurologia','Um paciente que apresente, durante a noite, episódios de atividade motora vigorosa, podendo lesar a si mesmo ou ao seu companheiro, acompanhados de sonhos vividos terá o diagnóstico de','','','["distúrbio comportamental do sono REM.", "hipersonia recorrente.", "terror noturno.", "síndrome da apneia – hipopneia obstrutiva do sono."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa A. Resposta indicada no gabarito: distúrbio comportamental do sono REM..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
