insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Neurologia','As doenças de canais iônicos caracterizam-se por mutações genéticas que codificam os canais de cloro, sódio e cálcio. Aquelas que afetam o músculo esquelético dividem-se clinicamente em:','','','["miotonia e paramiotonia.", "doença de Pompe, miopatia ocular mitocondrial.", "miotonia congênita de Becker, Thomsen e Steinert.", "miotonias congênitas, paralisias periódicas e hipertermia maligna."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa D. Resposta indicada no gabarito: miotonias congênitas, paralisias periódicas e hipertermia maligna..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
