insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Neurologia','No tratamento da neurotuberculose, quando há suspeita de resistência, utilizam-se as seguintes drogas nos 2 primeiros meses:','','','["isoniazida e etambutol.", "isoniazida e rifampicina ou etambutol.", "isoniazida, rifampicina, pirazinamida e estreptomicina ou etambutol.", "ácido para-aminosaicílico e etionamida."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa C. Resposta indicada no gabarito: isoniazida, rifampicina, pirazinamida e estreptomicina ou etambutol..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Neurologia','O tratamento de escolha no paciente com SIDA / AIDS e neurotoxoplasmose associa duas drogas:','','','["pirimetamina e ácido folínico.", "sulfadiazina e izoniazida.", "pirimetamina e sulfadiazina.", "clindamicina e pirimetamina."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa C. Resposta indicada no gabarito: pirimetamina e sulfadiazina..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Neurologia','A leucoencefalopatia multifocal progressiva é uma doença desmielinizante que acomete aproxima- damente 4% dos pacientes HIV+. O agente etiológico implicado é o','','','["HHV8.", "vírus Epstein-Baar.", "paramyxovirus.", "vírus John Cunningham."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa D. Resposta indicada no gabarito: vírus John Cunningham..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Neurologia','A neuropatia mais comumente associada à AIDS / SIDA é a','','','["mononeuropatia múltipla.", "polineuropatia sensitiva distal.", "polirradiculoneuropatia.", "craniana."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: polineuropatia sensitiva distal..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Neurologia','Meningite carcinomatosa, uma forma especial de metástase, é mais comumente associada à presença de tumor(es) de','','','["útero e ovário.", "rim.", "ovário.", "mama e pulmão."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa D. Resposta indicada no gabarito: mama e pulmão..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Neurologia','O anticorpo relacionado à degeneração cerebelar, manifestação paraneoplásica relacionada a tumores ovarianos e pulmonares dentre outros é o:','','','["anti-Ri (ANNA 2).", "anti-Yo.", "anti-CRMP-5.", "anti-CAR (antirecoverina)."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: anti-Yo..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Neurologia','A sídrome de Wernicke - Korsakoff é relacionada à deficiência de','','','["vitamina B12.", "ácido nicotínico.", "tiamina.", "vitamina E."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa C. Resposta indicada no gabarito: tiamina..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Neurologia','Uma das manifestações neurológicas relacionadas ao uso das drogas para o tratamento da tuberculose é a polineuropatia carencial, resultante da deficiência de','','','["piridoxina.", "ácido nicotínico.", "vitamina B12.", "tiamina."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa A. Resposta indicada no gabarito: piridoxina..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Neurologia','A síndrome conhecida como pseudotumor cerebri pode resultar do excesso de','','','["piridoxina.", "vitamina A.", "vitamina B12.", "tiamina."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: vitamina A..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Neurologia','Até o momento não foi comprovada que a intoxicação por metais pesados possa estar implicada na fisiopatologia da esclerose lateral amiotrófica, ainda que haja relatos de comprometimento radicular e medular relacionados à intoxicação por','','','["mercúrio.", "ferro.", "manganês.", "chumbo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa D. Resposta indicada no gabarito: chumbo..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Neurologia','O traçado eleroencefalográfico caracterizado pela presença de complexos ponta-onda lenta, de projeção generalizada, em torno de 3 Hz por segundo, que aumentam com a hiperventilação, é característico das crises','','','["parciais complexas.", "tônico-clônicas generalizadas.", "de ausência.", "mioclônicas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa C. Resposta indicada no gabarito: de ausência..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Neurologia','As paralisias faciais ocorrem por lesão supranuclear ou nuclear, individualizando duas síndromes distintas: paralisia facial central ou periférica. Assinale a verdadeira.','','','["A paralisia facial central é homolateral à lesão.", "A paralisia facial periférica acomete toda a hemiface contralateral à lesão.", "A paralisia facial central acomete o andar inferior da hemiface contralateral à lesão.", "Na paralisia facial periférica, o desvio da comissura labial se faz para o lado comprometido."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa C. Resposta indicada no gabarito: A paralisia facial central acomete o andar inferior da hemiface contralateral à lesão..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Neurologia','No estado de mal convulsivo, o anticonvulsivante de primeira linha a ser administrado é','','','["fenobarbital.", "topiramato.", "clonazepan.", "fenitoína."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa D. Resposta indicada no gabarito: fenitoína..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Neurologia','A ataxia cerebelar caracteriza-se por','','','["disbasia, dismetria e hipotonia.", "decomposição de movimentos, hipotonia e sinal de Romberg positivo.", "disdiadococinesia, tremor postural e hipotonia.", "dança dos tendões, dismetria e comprometi-mento da sensibilidade profunda."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa A. Resposta indicada no gabarito: disbasia, dismetria e hipotonia..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Neurologia','A polineuropatia diferencia-se da mononeu- ropatia múltipla pelo acometimento','','','["de vários nervos periféricos, de forma simétrica.", "de vários nervos aleatoriamente.", "de nervos sensitivos ao mesmo tempo.", "distal e assimétrico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa A. Resposta indicada no gabarito: de vários nervos periféricos, de forma simétrica..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Neurologia','Em relação à miastenia gravis, é correto afirmar:','','','["O mecanismo fisiopatológico está relacionado ao aumento de acetilcolina.", "Acima de 50 anos de idade, predomina no sexo masculino, é flutuante, está associada à timoma.", "A forma ocular da doença é a mais frequente.", "A presença de anticorpos contra receptores de acetilcolina não é comum."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: Acima de 50 anos de idade, predomina no sexo masculino, é flutuante, está associada à timoma..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Neurologia','Na lesão da via piramidal acarretando hemiplegia contralateral, o paciente assume a postura de Wernicke-Mann, que se caracteriza pelo predomínio da musculatura:','','','["extensora do membro inferior e flexora do membro superior.", "flexora do membro inferior e extensora do membro superior.", "extensora do membro superior e inferior.", "flexora do membro superior e inferior."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa A. Resposta indicada no gabarito: extensora do membro inferior e flexora do membro superior..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Neurologia','Na síndrome miastênica de Lambert-Eaton,','','','["há uma boa resposta clínica ao tratamento com anticolinesterásicos.", "é frequente a associação com carcinoma pulmonar de pequenas células.", "são comuns as queixas de diplopia, disfagia, ptose e disartria.", "não são comuns as manifestações autonômicas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: é frequente a associação com carcinoma pulmonar de pequenas células..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Neurologia','Paciente notou, ao acordar pela manhã, dificuldades na extensão e abdução do punho, dedos da mão D e polegar, do mesmo lado, alem de “dormência” na região dorsal do polegar da mesma mão. O diagnóstico mais provável é:','','','["acidente vascular cerebral.", "mononeuropatia do radial.", "mononeuropatia do mediano.", "mononeuropatia múltipla."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: mononeuropatia do radial..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Neurologia','Recentemente, a esposa de um conhecido artista de cinema, de 45 anos de idade, ao esquiar, sofreu uma queda, com trauma craniano, aparentemente sem gravidade. Permaneceu consciente, porém evoluiu posteriormente, com rebaixamento do nível de consciência e coma (“talk and die”). Qual o diagnóstico mais provável?','','','["Aneurisma cerebral.", "Hematoma subdural crônico.", "Hematoma extradural.", "Trombose venosa."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa C. Resposta indicada no gabarito: Hematoma extradural..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Neurologia','Em relação ao hematoma subdural crônico, pós- -traumático, podemos afirmar que','','','["a história de trauma é sempre clara.", "apatia, cefaleia, bradipsiquismo e confusão são sintomas frequentes.", "os sinais focais são sempre proeminentes.", "as convulsões são comuns nos adultos, diferentemente das crianças."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: apatia, cefaleia, bradipsiquismo e confusão são sintomas frequentes..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Neurologia','Quanto à síndrome de Guillain-Barré, é correto afirmar:','','','["O déficit motor é ascendente e os reflexos miotáticos são vivos.", "O agente etiológico frequentemente identificado nas infecções que precedem a síndrome neurológica é o Campilobacter jejuni.", "A diplegia facial invalida o diagnóstico de polirradiculoneuropatia inflamatória aguda.", "Não é necessário vigilância estrita uma vez que os fenômenos disautonômicos são raros."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: O agente etiológico frequentemente identificado nas infecções que precedem a síndrome neurológica é o Campilobacter jejuni..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Neurologia','Quanto à síndrome do cativeiro ou síndrome de locked-in, são verdadeiras as afirmativas, com EXCEÇÃO de:','','','["Decorre de lesão ao nível da ponte, preservando as vias somatossensitivas e os sistemas neuronais ascendentes, interrom- pendo as vias corticoespinhal e corticobulbar.", "O paciente encontra-se comatoso e tetraplégico.", "O paciente encontra-se consciente, sem poder movimentar os quatro membros.", "A única forma de interação do paciente com o meio se faz através do movimento conjugado do olhar vertical e piscamento."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: O paciente encontra-se comatoso e tetraplégico..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Neurologia','Paciente de 30 anos de idade, do sexo feminino, apresenta hemiplegia direita de início súbito. A tomografia computadorizada do crânio revela infarto isquêmico no território da artéria cerebral média esquerda. Há relato de trauma craniocervical prévio, com menos de 48 horas. É correto afirmar que a possibilidade etiológica mais provável seja','','','["hematoma subdural agudo.", "cardioembolia.", "dissecção da carótida interna ou de seus ramos intracranianos.", "displasia fibromuscular."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa C. Resposta indicada no gabarito: dissecção da carótida interna ou de seus ramos intracranianos..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Neurologia','Paciente masculino de 28 anos de idade apresentou, durante exercício físico, cefaleia intensa, de início súbito, associada à perda fugaz dos sentidos. Foi admitido, na Emergência, obnubilado, com sinais de Kernig e Brudzinski presentes e paralisia do nervo oculomotor direito. Nesse caso, a hipótese mais provável é','','','["hemorragia intraparenquimatosa hiperten- siva.", "embolia da artéria cerebral média direita.", "enxaqueca oftalmoplégica.", "hemorragia subaracnoide por ruptura de aneurisma intracraniano."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa D. Resposta indicada no gabarito: hemorragia subaracnoide por ruptura de aneurisma intracraniano..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Neurologia','Em relação ao coma, é correto afirmar:','','','["A postura em descerebração com opistótono ocorre nas lesões ao nível do tronco cerebral, na região intercolicular.", "O ritmo respiratório de Cheyne-Stokes que se caracteriza por hiperpneia intercalada com períodos curtos de apneia, é característico da lesão pontina", "A sua avaliação pela escala de Glasgow considera os seguintes parâmetros: abertura ocular, melhor resposta verbal, melhor resposta motora e padrão respiratório.", "No paciente comatoso, com desvio conjugado do olhar para a direita, deduz-se que a lesão se encontra no hemisfério esquerdo."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa A. Resposta indicada no gabarito: A postura em descerebração com opistótono ocorre nas lesões ao nível do tronco cerebral, na região intercolicular..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Neurologia','Paciente jovem, feminina, com sintomas sugestivos de neuralgia do trigêmio de repetição, acometendo os ramos II e III. Qual a principal possibilidade diagnóstica?','','','["Síndrome de Tolosa-Hunt.", "Compressão vascular.", "Esclerose múltipla.", "Processo expansivo ao nível do seio cavernoso."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa C. Resposta indicada no gabarito: Esclerose múltipla..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Neurologia','Em relação à esclerose múltipla, podemos afirmar:','','','["É uma doença que acomete principalmente homens, entre 50 e 60 anos de idade.", "A neurite óptica isolada é considerada síndrome clínica isolada e, portanto, há um  risco maior de desenvolvimento da doença, esclerose múltipla, principalmente quando a neurite óptica ocorrer na idade adulta e não na puberdade.", "Os critérios de Poser consideram a ressonância magnética do crânio como elemento de diagnóstico e prognóstico da doença.", "A tríade de Charcot, nistagmo, fala escandida e tremor intencional, é observada, com frequência, nas fases iniciais da doença."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa B. Resposta indicada no gabarito: A neurite óptica isolada é considerada síndrome clínica isolada e, portanto, há um  risco maior de desenvolvimento da doença, esclerose múltipla, principalmente quando a neurite óptica ocorrer na idade adulta e não na puberdade..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Neurologia','Assinale a afirmativa correta.','','','["Dentre as principais causas de coma, estão o acidente vascular cerebral, o trauma, os estados pós convulsivos, as meningites, as intoxicações exógenas e o diabetes.", "A intoxicação etílica é sempre acompanhada de convulsões e o paciente evolui para o coma somente pela ingesta abusiva de álcool.", "A trombose venosa cerebral é uma causa comum de coma.", "A hipertensão intracraniana não é uma causa de coma."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa A. Resposta indicada no gabarito: Dentre as principais causas de coma, estão o acidente vascular cerebral, o trauma, os estados pós convulsivos, as meningites, as intoxicações exógenas e o diabetes..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Neurologia','Assinale a afirmativa INCORRETA.','','','["As demências dividem-se em reversíveis ou tratáveis e irreversíveis ou degenerativas.", "Demência é uma síndrome caracterizada por déficit de memória somado a um ou mais déficits cognitivos.", "A demência vascular e a demência de Alzheimer são condições que não se sobrepõem em um mesmo paciente.", "Estado de mal não convulsivo é um diagnóstico diferencial possível entre as síndromes demenciais."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa C. Resposta indicada no gabarito: A demência vascular e a demência de Alzheimer são condições que não se sobrepõem em um mesmo paciente.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Neurologia','Sobre as síndromes demenciais, é correto afirmar:','','','["No diagnóstico diferencial das demências reversíveis estão: meningiomas, hematomas subdurais, hipovitaminose B12, hipona-tremia, uremia e a depressão, dentre outros.", "O estudo anátomo patológico da D. de Alzheimer revela emaranhado de neurofibrilas, aumento de acetilcolina e aumento das cavidades ventriculares supratentoriais.", "O paciente com possível diagnóstico de D. de Alzheimer procura, rapidamente, atendimento médico.", "Nas síndromes demenciais, uma primeira avaliação clínica é realizada através do mini-exame do estado mental, o qual não leva em consideração o nível de escolaridade do paciente."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa A. Resposta indicada no gabarito: No diagnóstico diferencial das demências reversíveis estão: meningiomas, hematomas subdurais, hipovitaminose B12, hipona-tremia, uremia e a depressão, dentre outros..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Neurologia','Considerando as desordens neurológicas congênitas, assinale a correta.','','','["Nas cranioestenoses, o tratamento cirúrgico não está indicado após os 3 meses de idade, a não ser que ocorram sintomas de hipertensão intracraniana.", "Na má formação de Chiari tipo II, a hidrocefalia progressiva não ocorre.", "A síndrome de Dandy-Walker caracteriza- se por falha do desenvolvimento do tronco cerebral.", "As menigomieloceles raramente represen- tam risco adicional com relação à infecção meníngea."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa A. Resposta indicada no gabarito: Nas cranioestenoses, o tratamento cirúrgico não está indicado após os 3 meses de idade, a não ser que ocorram sintomas de hipertensão intracraniana..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Neurologia','Ainda considerando as desordens neurológicas congênitas, assinale a INCORRETA.','','','["As facomatoses são doenças hereditárias. A esclerose tuberosa é uma facomatose que se caracteriza pela tríade de adenoma sebáceo, epilepsia e retardo mental.", "É comum encontrarmos lesões semelhantes a vitiligo na esclerose tuberosa.", "A neurofibromatose, outra facomatose, caracteriza-se pela presença de manchas café com leite associadas à neurinoma do acústico.", "O tratamento dos tumores cutâneos encontrados na neurofibromatose consiste na sua extirpação cirúrgica."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa D. Resposta indicada no gabarito: O tratamento dos tumores cutâneos encontrados na neurofibromatose consiste na sua extirpação cirúrgica.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Neurologia','A terapia dos 3 Hs (hemodiluição, hipervolemia e hipertensão) está indicada no tratamento agudo de','','','["edema cerebral.", "hipertensão intracraniana.", "hemorragia cerebral.", "vasoespasmo cerebral."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa D. Resposta indicada no gabarito: vasoespasmo cerebral..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Neurologia','No estado de mal convulsivo, são tomadas as seguintes condutas emergenciais iniciais, com EXCEÇÃO de','','','["verificar parâmetros vitais.", "oxigenar o paciente.", "hidratar com soro glicosado.", "administrar diazepan endovenoso."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia: alternativa C. Resposta indicada no gabarito: hidratar com soro glicosado..' from public.exams where slug='pmerj-2010-medico-neurologia' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-neurologia-pediatrica','PMERJ 2010 — Oficial — Médico Neurologia Pediátrica','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Neurologia Pediátrica','Na convulsão febril benigna, é correto afirmar que','','','["o tratamento profilático com fenobarbital deve ser feito em todos os casos.", "o eletroencefalograma tem importância secundária na decisão do tratamento profilático.", "a probabilidade de recorrência é maior quanto mais velha for a criança.", "a carbamazepina é a melhor opção terapêutica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: o eletroencefalograma tem importância secundária na decisão do tratamento profilático..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Neurologia Pediátrica','Assinale a alternativa correta.','','','["A testagem de Q.I. (quociente intelectual) não tem nenhum valor no diagnóstico do retardo mental.", "A dislexia é causada habitualmente pela asfixia perinatal.", "Pacientes que têm atividades de lazer compatível com a sua faixa etária não podem ter retardo mental.", "A incidência de autistas e de retardados mentais é maior no sexo masculino por conta, por exemplo, da síndrome do X frágil."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Resposta indicada no gabarito: A incidência de autistas e de retardados mentais é maior no sexo masculino por conta, por exemplo, da síndrome do X frágil..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Neurologia Pediátrica','Paciente com paralisia flácida arreflexa ascendente e exame liquórico com dissociação albumino citológica tem como provável diagnóstico a(o)','','','["polirradiculoneurite.", "siringomielia.", "compressão medular lombar.", "tumor cervical."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: polirradiculoneurite..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Neurologia Pediátrica','Em relação às facomatoses, é correto afirmar:','','','["A justificativa para o acometimento de pele e SNC é embriológica (alteração no mesoderma).", "A neurofibromatose tipo I pode estar associada com retardo mental.", "A cirurgia para a retirada dos tumores periféricos é o tratamento definitivo para os sintomas da neurofibromatose tipo I.", "A doença de Sturge-Weber apresenta mancha hipocrômica em território de trigêmio, fibromas plexiformes e retardo mental na sua tríade clássica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: A neurofibromatose tipo I pode estar associada com retardo mental..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Neurologia Pediátrica','Paciente adolescente do sexo feminino, que inicie um quadro com diplopia e ptose palpebral ao final da tarde, tem qual diagnóstico com maior probabilidade, e como confirmá-lo com os exames apresentados?','','','["Distrofia de Becker/ eletroneuromiografia.", "Miastenia Gravis / punção lombar.", "Miastenia congênita / eletroneuromiografia.", "Miastenia Gravis/ eletroneuromiografia."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Resposta indicada no gabarito: Miastenia Gravis/ eletroneuromiografia..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Neurologia Pediátrica','Em relação aos distúrbios convulsivos na infância, é correto afirmar que','','','["o EEG deve ser sempre realizado imediatamente após a crise.", "o achado clássico da ausência é a presença de complexos ponta onda 3Hz.", "não se deve permitir que a criança durma após a crise.", "a convulsão febril sempre deve ser tratada com fenobarbital."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: o achado clássico da ausência é a presença de complexos ponta onda 3Hz..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Neurologia Pediátrica','É critério obrigatório para o diagnóstico de convulsão febril:','','','["inexistência de outras patologias do Sistema Nervoso Central.", "febre superior a 41°C.", "infecção de sistema nervoso central.", "eletroencefalograma alterado."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: inexistência de outras patologias do Sistema Nervoso Central..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Neurologia Pediátrica','Marque a alternativa cuja afirmativa está correta.','','','["A impregnação por bilirrubina é a causa da encefalomalacia periventricular.", "A sequela extrapiramidal mais comum relacionada ao kernicterus é o tremor de repouso.", "A diplegia espástica está relacionada principalmente à injúria parassagital do pós--termo.", "A encefalopatia hipóxico isquêmica do recém-nato a termo é associada habitualmente à alteração em outros sistemas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Resposta indicada no gabarito: A encefalopatia hipóxico isquêmica do recém-nato a termo é associada habitualmente à alteração em outros sistemas..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Neurologia Pediátrica','Assinale a alternativa correta no tocante às síndromes epilépticas da infância.','','','["A hipsiarritmia aparece com o uso do ACTH.", "A vigabatrina pode ser utilizada nos espasmos infantis.", "A carbamazepina é droga de escolha no tratamento da ausência típica.", "O prognóstico habitual da síndrome de Lennox Gastaut é excelente."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: A vigabatrina pode ser utilizada nos espasmos infantis..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Neurologia Pediátrica','Paciente de 3 anos, alérgico, apresenta-se, há 4 dias, com febre, crises convulsivas, diminuição do nível de consciência, sem rigidez de nuca, líquor com discreta hiperproteinorraquia e pleiocitose (15 células: 66% de linfomononucleares) e TC de crânio com hipercaptação de contraste em regiões temporais. Qual a conduta mais adequada?','','','["Antibiótico de amplo espectro, pois se trata de abscesso cerebral.", "Esquema RIP, pois se trata de meningite por BK.", "Penicilina cristalina venosa de imediato, pois se trata de quadro bacteriano e não podemos esperar as culturas.", "Acyclovir pois se trata de provável encefalite herpética."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Resposta indicada no gabarito: Acyclovir pois se trata de provável encefalite herpética..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Neurologia Pediátrica','Na doença de Sturge-Weber, só NÃO podemos observar','','','["angioma meningo cortical.", "angioma em território relacionado a um dos ramos do nervo facial.", "hemihipertrofia corporal.", "convulsões."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: angioma em território relacionado a um dos ramos do nervo facial..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Neurologia Pediátrica','Em relação aos defeitos de fechamento do tubo neural, assinale a alternativa correta.','','','["Nunca são detectáveis no período gestacional.", "São associados à doença de Bud-Chiari tipo II.", "Podem estar associados ao pé torto congênito.", "A localização cervical é a mais comum."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: Podem estar associados ao pé torto congênito..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Neurologia Pediátrica','A hemianopsia bitemporal é fortemente sugestiva de qual topografia e de que tipo de tumor?','','','["Hipófise (relacionado a resquícios da bolsa de Rathke).", "Astrocitoma no córtex da cisura calcarina do lobo occipital.", "Metástase em lobo frontal.", "Lobo parietal (oligondendroglioma)."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: Hipófise (relacionado a resquícios da bolsa de Rathke)..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Neurologia Pediátrica','NÃO constitui defeito de fechamento do tubo neural:','','','["mielomeningocele.", "meningocele.", "Dandy-Walker.", "spina bífida oculta."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: Dandy-Walker..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Neurologia Pediátrica','Em relação às distrofias de uma forma geral, é correto afirmar que','','','["têm caráter estático.", "têm caráter heredofamiliar.", "ocorrem principalmente no sexo feminino.", "apresentam alterações sensitivas associadas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: têm caráter heredofamiliar..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Neurologia Pediátrica','Das opções abaixo, assinale a conduta que NÃO pode ser considerada modalidade de tratamento da polirradiculoneurite.','','','["Sedação.", "Plasmaferese.", "Fisioterpia respiratória.", "Imunoglobulina."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: Sedação..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Neurologia Pediátrica','Em relação à esclerose tuberosa (doença de Bourneville), assinale a alternativa correta.','','','["É mais comum em negros.", "Não tem caráter heredofamiliar.", "Apresenta crescimentos tumorais em nervos periféricos.", "Caracteriza-se por epilepsia, transtornos mentais e adenomas cutâneos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Resposta indicada no gabarito: Caracteriza-se por epilepsia, transtornos mentais e adenomas cutâneos..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Neurologia Pediátrica','Escolar de oito anos é levado ao seu consultório por não conseguir ser alfabetizado. Na história familiar há o relato de um tio materno com quadro semelhante. Apresenta fronte e orelhas proeminentes, hiperextensão de artelhos e “flapping hands”. Qual a hipótese mais plausível?','','','["Sindrome de Down.", "Sindrome do cromossomo X frágil.", "Sindrome de Marfan.", "Esquizofrenia."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: Sindrome do cromossomo X frágil..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Neurologia Pediátrica','Recém-nato a termo, de parto normal, com período expulsivo prolongado, apresenta deformidade craniana delimitada ao parietal esquerdo, de consistência firme. O RX não apresentou fratura, e a deformidade é de provável conteúdo líquido. A criança está normal do ponto de vista clínico. Assinale o diagnóstico e a conduta adequados.','','','["Kernicterus/ Iniciar foto preventiva pela probabilidade de encefalopatia por bilirrubina.", "Crigler najar/Iniciar fenobarbital oral na dose de 3 mg/kg visando ao aumento da excreção de bilirrubina e diminuição do risco de danos ao cérebro.", "Céfalo-hematoma/ Avisar aos pais que a criança pode ficar ictérica e deverá retornar para reavaliação ambulatorial.", "Hematoma subdural / Drenar em ambiente cirúrgico com agulha fina e distante do centro da tumoração, visando à descom- pressão."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: Céfalo-hematoma/ Avisar aos pais que a criança pode ficar ictérica e deverá retornar para reavaliação ambulatorial..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Neurologia Pediátrica','Em relação aos tumores do SNC, assinale a INCORRETA.','','','["São neoplasias extremamente raras na infância.", "A localização supratentorial pode apresentar convulsões como manifestação clínica.", "A localização infratentorial costuma complicar-se com hidrocefalia.", "A localização infratentorial é melhor avaliada pela ressonância."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: São neoplasias extremamente raras na infância.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Neurologia Pediátrica','Assinale a alternativa INCORRETA.','','','["Os tocotaumatismos afetam sempre o neonato de forma transitória.", "A asfixia perinatal é uma das causas mais comuns de convulsões neonatais.", "A meningite neonatal tem associação com vasculites.", "A hemorragia periventricular grau IV tem péssimo prognóstico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: Os tocotaumatismos afetam sempre o neonato de forma transitória.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Neurologia Pediátrica','Em relação à encefalite pelo Herpes, é INCORRETO afirmar que','','','["o EEG pode apresentar lentificação bilateral no lobo temporal.", "a biópsia cerebral é a ferramenta diagnóstica usual na avaliação.", "o liquor pode ter poucas alterações laboratoriais.", "a tomografia computadorizada de crânio no segundo dia de doença pode estar normal."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: a biópsia cerebral é a ferramenta diagnóstica usual na avaliação..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Neurologia Pediátrica','Assinale a alternativa correta no tocante às síndromes epilépticas e álgicas em pediatria.','','','["A ausência típica é tratada preferencial- mente pela carbamazepina.", "Não existe tratamento profilático para a enxaqueca em crianças.", "O uso da hidantoína oral é indicado em convulsões parciais benignas primárias do lactente.", "A convulsão febril pode ser tratada profilaticamente em condições especiais."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Resposta indicada no gabarito: A convulsão febril pode ser tratada profilaticamente em condições especiais..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Neurologia Pediátrica','Leia o enunciado e as alternativas da questão 24 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-neurologia-pediatrica-q24-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Neurologia Pediátrica','Quais dos sinais abaixo podem ser encontrados na amiotrofia espinal progressiva?','','','["Hiperreflexia + atrofia.", "Hiporreflexia + hipoestesia.", "Hipotrofia + fasciculação.", "Hipertrofia+ fasciculação."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: Hipotrofia + fasciculação..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Neurologia Pediátrica','Em relação ao acometimento neurológico pelo vírus HIV, assinale a alternativa correta.','','','["O envolvimento do sistema nervoso central na infância é pouco frequente e apenas é observado entre as crianças que apresentam complicações infecciosas.", "As infecções piogênicas na criança com SIDA têm perfil bacteriológico diferente daquelas observadas no paciente imunocompetente.", "A encefalopatia pelo HIV apresenta manifestações radiológicas (na ressonância magnética) típicas, traduzidas por atrofia cortical, dilatação ex-vácuo dos ventrículos laterais e atenuação da substância branca.", "A carga viral liquórica não apresenta correlação clínica significativa com as manifestações."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: A encefalopatia pelo HIV apresenta manifestações radiológicas (na ressonância magnética) típicas, traduzidas por atrofia cortical, dilatação ex-vácuo dos ventrículos laterais e atenuação da substância branca..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Neurologia Pediátrica','O reflexo de preensão palmar costuma DESAPARECER em que idade?','','','["4 a 5 meses.", "7 a 8 meses.", "5 a 6 meses.", "3 a 4 meses."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: 4 a 5 meses..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Neurologia Pediátrica','Assinale a alternativa INCORRETA para a doença de Sturge-Weber.','','','["Imagem radiológica em trilho de ferrovia pode estar presente no RX de crânio.", "Hemiparesia.", "Conclusão.", "Placas de chagrem."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: Imagem radiológica em trilho de ferrovia pode estar presente no RX de crânio.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Neurologia Pediátrica','Em qual das situações abaixo, o uso do valproato de sódio está contraindicado?','','','["Tratamento de crises mioclônicas em criança com encefalopatia mitocondrial do tipo MERRF.", "Tratamento de epilepsia mioclônica em pré--escolar com lipofuccinose.", "Tratamento da Síndrome de West em lactente com hiperglicinemia não cetótica.", "Tratamento de ausência atípica em lactente com Galactosemia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: Tratamento da Síndrome de West em lactente com hiperglicinemia não cetótica..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Neurologia Pediátrica','Uma criança de 7 anos foi vítima de traumatismo craniano fechado com lesão do tipo axonal difusa. Após avaliação da equipe de neurocirurgia, foi decidido pela colocação de cateter para monitorização da PIC (pressão intracraniana). Nesse caso, a PIC ideal deve permanecer abaixo de','','','["15 mmHg.", "25 mmHg.", "30 mmHg.", "20 mmHg."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: 15 mmHg..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Neurologia Pediátrica','Em relação ao uso de fenitoína profilática no traumatismo de crânio, assinale a alternativa verdadeira.','','','["Deve ser administrada a todos os pacientes com TCE grave.", "Seu uso pode ser considerado entre aqueles pacientes com lacerações cerebrais extensas.", "Nunca deve ser administrado profilática- mente, apenas para fins terapêuticos.", "Pode ser administrado, mas não há necessidade de dose de ataque."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: Seu uso pode ser considerado entre aqueles pacientes com lacerações cerebrais extensas..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Neurologia Pediátrica','Dentre as indicações de toxina botulínica, qual das opções abaixo pode ser considerada uma CONTRAINDICAÇÃO ao seu uso?','','','["Espasticidade com graduação 3 na escala de Ashworth modificada.", "Distonia cervical.", "Espasticidade com graduação 2 na escala de Ashworth modificada.", "Para Criança que não faz tratamento de reabilitação."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Resposta indicada no gabarito: Para Criança que não faz tratamento de reabilitação..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Neurologia Pediátrica','Um paciente com 14 meses chega para consulta ambulatorial e a queixa principal da mãe é “crise convulsiva”. A responsável refere que a criança já apresentou três episódios caracterizados por perda de consciência. Na anamnese você esclarece que os episódios foram precedidos por uma queda súbita ou  quando a criança é contrariada, seguida de choro intenso, apneia expiratória, cianose, sudorese fria e perda de consciência com duração de aproximadamente 10 ou 20 segundos. O exame neurológico foi normal para a idade e o eletroencefalograma (solicitado pelo pediatra) evidenciou: “Anormal focal inespecífico com ritmo dominante posterior lentificado, com frequência de 4- 5 Hz em região occipital”. Qual seria sua conduta?','','','["Iniciar carbamazepina.", "Iniciar fenobarbital.", "Reencaminhar a criança ao pediatra assistente e sugerir uma conduta expectante.", "Solicitar TILT teste."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: Reencaminhar a criança ao pediatra assistente e sugerir uma conduta expectante..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Neurologia Pediátrica','Você foi chamado para dar um parecer sobre um paciente com epilepsia focal refratária. A família informa que o paciente já fez uso de carbamazepina e valproato de sódio de maneira isolada ou em associação com diversos diazepínicos. O esquema terapêutico atual é oxcarbazepina (em dose máxima) associada ao clobazam. Qual das drogas abaixo representa uma boa opção para este paciente?','','','["Lamotrigina.", "Corticoide.", "Etosuximida.", "Sultiame."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: Lamotrigina..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Neurologia Pediátrica','Dentre as drogas abaixo, qual a que NÃO faz parte do arsenal farmacológico para o tratamento da crise de enxaqueca na infância?','','','["Ciproeptadina.", "Ibuprofeno.", "Sumatriptano.", "Dipirona."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: Ciproeptadina..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Neurologia Pediátrica','Em relação ao uso do metilfenidato para o tratamento do transtorno hiperativo com déficit de atenção, assinale a alternativa INCORRETA.','','','["Seu provável mecanismo de ação é a inibição dos receptores de recaptação da dopamina.", "Recomenda-se a administração cerca de 30 minutos antes das refeições.", "A droga atua melhor no controle da impulsividade com pouco efeito sobre a atenção.", "A redução do apetite e suas repercussões sobre o ganho ponderal da criança são os principais efeitos colaterais."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: A droga atua melhor no controle da impulsividade com pouco efeito sobre a atenção.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Neurologia Pediátrica','Dentre as formas/modalidades não farmacológicas para o tratamento de crianças com transtorno hiperativo e com déficit de atenção, qual das opções abaixo NÃO apresenta eficácia comprovada?','','','["Terapia cognitivo-comportamental.", "Terapia comportamental.", "Psicoterapia de apoio para as crianças e sua família.", "Dietoterapia."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Resposta indicada no gabarito: Dietoterapia..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Neurologia Pediátrica','Um escolar com nove anos chega para consulta ambulatorial. Seus pais relataram a ocorrência de três crises convulsivas nos últimos meses. Todos os fenômenos ocorreram sem febre ou qualquer outro fator precipitante e podem ser classificados como crises tônico-clônica generalizadas. Contudo, durante a anamnese, você percebe que a criança também apresenta crises de ausência. O pediatra assistente já iniciou fenobarbital. Como o exame neurológico deste paciente foi absolutamente normal, qual seria a melhor conduta?','','','["Solicitar um eletroencefalograma e manter a medicação em uso.", "Solicitar um eletroencefalograma e iniciar a transição do fenobarbital para o valproato de sódio.", "Solicitar um eletroencefalograma e iniciar a transição do fenobarbital para a etosuxi- mida.", "Não solicitar eletroencefalograma e substi- tuir imediatamente o fenobarbital por valproato de sódio."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: Solicitar um eletroencefalograma e iniciar a transição do fenobarbital para o valproato de sódio..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Neurologia Pediátrica','Em relação aos reflexos primitivos do lactente, assinale a alternativa correta.','','','["O reflexo de Landau costuma ser mais evidente no segundo semestre de vida e sua ausência indica a presença de hipotonia.", "O reflexo tônico cervical assimétrico deve estar ausente no término do primeiro mês de vida e sua persistência indica a possibilidade de um lactente espástico.", "O reflexo de Moro desaparece entre o primeiro e o segundo mês e sua persistência, após esse período, é indicativa de disfunção neuromotora.", "A preensão palmar desaparece entre o quinto e o sexto mês de vida, sendo substituída pela movimentação voluntária das mãos. Seu surgimento, posteriormente, no adulto, está relacionado com lesões frontais."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: O reflexo de Landau costuma ser mais evidente no segundo semestre de vida e sua ausência indica a presença de hipotonia..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Neurologia Pediátrica','Assinale a opção que NÃO constitui causa de papiledema.','','','["Astrocitoma cerebelar.", "Hipervitaminose A.", "Corioretinite.", "Neuromielite óptica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: Corioretinite..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Neurologia Pediátrica','Uma adolescente de 14 anos com diagnóstico de lúpus eritematoso sistêmico grave e em atividade está internada para tratamento com ciclofosfamida (pulsoterapia) e prednisona (60 mg/dia, por via oral). Os últimos exames complementares apontam que a paciente se encontra com neutropênica (900 granulócitos, sem alterações plaquetárias), com níveis séricos de complemento baixo e com quadro febril persistente. Há cerca de 2 horas ela apresentou, pela primeira vez em sua vida, convulsão tônico-clônica generalizada. O exame neurológico foi prejudicado pelo uso de diazepam venoso. De acordo com as principais hipóteses diagnósticas e a lista de prioridades para este caso, quais seriam os exames complementares necessários?','','','["Ressonância magnética do crânio com estudo angiográfico e exame de liquor.", "Ressonância magnética do crânio e exame de liquor com raquimanometria.", "Tomografia computadorizada de crânio contrastada e exame de liquor.", "Ressonância magnética do crânio com estudo angiográfico e exame de liquor com raquimanometria."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Resposta indicada no gabarito: Ressonância magnética do crânio com estudo angiográfico e exame de liquor com raquimanometria..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Neurologia Pediátrica','Em relação à paralisia de Bell, assinale a alternativa INCORRETA.','','','["Trata-se de paralisia facial periférica idiopática.", "Não existem evidências de que o uso de corticosteroides interfira no prognóstico, por esta razão seu uso é contraindicado.", "O uso de antivirais não é indicado.", "O tratamento fisioterápico deve ser recomendado e exercícios faciais devem ser ensinados à criança."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: Não existem evidências de que o uso de corticosteroides interfira no prognóstico, por esta razão seu uso é contraindicado.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Neurologia Pediátrica','Em uma criança com Síndrome de Kinsbourne, é primordial o rastreamento de qual das patologias abaixo?','','','["Meduloblastoma.", "Esclerose Múltipla.", "Neuroblastoma.", "Hipertireoidismo."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: Neuroblastoma..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Neurologia Pediátrica','Uma criança de 4 anos chega à emergência com quadro de ataxia aguda sem nenhuma outra queixa precedente. Dentre os exames abaixo, qual representa a prioridade no atendimento deste paciente?','','','["Ressonância magnética do crânio.", "Exame do liquor.", "Tomografia computadorizada do crânio.", "Triagem ampliada para erros inatos do metabolismo."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: Ressonância magnética do crânio..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Neurologia Pediátrica','A diferenciação entre a encefalomielite aguda disseminada (ADEM) e a esclerose múltipla, certas vezes, é bastante difícil. Com relação a esse tema, assinale a alternativa correta.','','','["Geralmente a esclerose múltipla apresenta manifestações com envolvimento cortical, tais como convulsões e alterações do sensório.", "Em geral, o ADEM tem curso monofásico, mas a presença de lesões em diferentes estágios na ressonância magnética é bastante característica desta condição.", "A presença de bandas oligoclonais no líquor sugere a possibilidade do diagnóstico de esclerose múltipla.", "O acompanhamento clínico é fundamental para verificar a recorrência da sintoma- tologia desmielinizante, característica primordial da ADEM."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa C. Resposta indicada no gabarito: A presença de bandas oligoclonais no líquor sugere a possibilidade do diagnóstico de esclerose múltipla..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Neurologia Pediátrica','Dentre as vacinas abaixo, qual a que pode causar, com maior frequência, encefalomielite aguda disseminada em nosso meio?','','','["Tríplice viral.", "Varicela.", "Rotavirus.", "Antirábica."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: Tríplice viral..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Neurologia Pediátrica','Um pré-escolar com diagnóstico de Síndrome de Lennox Gastaut está sendo discutido em uma sessão de neuropediatras. O colega que o assiste apresenta o caso e informa que já fez uso de inúmeras medicações anticonvulsivantes sem melhora clínica significativa. Dentre os procedimentos abaixo, qual seria a melhor sugestão que poderíamos fornecer ao nosso colega?','','','["Referenciá-lo a um centro especializado em cirurgia de epilepsia.", "Propor o início de dieta cetogênica.", "Iniciar corticoterapia.", "Administrar imunoglobulina humana por via intravenosa e reiniciar novo esquema medicamentoso."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: Propor o início de dieta cetogênica..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Neurologia Pediátrica','Você foi chamado para um parecer na UTI neonatal de uma criança com 4 dias de vida, nascida a termo, de parto cesáreo (indicado por sofrimento fetal agudo) com índice de Apgar 4 e 8. Apesar do desconforto respiratório que apresentou nas primeiras horas de vida, em 12 horas foi liberado para alojamento conjunto. Com 36 horas de vida, apresentou episódio convulsivo generalizado, com glicemia capilar normal e tratado com fenobarbital venoso. No momento, o paciente se apresenta sonolento, hipoativo, com redução global da motilidade espontânea, hipotonia com reflexos profundos preservados e reflexos primitivos ausentes. Diante das inúmeras possibilidades diagnósticas, quais seriam os exames que você solicitaria para guiar seu raciocínio clinico inicial?','','','["Gasometria, ureia, amônia, lactato, eletroencefalograma, ultrassonografia trans-fontanela e dosagem de ácidos orgânicos em urina.", "Glicemia, ureia, amônia, lactato, eletroen- cefalograma, doppler transcraniano e triagem ampliada para erros inatos do metabolismo.", "Gasometria, glicemia, amônia, lactato, piruvato e triagem ampliada para erros inatos do metabolismo.", "Gasometria, glicemia, amônia, lactato, piruvato, eletroencefalograma, ultrassono- grafia transfontanela e triagem ampliada para erros inatos do metabolismo."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa D. Resposta indicada no gabarito: Gasometria, glicemia, amônia, lactato, piruvato, eletroencefalograma, ultrassono- grafia transfontanela e triagem ampliada para erros inatos do metabolismo..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Neurologia Pediátrica','Dentre as opções abaixo, assinale aquela que NÃO é encontrada em associação com a infecção por Mycoplasma pneumoniae.','','','["Radiculite.", "Infecção granulomatosa em sistema nervoso central.", "Encefalite.", "Mielite."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa B. Resposta indicada no gabarito: Infecção granulomatosa em sistema nervoso central.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Neurologia Pediátrica','Uma adolescente de 13 anos e com quadro de epilepsia generalizada, controlada (último evento há 14 meses) com uso de valproato de sódio, procura o seu ambulatório, pois voltou a apresentar crises diárias nos últimos 10 dias. A mãe relata que não interrompeu a medicação, que as crises são menos intensas que as anteriores e ocorrem durante o sono. Segundo ela, a paciente não desperta e permanece de olhos fechados enquanto apresenta abalos clônicos em todo o corpo e não há liberação esfincteriana nem sialorreia. O exame neurológico é normal. Nesse caso, qual dos exames abaixo seria de maior utilidade para confirmação de sua hipótese diagnóstica principal?','','','["Vídeo-eletroencefalograma.", "Polissonografia.", "Nível sérico do valproato de sódio.", "Eletroencefalograma interictal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Neurologia Pediátrica: alternativa A. Resposta indicada no gabarito: Vídeo-eletroencefalograma..' from public.exams where slug='pmerj-2010-medico-neurologia-pediatrica' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-obstetricia','PMERJ 2010 — Oficial — Médico Obstetrícia','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Obstetrícia','Em relação às consultas, o importante na assistência pré-natal é','','','["mínimo de 4 (quatro) consultas.", "mínimo de 9 (nove) consultas.", "o maior número possível.", "a qualidade das consultas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: a qualidade das consultas..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Obstetrícia','O risco de transmissão vertical da sífilis ocorre','','','["em qualquer idade gestacional.", "somente a partir do segundo trimestre.", "no terceiro trimestre.", "no primeiro trimestre."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa A. Resposta indicada no gabarito: em qualquer idade gestacional..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Obstetrícia','Na assistência pré-natal, a suplementação com vitaminas e sais minerais deve incluir','','','["vitamina A + ácido fólico.", "vitamina C + ácido fólico.", "ferro + ácido fólico.", "vitamina C + complexo B."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: ferro + ácido fólico..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Obstetrícia','O diagnóstico do trabalho de parto deve levar em consideração o','','','["apagamento do colo, dilatação cervical e dor abdominal.", "apagamento do colo, formação da bolsa das águas e antecedente de abortamento.", "apagamento do colo, emissão de mucosidades e disúria.", "apagamento do colo, dilatação cervical e contrações uterinas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: apagamento do colo, dilatação cervical e contrações uterinas..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Obstetrícia','A indução do parto com colo desfavorável deve ser','','','["iniciada na residência da paciente, com os devidos cuidados.", "monitorada com o partograma.", "realizada com o uso da ocitocina na dose de 1-8 mUI/min.", "realizada com o uso prévio do misoprostol na dose inicial de 25 microgramas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: realizada com o uso prévio do misoprostol na dose inicial de 25 microgramas..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Obstetrícia','Os graus de desproporção cefalo-pélvica segundo Titus e levando em consideração a medida da conjugata vera (CV) são os seguintes:','','','["Primeiro grau: CV de 11 a 9 cm Segundo grau: CV de 9 a 7 cm Terceiro grau: CV menor que 7 cm", "Primeiro grau: CV de 10,5 a 9 cm Segundo grau: CV de 9 a 7 cm Terceiro grau: CV menor que 7 cm", "Primeiro grau: CV de 10,5 a 8 cm Segundo grau: CV de 8 a 7 cm Terceiro grau: CV menor que 7 cm", "Primeiro grau: CV de 10 a 8 cm Segundo grau: CV de 8 a 7 cm Terceiro grau: CV menor que 7 cm"]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: Primeiro grau: CV de 10,5 a 9 cm Segundo grau: CV de 9 a 7 cm Terceiro grau: CV menor que 7 cm.' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Obstetrícia','São irregularidades no mecanismo de parto na apresentação pélvica:','','','["rotação posterior do dorso, deflexão dos braços, deflexão da cabeça.", "insinuação do biacromial num dos diâmetros oblíquos da bacia, deflexão dos braços, deflexão da cabeça.", "insinuação da cabeça derradeira no diâmetro transverso da bacia, cabeça defletida em OS, rotação anterior do dorso.", "insinuação da cabeça derradeira no diâmetro oblíquo da bacia, cabeça defletida em mento-pubis, desprendimento do biacromial no diâmetro transverso."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa A. Resposta indicada no gabarito: rotação posterior do dorso, deflexão dos braços, deflexão da cabeça..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Obstetrícia','O estímulo ao aleitamento materno deve começar','','','["na gestação.", "na sala de parto.", "no alojamento conjunto.", "no seguimento do recém-nascido."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa A. Resposta indicada no gabarito: na gestação..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Obstetrícia','Operação cesariana após trabalho de parto e amniorrexe de qualquer duração em mulheres não indigentes apresenta o seguinte risco de infecção puerperal:','','','["muito alto (40% a 85%).", "alto (10% a 40%).", "moderado (03% a 10%).", "baixo (01% a 03%)."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: alto (10% a 40%)..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Obstetrícia','A endometrite puerperal caracteriza-se por','','','["baixa frequência (menos de 1% dos partos), aparecimento mais frequente no 4º-5º dia de puerpério e dor parametrial.", "temperatura subfebril (abaixo de 38,5º C), disúria e lóquios hemorrágicos.", "útero amolecido, colo permeável à polpa digital e lóquios purulentos.", "cistite, temperatura persistente por mais de 10 dias, oscilando entre 39º a 39,5º C e hemorragia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: útero amolecido, colo permeável à polpa digital e lóquios purulentos..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Obstetrícia','O tratamento da gestante diabética deve incluir','','','["dieta para as gestantes com diabetes pré- -gestacional, insulinoterapia apenas para as diabéticas pré-gestacionais, exercício físico.", "dieta para todas as gestantes, insulinoterapia nas diabéticas gestacionais com média glicêmica acima de 100 mg/dl, exercício físico.", "dieta para as gestantes que não precisem de insulina, insulina para prevenção de anomalias fetais, exercício físico.", "diabetes para gestantes com história prévia de diabetes, insulina NPH na dose inicial de 25 UI/dia, exercício físico."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: dieta para todas as gestantes, insulinoterapia nas diabéticas gestacionais com média glicêmica acima de 100 mg/dl, exercício físico..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Obstetrícia','O parto da gestante diabética','','','["deve ser cesáreo, tão logo atingido o termo.", "deve ser espontâneo, tão logo atingido o termo.", "é recomendável o parto espontâneo.", "não é recomendável o parto espontâneo pela maior incidência de distocias."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: é recomendável o parto espontâneo..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Obstetrícia','O parto na gestante cardiopata deve ser','','','["cesáreo nas portadoras de cardiopatia classe I da New York Heart Association (NYHA).", "cesáreo nas portadoras de classe III da NYHA.", "espontâneo com qualquer classificação da NYHA.", "vaginal com fórcipe de alívio em qualquer classificação da NYHA."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: vaginal com fórcipe de alívio em qualquer classificação da NYHA..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Obstetrícia','A bacteriúria assintomática na gravidez','','','["é inofensiva, visto que é assintomática .", "deve ser tratada somente a partir do primeiro trimestre.", "deve ser tratada tão logo identificada.", "deve ser tratada no último trimestre pela associação com infecção puerperal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: deve ser tratada tão logo identificada..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Obstetrícia','São requisitos para a operação cesariana eletiva em portadoras de HIV:','','','["qualquer carga viral, bolsa rota, início do trabalho de parto e gravidez com mais de 36 semanas.", "carga viral > 1000, bolsa íntegra, ausência de trabalho de parto e gestação com mais de 38 semanas.", "carga viral < 1000, bolsa rota há mais de 6 horas, início de trabalho de parto e gestação com mais de 39 semanas.", "carga viral > 10000, bolsa íntegra, ausência de trabalho de parto e gestação a partir de 36 semanas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: carga viral > 1000, bolsa íntegra, ausência de trabalho de parto e gestação com mais de 38 semanas..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Obstetrícia','O diagnóstico clínico da apresentação pélvica baseia-se em','','','["polo pélvico ocupando o fundo uterino, nádega fetal fixa no estreito superior, toque obstétrico identificando tuberosidades isquiáticas.", "polo cefálico ocupando o fundo uterino, nádega identificada à palpação abdominal, toque obstétrico identificando o sacro.", "polo pélvico ocupando o fundo uterino, nádega fetal não identificável à palpação abdominal e toque vaginal identificando a genitália externa.", "polo cefálico ocupando o fundo uterino, identificação da nádega pela manobra de Budin e toque vaginal identificando o sacro."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: polo cefálico ocupando o fundo uterino, nádega identificada à palpação abdominal, toque obstétrico identificando o sacro..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Obstetrícia','Das condições abaixo, quais são exigidas para o parto gemelar por via vaginal?','','','["Primeiro gemelar cefálico, segundo gemelar com peso < 1000 g e segundo gemelar cefálico ou não.", "Primeiro gemelar não cefálico, segundo gemelar com peso > 1500 g e segundo gemelar cefálico ou não.", "Primeiro gemelar cefálico, segundo gemelar não cefálico com versão externa intraparto com sucesso.", "Primeiro gemelar não cefálico, segundo gemelar cefálico e segundo gemelar com mais de 1500 g."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: Primeiro gemelar cefálico, segundo gemelar não cefálico com versão externa intraparto com sucesso..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Obstetrícia','As funções do fórcipe obstétrico são:','','','["preensão, rotação e redução do volume cefálico.", "rotação, extração e correção da pegada.", "preensão, rotação e pegada correta.", "preensão, rotação e extração."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: preensão, rotação e extração..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Obstetrícia','Exigem-se como condições de praticabilidade do fórcipe obstétrico na apresentação de crânio:','','','["cabeça insinuada, dilatação total do colo, bolsa rota.", "cabeça insinuada, dilatação total do colo, variedade de posição em OP.", "cabeça insinuada, avaliação da bacia, avaliação do volume fetal.", "cabeça insinuada, colo mesmo incompletamente dilatado, variedade de posição posterior."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa A. Resposta indicada no gabarito: cabeça insinuada, dilatação total do colo, bolsa rota..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Obstetrícia','A extração fetal na cesariana pode ser difícil devido à','','','["cabeça adaptada ao estreito superior, cabeça flutuante ou apresentação pélvica.", "cabeça flutuante, feto muito pequeno ou situação transversa.", "cabeça profundamente insinuada, feto em apresentação córmica ou peso fetal em torno de 3000 g.", "cabeça encravada no canal do parto, feto muito pequeno ou placenta prévia marginal."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: cabeça flutuante, feto muito pequeno ou situação transversa..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Obstetrícia','Diante de distocia de espádua, a ordem das manobras para a liberação dos ombros deve ser:','','','["pressão suprapúbica, desprendimento do braço posterior e manobra de Zavanelli.", "manobra de McRoberts, manobra de Corrêa da Costa e fratura intencional da clavícula.", "pressão suprapúbica aliada à manobra de McRoberts, manobra de rotação da espádua e desprendimento do braço posterior.", "manobra de rotação da espádua, manobra de Zavanelli e fratura intencional da clavícula."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: pressão suprapúbica aliada à manobra de McRoberts, manobra de rotação da espádua e desprendimento do braço posterior..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Obstetrícia','O desenho de estudo adequado para avaliar tratamento é','','','["estudo de coorte.", "estudo caso-controle.", "estudo transversal.", "ensaio clínico randomizado."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: ensaio clínico randomizado..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Obstetrícia','Entre as ações para reduzir a mortalidade materna, incluem-se:','','','["melhorar a assistência pré-natal, melhorar a assistência ao parto e fornecer apoio psicológico para o aleitamento.", "melhorar a assistência pré-natal, melhorar a assistência ao parto e evitar cesarianas desnecessárias.", "implantar os Comitês Estaduais de Mortalidade Materna, incluir pesquisa de rubéola na pré-natal e implementar o planejamento familiar.", "evitar cesarianas desnecessárias, incluir pesquisa de viroses na assistência pré-natal e melhorar a assistência ao parto."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: melhorar a assistência pré-natal, melhorar a assistência ao parto e evitar cesarianas desnecessárias..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Obstetrícia','Qual das opções abaixo melhor representa as causas de mortalidade perinatal?','','','["Hipertensão arterial, diabetes e parto normal.", "Cesariana, descolamento prematuro da placenta e cardiopatia materna.", "Hemorragia da segunda metade da gravidez, diabetes mellitus e infecção perinatal.", "Parto a fórcipe, apesar de baixo em OP, asfixia intraparto e pré-eclampsia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: Hemorragia da segunda metade da gravidez, diabetes mellitus e infecção perinatal..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Obstetrícia','Erro médico é a conduta profissional inadequada caracterizada por','','','["imperícia, imprudência ou cobrança de honorários excessivos.", "imprudência, negligência e participação de greve de médicos.", "imprudência, negligência e mau resultado do tratamento.", "imperícia, imprudência ou negligência."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: imperícia, imprudência ou negligência..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Obstetrícia','Segundo a lei nº 9623 de 12 de janeiro de 1996, são exigências para a esterilização tubária:','','','["mulheres com capacidade civil plena, maiores de 25 anos ou, pelo menos, com dois filhos vivos.", "mulheres maiores de 25 anos, sadias, com, pelo menos, um filho vivo.", "risco à saúde da mulher, solicitação por parte da paciente, dispensando documento escrito.", "pedido do marido, indicação de cesariana, disponibilidade de laparoscopia por parte do serviço."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa A. Resposta indicada no gabarito: mulheres com capacidade civil plena, maiores de 25 anos ou, pelo menos, com dois filhos vivos..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Obstetrícia','Primigesta, com 16 semanas de idade gestacional, queixa-se de aumento do ritmo miccional que se acentua no período do sono. Ao exame: PA = 120 x 80 mmHg, temperatura axilar 36,4ºC, medida do fundo uterino de 20 cm, BCF = 150 bpm. Ao toque: colo posterior fechado sem perdas vaginais. Qual a melhor conduta?','','','["Antibioticoterapia por no mínimo 07 dias, empregando preferencialmente cefalospo- rina.", "Orientação, dispensado tratamento especial por tratar-se de nictúria fisiológica da gravidez.", "Correção cirúrgica da hipotonia do esfíncter uretro-vesical.", "Realizar prova urodinâmica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: Orientação, dispensado tratamento especial por tratar-se de nictúria fisiológica da gravidez..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Obstetrícia','Gestante com 32 semanas de idade gestacional, GI, P0, A0, atendida em consulta de rotina pré-natal. Ao exame: PA = 150 x 90 mmHg, medida do fundo uterino = 27cm, BCF = 144bpm. Propedêutica biofísica fetal: Dopplerfluxometria da artéria umbilical apresentado diástole zero, índice de pulsatilidade (PI) da artéria cerebral média com PI = 0,75 e do ducto venoso apresentando fluxo diastólico reverso. Qual a melhor conduta?','','','["Considerar a interrupção imediata da gestação.", "Solicitar perfil biofísico fetal duas vezes por semana.", "Corticoide e acompanhamento semanal com Cardiotocografia basal.", "Repouso no leito em decúbito lateral esquerdo e reavaliar em dois dias."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa A. Resposta indicada no gabarito: Considerar a interrupção imediata da gestação..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Obstetrícia','Durante a expulsão, os ombros geralmente se insinuam no diâmetro oblíquo ou transverso, sob o ramo púbico. Os puxos, esforço materno involuntário para expulsão fetal, irão impulsionar o ombro anterior sob o pube que, após passar pelo estreito superior da bacia e ganhar o assoalho pélvico, sofrem rotação para orientar o diâmetro biacromial no sentido antero- posterior da saída do canal de parto. Considerando que o ombro não rode para o diâmetro oblíquo antes de sua insinuação, mantendo posição anteroposterior, qual a complicação mais comum?','','','["Paralisia de Zavanelli.", "Paralisia de Klumpke.", "Paralisia de McRoberts.", "Paralisia de Erb-Duchene."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: Paralisia de Erb-Duchene..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Obstetrícia','Gestante com 20 semanas de idade gestacional chega para a primeira consulta de pré-natal trazendo o seguinte laudo de ultrassonografia: gestação gemelar monocoriônica e diamniótica, feto A em apresentação pélvica, dorso à direita, biometria compatível com o datismo menstrual, maior bolsão vertical com 07cm; feto B apresentando má formação complexa envolvendo cabeça e parte superior do corpo com coração rudimentar não funcionante e maior bolsão vertical de 03cm. Qual o diagnóstico?','','','["Síndrome da transfusão feto-fetal grave.", "Gêmeo acárdico.", "Gemelidade inperfecta (gêmeos unidos).", "Óbito unifetal."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: Gêmeo acárdico..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Obstetrícia','Gestante com 13 semanas de idade gestacional chega para a primeira consulta de pré-natal com a informação dada pelo ultrassonografista de que se trata de uma gestação gemelar dicoriônica e diamniótica. Qual dos sinais abaixo, identificado pelo ultrassonografista, permitiu este diagnóstico?','','','["Identificação do córion em um único anel.", "Projeção triangular do corion entre as duas camadas do âmnio “twin peak sign”.", "Dois embriões vistos em um único saco, não se identificando a membrana entre eles.", "Gêmeos de sexos iguais."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: Projeção triangular do corion entre as duas camadas do âmnio “twin peak sign”..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Obstetrícia','Dos marcadores do perfil biofísico fetal a seguir, assinale o que mais tardiamente se compromete frente à hipoxia fetal.','','','["Movimento respiratório fetal.", "Movimento fetal.", "Cardiotocografia.", "Grau de maturidade placentária."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: Movimento fetal..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Obstetrícia','Das doenças a seguir, qual a que mais comumente se associa com restrição do crescimento intrauterino grave e precoce?','','','["Hipertensão arterial.", "Diabete gestacional.", "Cromossomopatia.", "Lupus eritematoso sistêmico."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: Cromossomopatia..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Obstetrícia','Em uma gestação cujo comprimento cabeça nádega (CCN) é de 55mm e a medida da translucência nucal de 3,1 mm, qual a opção correta?','','','["Gestação de risco para aneuploidia.", "Feto com higroma cístico.", "Feto portador de síndrome de Down.", "Esta medida foi realizada fora do período ideal, não permitindo nenhuma conclusão."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa A. Resposta indicada no gabarito: Gestação de risco para aneuploidia..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Obstetrícia','Gestante com 37 semanas apresenta sangramento vaginal intenso há 01 hora, nega contrações e esforço físico. Ao exame, paciente apresentando sudorese e taquicardia, BCF = 126 bpm, ao toque, colo dilatado 02 cm, toca-se a superfície materna da placenta. Qual a melhor conduta?','','','["Reposição volêmica e cesariana.", "Tocolíticos e repouso.", "Circlagem do colo uterino.", "Misoprostol 25mg via vaginal a cada 2 horas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa A. Resposta indicada no gabarito: Reposição volêmica e cesariana..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Obstetrícia','Qual a mais frequente complicação materna no quarto período do parto?','','','["Trombembolismo.", "Convulsões.", "Hemorragia.", "Choque séptico."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: Hemorragia..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Obstetrícia','Gestante com 28 semanas de idade gestacional apresenta glicemia de jejum de 110mg/dl e glicemia 2 horas após sobrecarga de 100g de glicose de 175mg/dl. Qual das medidas abaixo tem maior impacto para a redução da mortalidade perinatal nesta gestante?','','','["Ultrassonografia a cada 15 dias para monitorização do volume de líquido amniótico.", "Dopplerfluxometria semanal.", "Controle da glicemia materna.", "Ecocardiograma fetal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: Controle da glicemia materna..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Obstetrícia','Leia o enunciado e as alternativas da questão 38 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-obstetricia-q38-1-v3.png", "/pmerj-arquivo/pmerj-2010-medico-obstetricia-q38-2-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Obstetrícia','A sequência clássica das alterações de fluxo à dopplervelocimetria no modelo obstrutivo é:','','','["artéria umbilical, ducto venoso, artéria cerebral média, artérias uterinas", "artérias uterinas, artéria umbilical, artéria cerebral média, ducto venoso.", "artéria umbilical, artérias uterinas, ducto venoso, artéria cerebral média.", "artéria cerebral média, artéria umbilical, ducto venoso, artérias uterinas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: artérias uterinas, artéria umbilical, artéria cerebral média, ducto venoso..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Obstetrícia','Gestante com 28 anos, terceira gestação, no momento com 12 semanas de idade gestacional e história de dois abortamentos tardios (com 17 e 16 semanas respectivamente, ambos os fetos vivos que nasceram ainda em casa e morreram em seguida). Qual a melhor conduta?','','','["Progestágenos.", "Beta-miméticos e repouso.", "Circlagem do colo uterino.", "Aspiração manual intrauterina (AMIU)."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: Circlagem do colo uterino..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Obstetrícia','Gestante de 25 anos apresenta laudo ultrassonográfico compatível com higroma cístico em um feto com genitália feminina. Qual das opções abaixo melhor se relaciona a este achado?','','','["Síndrome de Down.", "Síndrome de Turner.", "Síndrome de Edwards.", "Síndome de Patau."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: Síndrome de Turner..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Obstetrícia','Gestante de 38 anos apresenta laudo de ecocardiografia fetal compatível com defeito do septo interventricular. Após discussão com o médico assistente, optaram por fazer amniocentese para cariótipo fetal. Qual o diagnóstico mais provável?','','','["Trissomia do 21.", "Trissomia do 13.", "Trissomia do 18.", "Monossomia do X."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa A. Resposta indicada no gabarito: Trissomia do 21..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Obstetrícia','A dopplervelocimetria é uma técnica que pode ser utilizada como método preditivo de anemia fetal. Que vaso da economia fetal possui os melhores resultados nesse tipo de investigação?','','','["Ducto venoso.", "Artéria Renal.", "Artéria Cerebral Média.", "Artéria Umbilical."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: Artéria Cerebral Média..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Obstetrícia','Gestante apresenta infecção primária por rubéola. Sobre esse caso, é correto afirmar:','','','["O período de incubação varia de 02 a 05 dias.", "2/3 das gestantes permanece assintomática na fase aguda da doença.", "O risco do concepto em ser atingido quando a mãe desenvolve o quadro agudo no primeiro trimestre é de 90%.", "O risco do concepto em ser atingido decresce no terceiro trimestre."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: O risco do concepto em ser atingido decresce no terceiro trimestre..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Obstetrícia','Sobre a hepatite B na gestação, podemos afirmar:','','','["O período de incubação varia de 10 a 15 dias.", "A transmissão vertical ocorre fundamentalmente no curso da gravidez, por via transplacentária.", "A incidência da transmissão vertical no terceiro trimestre é de 10%.", "Em paciente HBsAg e HBeAg positiva a transmissão vertical ocorre em 90% das vezes."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: Em paciente HBsAg e HBeAg positiva a transmissão vertical ocorre em 90% das vezes..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Obstetrícia','Sobre lúpus e gravidez é correto afirmar:','','','["Todos os onze critérios estabelecidos pelo American College of Rheumatology (ACR), são necessários para firmar o diagnóstico.", "A glicosúria é considerada patognomônica.", "O diagnóstico se alicerça em dados clínicos e laboratoriais.", "A marca registrada do LES é a completa ausência de autoanticorpos no soro das pacientes."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: O diagnóstico se alicerça em dados clínicos e laboratoriais..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Obstetrícia','Dentre os testes listados abaixo para o diagnóstico da síndrome antifosfolipídeo, o que se associa de modo independente com o prognóstico fetal adverso, em especial quando seus valores se mostram superiores a 40GPL, é:','','','["teste sorológico falso-positivo para sífilis (VDRL).", "anticorpo anticoagulante lúpico - AL.", "anticorpos anticardiolipinas classe IgG.", "anticorpos antibeta dois glicoproteína."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa C. Resposta indicada no gabarito: anticorpos anticardiolipinas classe IgG..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Obstetrícia','Gestante com 23 semanas de idade gestacional e diagnóstico de sífilis primária tratada com 1.200.000 UI de Penicilina G benzatina, evolui com óbito fetal. Sobre esse caso, assinale a opção correta.','','','["Considerar natimorto por sífilis congênita.", "A infecção vertical se dá mais frequen- temente durante o parto, portanto devem-se buscar outras causas de óbito fetal.", "A penicilina G benzatina na dose de 1.200.000 UI em dose única é indicada em qualquer estágio da doença.", "Está dispensado o tratamento do parceiro, pois a gestação já se resolveu espontânea- mente."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa A. Resposta indicada no gabarito: Considerar natimorto por sífilis congênita..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Obstetrícia','Uma gestante deve ser considerada adequada- mente tratada para sífilis na gestação e seu filho necessita de cuidados especiais como os prestados aos filhos de mães não tratadas se','','','["uma paciente alérgica usou corretamente um regime de tratamento não penicilínico.", "houve queda nos títulos do VDRL de no mínimo duas vezes no seguimento pós- -tratamento, que deve ser mensal.", "a paciente refere ter usado 03 doses de penicilina G benzatina.", "o tratamento foi concluído há menos de um mês."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa B. Resposta indicada no gabarito: houve queda nos títulos do VDRL de no mínimo duas vezes no seguimento pós- -tratamento, que deve ser mensal..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Obstetrícia','Uma gestante assintomática apresenta ultrassonografia compatível com hidropisia fetal e sinais de anemia severa pela dopplerfluxometria. Qual o diagnóstico provável que irá nortear sua propedêutica?','','','["Toxoplasmose congênita.", "Infecção pelo vírus da Hepatite B.", "Rubéola congênita.", "Infecção por parvovírus B19."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Obstetrícia: alternativa D. Resposta indicada no gabarito: Infecção por parvovírus B19..' from public.exams where slug='pmerj-2010-medico-obstetricia' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-odontologia-clinica-geral','PMERJ 2010 — Oficial — Odontologia Clínica Geral','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Odontologia Clínica Geral','Histologicamente a lesão abaixo é caracterizada pela reabsorção do aspecto interno da raiz, ditada pelas células gigantes adjacentes ao tecido de granulação da polpa. Na radiografia, observa-se o alargamento em forma oval do espaço do canal radicular. Geralmente é assintomática. Essa descrição se refere à','','','["concussão.", "reabsorção radicular externa.", "degeneração hialina da polpa.", "reabsorção radicular interna."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: reabsorção radicular interna..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Odontologia Clínica Geral','As lesões de luxação são as mais comuns de todas as lesões dentárias com incidências relatadas, variando de','','','["40% a 60%.", "70% a 75%.", "30% a 44%.", "35% a 45%."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: 30% a 44%..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Odontologia Clínica Geral','A teoria principal (central core) pode ser a melhor explicação para o','','','["sucesso do bloqueio do nervo alveolar superior posterior.", "insucesso do bloqueio do nervo alveolar superior posterior.", "sucesso do bloqueio do nervo alveolar superior médio.", "insucesso do bloqueio do nervo alveolar inferior."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: insucesso do bloqueio do nervo alveolar inferior..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Odontologia Clínica Geral','Leia com atenção as seguintes afirmações. I. As espécies individuais da flora endodôntica possuem alta virulência. II. Interações que ocorrem com outros microrganismos, não resultam em uma sociedade sinergisticamente benéfica para o aumento da infecção endodôntica. III. Coletivamente elas são patogênicas por uma combinação de fatores. IV. Não existem evidências de que as interações microbianas possuem um papel significante na regulação ecológica e no desenvolvi-mento eventual de uma flora adaptada ao habitat endodôntico. Após análise dessas afirmações, é possível concluir que','','','["a afirmação número I é a única correta.", "apenas as afirmações I e III são corretas.", "as afirmações I, II e IV são incorretas.", "todas as afirmações estão incorretas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: as afirmações I, II e IV são incorretas..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Odontologia Clínica Geral','Quanto aos cimentos à base de óxido de zinco e eugenol, pode-se afirmar que','','','["apresentam um tempo de presa pequeno, e são extremamente citotóxicos.", "não sofrem contração ao tomar presa e possuem baixa atividade bacteriana.", "não mancham a coroa dentária e sua remoção é bastante fácil.", "possuem boa atividade antimicrobiana e apresentam um tempo de presa grande."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: possuem boa atividade antimicrobiana e apresentam um tempo de presa grande..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Odontologia Clínica Geral','Várias doenças orofaciais podem simular dor endodôntica e produzir uma incorreta interpretação sensorial, devido à superposição do nervo trigêmio e à inervação cervical craniana adjacente. Para controlar a dor de um paciente, o clínico deve I. procurar revelar sinais e sintomas determinados pelas doenças inflamatórias pulpares e periapicais. II. lembrar que, mesmo em uma emergência endodôntica verdadeira, a maior chance é que vários dentes estejam envolvidos. III. saber que a dor dentária pode estar associada a várias doenças que se manifestam com dor orofacial. IV. identificar a dor orofacial como uma dor de origem odontogênica, mesmo quando esta se irradia para uma área maior da face. Após analisar as sentenças acima, é lícito concluir que','','','["todas estão corretas.", "todas estão incorretas.", "as afirmações I, III e IV estão corretas.", "as afirmações I e IV estão corretas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: as afirmações I, III e IV estão corretas.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Odontologia Clínica Geral','A intensidade das reações celulares depende da(o) I. dose de radiação. II. área irradiada. III. sensibilidade do tecido. IV. estágio de desenvolvimento das células. V. ritmo de aplicação. Qual das seguintes alternativas é a correta?','','','["I, II e IV.", "II, III e IV.", "I, III, IV e V.", "Todas estão corretas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: Todas estão corretas..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Odontologia Clínica Geral','“Relacionando com o tamanho da área focal, procurou-se dar à área focal a inclinação de 20º com o plano vertical, gerando uma projeção geométrica quadrangular.” A esse princípio damos o nome de','','','["princípio CIENSZYNSKI.", "princípio COOLIDGE.", "princípio da emissão termo-iônica.", "efeito BENSON ou princípio do foco linear."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: efeito BENSON ou princípio do foco linear..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Odontologia Clínica Geral','No método do deslizamento para localização radiográfica, usado principalmente na maxila, tomam- se duas radiografias com','','','["mesmos ângulos verticais, mesmos ângulos horizontais e mesmos pontos de incidência.", "mesmos ângulos verticais, diferentes ângulos horizontais e mesmos pontos de incidência.", "diferentes ângulos verticais, mesmos ângulos horizontais e mesmos pontos de incidência.", "diferentes ângulos verticais, diferentes ângulos horizontais e diferentes pontos de incidência."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa B. Resposta indicada no gabarito: mesmos ângulos verticais, diferentes ângulos horizontais e mesmos pontos de incidência..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Odontologia Clínica Geral','Na ocorrência da gengivite, a lesão gengival precoce ocorre aproximadamente sete dias após o acúmulo de placa e, sob o aspecto histológico, os leucócitos predominantes no infiltrado nesta fase são os','','','["linfócitos e neutrófilos.", "linfócitos e plasmócitos.", "neutrófilos e plasmócitos.", "plasmócitos e macrófagos."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa A. Resposta indicada no gabarito: linfócitos e neutrófilos..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Odontologia Clínica Geral','Paciente adulto, com doença periodontal, apresenta bolsas com 6 mm de profundidade de sondagem. As principais fontes de sais minerais para a formação de cálculo supragengival e subgengival são','','','["dos minerais presentes na saliva e das proteínas liberadas pelas bactérias.", "das secreções salivares e do exsudato inflamatório do fluido gengival.", "dos minerais presentes na saliva e do exsudato inflamatório da bolsa periodontal.", "das lectinas dietéticas salivares e das proteínas liberadas pelas bactérias."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: dos minerais presentes na saliva e do exsudato inflamatório da bolsa periodontal..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Odontologia Clínica Geral','Para preenchimento de defeito infraósseo, um paciente recebeu enxerto de um material constituído de osso descalcificado congelado e seco. Esse material trata-se de um','','','["heteroenxerto.", "xenoenxerto.", "autoenxerto.", "aloenxerto."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: aloenxerto..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Odontologia Clínica Geral','Para a formação de uma nova inserção em raízes previamente expostas a patógenos periodontais, é necessária a participação de células oriundas do','','','["tecido conjuntivo gengival.", "epitélio oral.", "ligamento periodontal.", "colágeno das fibras gengivais."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: ligamento periodontal..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Odontologia Clínica Geral','Considerando as características do cemento radicular descrito como um tecido calcificado especializado, é INCORRETO afirmar que','','','["possui muitas características em comum com o tecido ósseo.", "sua porção mineral é formada principalmente por cristais de hidroxiapatita.", "sofre remodelação e reabsorção fisiológicas ao longo da vida.", "é constituído de fibras colágenas embutidas em matriz orgânica."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: sofre remodelação e reabsorção fisiológicas ao longo da vida..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Odontologia Clínica Geral','Sobre a Sarcoidose, está correto afirmar que','','','["embora qualquer órgão possa ser envolvido os pulmões, linfonodos, pele, olhos e glândulas salivares são os locais menos acometidos.", "a resposta de defesa inadequada pode resultar de curta ou nenhuma exposição antigênica, de uma imunodesregulação, que impede uma resposta celular satisfatória, de uma regulação defeituosa da reação imune inicial ou de uma combinação de todos esses três fatores.", "as evidências indicam degradação inadequada de material antigênico, sem a produção de inflamação granulomatosa não caseosa.", "é uma desordem granulomatosa multis- sistêmica de causa desconhecida."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: é uma desordem granulomatosa multis- sistêmica de causa desconhecida..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Odontologia Clínica Geral','Na maioria dos casos, as manifestações bucais do lúpus eritematoso cutâneo crônico (LECC) se apresentam clinicamente idênticas às lesões do(a)','','','["líquen plano erosivo.", "psoríase.", "síndrome de Reiter.", "esclerose sistêmica."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa A. Resposta indicada no gabarito: líquen plano erosivo..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Odontologia Clínica Geral','O aumento difuso e acentuadamente eritematoso dos tecidos gengivais é uma manifestação oral identificada nos pacientes portadores de','','','["hipercortisilismo (Síndrome de Cushing).", "hiperparatiroidismo.", "hipofosfatasia.", "diabetes tipo I."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: diabetes tipo I..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Odontologia Clínica Geral','Radiograficamente, o mixoma se apresenta como uma lesão radiotransparente. Pode-se afirmar ainda que','','','["na maioria das vezes as margens da lesão são regulares e festonadas.", "a lesão multilocular ou unilocular pode deslocar ou causar reabsorção dos dentes na região do tumor.", "os mixomas de maxilares não são considerados, atualmente, de origem odontogênica.", "a faixa etária mais afetada é acima de 50 anos; além disso, essa patologia é mais observada em pacientes do sexo feminino."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa B. Resposta indicada no gabarito: a lesão multilocular ou unilocular pode deslocar ou causar reabsorção dos dentes na região do tumor..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Odontologia Clínica Geral','Em relação aos dentes reimplantados após avulsão dentária, pode-se afirmar que','','','["a longevidade dos dentes avulsionados reimplantados depende do estágio de desenvolvimento radicular no momento do traumatismo, sendo desfavorável com a proximidade da conclusão da rizogênese.", "os testes de sensibilidade são confiáveis, mesmo quando realizados imediatamente após o reimplante.", "dentes portadores de doença periodontal também podem e devem ser reimplatados.", "os dentes reimplantados devem receber contenção por um período de tempo mínimo. Uma semana normalmente é suficiente para assegurar uma sustentação adequada."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: os dentes reimplantados devem receber contenção por um período de tempo mínimo. Uma semana normalmente é suficiente para assegurar uma sustentação adequada..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Odontologia Clínica Geral','A Bainha Epitelial de Hertwig (BEH) é uma estrutura tubular contínua de células Epiteliais, que separa a polpa do folículo dental. Sobre o papel dessa estrutura nobre, é INCORRETO afirmar que','','','["ela envolve completamente a papila dental, exceto por uma abertura em sua base, o forame apical primário.", "o fato de que a BEH pode continuar a funcionar, apesar de uma inflamação induzida por necrose pulpar parcial, demonstra que o desenvolvimento e o fechamento radicular apical devem ser tomados como critérios de vitalidade pulpar.", "após a formação dos odontoblastos e a formação do cemento intermediário, a BEH degenera-se e as células migram para longe, para formar os restos epiteliais de Mallassez.", "a formação radicular é determinada pela atividade da BEH."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa B. Resposta indicada no gabarito: o fato de que a BEH pode continuar a funcionar, apesar de uma inflamação induzida por necrose pulpar parcial, demonstra que o desenvolvimento e o fechamento radicular apical devem ser tomados como critérios de vitalidade pulpar..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Odontologia Clínica Geral','A candidose é a mais comum das manifestações intraorais da infecção por HIV e muitas vezes é o sinal de apresentação que leva ao diagnóstico inicial. Dentre as alternativas abaixo, marque aquela que enumera os exames indicados para o diagnóstico final.','','','["Detecção de antígenos e anticorpos para o HIV.", "Pode ser comprovada por esfregaço citológico e hemograma completo.", "Pode ser comprovada por esfregaço citológico ou por biópsia.", "Leucograma e biópsia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: Pode ser comprovada por esfregaço citológico ou por biópsia..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Odontologia Clínica Geral','A concrescência é a união de dois dentes adjacentes apenas pelo cemento; além disso, pode-se afirmar que','','','["pode ser resultado do desenvolvimento ou ser pós-inflamatória, sem confluência da dentina.", "é uma tentativa de um único germe dentário dividir-se.", "resulta na formação de um dente unido com confluência de dentina.", "em alguns casos resulta na formação de dentes extranumerários."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa A. Resposta indicada no gabarito: pode ser resultado do desenvolvimento ou ser pós-inflamatória, sem confluência da dentina..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Odontologia Clínica Geral','Doença periodontal avançada tanto na dentição temporária quanto na permanente, que se desenvolve logo após a erupção dos dentes, presença de gengivite hiperplásica e hemorragia extensa são manifestações intraorais da','','','["doença de Paget.", "síndrome de Frey.", "síndrome de Papillon-Lefèvre.", "doença de Crohn."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: síndrome de Papillon-Lefèvre..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Odontologia Clínica Geral','Marque a alternativa INCORRETA.','','','["Andreassen e Hjorting-Hansen descreveram 4 tipos de cicatrização das fraturas radiculares: cicatrização com tecido calcificado, cicatrização com tecido conjuntivo interposto, cicatrização com osso e tecido conjuntivo interpostos e cicatrização por tecido inflamatório interposto sem cicatrização.", "Os 3 primeiros tipos de cicatrização são considerados sucesso. Os dentes geralmente são assintomáticos e respondem positiva-mente ao teste de sensibilidade.", "Na cicatrização com osso e tecido conjuntivo interpostos, no exame radiográfico, é possível observar que os fragmentos se apresentam unidos por uma ponte óssea distinta.", "Na cicatrização com tecido calcificado, no exame radiográfico, é possível observar que a linha de fratura é discernível, mas os fragmentos estão em íntimo contato."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: Na cicatrização com osso e tecido conjuntivo interpostos, no exame radiográfico, é possível observar que os fragmentos se apresentam unidos por uma ponte óssea distinta.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Odontologia Clínica Geral','Sobre a película adquirida, pode-se afirmar que','','','["as superfícies dentárias, o esmalte, assim como o cemento exposto, são normalmente cobertos por uma fina película adquirida formada por glicoproteínas.", "caso removida por instrumentação mecânica, ela se formará novamente em aproximadamente 60 minutos.", "não desempenham papel preponderante na aderência seletiva de bactérias a superfície dentária.", "o primeiro material celular a aderir à película sobre a superfície do dente consiste em formas filamentosas, células epiteliais e leucócitos polimorfosnucleares."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa A. Resposta indicada no gabarito: as superfícies dentárias, o esmalte, assim como o cemento exposto, são normalmente cobertos por uma fina película adquirida formada por glicoproteínas..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Odontologia Clínica Geral','O condicionamento do esmalte com ácido fosfórico, além de descalcificar a sua superfície criando microporosidades necessárias para a retenção micromecânica do adesivo, é essencial para','','','["que o ângulo de contato do adesivo aplicado sobre o esmalte seja pequeno, possibilitando uma boa capacidade de umedecimento.", "aumentar a energia superficial, obtendo uma superfície de esmalte menos receptiva.", "diminuir a energia superficial, obtendo uma superfície de esmalte mais receptiva.", "restringir o escoamento do adesivo apenas sobre área descalcificada, impedindo excessos danosos à adaptação marginal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa A. Resposta indicada no gabarito: que o ângulo de contato do adesivo aplicado sobre o esmalte seja pequeno, possibilitando uma boa capacidade de umedecimento..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Odontologia Clínica Geral','Nas restaurações de amálgama de prata pela técnica adesiva, o mecanismo de união do sistema adesivo ao amálgama baseia-se no emprego de um adesivo que tenha ativação química e que se unirá ao amálgama durante sua condensação na cavidade, proporcionando entre o adesivo e a restauração de amálgama uma união do tipo','','','["macromecânica.", "micromecânica.", "química.", "híbrida."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa B. Resposta indicada no gabarito: micromecânica..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Odontologia Clínica Geral','Considere as seguintes afirmações sobre o cimento de ionômero de vidro convencional: I. Sua união ao dente é maior em relação à dentina do que ao esmalte. II. Apresentam, dentre os materiais restaura- dores, os valores de coeficiente de expansão térmica linear mais próximos aos da estrutura dental. III. Sua característica de biocompatibilidade é atribuída a alguns fatores, dentre eles o baixo peso molecular do ácido poliacrílico. IV. O flúor liberado por suas restaurações pode ser incorporado à estrutura dental adjacente, tornando-a mais resistente à desminera-lização. APENAS está correto o que se afirma em','','','["I, II e III.", "III e IV.", "II e IV.", "I, II, e IV."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: II e IV..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Odontologia Clínica Geral','Analise as afirmativas referentes ao Grau de Conversão das Resinas Compostas. I. O grau de conversão de uma resina composta representa a quantidade de monômero que é convertida em polímero. II. As resinas compostas fotopolimerizáveis apresentam menor grau de conversão se comparadas às resinas compostas quimicamente ativadas. III. O uso de métodos de polimerização complementar por calor propicia um maior grau de conversão, sendo usado para restaurações indiretas. APENAS está correto o que se afirma em','','','["I e II.", "I e III.", "II e III.", "I, II e III."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa B. Resposta indicada no gabarito: I e III..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Odontologia Clínica Geral','Em casos de colagem dental, o fragmento pode ser colado ao remanescente dental, tanto com resina composta fotopolimerizável como com resina composta quimicamente ativada, pois não há diferença entre ambas quanto à capacidade de retenção do fragmento colado. Todavia, nos casos em que não houve perda de substância dental e há perfeita coaptação entre o fragmento e o remanescente dental, qual dos tipos de resina composta é mais recomendada para o procedimento de colagem?','','','["Resina composta fotopolimerizável nano- particulada.", "Resina composta fotopolimerizável micro- híbrida.", "Resina composta fotopolimerizável flow.", "Resina composta quimicamente ativada."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: Resina composta fotopolimerizável flow..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Odontologia Clínica Geral','Dados disponíveis na literatura apoiam a teoria da formação de fluoreto de cálcio (CaF2) como a fase precursora para o aumento da resistência do esmalte dental, inibindo a desmineralização e potencializando a remineralização pelo fornecimento de fonte de baixa concentração de íons de flúor, controlada pela variação cíclica do pH do biofilme dental. Baseado nessas informações, analise as seguintes afirmativas. I. O CaF2 tem a solubilidade limitada na saliva, permanecendo no esmalte e no biofilme dental durante semanas. II. A deposição de CaF2 sobre a superfície do esmalte está condicionada à remoção da película adquirida. III. O CaF2 desempenha um importante papel como reservatório de flúor, controlado pela variação do pH no biofilme dental. Este fluoreto é subsequentemente depositado na superfície do esmalte como flúor- hidroxiapatita, com íons de cálcio e fosfato sendo liberados do esmalte dental. APENAS está correto o que se afirma em','','','["I e II.", "I e III.", "II e III.", "II."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa B. Resposta indicada no gabarito: I e III..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Odontologia Clínica Geral','Dois fatores salivares têm sido utilizados na clínica para a identificação da atividade cariogênica; são eles: o fluxo salivar e a capacidade tampão. Marque a alternativa INCORRETA.','','','["O fluxo salivar e a capacidade tampão são geralmente baixos em crianças e variam com a idade e o tamanho da glândula. Isso justifica a maior prevalência de cárie em crianças.", "Há uma relação direta entre o fluxo salivar e a capacidade tampão da saliva, pois, com o aumento do fluxo salivar, aumenta a concentração de bicarbonato.", "O fluxo salivar é considerado baixo quando os níveis estão abaixo de 0,7 ml/min.", "A avaliação do fluxo salivar é um dado que pode ser utilizado na determinação da atividade da doença cárie."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa A. Resposta indicada no gabarito: O fluxo salivar e a capacidade tampão são geralmente baixos em crianças e variam com a idade e o tamanho da glândula. Isso justifica a maior prevalência de cárie em crianças.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Odontologia Clínica Geral','Durante muito tempo, o tratamento da doença cárie foi baseado em procedimentos restauradores de cavidades na superfície dentárias; contudo, o benefício limitado do tratamento restaurador em si fez com que os pesquisadores reconsiderassem esse enfoque. Dentro desse contexto, observe as afirmativas abaixo: I. A cárie dentária é uma doença crônica, sendo, portanto, de longa duração e progressão lenta para a maioria dos indivíduos de uma população. II. A doença cárie pode ser estacionada em qualquer estágio de desenvolvimento, desde lesões ativas subclínicas até lesões ativas com cavidades. III. O tratamento da doença cárie inclui aplicação tópica de flúor, aconselhamento dietético e procedimentos restauradores de maneira padronizada para todos os indivíduos. IV. Estima-se que aproximadamente 0,5 mm de espessura do esmalte é desmineralizado antes de ser detectado radiograficamente. APENAS está correto o que se afirma em','','','["I e II.", "II e III.", "II, III e IV.", "I, II e IV."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: I, II e IV..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Odontologia Clínica Geral','A presença de açúcares é indispensável para o desenvolvimento da doença cárie, mas o perfil bacteriano, a suscetibilidade do hospedeiro e o tempo de contato desses açúcares com as bactérias do biofilme influenciam de modo decisivo todo o processo. Dentro desse contexto, marque a alternativa correta.','','','["O Streptococos Mutans e Sobrinus são bactérias importantes para o aparecimento da cárie dentária porque são  microrganismos com capacidade de aderência, de produzirem ácidos inorgânicos e de sintetizarem polissacarídeos extracelulares solúveis a partir da sacarose.", "Os estreptococos do grupo mutans são capazes de produzir invertase, enzima que cinde a sacarose em glicose e frutose.", "Os polissacarídeos, por serem moléculas pequenas, difundem-se facilmente no biofilme dental, ficando disponíveis para o metabolismo bacteriano.", "A sacarose é o substrato específico para a formação de polissacarídeos extracelulares, glicano e frutano, além do mutano que é solúvel, aumentando a viscosidade do bio- filme e facilitando a aderência microbiana."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa B. Resposta indicada no gabarito: Os estreptococos do grupo mutans são capazes de produzir invertase, enzima que cinde a sacarose em glicose e frutose..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Odontologia Clínica Geral','Em relação à etapa de moldagem para a confecção de próteses fixas, é correto afirmar que','','','["nos métodos de retração gengival mecanoquímicos a epinefrina, em relação aos adstringentes, possui como vantagem ser melhor hemostático, promovendo por isso melhor afastamento gengival.", "os materiais de moldagem devem ser compatíveis com os materiais utilizados para a obtenção dos modelos e passíveis de desinfecção após o vazamento, sem que suas propriedades sejam alteradas.", "dentre os adstringentes, o sulfato férrico é o indicado para promover o afastamento gengival nas moldagens com siliconas de adição, por não alterar sua reação de polimerização.", "os polissulfetos são materiais de moldagem à base de borracha com características de alta resistência ao rasgamento e boa reprodução de detalhes."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: os polissulfetos são materiais de moldagem à base de borracha com características de alta resistência ao rasgamento e boa reprodução de detalhes..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Odontologia Clínica Geral','Nos casos de grande destruição coronária, nos quais o remanescente coronário não é suficiente para prover resistência estrutural ao material de preenchimento, indica-se o uso de núcleos metálicos fundidos. Dos itens abaixo, marque o correto em relação ao comprimento do pino (parte intraradicular).','','','["O comprimento da parte intrarradicular deve ser igual ou menor que a coroa clínica para proporcionar uma distribuição mais uniforme das forças oclusais ao longo da raiz.", "Naqueles dentes que tenham sofrido perda óssea, o pino deve ter o comprimento equivalente a 2/3 do comprimento total da raiz.", "O comprimento do pino intrarradicular deve preservar a quantidade máxima de 4mm de material obturador na região apical para garantir o vedamento efetivo desta região.", "Como regra geral, o comprimento do pino intrarradicular deve atingir 2/3 do comprimento total do remanescente dental."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: Como regra geral, o comprimento do pino intrarradicular deve atingir 2/3 do comprimento total do remanescente dental.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Odontologia Clínica Geral','Durante o delicado procedimento de seleção de cor para a confecção de prótese dental, qual das opções abaixo pode interferir na fidelidade do resultado?','','','["O volume do dente a ser restaurado.", "A idade do paciente.", "A fonte de luz.", "A anatomia dos dentes adjacentes."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: A fonte de luz..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Odontologia Clínica Geral','O preparo de um dente com finalidade protética deve seguir princípios mecânicos fundamentais. Das alternativas abaixo, assinale a correta.','','','["O preparo deve apresentar princípios de retenção que se caracteriza pelo impedimento ao deslocamento axial da restauração quando submetida às forças oblíquas.", "A forma do preparo deve ser capaz de prevenir o deslocamento da restauração quando submetida às forças de tração, o que caracteriza forma de resistência ou estabilidade.", "A forma de retenção não está relacionada com a área do preparo e a sua textura superficial.", "Em um preparo para coroa total, quanto maior a altura das paredes, maior será a área de resistência do preparo ao deslocamento, quando submetida às forças laterais."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: Em um preparo para coroa total, quanto maior a altura das paredes, maior será a área de resistência do preparo ao deslocamento, quando submetida às forças laterais..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Odontologia Clínica Geral','Qual ligamento da articulação temporoman- dibular tem por função limitar o movimento de protrusão excessivo da mandíbula?','','','["Ligamento estilomandibular.", "Ligamento esfenomandibular.", "Ligamento capsular.", "Porção externa oblíqua do ligamento temporomandibular."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa A. Resposta indicada no gabarito: Ligamento estilomandibular..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Odontologia Clínica Geral','Qual dos relaxantes musculares listados abaixo, que pode ser empregado no tratamento das desordens temporomandibulares (DTMs), é um composto similar aos antidepressivos tricíclicos e age de maneira semelhante a estes no tratamento das DTMs?','','','["Mefenesina.", "Metaxalona.", "Clorzoxazona.", "Ciclobenzaprina."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: Ciclobenzaprina..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Odontologia Clínica Geral','Qual das condições abaixo é caracterizada quando o paciente apresenta dor miogênica regional com áreas locais firmes hipersensitivas de tecidos musculares definidas como pontos de gatilho?','','','["Dor miofascial.", "Miosite crônica.", "Fibromialgia.", "Fibrosite."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa A. Resposta indicada no gabarito: Dor miofascial..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Odontologia Clínica Geral','Das alternativas abaixo, assinale aquela que NÃO é um fator que predispõe às desordens de desarranjo do disco articular da articulação temporomandibular.','','','["Inclinação da eminência articular.", "Fatores hormonais.", "Morfologia do côndilo e da fossa articular.", "Inserção do músculo pterigoideo lateral inferior."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: Inserção do músculo pterigoideo lateral inferior.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Odontologia Clínica Geral','No diagnóstico das infecções odontogênicas, assinale aquela na qual a infecção ainda está confinada ao osso não tendo ainda ultrapassado as barreiras do periósteo e da cortical óssea.','','','["Celulite.", "Abscesso.", "Osteíte periapical.", "Fleimão."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: Osteíte periapical..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Odontologia Clínica Geral','A via de drenagem natural do seio maxilar localiza-se em seu óstio, que está situado em que altura das fossas nasais?','','','["Abaixo do meato médio.", "No meato inferior.", "No centro do meato superior.", "No soalho nasal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa A. Resposta indicada no gabarito: Abaixo do meato médio..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Odontologia Clínica Geral','Em relação aos retalhos cirúrgicos intrabucais, qual das afirmações abaixo está INCORRETA?','','','["As margens do retalho devem estar apoiadas sobre osso sadio.", "Os retalhos devem ser afastados sem tensão.", "O retalho deve ser mucoperiosteal.", "A incisão relaxante deve ser no centro da papila gengival."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa D. Resposta indicada no gabarito: A incisão relaxante deve ser no centro da papila gengival.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Odontologia Clínica Geral','As fraturas intracapsulares do côndilo mandibular são aquelas que ocorrem acima das inserções da cápsula articular. Neste tipo de fratura, quando não há comprometimento da oclusão dentária, o tratamento instituído é','','','["o acompanhamento clínico e fisioterapia.", "a condilectomia parcial.", "o acesso cirúrgico com fixação dos fragmentos ósseos.", "o bloqueio maxilo-mandibular por, no mínimo, 4 semanas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa A. Resposta indicada no gabarito: o acompanhamento clínico e fisioterapia..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Odontologia Clínica Geral','O método de anestesia local denominado técnica de Vazirani-Akinosi (boca fechada), visa a obter o bloqueio do nervo','','','["infraorbitário.", "maxilar.", "mandibular.", "alveolar superior posterior."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: mandibular..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Odontologia Clínica Geral','A noradrenalina, através de estimulação alfa, produz constrição dos vasos sanguíneos cutâneos. Isso leva a um aumento da resistência periférica total e aumento das pressões sistólicas e diastólicas. O grau de duração da isquemia produzida, então, pela injeção extravascular de noradrenalina pode levar à','','','["diminuição do consumo de oxigênio pelos tecidos, na área da injeção.", "diminuição da glicemia.", "necrose de tecidos moles.", "demora do início da anestesia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: necrose de tecidos moles..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Odontologia Clínica Geral','A classificação das drogas simpaticomiméticas por estrutura química é relacionada à presença ou ausência de um núcleo catecol. Os vasoconstrictores que não possuem grupos hidroxila (OH) na terceira e quarta posição da molécula aromática não são  catecóis, mas são aminas, pois apresentam um grupo amina (NH2) fixado à cadeia lateral alifática, sendo, então, denominados não catecolaminas. Baseado nisso, qual alternativa abaixo representa um vasoconstrictor não catecolamina?','','','["Adrenalina.", "Efedrina.", "Levonordefrina.", "Dopamina."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa B. Resposta indicada no gabarito: Efedrina..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Odontologia Clínica Geral','Quanto à região anatômica acometida, as fraturas mandibulares localizadas entre o ângulo da mandíbula e a região inferior do côndilo e do processo coronoide são classificadas como fraturas','','','["do processo coronoide.", "subcondilares.", "do ramo.", "do ângulo."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Clínica Geral: alternativa C. Resposta indicada no gabarito: do ramo..' from public.exams where slug='pmerj-2010-odontologia-clinica-geral' on conflict(exam_id,number) do nothing;
