insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Oftalmologia','Normalmente, para pleno funcionamento retiniano, a pressão intraocular está','','','["acima da mínima da artéria central da retina.", "entre a máxima e a mínima da artéria central da retina.", "próximo da máxima da artéria central da retina.", "abaixo da mínima da artéria central da retina."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa D. Resposta indicada no gabarito: abaixo da mínima da artéria central da retina..' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Oftalmologia','O achado em fundo de olho de drusas, representa','','','["depósitos de colesterol na camada ganglionar.", "restos de microaneurismas retinianos fibrosados.", "depósitos de cálcio na membrana limitante interna.", "depósitos hialinos na membrana de Bruch."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa D. Resposta indicada no gabarito: depósitos hialinos na membrana de Bruch..' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Oftalmologia','As pérolas de Elsching significam','','','["lesão isquêmica da unidade coriocapilar.", "lesão isquêmica da unidade capilar da retina.", "lesão isquêmica venular retiniana.", "proliferação do epitélio cristaliniano."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa D. Resposta indicada no gabarito: proliferação do epitélio cristaliniano..' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Oftalmologia','No teste bicromático, quando um paciente míope vê mais nitidamente os optotipos do lado vermelho, significa','','','["hipocorrigido.", "hipercorrigido.", "que necessita de mais lentes positivas.", "que necessita de redução de lentes negativas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa A. Resposta indicada no gabarito: hipocorrigido..' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Oftalmologia','A inversão do canal de Cloquet observado na biomicoscopia do vítreo é um dos sinais de','','','["glaucoma.", "uveíte.", "edema de papila.", "hialose asteroide."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa B. Resposta indicada no gabarito: uveíte..' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Oftalmologia','Cegueira legal corresponde a','','','["acuidade visual menor ou igual a 20/100 e campo visual menor que 120º.", "acuidade visual menor ou igual a 20/200 e campo visual menor que 20º.", "acuidade visual menor ou igual a 20/400 e campo visual menor que 90º.", "acuidade visual menor ou igual a 20/100 e campo visual menor que 90º."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa B. Resposta indicada no gabarito: acuidade visual menor ou igual a 20/200 e campo visual menor que 20º..' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Oftalmologia','O teste de oclusão de um olho do paciente com desvio vertical dissociado provoca nesse olho','','','["inciclodução, adução e elevação.", "inciclodução, abdução e elevação.", "elevação, exciclodução e abdução.", "abaixamento, exciclodução e abdução."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa C. Resposta indicada no gabarito: elevação, exciclodução e abdução..' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Oftalmologia','Na refração estática de um olho é + 3.00 esf. combinado com -5.00 cil. a 180º significa:','','','["hipermetropia de + 5.00 horizontal e miopia de −2.00 vertical.", "hipermetropia de + 3.00 vertical e miopia de −5.00 horizontal.", "hipermetropia de + 3.00 horizontal e miopia de −5.00 vertical.", "hipermetropia de + 3.00 horizontal e miopia de −2.00 vertical."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa D. Resposta indicada no gabarito: hipermetropia de + 3.00 horizontal e miopia de −2.00 vertical..' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Oftalmologia','As condições abaixo podem produzir defeitos campimétricos similares aos observados no glaucoma, EXCETO','','','["papiledema crônico.", "drusas do disco óptico.", "neuropatia óptica isquêmica anterior.", "infarto occipital."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa D. Resposta indicada no gabarito: infarto occipital.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Oftalmologia','Das condições abaixo, assinale a que não é classificada como Sindrome endotelial iridocorneana (ICE Syndrome).','','','["Síndrome de Chandler.", "Síndrome de Axenfeld-Rieger.", "Síndrome Nevus-iriano.", "Atrofia essencial da íris."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa B. Resposta indicada no gabarito: Síndrome de Axenfeld-Rieger.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Oftalmologia','Leia o enunciado e as alternativas da questão 50 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-oftalmologia-q50-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Oftalmologia: alternativa A. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-oftalmologia' on conflict(exam_id,number) do nothing;
