insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Odontologia Ortodontia','O uso de colimadores para a obtenção da radiografia cefalométrica justifica-se porque','','','["eles não restringem a área irradiada.", "eles aumentam a radiação secundária.", "eles diminuem a distorção da imagem.", "com eles ocorre menor perda de contraste (“velo”) da imagem."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: com eles ocorre menor perda de contraste (“velo”) da imagem..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Odontologia Ortodontia','Durante a tomada da radiografia cefalométrica de perfil ou em norma lateral,','','','["o feixe de raios X deve estar direcionado para a região mais inferior do osso zigomático, mantendo-se uma distância de 1,524m entre a fonte e o filme.", "o feixe de raios X deve estar direcionado para o centro dos posicionadores auriculares do cefalostato, mantendo-se uma distância de 1,524m entre a fonte e o plano médio sagital da cabeça.", "o feixe de raios X deve estar direcionado para a região mais inferior do osso zigomático, mantendo-se uma distância de 1,524m entre a fonte e o plano médio sagital da cabeça.", "o feixe de raios X deve estar direcionado para o centro dos posicionadores auriculares do cefalostato, mantendo-se uma distância de 1,524m entre a fonte e o filme."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: o feixe de raios X deve estar direcionado para o centro dos posicionadores auriculares do cefalostato, mantendo-se uma distância de 1,524m entre a fonte e o plano médio sagital da cabeça..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Odontologia Ortodontia','Leia o enunciado e as alternativas da questão 3 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-odontologia-ortodontia-q03-1-v3.png", "/pmerj-arquivo/pmerj-2010-odontologia-ortodontia-q03-2-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Odontologia Ortodontia','De acordo com Sassouni, em uma face proporcional,','','','["o arco anterior, a partir do ponto násio, deverá passar pelos pontos supramental e subespinhal.", "as faces superior e inferior possuem a mesma altura na região posterior.", "o arco anterior, a partir do ponto násio, deverá passar pelos pontos espinha nasal anterior e supramental.", "a face superior possui altura maior na região posterior."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: as faces superior e inferior possuem a mesma altura na região posterior..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Odontologia Ortodontia','Ricketts propôs uma simplificação de sua análise cefalométrica lateral, denominada análise sumária ou análise dos dez fatores. As seguintes medidas cefalométricas fazem parte da análise dos dez fatores:','','','["ângulo do eixo facial, convexidade maxilar, extrusão do incisivo inferior e protrusão labial.", "profundidade facial, altura facial inferior, convexidade maxilar e protrusão labial.", "ângulo do eixo facial, ângulo do plano mandibular, extrusão do incisivo inferior e posição do molar superior.", "ângulo do eixo facial, ângulo do plano mandibular, profundidade maxilar e posição do molar superior."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: profundidade facial, altura facial inferior, convexidade maxilar e protrusão labial..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Odontologia Ortodontia','Com relação à Análise de McNamara, é correto afirmar que','','','["a modificação do valor da altura facial ântero-inferior é capaz de alterar a aparência da relação entre a maxila e a mandíbula.", "nas más oclusões de Classe III, nas quais a base craniana anterior está encurtada, os valores da variável “relação da maxila com a base do crânio” indicarão um posicionamento equivocadamente posterior da maxila.", "o ângulo do eixo facial corresponde ao ângulo formado entre a linha SN e o eixo facial.", "na avaliação das vias aéreas, a largura da nasofaringe é medida desde a parede anterior do palato mole até a parede posterior da faringe."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: a modificação do valor da altura facial ântero-inferior é capaz de alterar a aparência da relação entre a maxila e a mandíbula..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Odontologia Ortodontia','Com relação à Análise de Downs, é correto afirmar que','','','["o ângulo do eixo Y é determinado pela interseção do eixo Y com o plano facial.", "o valor do ângulo de convexidade é negativo quando o ponto A está situado adiante do plano facial.", "na determinação da tipologia facial, quando existe prognatismo mandibular, determinado pelo ângulo facial, em associação com perfil côncavo, determinado pelo ângulo de convexidade, estamos diante do verdadeiro prognatismo.", "o ângulo do plano A-B é determinado pela interseção da linha A-B com o plano facial."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: o ângulo do plano A-B é determinado pela interseção da linha A-B com o plano facial..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Odontologia Ortodontia','Os seguintes pontos sagitais de referência podem ser identificados sobre a radiografia cefalométrica lateral:','','','["básio, násio, subespinhal, supramental e próstio.", "bolton, básio, cribriforme, subespinhal e supramental.", "básio, násio, subespinhal, supramental e cribriforme.", "bolton, básio, próstio, subespinhal e supramental."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: básio, násio, subespinhal, supramental e próstio..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Odontologia Ortodontia','A desvantagem de se utilizar o tecido mole como referência anterior para mensurar o espaço aéreo livre, como propôs McNamara, é','','','["a imagem radiopaca do palato mole pode ser facilmente confundida com imagem do dorso da língua.", "caso o paciente esteja deglutindo durante a tomada radiográfica, o palato mole tomará a forma de um “V” invertido, prejudicando a medição.", "é muito difícil localizar pontos cefalométricos sobre os tecidos moles, devido à superposição de imagens.", "as imagens dos tecidos moles são difusas e distorcidas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: caso o paciente esteja deglutindo durante a tomada radiográfica, o palato mole tomará a forma de um “V” invertido, prejudicando a medição..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Odontologia Ortodontia','Com relação à mensuração do espaço aéreo livre, deve-se utilizar.','','','["a variável ENP-ad2, pois esta obteve uma concordância estatisticamente perfeita quando confrontada com os resultados do exame endoscopia, adotado como padrão- -ouro para este tipo de avaliação.", "a variável ENP-So, pois esta obteve uma concordância estatisticamente perfeita quando confrontada com os resultados do exame endoscopia, adotado como padrão- -ouro para este tipo de avaliação.", "a variável ad2,-So, pois esta obteve uma concordância estatisticamente perfeita quando confrontada com os resultados do exame endoscopia, adotado como padrão- -ouro para este tipo de avaliação.", "a variável ENP-ad1, pois esta obteve uma concordância estatisticamente perfeita quando confrontada com os resultados do exame endoscopia, adotado como padrão- -ouro para este tipo de avaliação."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: a variável ENP-ad2, pois esta obteve uma concordância estatisticamente perfeita quando confrontada com os resultados do exame endoscopia, adotado como padrão- -ouro para este tipo de avaliação..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Odontologia Ortodontia','Com relação à Análise Frontal de Ricketts, assinale a assertiva correta.','','','["A largura nasal corresponde à distância entre os pontos Ag dos lados esquerdo e direito.", "De acordo com Ricketts, a largura nasal aumenta 0,8 mm por ano.", "A largura mandibular corresponde à distância que vai do ponto Ag do lado direito até o ponto Ag do lado esquerdo.", "De acordo com Ricketts, a largura mandibular aumenta 5 mm por ano."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: A largura mandibular corresponde à distância que vai do ponto Ag do lado direito até o ponto Ag do lado esquerdo..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Odontologia Ortodontia','O valor do ângulo GoGn.SN, da Análise de Steiner,','','','["expressa a relação ântero-posterior da mandíbula com a base do crânio.", "quando elevado, indica um bom padrão de crescimento mandibular.", "não pode ser utilizado como indicador do crescimento da área condilar.", "sofre a influência do grau de inclinação da linha SN."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: sofre a influência do grau de inclinação da linha SN..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Odontologia Ortodontia','O valor do ângulo ANB pode sofrer influência de diversos fatores. Entre eles estão:','','','["redução do comprimento da base craniana anterior, rotação dos ossos basais, altura vertical da face e crescimento.", "crescimento, redução do comprimento da base craniana anterior, rotação dos ossos basais e localização do ponto S.", "crescimento, redução do comprimento da base craniana anterior, rotação dos ossos basais e inclinação do plano mandibular.", "crescimento, rotação dos ossos basais, localização do ponto S e inclinação do plano mandibular."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: redução do comprimento da base craniana anterior, rotação dos ossos basais, altura vertical da face e crescimento..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Odontologia Ortodontia','Com relação à superposição de traçados cefalométricos, é INCORRETO afirmar que','','','["as técnicas que se baseiam nos contornos ósseos são mais confiáveis que aquelas que tomam como referência apenas dois pontos.", "a superposição na linha S-N com registro em S foi descrita por Broadbent, em 1931, que recomendou seu uso apenas nos casos em que não houvesse aumento do comprimento da linha S-N.", "a superposição na linha S-N com registro em N não deve ser utilizada nos pacientes que ainda apresentam crescimento.", "algumas técnicas que apresentam um grau satisfatório de precisão não são utilizadas rotineiramente devido à dificuldade de execução."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: a superposição na linha S-N com registro em N não deve ser utilizada nos pacientes que ainda apresentam crescimento..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Odontologia Ortodontia','Com relação à superposição de traçados cefalométricos, assinale a resposta correta.','','','["O ponto Ptm foi utilizado como registro para a superposição total da maxila por Bjork, em 1955.", "A superposição da maxila sobre seu próprio contorno ósseo apresenta apenas ponto de registro horizontal.", "A superposição da mandíbula sobre Ar é realizada através da superposição no contorno do osso esfenoide e da placa cribriforme do osso etmoide, utilizando como registro o ponto médio entre as grandes asas esfenoidais.", "A superposição da maxila sobre seu próprio contorno ósseo apresenta apenas ponto de registro vertical."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: A superposição da mandíbula sobre Ar é realizada através da superposição no contorno do osso esfenoide e da placa cribriforme do osso etmoide, utilizando como registro o ponto médio entre as grandes asas esfenoidais..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Odontologia Ortodontia','Pode-se definir o ponto Id como','','','["o ponto mais anterior do processo alveolar da maxila, geralmente situado entre os incisivos centrais, na extremidade do septo interalveolar.", "o ponto mais anterior da mandíbula, localizado entre o ponto B e o pogônio.", "o ponto situado no centro do contorno da seção transversal da sínfise mandibular.", "o ponto mais anterior do processo alveolar da mandíbula, geralmente situado entre os incisivos centrais, na extremidade do septo interalveolar."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: o ponto mais anterior do processo alveolar da mandíbula, geralmente situado entre os incisivos centrais, na extremidade do septo interalveolar..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Odontologia Ortodontia','Considerando-se uma radiografia póstero- -anterior, o ponto mediano situado no centro do bordo externo da apófise zigomática é denominado','','','["ponto Z.", "ponto Za.", "ponto J.", "ponto NC."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: ponto Za..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Odontologia Ortodontia','A medida linear AO-BO, da Análise de “Wits”,','','','["apresenta o valor de 0 mm para os homens e −1 mm para as mulheres.", "analisa o relacionamento entre a maxila e a mandíbula através do plano oclusal.", "é utilizada para diferenciar um problema causado por uma discrepância esquelética de outro, de origem dentária.", "é capaz de determinar o grau de dificuldade do tratamento."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: analisa o relacionamento entre a maxila e a mandíbula através do plano oclusal..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Odontologia Ortodontia','As linhas e planos utilizados na Análise Vertical preconizada por Wylie são:','','','["plano horizontal de Frankfurt, linha N-Me, linha Go-Me e linha Go-Cd.", "plano horizontal de Frankfurt, plano mandibular, linha N-Me e linha Ba-N.", "plano horizontal de Frankfurt, linha Ba-N, linha Go-Me e plano mandibular.", "plano horizontal de Frankfurt, linha N-Me, linha Ba-N e linha Go-Cd."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: plano horizontal de Frankfurt, linha N-Me, linha Go-Me e linha Go-Cd..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Odontologia Ortodontia','Com relação à Análise de Diagnóstico Diferencial, assinale a assertiva correta.','','','["O ângulo Z é formado pela interseção da linha tangente ao Pog e ao ponto mais anterior do lábio mais proeminente com o plano horizontal de Frankfurt.", "A altura facial anterior corresponde à distância medida perpendicularmente desde o ponto násio até o ponto mento.", "A espessura do lábio superior corresponde à distância linear medida desde a linha N- A até a borda do vermelhão do lábio superior.", "A altura facial posterior deve corresponder a 69% da altura facial anterior."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: A altura facial posterior deve corresponder a 69% da altura facial anterior..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Odontologia Ortodontia','Enquanto ocorre a ossificação da base do crânio, importantes áreas de crescimento, denominadas sincondroses, permanecem entre os centros de ossificação. Essas sincondroses são','','','["sincondrose esfeno-occipital, sincondrose interesfenoidal e sincondrose esfenoetmoi- dal.", "sincondrose esfeno-occipital, sincondrose esfenoidal e sincondrose esfenoetmoidal.", "sincondrose esfeno-occipital, sincondrose esfenoidal e sincondrose bregmática.", "sincondrose esfeno-occipital, sincondrose bregmática e sincondrose esfenoetmoidal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: sincondrose esfeno-occipital, sincondrose interesfenoidal e sincondrose esfenoetmoi- dal..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Odontologia Ortodontia','De acordo com Proffit, o espaço livre de Nance mede, em média:','','','["No arco superior 1,8 mm e no arco inferior 3,4 mm.", "No arco superior 0,9 mm e no arco inferior 1,7 mm.", "No arco superior 1,5 mm e no arco inferior 5,0 mm.", "No arco superior 1,7 mm e no arco inferior 3,4 mm."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: No arco superior 1,5 mm e no arco inferior 5,0 mm..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Odontologia Ortodontia','Com relação ao crescimento do complexo craniofacial, é correto afirmar que','','','["o crescimento do osso nasal estará completo aproximadamente aos 16 anos de idade.", "a região do mento mandibular é uma área de crescimento muito ativa.", "a mandíbula cresce em comprimento por aposição de novo osso na superfície anterior do ramo.", "o crescimento do osso nasal estará completo aproximadamente aos 10 anos de idade."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: o crescimento do osso nasal estará completo aproximadamente aos 10 anos de idade..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Odontologia Ortodontia','A relação normal dos molares decíduos é o plano terminal reto. Nesse caso, a relação de chave de oclusão, considerada normal na dentição permanente, pode ser alcançada','','','["pelo crescimento diferencial da mandíbula em relação à maxila.", "pelo maior deslocamento mesial dos mola- res inferiores para o espaço livre de Nance, em comparação com os molares superiores.", "pelo crescimento diferencial da mandíbula em relação à maxila e pelo maior deslocamento mesial dos molares inferiores para o espaço livre de Nance, em comparação com os molares superiores.", "pelo maior deslocamento mesial dos molares superiores para o espaço livre de Nance, em comparação com os molares inferiores."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: pelo crescimento diferencial da mandíbula em relação à maxila e pelo maior deslocamento mesial dos molares inferiores para o espaço livre de Nance, em comparação com os molares superiores..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Odontologia Ortodontia','Durante o estágio tardio de desenvolvimento existe uma sequência definida para o crescimento nos três planos do espaço dos ossos maxilares. Essa sequência é:','','','["comprimento, largura e altura.", "largura, comprimento e altura.", "comprimento, altura e largura.", "altura, comprimento e largura."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: largura, comprimento e altura..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Odontologia Ortodontia','A largura aparente dos dentes ântero-superiores no sorriso e suas reais larguras mesiodistais diferem por causa da curvatura do arco dentário. Para a melhor estética, deve haver uma razão entre a largura do incisivo central em relação à do lateral e desta em relação à largura do canino. Essa razão, muitas vezes chamada de “proporção áurea”, deve ser de','','','["62%.", "58%.", "60%.", "64%."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: 62%..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Odontologia Ortodontia','Em relação à interposição lingual, é correto afirmar que','','','["indivíduos que colocam a ponta da língua para frente quando deglutem não fazem mais força lingual contra os dentes do que aqueles que mantêm a ponta da língua atrás dos dentes ao deglutirem.", "é o hábito oral deletério mais comum nos dois primeiros anos de vida.", "é uma adaptação patológica útil nos casos de mordida aberta.", "é hábito oral deletério que deve ser tratado após o início do surto de crescimento puberal."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: indivíduos que colocam a ponta da língua para frente quando deglutem não fazem mais força lingual contra os dentes do que aqueles que mantêm a ponta da língua atrás dos dentes ao deglutirem..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Odontologia Ortodontia','Um padrão respiratório alterado NÃO é capaz de causar','','','["supererupção dos dentes posteriores.", "inclinação da cabeça para frente.", "estreitamento do arco dentário superior.", "inclinação da cabeça para trás."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: inclinação da cabeça para frente.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Odontologia Ortodontia','Em relação à obstrução nasal, marque a resposta correta.','','','["Obstruções nasais totais são comuns em seres humanos.", "Macacos em crescimento com obstruções nasais totais desenvolvem más oclusões idênticas àquelas comumente associadas à respiração bucal em humanos.", "A mucosa nasal sofre ciclos de aumento e diminuição do fluxo sanguíneo. Os ciclos se alternam entre as duas narinas: quando uma está livre, a outra está obstruída.", "A obstrução nasal total não é capaz de causar má oclusão."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: A mucosa nasal sofre ciclos de aumento e diminuição do fluxo sanguíneo. Os ciclos se alternam entre as duas narinas: quando uma está livre, a outra está obstruída..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Odontologia Ortodontia','Substâncias químicas e outros agentes capazes de produzir defeitos embrionários, administrados em momento crítico, são chamados de teratógenos. Assinale a opção que contém apenas os teratógenos capazes de produzir distúrbios ortodônticos.','','','["Vírus da rubéola, Talidomida, Dilantin e vírus da malária.", "Vírus da hepatite, Diazepan, Dilantin e Talidomida.", "Aspirina, Diazepan, Dilantin e Aminopterina.", "Vírus da rubéola, Talidomida, Dilantin e Vitorin."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: Aspirina, Diazepan, Dilantin e Aminopterina..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Odontologia Ortodontia','Assinale a alternativa correta, em relação ao tratamento dos casos com excesso mandibular.','','','["Quando se aplica uma força extrabucal contra o mento, é difícil evitar que os incisivos inferiores se inclinem para lingual.", "Na terapia com mentoneira, quando a linha de aplicação de força passa abaixo do côndilo, o mento é girado no sentido anti- horário.", "Na terapia com mentoneira, quando a linha de aplicação de força está direcionada diretamente através do côndilo mandibular, o mento é girado para baixo e para trás.", "Aparelhos funcionais para o tratamento de prognatismo mandibular giram a mandíbula no sentido anti-horário."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: Quando se aplica uma força extrabucal contra o mento, é difícil evitar que os incisivos inferiores se inclinem para lingual..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Odontologia Ortodontia','Com relação ao material utilizado na confecção dos braquetes ortodônticos, é correto afirmar que','','','["recentemente o aço inoxidável deixou de ser o material padrão para a confecção de braquetes ortodônticos.", "uma das alternativas aos braquetes de aço inoxidável são os braquetes de titânio, que contem níquel em sua liga, sendo excepcionalmente biocompatíveis.", "um dos grandes problemas dos braquetes plásticos é a fricção com o fio, o que dificulta o deslizamento do dente para uma nova posição.", "um dos problemas dos braquetes cerâmicos é a possibilidade de causar danos ao esmalte quando removido. É recomendável produzir uma tensão de torção ao invés de induzir uma quebra assimétrica durante sua remoção."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: um dos grandes problemas dos braquetes plásticos é a fricção com o fio, o que dificulta o deslizamento do dente para uma nova posição..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Odontologia Ortodontia','Quando um aparelho extrabucal é aplicado na maxila em um indivíduo pré-adolescente, ocorre','','','["diminuição da quantidade de movimento anterior e/ou inferior da maxila pela mudança no padrão de aposição de osso nas suturas, mas o aparelho deve ser usado por, no mínimo, 10 a 12 horas por dia.", "diminuição da quantidade de movimento posterior e/ou superior da maxila pela mudança no padrão de aposição de osso nas suturas, mas o aparelho deve ser usado por, no mínimo, 10 a 12 horas por dia.", "diminuição da quantidade de movimento anterior e/ou inferior da maxila pela mudança no padrão de aposição de osso nas suturas, mas o aparelho deve ser usado por, no mínimo, 16 a 18 horas por dia.", "diminuição da quantidade de movimento posterior e/ou superior da maxila pela mudança no padrão de aposição de osso nas suturas, mas o aparelho deve ser usado por, no mínimo, 16 a 18 horas por dia."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: diminuição da quantidade de movimento anterior e/ou inferior da maxila pela mudança no padrão de aposição de osso nas suturas, mas o aparelho deve ser usado por, no mínimo, 10 a 12 horas por dia..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Odontologia Ortodontia','Em relação ao planejamento ortodôntico que inclui extrações dentárias, é correto afirmar que','','','["com a extração, a desvantagem é a perda do dente ou dentes; a vantagem é a provável maior estabilidade do resultado, e pode haver efeitos negativos sobre a estética facial.", "com a extração, a desvantagem é a perda do dente ou dentes; a vantagem é a provável maior estabilidade do resultado, e pode haver efeitos negativos ou positivos sobre a estética facial.", "com a extração, a desvantagem é a perda do dente ou dentes; a vantagem é a provável maior estabilidade do resultado, e pode haver efeitos positivos sobre a estética facial.", "quem deve decidir sobre a necessidade de extrações é o ortodontista, não se devendo discutir os prós e os contras com o paciente e com os pais."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: com a extração, a desvantagem é a perda do dente ou dentes; a vantagem é a provável maior estabilidade do resultado, e pode haver efeitos negativos ou positivos sobre a estética facial..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Odontologia Ortodontia','Nos pacientes com pouco ou nenhum crescimento, o plano de tratamento só NÃO pode incluir','','','["o deslocamento dos dentes sobre o osso de suporte, para compensar a discrepância maxilomandibular nos problemas esqueléticos de Classe II.", "o reposicionamento cirúrgico da maxila e/ou da mandíbula.", "extrações dentárias para obter relações molares e dos incisivos corretas apesar da relação maxilomandibular.", "o deslocamento dos dentes sobre o osso de suporte, para compensar a discrepância maxilomandibular nos problemas esqueléticos de Classe III."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: o deslocamento dos dentes sobre o osso de suporte, para compensar a discrepância maxilomandibular nos problemas esqueléticos de Classe III..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Odontologia Ortodontia','Em relação ao controle da força ortodôntica, pode-se afirmar que','','','["como regra geral, as melhores molas digitais para aparelhos removíveis são feitas com fio de beta titânio.", "uma maneira de se obter uma melhor combinação de resiliência e resistência é juntar dois ou mais segmentos de fio de menor diâmetro.", "o TMA, como intermediário entre o NiTi e o aço, é mais útil do que qualquer um dos dois nos primeiros estágios do tratamento com aparelhos ortodônticos fixos completos.", "confeccionar alças num fio de aço diminui a sua resiliência."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: uma maneira de se obter uma melhor combinação de resiliência e resistência é juntar dois ou mais segmentos de fio de menor diâmetro..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Odontologia Ortodontia','Em relação à utilização de magnetos para se obter força ortodôntica, pode-se afirmar que','','','["efeitos citotóxicos diretos são observados quando magnetos lacrados são colocados intra-oralmente.", "a força produzida pelos magnetos segue a lei do inverso do quadrado, ou seja, a força muda com o quadrado da distância entre os magnetos.", "existem muitas dúvidas de que os magnetos podem ser clinicamente eficientes.", "a força produzida pelos magnetos segue a lei da raiz quadrada, ou seja, a força muda com a raiz quadrada da distância entre os magnetos."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: a força produzida pelos magnetos segue a lei do inverso do quadrado, ou seja, a força muda com o quadrado da distância entre os magnetos..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Odontologia Ortodontia','Em relação à mecânica ortodôntica, assinale a opção correta.','','','["Um binário de força pode ser definido como duas forças de igual magnitude e direção.", "O centro de rotação de qualquer dente está situado aproximadamente no ponto médio da porção da raiz implantada no osso.", "O momento é definido como o produto da força vezes a distância perpendicular desde o ponto de aplicação da força ao centro de resistência.", "Um binário irá produzir rotação pura, girando o objeto ao redor do seu centro de rotação."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: O momento é definido como o produto da força vezes a distância perpendicular desde o ponto de aplicação da força ao centro de resistência..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Odontologia Ortodontia','Assinale a opção INCORRETA com relação aos aparelhos ortodônticos.','','','["Os aparelhos fixos contemporâneos são predominantemente variações do sistema de aparelhos edgewise.", "Os aparelhos removíveis permitem que alguns tipos de tratamento com orientação do crescimento sejam realizados mais cedo do que seria possível com aparelhos fixos.", "O grampo mais usual e versátil para aparelhos removíveis é o grampo de Adams.", "O aparelho de Begg caiu em desuso por não permitir um bom controle de coroa e raiz nos três planos do espaço."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: O aparelho de Begg caiu em desuso por não permitir um bom controle de coroa e raiz nos três planos do espaço.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Odontologia Ortodontia','É correto afirmar que','','','["os tecidos gengivais e periodontais não são afetados pela movimentação ortodôntica dos dentes e necessitam de tempo para reorganização, quando os aparelhos são removidos.", "as correções dos problemas de Classe II são altamente instáveis.", "as alterações provocadas pelo crescimento não interferem no resultado do tratamento ortodôntico.", "os dentes podem estar numa posição inerentemente instável após o tratamento ortodôntico, de tal forma que as pressões dos tecidos moles produzam uma tendência à recidiva."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: os dentes podem estar numa posição inerentemente instável após o tratamento ortodôntico, de tal forma que as pressões dos tecidos moles produzam uma tendência à recidiva..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Odontologia Ortodontia','Assinale a alternativa INCORRETA em relação à contenção ortodôntica.','','','["A capacidade da contenção de Hawley fornecer alguma movimentação dentária é vantajosa nos casos de extração de pré- -molares.", "A contenção deve ser mantida de forma parcial por pelo menos 12 meses para permitir tempo para o remodelamento dos tecidos gengivais.", "A contenção removível mais comum é a contenção de Hawley.", "Os contensores ortodônticos fixos são normalmente usados em situações nas quais a instabilidade intra-arco é prevista e uma contenção prolongada é planejada."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: A capacidade da contenção de Hawley fornecer alguma movimentação dentária é vantajosa nos casos de extração de pré- -molares.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Odontologia Ortodontia','Dor e disfunção temporomandibular (sintomas da DTM) raramente são encontradas em crianças que procuram tratamento ortodôntico, mas a DTM é um fator motivador significativo para adultos que procuram por tratamento ortodôntico. Em respeito a esse tópico, é correto afirmar que','','','["discrepâncias oclusais em qualquer grau irão levar a sintomas de DTM.", "o clique e os sintomas associados dificilmente serão corrigidos apenas com a instalação de uma placa oclusal.", "para produzir dor miofascial, o paciente deve estar fazendo apertamento ou rangendo os dentes por muitas horas por dia.", "o clique e os sintomas associados dificilmente serão corrigidos apenas pelo tratamento ortodôntico."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: para produzir dor miofascial, o paciente deve estar fazendo apertamento ou rangendo os dentes por muitas horas por dia..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Odontologia Ortodontia','Assinale a opção que contém as principais aplicações da ancoragem esquelética em pacientes adultos.','','','["Extrusão de dentes anteriores para fechamento de mordida aberta, movimento distal dos molares superiores e retração e intrusão de incisivos superiores.", "Movimento distal dos molares superiores, retração e intrusão de incisivos superiores e posicionamento individual de dentes quando nenhuma outra ancoragem estiver disponível.", "Intrusão de dentes posteriores para fechamento de mordida aberta anterior, movimento distal dos molares superiores e extrusão de incisivos superiores.", "Intrusão de dentes posteriores para fechamento de mordida aberta anterior, movimento mesial dos molares superiores e retração e intrusão de incisivos superiores."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: Movimento distal dos molares superiores, retração e intrusão de incisivos superiores e posicionamento individual de dentes quando nenhuma outra ancoragem estiver disponível..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Odontologia Ortodontia','Em relação ao tratamento ortocirúrgico, assinale a opção correta.','','','["Previsões através de imagens computadori- zadas não devem ser mostradas aos pacientes, pois poderiam criar expectativas irreais e levar a desapontamentos com o resultado verda-deiro.", "O tratamento cirúrgico e ortodôntico combinado pode ser planejado para pacientes com problemas dentofaciais severos somente em algumas situações.", "Qualquer que seja a idade do paciente não é preciso esperar um período de ajuste psicológico seguinte à cirurgia facial.", "Algumas condições que poderiam ser tratadas somente com ortodontia em crianças tornam-se problemas cirúrgicos em adultos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: Algumas condições que poderiam ser tratadas somente com ortodontia em crianças tornam-se problemas cirúrgicos em adultos..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Odontologia Ortodontia','Em relação ao tratamento ortocirúrgico, assinale a opção correta.','','','["A fase pré-cirúrgica não dever requerer mais de um ano, exceto para os pacientes que ainda não completaram o crescimento.", "Durante a fase pré-cirúrgica, não é particularmente importante planejar o nivelamento dos arcos dentários.", "A fase pós-cirúrgica pode ser iniciada assim que o edema decorrente da cirurgia tenha sido reabsorvido.", "A fase pós-cirúrgica pode ser iniciada seis meses após o ato cirúrgico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: A fase pré-cirúrgica não dever requerer mais de um ano, exceto para os pacientes que ainda não completaram o crescimento..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Odontologia Ortodontia','São indicações para o uso de bandas em vez de acessórios colados:','','','["Dentes que irão receber forças pesadas e intermitentes contra seus acessórios e dentes que necessitam ser restaurados.", "Dentes que necessitarão tanto de acessórios vestibulares como linguais e dentes que necessitam ser restaurados.", "Dentes com coroas clínicas pequenas e dentes que necessitam ser restaurados.", "Dentes que necessitarão tanto de acessórios vestibulares como linguais e dentes com coroas clínicas pequenas."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: Dentes que necessitarão tanto de acessórios vestibulares como linguais e dentes com coroas clínicas pequenas..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Odontologia Ortodontia','A terapia com alinhadores transparentes (TAT), como o Invisalign, é indicada nas seguintes situações:','','','["apinhamento médio a moderado com desgaste interproximal do esmalte ou expansão, fechamento de espaços resultantes de extrações dentárias e expansão dentária posterior.", "verticalização de molares, apinhamento médio a moderado com desgaste interproximal do esmalte ou expansão e expansão dentária posterior;", "extração de um incisivo inferior em apinhamento severo, fechamento de espaços médio a moderado e expansão dentária posterior.", "apinhamento médio a moderado com desgaste interproximal do esmalte ou expansão, verticalização de molares e expansão dentária posterior."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa C. Resposta indicada no gabarito: extração de um incisivo inferior em apinhamento severo, fechamento de espaços médio a moderado e expansão dentária posterior..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Odontologia Ortodontia','Em relação ao plano de tratamento ortodôntico dos pacientes que possuem dentes anquilosados, é correto afirmar que','','','["quando os dentes decíduos anquilosados não possuem sucessor permanente devem ser deixados no arco para manter o espaço.", "quando os dentes decíduos anquilosados não possuem sucessor permanente devem ser extraídos antes que grandes discrepâncias verticais se desenvolvam.", "quando os dentes decíduos anquilosados possuem sucessor permanente devem ser deixados no arco para manter o espaço.", "quando os dentes decíduos anquilosados não possuem sucessor permanente devem ser extraídos, assim como seus antagonistas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa B. Resposta indicada no gabarito: quando os dentes decíduos anquilosados não possuem sucessor permanente devem ser extraídos antes que grandes discrepâncias verticais se desenvolvam..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Odontologia Ortodontia','O paciente ideal para o tratamento do crescimento mandibular excessivo com mentoneira tem','','','["um problema esquelético severo, com a capacidade de trazer os incisivos de topo a topo ou quase isso.", "altura vertical de face aumentada.", "dentes posteriores com coroas clínicas grandes.", "incisivos inferiores posicionados normal- mente ou protruídos, mas não retruídos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa D. Resposta indicada no gabarito: incisivos inferiores posicionados normal- mente ou protruídos, mas não retruídos..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Odontologia Ortodontia','Os contensores ortodônticos fixos são normalmente utilizados nas seguintes situações:','','','["manutenção da posição dos incisivos inferiores durante o final do crescimento, manutenção do fechamento de diastema e manutenção do espaço de um pôntico ou implante.", "manutenção da posição dos incisivos superiores durante o final do crescimento, manutenção do fechamento de diastema e manutenção do fechamento dos espaços de extrações.", "manutenção da posição dos incisivos superiores durante o final do crescimento, manutenção do fechamento de diastema e manutenção do espaço de um pôntico ou implante.", "manutenção da posição dos incisivos inferiores durante o final do crescimento, manutenção da posição dos incisivos superiores durante o final do crescimento e manutenção do fechamento dos espaços de extrações."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Odontologia Ortodontia: alternativa A. Resposta indicada no gabarito: manutenção da posição dos incisivos inferiores durante o final do crescimento, manutenção do fechamento de diastema e manutenção do espaço de um pôntico ou implante..' from public.exams where slug='pmerj-2010-odontologia-ortodontia' on conflict(exam_id,number) do nothing;
