insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Ortopedia','Na doença de PAGET, a malignização ocorre, mais frequentemente, para a forma','','','["monostótica do osteossarcoma.", "poliostótica do osteossarcoma.", "monostótica do condrossarcoma.", "poliostótica do condrossarcoma."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Ortopedia: alternativa B. Resposta indicada no gabarito: poliostótica do osteossarcoma..' from public.exams where slug='pmerj-2010-medico-ortopedia' on conflict(exam_id,number) do nothing;
