insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Ortopedia','Leia o enunciado e as alternativas da questão 5 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-ortopedia-q05-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Ortopedia: alternativa C. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-ortopedia' on conflict(exam_id,number) do nothing;
