insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Ortopedia','Na síndrome de EHLERS-DANLOS, são achados clínicos característicos:','','','["a hipermobilidade articular, a hiperelas- ticidade cutânea e hemorragias subcutâneas.", "a hipermobilidade articular, hemorragias subcutâneas e áreas hipocrômicas na pele.", "a hipermobilidade articular, a hiperelas- ticidade cutânea e áreas hipocrômicas na pele.", "a hiperelasticidade cutânea, hemorragias subcutâneas e áreas hipocrômicas na pele."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Ortopedia: alternativa A. Resposta indicada no gabarito: a hipermobilidade articular, a hiperelas- ticidade cutânea e hemorragias subcutâneas..' from public.exams where slug='pmerj-2010-medico-ortopedia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Ortopedia','Na apófise coracoide estão inseridos','','','["o subescapular e o omo-hioide.", "o peitoral menor e o córaco braquial.", "a cabeça longa do bíceps e o romboide.", "a cabeça curta do bíceps e o redondo menor."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Ortopedia: alternativa B. Resposta indicada no gabarito: o peitoral menor e o córaco braquial..' from public.exams where slug='pmerj-2010-medico-ortopedia' on conflict(exam_id,number) do nothing;
