insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Ortopedia','A forma e a força tênsil da cartilagem articular são garantidas por','','','["colágeno tipo I.", "colágeno tipo II.", "proteínas não colágenas.", "proteoglicanos."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Ortopedia: alternativa B. Resposta indicada no gabarito: colágeno tipo II..' from public.exams where slug='pmerj-2010-medico-ortopedia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Ortopedia','O portador de claudicação neurogênica, quando tem dor, necessita','','','["deitar.", "sentar.", "parar de andar.", "hiperestender a coluna."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Ortopedia: alternativa B. Resposta indicada no gabarito: sentar..' from public.exams where slug='pmerj-2010-medico-ortopedia' on conflict(exam_id,number) do nothing;
