insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Otorrinolaringologia','As bactérias mais comumente isoladas nos seios maxilares de pacientes adultos imunocompetentes com rinossinusite aguda são','','','["streptococos pneumoniae e staphylococos aureus.", "haemophilus influenza e moraxella catarrhalis.", "haemophilus influenza e streptococos pneumoniae.", "streptococos pneumoniae e moraxella catarrhalis."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa C. Resposta indicada no gabarito: haemophilus influenza e streptococos pneumoniae..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Otorrinolaringologia','Assinale a única opção em que TODOS os medicamentos indicados apresentam possibilidades terapêuticas em casos de rinossinusite crônica.','','','["Descongestionantes tópicos nasais, mometasona e cefalosporinas.", "Descongestionantes orais, solução isotônica tópica nasal e quinolonas.", "Clindamicina, descongestionantes orais e solução hipertônica tópica nasal.", "Itraconazol, prednisona e amoxicilina com ácido clavulânico."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa D. Resposta indicada no gabarito: Itraconazol, prednisona e amoxicilina com ácido clavulânico..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
