insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Otorrinolaringologia','Em relação às rinites não alérgicas, assinale o item que apresenta apenas exemplos de rinites bastante sensíveis ao uso de agentes anticolinérgicos.','','','["Rinite ocupacional e rinite idiopática.", "Rinite gustativa e rinite do idoso.", "Rinite do esporte e rinite medicamentosa.", "Rinite por fármacos e rinite eosinofílica não alérgica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa B. Resposta indicada no gabarito: Rinite gustativa e rinite do idoso..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Otorrinolaringologia','Assinale a única opção que pode ser causa de rinossinusite crônica localizada.','','','["Alergia.", "Processos odontogênicos.", "Discinesia ciliar primária.", "Imunodeficiências."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa B. Resposta indicada no gabarito: Processos odontogênicos..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Otorrinolaringologia','O padrão histológico mais comum dos pólipos na polipose nasossinusal é o de','','','["pólipo edematoso eosinofílico.", "pólipo fibroinflamatório.", "pólipo com pronunciada hiperplasia de glândulas seromucosas.", "pólipo com estroma atípico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa A. Resposta indicada no gabarito: pólipo edematoso eosinofílico..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Otorrinolaringologia','Leia o enunciado e as alternativas da questão 8 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-medico-otorrinolaringologia-q08-1-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa D. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Otorrinolaringologia','Em relação ao papiloma escamoso benigno nasal, assinale a única opção correta.','','','["Sua terapêutica é essencialmente cirúrgica com radioterapia associada.", "Tem grande tendência a recidiva.", "Apresenta grande tendência a malignização.", "Está geralmente associado ao papilomavírus humano."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa D. Resposta indicada no gabarito: Está geralmente associado ao papilomavírus humano..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Otorrinolaringologia','Na rinoscopia anterior de uma criança com tumoração ocupando parcial ou totalmente uma fossa nasal, qual sinal é positivo para meningoencefalocele?','','','["Sinal de Nikolsky.", "Sinal de Hutchison.", "Sinal de Furstenberg.", "Sinal de Arndt."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa C. Resposta indicada no gabarito: Sinal de Furstenberg..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Otorrinolaringologia','Em relação ao líquen plano oral, NÃO é correto afirmar que','','','["OMS o classifica em sete formas: reticular, papular, tipo placas, atrófico, erosivo, ulcerativo e bolhoso.", "clinicamente o local mais comum é a mucosa bucal, na qual as lesões são bilaterais.", "o uso da imunofluorescência direta não confirma o diagnóstico clínico.", "existem dificuldades no diagnóstico diferencial com as reações liquenoides."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa C. Resposta indicada no gabarito: o uso da imunofluorescência direta não confirma o diagnóstico clínico.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Otorrinolaringologia','Assinale o único exame complementar que NÃO deve ser realizado em quadros agudos de sialoadenite bacteriana.','','','["Sialografia.", "Tomografia computadorizada.", "Ressonância nuclear magnética.", "Ultrassonografia."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa A. Resposta indicada no gabarito: Sialografia..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Otorrinolaringologia','Qual é a mais comum das complicações orais ocasionadas pela infecção pelo HIV?','','','["Estomatite aftosa.", "Candidíase.", "Leucoplasia pilosa.", "Sarcoma de Kaposi."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa B. Resposta indicada no gabarito: Candidíase..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Otorrinolaringologia','Em relação às lesões aftosas recorrentes da mucosa oral, é correto afirmar que','','','["a Doença de Behçet e a neutropenia cíclica são as causas identificáveis mais frequentes.", "no HIV positivo a lesão mais frequentemente encontrada é a afta herpetiforme.", "hereditariedade não é um fator predispo- nente.", "lesões aftosas não são decorrentes da hipersensibilidade celular."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa A. Resposta indicada no gabarito: a Doença de Behçet e a neutropenia cíclica são as causas identificáveis mais frequentes..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Otorrinolaringologia','Assinale o item que NÃO pode ser considerado como grupo de risco para uma criança apresentar quadro persistente de insuficiência velofaríngea após adenoamigdalectomia.','','','["Anomalias orofaciais.", "Fenda palatina submucosa.", "Desordens neuromusculares.", "Doenças autoimunes."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa D. Resposta indicada no gabarito: Doenças autoimunes..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Otorrinolaringologia','A causa mais comum da síndrome da apneia e da hipopneia obstrutivas do sono em crianças é a','','','["doença do refluxo gastroesofágico.", "hipertrofia adenoamigdaliana.", "obesidade.", "obstrução nasal crônica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa B. Resposta indicada no gabarito: hipertrofia adenoamigdaliana..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Otorrinolaringologia','Dentre os critérios polissonográficos pediátricos abaixo, assinale o único item que NÃO faz parte dos parâmetros de normalidade.','','','["Índice de apneia e hipopneia menor que um evento respiratório por hora.", "Saturação de oxiemoglobina maior que 90%.", "Gás carbônico ao final da expiração menor que 5% do tempo total de sono.", "Ausência de inspiração paradoxal."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa C. Resposta indicada no gabarito: Gás carbônico ao final da expiração menor que 5% do tempo total de sono..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Otorrinolaringologia','Compreende-se por apneia obstrutiva do sono a ocorrência de','','','["cessação do fluxo aéreo por, pelo menos, 15 segundos na presença de esforço respiratório.", "cessação do fluxo aéreo por, pelo menos, 10 segundos na presença de esforço respiratório.", "cessação do fluxo aéreo por, pelo menos, 15 segundos na ausência de esforço respiratório.", "cessação do fluxo aéreo por, pelo menos, 10 segundos na ausência de esforço respiratório."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa B. Resposta indicada no gabarito: cessação do fluxo aéreo por, pelo menos, 10 segundos na presença de esforço respiratório..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Otorrinolaringologia','Assinale o único item que representa, ao mesmo tempo, um fator predisponente e um fator associado à síndrome da apneia e da hipopneia obstrutivas do sono em adultos.','','','["Refluxo gastroesofágico.", "Anormalidades craniofaciais.", "Hipertensão arterial sistêmica.", "Obesidade."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa D. Resposta indicada no gabarito: Obesidade..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Otorrinolaringologia','Um paciente adulto apresenta IAH (índice de apneia/hipopneia) de 48 eventos por hora em seu exame polissonográfico. Assinale o único item que pode ser considerado uma possível indicação terapêutica nesse paciente.','','','["Avanço maxilo-mandibular.", "Redução volumétrica dos tecidos por radiofrequência.", "Aparelho intraoral.", "Uvulopalatofaringoplastia convencional."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa A. Resposta indicada no gabarito: Avanço maxilo-mandibular..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
