insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Otorrinolaringologia','Assinale a única alternativa que NÃO apresenta um exemplo de patologia que cursa com macroglossia adquirida.','','','["Amiloidose primária.", "Mixedema.", "Sarcoidose.", "Síndrome de Down."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa D. Resposta indicada no gabarito: Síndrome de Down..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
