insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Otorrinolaringologia','São procedimentos para compensar a paralisia unilateral de prega vocal, com EXCEÇÃO da','','','["injeção de gordura.", "tiroplastia tipo I.", "rotação de aritenoide.", "aritenopexia."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa D. Resposta indicada no gabarito: aritenopexia..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Otorrinolaringologia','São procedimentos para elevar o pitch vocal, com EXCEÇÃO da(o)','','','["aproximação cricotireoidea.", "alongamento da lâmina anterior.", "avanço da comissura anterior.", "tiroplastia tipo II."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa D. Resposta indicada no gabarito: tiroplastia tipo II..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Otorrinolaringologia','Os esvaziamentos cervicais','','','["são de 4 tipos: radical, radical modificado, radical ampliado e seletivos.", "visam basicamente a ressecar vasos e nervos comprometidos por metástases.", "preservam ao máximo o plexo linfático regional.", "incluem a ressecção do nervo espinhal e do hipoglosso."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Otorrinolaringologia: alternativa A. Resposta indicada no gabarito: são de 4 tipos: radical, radical modificado, radical ampliado e seletivos..' from public.exams where slug='pmerj-2010-medico-otorrinolaringologia' on conflict(exam_id,number) do nothing;
