insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Patologia Clínica','Em relação ao número de neutrófilos é INCORRETO afirmar:','','','["Os estados inflamatórios graves diminuem o tempo de vida do neutrófilo e por isso causam neutropenia.", "Em negros pode haver uma neutrofilia fisiológica.", "As síndromes de Kostmann e Shwachman são causas de agranulocitose genética infantil.", "Em pacientes portadores de anormalidades neutrofílicas qualitativas as doenças causadas por microorganismos como serratia, mycobactéria e candida são mais graves."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Patologia Clínica: alternativa B. Resposta indicada no gabarito: Em negros pode haver uma neutrofilia fisiológica..' from public.exams where slug='pmerj-2010-medico-patologia-clinica' on conflict(exam_id,number) do nothing;
