insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Patologia Clínica','Em relação à deficiência de ferro, assinale verdadeiro ou falso. Em seguida, marque a sequência correta. ( ) Nas crianças a causa mais comum é a carência dietética, já que o leite tem pouco ferro. ( ) Já nos adultos a causa mais comum é a perda sanguínea crônica. ( ) O teste mais confiável para diagnosticarmos a deficiência de ferro é a dosagem de ferro medular.','','','["F-V-F.", "V-V-V.", "V-V-F.", "F-V-V."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Patologia Clínica: alternativa B. Resposta indicada no gabarito: V-V-V..' from public.exams where slug='pmerj-2010-medico-patologia-clinica' on conflict(exam_id,number) do nothing;
