insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Patologia Clínica','Relacione o marcador tumoral com seu respectivo tumor. Em seguida, marque a opção correta. tecidual (2) Metabólitos urinários das catecolaminas (3) Hidroxiprolina urinária (4) Poliamina no líquor ( ) Tumor de mama ( ) Tumor cerebral ( ) Mieloma múltiplo ( ) Feocromocitoma','','','["2-4-1-3", "3-2-1-4", "1-4-3-2", "1-3-2-4"]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Patologia Clínica: alternativa C. Resposta indicada no gabarito: 1-4-3-2.' from public.exams where slug='pmerj-2010-medico-patologia-clinica' on conflict(exam_id,number) do nothing;
