insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Patologia Clínica','Mais de 80% da proteína total liquórica é proveniente de ultrafiltração plasmática e pinocitose.  Em relação às concentrações de proteína total no líquor, pode-se afirmar: [V] – dosagem de proteína no líquor ventricular [C] – dosagem de proteína no líquor cisternal [L] – dosagem de proteína no líquor extraído da região lombar Com base no exposto acima, assinale a opção correta.','','','["[L] < [C] < [V]", "[V] = [C] > [L]", "[L] = [C] = [V]", "[L] > [C] > [V]"]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Patologia Clínica: alternativa A. Resposta indicada no gabarito: [L] < [C] < [V].' from public.exams where slug='pmerj-2010-medico-patologia-clinica' on conflict(exam_id,number) do nothing;
