insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Patologia Clínica','Qual dos marcadores abaixo está relacionado ao tumor de ovário?','','','["CA 125.", "CEA.", "CA 19-9.", "CA 15-3."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Patologia Clínica: alternativa A. Resposta indicada no gabarito: CA 125..' from public.exams where slug='pmerj-2010-medico-patologia-clinica' on conflict(exam_id,number) do nothing;
