insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Pediatria','Um menino de 10 anos de idade é levado à emergência, apresentando lesão abdominal por arma de fogo. O paciente apresenta equilíbrio hemodinâmico. Assinale a alternativa que contém a melhor conduta a ser seguida.','','','["Radiografia simples de abdome e laparatomia exploratória.", "Ultrasonografia abdominal e laparatomia exploratória.", "Tomografia computadorizada com contraste e laparatomia exploratória.", "Rotina radiológica para abdome agudo e acompanhamento clínico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: Radiografia simples de abdome e laparatomia exploratória..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Pediatria','Uma criança de 1 ano de idade está há 3 dias em ventilação mecânica com pressão positiva, devido à presença de pneumonia, com os seguintes parâmetros no respirador: VMI, frequência = 12 ciclos / min, PIP = 20 cmH2O, PEEP = 3 cm H2O e FiO2 = 0.3. Sua gasometria arterial apresenta os seguintes resultados: pH = 7.48, PaO2 = 108mmHg e PaCO2 = 35 mmHg. O paciente apresenta estabilidade hemodinâmica, frequência respiratória espontânea de 20 incursões por minuto e sua dieta é administrada através de sonda enteral. Assinale a alternativa que apresenta a melhor conduta a ser seguida.','','','["Aumentar a frequência do respirador para 20 ciclos / min e o PEEP para 5 cm H2O.", "Suspender a dieta por 4 horas e extubar o paciente.", "Mudar o modo ventilatório para CPAP com 5 cm H2O.", "Aumentar a FiO2 para 0.4 e o PEEP para 5 cm H2O."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: Suspender a dieta por 4 horas e extubar o paciente..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Pediatria','Um lactente de 4 meses de idade é internado com quadro clínico de paralisia flácida descendente. O quadro iniciou-se com ptose seguido de disfagia, disfonia, redução do reflexo nauseoso e córneo- -palpebral. O exame do LCR foi normal. Não há relato de febre e há 36 horas a criança fez ingestão de mel de abelha “in natura”. Assinale a alternativa que apresenta a possibilidade diagnóstica a ser considerada.','','','["Miastenia gravis.", "Paralisia familiar periódica.", "Síndrome de Guillain- Barre.", "Botulismo infantil."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa D. Resposta indicada no gabarito: Botulismo infantil..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Pediatria','Assinale a alternativa correta em relação aos traumatismos raquimedulares em crianças.','','','["A região cervical é a mais acometida.", "São mais frequentes em lactentes.", "Alterações radiológicas estão presentes em 80% dos pacientes com alterações neurológicas.", "No caso de lesões intramedulares, a tomografia computadorizada é o melhor exame a ser realizado."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: A região cervical é a mais acometida..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Pediatria','Assinale a alternativa correta em relação às meningites bacterianas.','','','["A positividade das hemoculturas nos casos de meningite se situa em torno de 25%.", "A presença de trombocitopenia é contra- indicação absoluta para a realização de punção lombar.", "Convulsões estão presentes em torno de 20 a 30% dos casos e não possuem valor prognóstico. É", "O tratamento com antibióticos somente deve ser iniciado após a punção lombar ou tomografia computadorizada de crânio."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: Convulsões estão presentes em torno de 20 a 30% dos casos e não possuem valor prognóstico. É.' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Pediatria','Assinale a alternativa correta em relação às infecções causadas por cândida SP.','','','["A retirada do cateter venoso em que foi isolada candida albicans deverá ser feita após 2 semanas de tratamento com anfoterecina B no caso de não negativação das culturas.", "O tratamento com fluconazol está especialmente indicado nos casos de isolamento de cândida Kruzei ou candida glabrata.", "Os pacientes neutropênicos com febre prolongada costumam apresentar índice elevado de hemoculturas positivas para cândida.", "O crescimento de cândida em meios de hemocultura convencionais apresenta positividade de aproximadamente 90% em 72 horas e 97% em 7 dias."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa D. Resposta indicada no gabarito: O crescimento de cândida em meios de hemocultura convencionais apresenta positividade de aproximadamente 90% em 72 horas e 97% em 7 dias..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Pediatria','Uma criança de 5 anos de idade é conduzida ao consultório com diagnóstico de febre reumática. Assinale a alternativa correta quanto à confirmação diagnóstica.','','','["Presença de coréia, artralgia e níveis elevados de proteína C reativa.", "Presença de eritema marginatum e níveis elevados de proteína C reativa.", "Níveis elevados de proteína C reativa, intervalo PR aumentado e artralgia.", "Presença de cardite e artralgia em grandes articulações."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: Presença de coréia, artralgia e níveis elevados de proteína C reativa..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Médico Pediatria','Em relação ao emprego de fármacos no tratamento do choque séptico, assinale a alternativa correta.','','','["A epinefrina empregada em doses baixas (0,05 µg / Kg / min) apresenta preponderância de efeito β-2 adrenérgico.", "O emprego de dopamina em doses acima de 10µg / Kg / min causam predominância de estimulação β-1 adrenérgica.", "O emprego de milrinona é indicado nos pacientes com hipotensão refratária a outras drogas vasopressoras.", "A ausência de resposta vasopressora com emprego de dopamina em doses elevadas é uma contraindicação para o uso de norepinefrina."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: A epinefrina empregada em doses baixas (0,05 µg / Kg / min) apresenta preponderância de efeito β-2 adrenérgico..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Pediatria','Uma criança de 5 meses de idade está internada com síndrome de angústia respiratória aguda (SARA). Assinale a alternativa correta quanto a essa entidade.','','','["O comprometimento pulmonar se dá de forma homogênea em ambos os pulmões.", "Na ventilação mecânica por volume, objetivamos fornecer um volume corrente de 10 ml / Kg e atingir um valor de PaCO2 entre 35 e 45 mmHg.", "O emprego do “ PEEP” (pressão expiratória final positiva) tem como objetivo o recrutamento dos alvéolos e diminuir o bio e atelectrauma.", "O emprego de respiradores ciclados a tempo e limitados por pressão são superiores aos ciclados por volume."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: O emprego do “ PEEP” (pressão expiratória final positiva) tem como objetivo o recrutamento dos alvéolos e diminuir o bio e atelectrauma..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Médico Pediatria','Um recém-nascido a termo, com 48 horas de vida, apresenta-se taquipneico, pálido, sudorético, com sensório alterado, pulsos periféricos com amplitude mínima e frequência cardíaca de 280bpm. É realizado um ECG e constata-se a presença de arritmia com QRS estreitado. Assinale a alternativa correta quanto à conduta a ser tomada.','','','["Cardioversão.", "Manobra vagal.", "Digitalização.", "Amiodarona."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: Cardioversão..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Médico Pediatria','Assinale a alternativa que apresenta o grupo de condições que podem estar presentes, com maior frequência, em recém-nascidos, filhos de mãe diabética.','','','["Hipomagnesemia, síndrome de hipervisco- sidade sanguínea, anemia hemolítica.", "Hipocalcemia, defeitos do septo inter- ventricular, síndrome de regressão caudal.", "Coarctação da aorta, hipoglicemia, estenose hipertrófica de piloro.", "Cardiomiopatia hipertrófica, gastrosquise, doença da membrana hialina."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: Hipocalcemia, defeitos do septo inter- ventricular, síndrome de regressão caudal..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Médico Pediatria','Uma criança de 1 ano de idade apresenta febre elevada ( 39 – 40 oC ) há 5 dias. O exame físico revela a presença de artralgia, linfoadenopatia cervical, conjuntivite bulbar não exsudativa, língua em framboesa, edema e eritema de mãos e pés, descamação perineal e lábios ressecados com rachaduras. Assinale a alternativa correta quanto à conduta terapêutica a ser adotada.','','','["Iniciar metil-prednisolona.", "Iniciar penicilina benzatina 1.200.000 U.", "Iniciar metrotexate.", "Iniciar imunoglobulina EV."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa D. Resposta indicada no gabarito: Iniciar imunoglobulina EV..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Pediatria','Assinale a alternativa que apresenta o possível agente causal de crises aplásticas em crianças portadoras de anemia falciforme.','','','["Adenovírus.", "Influenza.", "Parvovírus B-19.", "HTLV-1."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: Parvovírus B-19..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Médico Pediatria','Assinale a alternativa correta em relação às neoplasias do SNC em crianças e adolescentes.','','','["Os tumores primários do SNC representam a segunda malignidade mais comum nesta faixa etária.", "Os meduloblastomas são mais frequentes em meninas.", "Os astrocitomas correspondem a 80 % dos casos.", "Os tumores de células germinativas apresentam baixos níveis de alfa- fetoproteína."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: Os tumores primários do SNC representam a segunda malignidade mais comum nesta faixa etária..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Médico Pediatria','A suplementação de ácido fólico é primordial em gestantes que fazem uso de fenobarbital a fim de prevenir qual tipo de anomalia fetal?','','','["Anemia esferocítica.", "Meningomielocele.", "Microcefalia.", "Talassemia."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: Meningomielocele..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Médico Pediatria','Assinale a alternativa correta em relação à doença de Werdnig-Hoffman (atrofia muscular espinhal tipo 1).','','','["O envolvimento do músculo diafragmático é precoce.", "Aproximadamente 2/3 dos pacientes morrem até os 2 anos de vida.", "A incontinência dos esfíncteres é um achado frequente.", "A hipotonia muscular surge após os 6 meses de vida."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: Aproximadamente 2/3 dos pacientes morrem até os 2 anos de vida..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Pediatria','Assinale a alternativa que apresenta o defeito cardíaco esperado em portadores da síndrome de Marfan.','','','["Comunicação interventricular.", "Comunicação interatrial.", "Prolapso da válvula mitral.", "Estenose da válvula pulmonar."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: Prolapso da válvula mitral..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Pediatria','Assinale a alternativa correta em relação à terapêutica transfusional.','','','["A diluição de concentrado de hemácias deve ser feita preferencialmente com solução de ringer lactato.", "A transfusão de 10 ml / Kg de concentrado de hemácias deverá elevar a concentração de hemoglobina sérica entre 3,5 e 4,0 g / dl.", "A transfusão de uma unidade de concentrado de plaquetas para cada 5 Kg de peso corporal elevará as plaquetas sanguíneas entre 20.000 e 50.000 plaquetas / mm3.", "Os pacientes sem sangramento, com contagem plaquetária menor que 50.000 / mm3 necessitam de reposição plaquetaria."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: A transfusão de uma unidade de concentrado de plaquetas para cada 5 Kg de peso corporal elevará as plaquetas sanguíneas entre 20.000 e 50.000 plaquetas / mm3..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Pediatria','Uma criança de 5 anos de idade pesando 25 Kg, apresenta hipotensão arterial após trauma com sangramento. Assinale a alternativa que apresenta a estimativa da perda sanguínea mínima do paciente.','','','["Entre 5 e 10 % da volemia.", "Entre 10 e 15 % da volemia.", "Entre 15 e 20 % da volemia", "Entre 25 e 30 % da volemia."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa D. Resposta indicada no gabarito: Entre 25 e 30 % da volemia..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Pediatria','Assinale a alternativa correta quanto às opções de tratamento para um recém-nascido, apresentando hipertensão arterial pulmonar com persistência da circulação fetal.','','','["Nitro-prussiato EV, óxido nítrico inalatório e digitálicos.", "Ventilação oscilatória de alta frequência, óxido nítrico inalatório, circulação extra- corpórea por membrana.", "Óxido nítrico inalatório, bloqueador de canal de cálcio, ventilação não invasiva.", "Óxido nítrico inalatório, isoproterenol EV, ventilação com alta frequência."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: Ventilação oscilatória de alta frequência, óxido nítrico inalatório, circulação extra- corpórea por membrana..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Pediatria','Assinale a alternativa correta em relação à exsanguineotransfusão em recém-nascidos.','','','["A técnica de retirada do sangue por um acesso simultaneamente à reposição por acesso diferente é mais eficaz do que a retirada e reposição por um único acesso.", "A exsanguineotransfusão de 1 volemia remove 70 – 75% das hemácias do recém- -nascido.", "A troca de 1 volemia é capaz de remover 90% da bilirrubina indireta presente.", "O uso de sangue heparinizado é desaconselhado, devido à sua baixa concentração de plaquetas."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: A exsanguineotransfusão de 1 volemia remove 70 – 75% das hemácias do recém- -nascido..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Pediatria','Um menino com 1 ano de vida apresentou 2 episódios de hemorragia digestiva baixa com 2 semanas de vida. Ao longo do primeiro ano teve vários episódios de infecções recorrentes e dermatite atópica. É realizado hemograma completo que revela diminuição no número e tamanho das plaquetas. Assinale a alternativa correta quanto à possibilidade diagnóstica do quadro em questão.','','','["Síndrome de Wiskott- Aldrich.", "Síndrome de DiGeorge.", "Síndrome de Chediak-Higashi.", "Ataxia-telangiectasia."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: Síndrome de Wiskott- Aldrich..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Pediatria','Um menino com 3 anos de idade apresenta uma massa de consistência firme nodular palpável no flanco direito causando desconforto. É realizada uma tomografia computadorizada de abdome que mostra presença de hemorragia e calcificações na massa. O paciente apresenta aumento da sudorese, hipertensão arterial e níveis elevados de ácido homovanílico na urina. Assinale a alternativa que apresenta a possibilidade diagnóstica para o quadro apresentado.','','','["Tumor de Wilms.", "Ganglioneuroma.", "Feocromocitoma.", "Neuroblastoma."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa D. Resposta indicada no gabarito: Neuroblastoma..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Médico Pediatria','Assinale a alternativa correta quanto ao emprego de opioides em crianças.','','','["O fentanil é 100 vezes mais potente que a morfina e sua eliminação é mais rápida nas crianças em relação aos adultos.", "A meperidina é mais potente que a morfina e apresenta efeito anticonvulsivante.", "A metadona pode ser usada por via oral ou venosa e sua principal vantagem é não ter efeito anticonvulsivante.", "A morfina é indicada preferencialmente em pacientes com broncoespasmo e instabilidade circulatória."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: O fentanil é 100 vezes mais potente que a morfina e sua eliminação é mais rápida nas crianças em relação aos adultos..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Médico Pediatria','Assinale a alternativa correta em relação à leptospirose.','','','["A meningite asséptica está presente em 50% dos pacientes.", "A apresentação como doença febril aguda com sintomas e sinais inespecíficos é a mais comum.", "A apresentação com disfunção hepática e renal corresponde a 80 % dos casos.", "A síndrome de Weil é mais comum nas crianças com menos de 1 ano de vida."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: A apresentação como doença febril aguda com sintomas e sinais inespecíficos é a mais comum..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Médico Pediatria','Uma criança de 3 anos de idade é conduzida à emergência devido a acidente automobilístico. Ela apresenta dor no ombro esquerdo. O paciente está com equilíbrio hemodinâmico. È realizada uma tomografia computadorizada de abdome que revela ruptura esplênica. Anteriormente tinha sido realizada paracentese que deu saída a líquido hemorrágico. Assinale a alternativa correta em relação à conduta a ser tomada.','','','["Repetir a tomografia após 6 horas, caso haja piora clínica.", "Esplenectomia de urgência.", "Conduta expectante com acompanhamento dos sinais vitais.", "Esplenectomia após a transfusão de concentrado de hemácias."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: Conduta expectante com acompanhamento dos sinais vitais..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Médico Pediatria','Um lactente de 4 meses de idade pesando 5 Kg chega à emergência com quadro clínico de irritabilidade e desidratação moderada. Sua doença teve início há 5 dias com o aparecimento de diarreia com emissão de fezes líquidas em torno de 5 episódios por dia. Desde a abertura do quadro, sua mãe vem fazendo reposição com solução hidratante oral. O paciente está sem urinar há 12 horas. Os exames laboratoriais de entrada revelam um sódio plasmático de 258 mEq / L e potássio sérico de 5,5 mEq / L. Baseado no quadro clínico apresentado, marque a opção correta quanto à conduta imediata.','','','["Reposição volumétrica rápida com soro fisiológico 20 ml / Kg.", "Reposição volumétrica rápida com solução glico-fisiológico 1:1 ( 150 mOsm / L ).", "Reposição volumétrica rápida com solução glico-fisiológico 2:1 ( 100 mOsm / L ).", "Reposição volumétrica rápida com solução glico-fisiológico 3:1 ( 75 mOsm / L )."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: Reposição volumétrica rápida com soro fisiológico 20 ml / Kg..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Médico Pediatria','Embasado no quadro clínico anteriormente descrito, assinale a alternativa correta em relação à correção da hipernatremia apresentada pelo paciente.','','','["O déficit de água é de aproximadamente 250 ml e a velocidade de correção do sódio deve ser a diminuição de 1 mEq por hora.", "O déficit de água é de aproximadamente 310 ml e a velocidade de correção do sódio deve ser a diminuição de 0,5 mEq por hora.", "O déficit de água é de aproximadamente 385 ml e a velocidade de correção do sódio deve ser a diminuição de 0,8 mEq por hora.", "O déficit de água é de aproximadamente 450 ml e a velocidade de correção do sódio deve ser a diminuição de 0,7 mEq por hora."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: O déficit de água é de aproximadamente 385 ml e a velocidade de correção do sódio deve ser a diminuição de 0,8 mEq por hora..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Médico Pediatria','Ainda em relação ao quadro clínico descrito na questão anterior, a diurese do paciente foi restabelecida, foram colhidos novos exames que mostravam uma creatinina sérica de 0,6 mg / dl e a gasometria arterial apresentava um pH = 7.1 uma PaCO2 = 25 mmHg. É realizada uma correção com bicarbonato de sódio e o valor do novo pH é de 7.4 . Assinale a alternativa correta sobre os novos valores de potássio que esperaríamos encontrar no paciente.','','','["Entre 5,0 e 4,4 mEq / L.", "Entre 4,0 e 3,0 mEq / L", "Entre 4,7 e 3,8 mEq / L.", "Entre 5,1 e 4,6 mEq / L."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: Entre 4,7 e 3,8 mEq / L..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Médico Pediatria','Assinale a alternativa correta em relação à displasia broncopulmonar.','','','["O emprego de dexametasona está relacionado com a redução do tempo de desmame da ventilação mecânica e menor risco de paralisia cerebral.", "O emprego de salbutamol inalatório pode aumentar a complacência pulmonar e diminuir a resistência das vias aéreas.", "Nos pacientes em ventilação mecânica com pressão positiva, objetivamos manter um valor de PaCO2 entre 35 – 45 mmHg e um valor de pH maior que 7.4.", "Nos pacientes que apresentam hipertensão pulmonar, devemos manter uma saturação da hemoglobina variando entre 75 – 80 %."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: O emprego de salbutamol inalatório pode aumentar a complacência pulmonar e diminuir a resistência das vias aéreas..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Médico Pediatria','Assinale a alternativa correta em relação à neurofibromatose.','','','["As manchas cutâneas café com leite estão presentes ao nascimento e aumentam em número e tamanho com a idade.", "A localização preferencial das manchas cutâneas são a face e membros inferiores.", "Os neurofibromas são de localização exclusivamente cutânea.", "É uma desordem autossômica recessiva."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: As manchas cutâneas café com leite estão presentes ao nascimento e aumentam em número e tamanho com a idade..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Pediatria','Assinale a alternativa correta em relação à apresentação comumente encontrada na hiperplasia congênita da glândula suprarrenal.','','','["Apresenta-se com desidratação, hipona- tremia, hipercalemia e sinais externos de virilização nas meninas.", "Apresenta-se com desidratação, hiperna- tremia, hipocalemia e genitália normal independente do sexo.", "Apresenta-se com desidratação, hiponatre- mia, hipocalemia e genitália normal independente do sexo.", "Apresenta-se com desidratação, hipernatre- mia, hipocalemia e sinais externos de virilização nas meninas."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: Apresenta-se com desidratação, hipona- tremia, hipercalemia e sinais externos de virilização nas meninas..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Pediatria','Assinale a alternativa correta em relação à estenose hipertrófica do piloro.','','','["É mais comum na raça negra.", "Os episódios de vômitos geralmente se iniciam após a terceira semana de vida.", "A presença de vômitos biliosos surge após ingestão de alimentos.", "A presença de alcalose metabólica com hipercalemia e hipercloremia fazem parte do quadro clínico."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: Os episódios de vômitos geralmente se iniciam após a terceira semana de vida..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Pediatria','Uma criança de 4 anos de idade apresenta crescimento deficiente, distensão abdominal, e episódios de diarreia. Sua dosagem de imunoglobulinas revela valores baixos de IgA. Qual exame estaria indicado para a confirmação ou exclusão de doença celíaca nesse paciente?','','','["Pesquisa de antigliadina IgA e IgG.", "Pesquisa de IgA antiendomisio.", "Biopsia de intestino delgado.", "Pesquisa de Ig A anti-transglutaminase."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: Biopsia de intestino delgado..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Pediatria','Assinale a alternativa correta em relação aos tocotraumatismos.','','','["As fraturas de costelas são relativamente comuns nos partos com apresentação pélvica.", "O cefalohematoma é mais frequente em recém-nascidos do sexo feminino de mãe multípara.", "A clavícula é o osso mais fraturado durante o parto.", "A paralisia do nervo frênico ocorre como lesão bilateral única."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: A clavícula é o osso mais fraturado durante o parto..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Pediatria','Assinale a alternativa correta em relação ao quadro de extravasamento aéreo pulmonar no período neonatal.','','','["A presença de pneumomediastino indica a necessidade de drenagem torácica.", "A associação com pneumoperitonio é frequente nos casos de pneumomediastino.", "O aumento da frequência respiratória, nos casos de ventilação com pressão positiva, aumenta a incidência de pneumotórax.", "A incidência de pneumotórax espontâneo ao nascimento é de aproximadamente 1% de todos os partos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa D. Resposta indicada no gabarito: A incidência de pneumotórax espontâneo ao nascimento é de aproximadamente 1% de todos os partos..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Pediatria','Um recém-nascido a termo desenvolve desconforto respiratório logo após o nascimento e cianose que não regride com administração de oxigênio. A história gestacional revela a presença de infecção urinária materna não tratada. É realizada uma radiografia torácica com laudo de pneumonia bilateral e um ecocardiograma mostra regurgitação tricúspide, forâmen oval e canal arterial patentes. Assinale a alternativa correta que apresenta o grupo de opções terapêuticas para esse paciente.','','','["CPAP nasal, furosemida e dobutamina.", "Ventilação mecânica, surfactante exógeno e óxido nítrico inalatório.", "Ventilação mecânica, bloqueador do canal de cálcio e óxido nítrico.", "CPAP nasal, hipercapnia permissiva e surfactante."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: Ventilação mecânica, surfactante exógeno e óxido nítrico inalatório..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Pediatria','Um recém-nascido a termo pesando 3700g , com Apgar 7 no primeiro minuto e 8 no quinto minuto, apresenta cianose e hepatomegalia. É realizado um ecocardiograma que revela atresia pulmonar com septo interventricular integro. Assinale a alternativa correta quanto à conduta terapêutica a ser tomada.','','','["Intubação orotraqueal e ventilação com pressão positiva com oxigênio a 100%.", "Iniciar infusão venosa de dopamina 2 µg / Kg / min e dobutamina 5 µg / Kg / min.", "Iniciar infusão de prostaglandina E1.", "Iniciar óxido nítrico inalatório."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: Iniciar infusão de prostaglandina E1..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Pediatria','Assinale a alternativa que apresenta condições indicadoras da necessidade de investigação de doença renal no período neonatal.','','','["Ausência de diurese após 24 horas de vida, bexiga não palpável, creatinina sérica com valor de 1,1 mg / dl com 12 horas de vida em RN a termo.", "Aumento da creatinina sérica nas primeiras 24 horas em RN pré-termo, ausência de diurese, bexiga não palpável.", "Presença de 20 hemácias por campo no EAS e aumento da creatinina sérica de 0,3 mg / dl para 0,6 mg / dl em RN a termo com 48 horas de vida.", "Ausência de diurese em RN a termo com 36 horas de vida, creatinina sérica de 1,0 mg / dl e bexiga não palpável."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: Presença de 20 hemácias por campo no EAS e aumento da creatinina sérica de 0,3 mg / dl para 0,6 mg / dl em RN a termo com 48 horas de vida..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Pediatria','Assinale a alternativa correta em relação ao diagnóstico das encefalites na infância.','','','["A pesquisa de vírus pela técnica do PCR no liquor (reação em cadeia pela polimerase) não apresenta boa sensibilidade para os principais agentes.", "A ressonância magnética é o exame de imagem de escolha quando há forte suspeita de encefalite.", "Nos casos de encefalite por Mycoplasma, frequentemente isolamos o micro- organismo na cultura do liquor.", "Na encefalite herpética há aumento específico da IgG no liquor a partir do terceiro dia de doença."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: A ressonância magnética é o exame de imagem de escolha quando há forte suspeita de encefalite..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Pediatria','Assinale a alternativa correta em relação à artrite séptica na infância.','','','["Acometem duas ou mais articulações em 50% dos casos.", "As hemoculturas costumam ser positivas em 10% dos casos.", "A ultrassonografia não mostra vantagem em relação à radiografia simples da articulação acometida.", "A cultura do material articular apresenta positividade em mais de 50% dos casos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa D. Resposta indicada no gabarito: A cultura do material articular apresenta positividade em mais de 50% dos casos..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Pediatria','Em relação à leucemia linfoblástica aguda podemos afirmar que','','','["é mais comum em crianças portadoras de anormalidades cromossômicas.", "a incidência é maior em crianças com idade inferior a 1 ano.", "sinais de envolvimento do SNC são frequentes.", "é mais comum em meninas com idade inferior a 2 anos."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: é mais comum em crianças portadoras de anormalidades cromossômicas..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Pediatria','Uma criança de 2 anos de idade que faz uso de ácido valproico para tratamento de desordem convulsiva, apresenta quadro de dor abdominal intensa, vômitos e febre. O quadro evoluiu com comprometimento hemodinâmico e surgimento de sinal de Cullen. Assinale a alternativa que corresponde à possibilidade diagnóstica a ser considerada.','','','["Colite pseudomembranosa.", "Isquemia mesentérica.", "Úlcera péptica perfurada.", "Pancreatite aguda."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa D. Resposta indicada no gabarito: Pancreatite aguda..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Pediatria','Em relação à febre do dengue hemorrágico, é correto afirmar que','','','["entre os critérios diagnóstico, incluem-se o derrame de serosas, hipoalbuminemia, trombocitopenia e hematócrito elevado.", "as plaquetas raramente estão abaixo de 100.000 / mm3.", "a síndrome do choque no dengue inclui os sinais do dengue hemorrágico e hipertensão arterial.", "dor epigástrica e hepatomegalia não ocorrem."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: entre os critérios diagnóstico, incluem-se o derrame de serosas, hipoalbuminemia, trombocitopenia e hematócrito elevado..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Pediatria','Na infecção do trato urinário em crianças, deve-se considerar correto o seguinte:','','','["Realizar ultrassonografia abdominal como método de eleição para evidenciar cicatriz renal.", "Somente 40% das crianças com refluxo vésico – ureteral apresentam anormalidades na ultrasonografia.", "A urografia excretora é o exame mais sensível para verificação de cicatriz renal.", "Constipação e disfunção miccional não são fatores de risco para infecção do trato urinário."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: Somente 40% das crianças com refluxo vésico – ureteral apresentam anormalidades na ultrasonografia..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Pediatria','Em relação às infecções por rotavírus, podemos afirmar que','','','["crianças menores que 3 meses de idade possuem proteção relativa pelo aleitamento materno e presença de anticorpos transplacentários.", "a doença mais severa ocorre a partir dos 24 meses de vida.", "a primeira dose da vacina deve ser administrada a partir do sexto mês de vida.", "a introdução de leite de soja é fator preponderante para cura nos casos de gastrenterite."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa A. Resposta indicada no gabarito: crianças menores que 3 meses de idade possuem proteção relativa pelo aleitamento materno e presença de anticorpos transplacentários..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Pediatria','Uma criança com 3 anos de vida apresenta quadro clínico de tosse e febre elevada. Ao exame, há lesões cutâneas infectadas após episódio de varicela. Há 24 horas vem queixando-se de dor torácica e, ao exame físico, evidencia-se a presença de hipotensão arterial, pulsos com amplitude diminuída, turgência jugular, hepatomegalia e presença de pulso paradoxal de 25 mmHg. O ECG mostra baixa voltagem em todas as derivações com QRS < 5 mm e elevação do segmento ST. Assinale, entre as opções abaixo, a principal a ser considerada.','','','["Choque séptico.", "S.A.R.A.", "Tamponamento cardíaco.", "Insuficiência cardíaca congestiva."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: Tamponamento cardíaco..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Pediatria','Um lactente com idade de 8 meses apresenta quadro de febre, vômitos, diarréia com fezes líquidas e, posteriormente, sanguinolentas. Após 6 dias de evolução, torna-se letárgico e oligúrico. O exame sanguíneo mostra a presença de trombocitopenia, esquizócitos e hemácias em capacete. Assinale a alternativa que apresenta a principal possibilidade diagnóstica a ser considerada.','','','["Choque séptico.", "Coagulação intravascular disseminada.", "Esferocitose.", "Síndrome hemolítico-urêmica."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa D. Resposta indicada no gabarito: Síndrome hemolítico-urêmica..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Pediatria','Assinale a alternativa correta em relação ao quase afogamento.','','','["As alterações eletrolíticas são fatores preponderantes no prognóstico.", "A lesão pulmonar e a síndrome hipóxico- isquêmica são os fatores de importância primária.", "A terapêutica ventilatória a ser utilizada irá depender do tipo de água aspirada, doce ou salgada.", "A manobra de Heimlich deve ser realizada logo que possível."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa B. Resposta indicada no gabarito: A lesão pulmonar e a síndrome hipóxico- isquêmica são os fatores de importância primária..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Pediatria','Assinale a alternativa correta em relação à artrite reumatóide juvenil.','','','["A forma pauciarticular afeta predominantemente as articulações das extremidades superiores.", "A forma poliarticular é caracterizada quando o acometimento articular é maior que 10 articulações.", "A forma sistêmica apresenta acometimento visceral e febre elevada além do articular.", "Anticorpos anti-nucleares são frequentes nas formas sistêmicas."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pediatria: alternativa C. Resposta indicada no gabarito: A forma sistêmica apresenta acometimento visceral e febre elevada além do articular..' from public.exams where slug='pmerj-2010-medico-pediatria' on conflict(exam_id,number) do nothing;
insert into public.exams(slug,title,source,year) values ('pmerj-2010-medico-pneumologia','PMERJ 2010 — Oficial — Médico Pneumologia','pmerj','2010') on conflict(slug) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Médico Pneumologia','Dentre as drogas abaixo listadas, qual a preferencial para o tratamento da pneumonia por Legionella?','','','["Cefuroxime.", "Clindamicina.", "Claritromicina.", "Tobramicina."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa C. Resposta indicada no gabarito: Claritromicina..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Médico Pneumologia','Nos pacientes portadores de doença bronquiectásica, com alterações principalmente em lóbulos inferiores, é correto afirmar que','','','["o uso de acetil cisteina tem eficácia comprovada como mucolítico.", "não é frequente a obstrução progressiva do fluxo ventilatório.", "a depuração do escarro pode ser obtida com mais facilidade através da fisioterapia respiratória.", "na exarcerbação, é comum escarro purulento, febre e leucocitose."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa C. Resposta indicada no gabarito: a depuração do escarro pode ser obtida com mais facilidade através da fisioterapia respiratória..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Médico Pneumologia','Dentre as alterações histopatológicas abaixo relacionadas, qual a que NÃO é observada nos casos de pneumonite por hipersensibilidade?','','','["Bronquiolite celular.", "Infiltrados intersticiais linfoplasmocitários.", "Granulomas não necrosantes mal formados.", "Proliferação histiocitária com granulomas apresentando corpúsculos eosinofílicos."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa D. Resposta indicada no gabarito: Proliferação histiocitária com granulomas apresentando corpúsculos eosinofílicos.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Médico Pneumologia','Para diferenciar o derrame pleural entre exsudato e transudato, podem-se utilizar vários testes diagnósticos. Dentre os citados abaixo, qual o de menor relação de sensibilidade e especificidade?','','','["Relação proteica líquido pleural e sérica maior que 0,5.", "Relação de LDH líquido pleural e soro maior que 0,6.", "Concentração de LDH no líquido pleural maior que dois terços do valor normal sérico.", "Relação de bilirrubina no líquido pleural e soro maior que 0,9."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa D. Resposta indicada no gabarito: Relação de bilirrubina no líquido pleural e soro maior que 0,9..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Médico Pneumologia','A quimioprofilaxia da tuberculose em grupos de alto risco de adoecimento deve ser feita com isoniazida por 6 meses na seguinte dose de quantos miligramas por quilo de peso por dia?','','','["10.", "15.", "20.", "25."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa A. Resposta indicada no gabarito: 10..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Médico Pneumologia','Qual o esquema terapêutico alternativo recomendado para o tratamento de paciente com tuberculose pulmonar diante do quadro de hepatotoxicidade ao esquema rifampicina, isoniazida e pirazinamida?','','','["Estreptomicina, etambutol, ofloxacina.", "Estreptomicina, etambutol, pirazinamida.", "Estreptomicina, etambutol, capreomicina.", "Estreptomicina, etambutol, terizidona."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa A. Resposta indicada no gabarito: Estreptomicina, etambutol, ofloxacina..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Médico Pneumologia','As imagens radiológicas pulmonares sugestivas de tuberculose no adulto são mais frequentes nos(na)','','','["terços superiores.", "linfonodos mediastinais.", "lobos inferiores.", "porção medial do lobo médio."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa A. Resposta indicada no gabarito: terços superiores..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
