insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Médico Pneumologia','Num paciente com neutropenia prolongada, o achado na tomografia computadorizada de tórax, de um nódulo com área de baixa atenuação circundante (sinal do halo), pode ser um dado auxiliar no diagnóstico de','','','["pneumocistose.", "aspergilose invasiva.", "criptococose.", "nocardiose."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa B. Resposta indicada no gabarito: aspergilose invasiva..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
