insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Médico Pneumologia','O teste para anticorpos citoplasmáticos antineutrófilos é de grande utilidade no diagnóstico de vasculites sistêmicas com envolvimento pulmonar. O padrão de coloração citoplasmático (c- ANCA) é encontrado com maior frequência em','','','["granulomatose de Wegener.", "síndrome de Churg-Strauss.", "poliarterite nodosa.", "poliangeite microscópica."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa A. Resposta indicada no gabarito: granulomatose de Wegener..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
