insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Médico Pneumologia','No caso de paciente com história clínica compatível com tuberculose pulmonar e imagem radiológica cavitária pulmonar, a primeira opção para diagnóstico é realizar pesquisa de BAAR através de','','','["escarro induzido.", "broncofibroscopia.", "exame direto de escarro.", "amplificação de ácido nucleico (PCR)."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa C. Resposta indicada no gabarito: exame direto de escarro..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Médico Pneumologia','As alterações reticulares subpleurais bilaterais em lobos inferiores dos pulmões acompanhadas de imagens em favo de mel encontradas na tomografia computadorizada de tórax de alta resolução são sugestivas de','','','["pneumonia criptogênica de organização.", "pneumonia intersticial inespecífica.", "pneumonia intersticial descamativa.", "fibrose pulmonar idiopática."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa D. Resposta indicada no gabarito: fibrose pulmonar idiopática..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Médico Pneumologia','Em relação às pneumonias bacterianas em pacientes soropositivos para HIV é correto afirmar que','','','["a frequência da pneumonia bacteriana diminui com o declínio na contagem de T CD4.", "a pneumonia bacteriana é mais comum nos soropositivos que nos soronegativos de controle.", "a associação de tabagismo apresenta risco mais elevado de pneumonia nos soropositivos do que nos soronegativos.", "os pacientes com HIV que desenvolvem pneumonia apresentam mortalidade igual àqueles com HIV sem pneumonia."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa B. Resposta indicada no gabarito: a pneumonia bacteriana é mais comum nos soropositivos que nos soronegativos de controle..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Médico Pneumologia','Nos pacientes com AIDS em tratamento para tuberculose e em uso de HAART, pode acontecer efeito paradoxal com agravamento da tuberculose nas primeiras semanas de medicação. Isso se deve à(ao)','','','["infecção por bactérias resistentes ao medicamento contra tuberculose.", "resposta de reconstituição imune.", "falta de adesão ao tratamento conjunto.", "aparecimento de outra infecção."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa B. Resposta indicada no gabarito: resposta de reconstituição imune..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Médico Pneumologia','Nos critérios de Fine que estratificam dados de risco, de acordo com a mortalidade estimada para os pacientes com pneumonia adquirida na comunidade, qual dentre os abaixo citados tem atribuição de 30 pontos positivos?','','','["Insuficiência cardíaca congestiva.", "Pressão arterial sistólica menor que 90 mmHg.", "pH arterial inferior a 7,35.", "Estado mental alterado."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa C. Resposta indicada no gabarito: pH arterial inferior a 7,35..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Médico Pneumologia','Nos casos de pacientes em ventilação mecânica que desenvolvem pneumonia, qual critério adicional melhora a exatidão diagnóstica da cultura de material coletado no lavado broncoalveolar?','','','["Menos de 5% das bactérias visualizadas no Gram são intracelulares.", "Mais de 10 células epiteliais descamativas encontradas no material.", "Um limiar de mais de 104 unidades formadoras de colônias.", "Menos de 10% de neutrófilos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa C. Resposta indicada no gabarito: Um limiar de mais de 104 unidades formadoras de colônias..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Médico Pneumologia','As paredes alveolares são compostas por dois tipos principais de células, os pneumócitos I e II, e em termos funcionais pode ser afirmado que','','','["os pneumócitos tipo I são metabolicamente ativos e produzem o surfactante.", "os pneumócitos tipo II tem como função essencial a difusão passiva.", "os pneumócitos tipo II são capazes de se diferenciar em tipo I para facilitar o reparo pulmonar.", "os pneumócitos tipo I representam cerca de 40% da superfície alveolar."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa C. Resposta indicada no gabarito: os pneumócitos tipo II são capazes de se diferenciar em tipo I para facilitar o reparo pulmonar..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
