insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Médico Pneumologia','Em relação à fibrose cística, qual das opções é INCORRETA?','','','["As manifestações pulmonares e pancreáticas dominam o quadro clínico.", "A fibrose cística afeta todas as glândulas exócrinas.", "A fibrose cística é causada por uma mutação no gene CFTR.", "Ocorre grande variação no acometimento dos órgãos."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa C. Resposta indicada no gabarito: A fibrose cística é causada por uma mutação no gene CFTR.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Médico Pneumologia','O diagnóstico de certeza da fibrose cística ocorre quando se tem','','','["história familiar positiva e um teste do suor pelo método da iontoforese quantitativa pela pilocarpina com resultado fortemente positivo.", "história familiar positiva e dois testes do suor pelo método da iontoforese quantitativa pela pilocarpina com resultados fortemente positivos.", "história familiar positiva e três testes do suor pelo método da iontoforese quantitativa pela pilocarpina com um resultado fortemente positivo e dois resultados limítrofes.", "história familiar positiva e pelo menos dois testes do suor pelo método da iontoforese quantitativa pela pilocarpina com resultados limítrofes."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa B. Resposta indicada no gabarito: história familiar positiva e dois testes do suor pelo método da iontoforese quantitativa pela pilocarpina com resultados fortemente positivos..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Médico Pneumologia','Na avaliação clínica inicial do paciente com o diagnóstico de fibrose cística, deve constar','','','["broncografia, teste do suor pelo método da iontoforese quantitativa pela pilocarpina e prova de função pancreática.", "tomografia computadorizada do tórax, prova de função pancreática e análise do sêmen.", "tomografia computadorizada de alta resolução do tórax, prova de função pulmonar e prova de função hepática.", "telerradiografia do tórax, prova de função pulmonar e cultura de escarro."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa D. Resposta indicada no gabarito: telerradiografia do tórax, prova de função pulmonar e cultura de escarro..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Médico Pneumologia','São fatores de risco reconhecidos para o desenvolvimento da hipertensão arterial pulmonar:','','','["gestação e doença vascular do colágeno.", "uso de fenfluoramina e infecção pelo HIV.", "uso de contraceptivo oral e doença hipertensiva portal.", "obesidade e shunt cardíaco pulmonar sistêmico congênito."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa B. Resposta indicada no gabarito: uso de fenfluoramina e infecção pelo HIV..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Médico Pneumologia','A classificação funcional da OMS para hipertensão pulmonar estabelece que os pacientes com essa doença levando à marcante limitação de atividade física seja estratificado como','','','["Classe I.", "Classe II.", "Classe III.", "Classe IV."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa C. Resposta indicada no gabarito: Classe III..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Médico Pneumologia','O tratamento da hipertensão pulmonar no paciente com doença pulmonar obstrutiva crônica se sustenta em','','','["oxigenioterapia e broncodilatadores.", "antibióticos e inibidores de canal de cálcio.", "prostaciclinas e flebotomia de repetição.", "inibidores do receptor da endotelina e terapia inalatória com óxido nítrico."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa A. Resposta indicada no gabarito: oxigenioterapia e broncodilatadores..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Médico Pneumologia','Qual a causa mais comum de tromboembolismo venoso na mulher abaixo dos 40 anos?','','','["Uso de contraceptivo oral.", "Gravidez.", "Deficiências de proteína C e proteína S.", "Lúpus eritematoso sistêmico."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa B. Resposta indicada no gabarito: Gravidez..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Médico Pneumologia','Em relação aos métodos diagnósticos utilizados na embolia pulmonar, é correto afirmar que','','','["a cintilografia pulmonar ventilatória- -perfusional, quando negativa, requer a complementação com uma arteriografia pulmonar.", "o teste do D-dímero apresenta elevada sensibilidade e especificidade.", "a tomografia computadorizada do tórax normal não exclui o diagnóstico nos pacientes de risco moderado.", "a maioria dos pacientes apresenta achados anormais na telerradiografia do tórax."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa D. Resposta indicada no gabarito: a maioria dos pacientes apresenta achados anormais na telerradiografia do tórax..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Médico Pneumologia','No tratamento do tromboembolismo pulmonar, está correto afirmar que','','','["a heparina de baixo peso molecular tem eficácia semelhante à heparina não fracionada", "à exceção de situações especiais, a heparina não fracionada permanece como o anticoagulante de escolha.", "nos pacientes com historia de sangramento recente a heparina de baixo peso molecular é opção apropriada.", "o monitoramento terapêutico é mandatório nos pacientes em uso de heparina de baixo peso molecular."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa A. Resposta indicada no gabarito: a heparina de baixo peso molecular tem eficácia semelhante à heparina não fracionada.' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Médico Pneumologia','No diagnóstico definitivo da síndrome apneia obstrutiva do sono, os critérios abaixo devem ser preenchidos:','','','["frequentes engasgos durante o sono e acordar recorrente.", "sonolência diurna excessiva e inexplicável e a sensação que o sono não foi repousante.", "déficit de concentração e 6 eventos / h no Índice Apneia / Hipopneia.", "fadiga diurna e 27 eventos em 6 horas no Índice Apneia / Hipopneia."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa C. Resposta indicada no gabarito: déficit de concentração e 6 eventos / h no Índice Apneia / Hipopneia..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Médico Pneumologia','Dentre as circunstâncias listadas como fator de risco para apneia obstrutiva do sono, qual é a INCORRETA?','','','["Ingesta de álcool.", "Síndrome de Down.", "Acromegalia.", "Peso corpóreo 75% acima do peso corpóreo ideal."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa D. Resposta indicada no gabarito: Peso corpóreo 75% acima do peso corpóreo ideal.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Médico Pneumologia','No rastreamento para apneia obstrutiva do sono (AOS), é correto afirmar que','','','["pacientes portadores de arritmia cardíaca noturna devem ser rastreados para AOS.", "as fases de apneia são detectadas na oximetria noturna independente da saturação de oxigênio.", "o padrão serrilhado na oximetria noturna é atípico na AOS.", "a oximetria noturna é considerada um exame de elevada sensibilidade no rastreamento da AOS."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa A. Resposta indicada no gabarito: pacientes portadores de arritmia cardíaca noturna devem ser rastreados para AOS..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Médico Pneumologia','Em relação às complicações após uma ressecção pulmonar, é correto afirmar:','','','["A abordagem inicial do quilotórax consiste em nova toracotomia e dieta com triglicerídios de cadeia média.", "O enfisema subcutâneo de grande monta é comumente uma condição com elevado risco de vida.", "A fístula pleuro-alveolar é provavelmente a complicação mais comum após uma ressecção pulmonar eletiva.", "A fibrilação atrial é uma complicação muito comum e sua incidência independe do tipo de ressecção pulmonar realizada."]'::jsonb,'C','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa C. Resposta indicada no gabarito: A fístula pleuro-alveolar é provavelmente a complicação mais comum após uma ressecção pulmonar eletiva..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Médico Pneumologia','Paciente de 62 anos, tabagista, submetido à pneumectomia direita há 15 meses por câncer de pulmão, vem apresentando tosse e dispneia aos esforços de caráter progressivo. A telerradiografia de tórax mostra importante migração do mediastino com hiperinsuflação do pulmão esquerdo e o brônquio fonte esquerdo pressionado sobre a coluna vertebral. Qual o diagnóstico principal?','','','["Torsão pulmonar.", "Síndrome pós-pneumectomia.", "Insuficiência ventricular direita.", "Insuficiência respiratória crônica."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa B. Resposta indicada no gabarito: Síndrome pós-pneumectomia..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Médico Pneumologia','No traumatismo penetrante do tórax, está indicado toracotomia na seguinte situação:','','','["traumatismo por arma de fogo.", "drenagem torácica inicial sanguinolenta de 1L.", "drenagem torácica sanguinolenta evolutiva de 100 ml/h em 3 horas.", "hemoptise."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa D. Resposta indicada no gabarito: hemoptise..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Médico Pneumologia','No exame radiológico do tórax, o nódulo pulmonar solitário é considerado compatível com malignidade quando apresenta um padrão de calcificação','','','["excêntrica.", "difusa.", "central.", "laminada."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa A. Resposta indicada no gabarito: excêntrica..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Médico Pneumologia','Na abordagem diagnóstica do nódulo pulmonar solitário, qual das afirmativas está INCORRETA?','','','["Nódulos benignos usualmente têm um tempo de dobra menor que 20 ou maior que 400 dias.", "Nódulos de 5 mm de diâmetro não necessitam de acompanhamento por imagem.", "Os nódulos com atenuação em vidro fosco podem representar uma hiperplasia adenomatosa benigna.", "Os nódulos com atenuação em vidro fosco podem representar um carcinoma bronquíoloalveolar."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa B. Resposta indicada no gabarito: Nódulos de 5 mm de diâmetro não necessitam de acompanhamento por imagem.. Atenção: o enunciado pede uma exceção ou uma afirmação incorreta; a alternativa selecionada não deve ser interpretada como uma regra correta.' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Médico Pneumologia','Em relação ao carcinoma de pulmão, é correto afirmar que','','','["o carcinoma escamoso é o principal carcinoma em frequência, tem uma forte relação com o tabagismo e é mais comum nos homens.", "o adenocarcinoma é usualmente uma lesão periférica, tem forte associação com o tabagismo e pode estar associado à fibrose.", "o carcinoma de grandes células é usualmente uma lesão intermediária, bastante frequente e na prática seu diagnóstico é de exclusão.", "o carcinoma de pequenas células é usualmente uma lesão central, altamente agressivo e com baixa resposta à quimioterapia."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa B. Resposta indicada no gabarito: o adenocarcinoma é usualmente uma lesão periférica, tem forte associação com o tabagismo e pode estar associado à fibrose..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Médico Pneumologia','Na insuficiência respiratória aguda, com relação aos fatores que aumentam a demanda ventilatória, é correto afirmar que,','','','["na asma aguda, ocorre uma diminuição na relação VD/VT.", "na sepse, ocorre um aumento na VO2.", "na ingestão excessiva de carboidratos, ocorre uma diminuição no RQ.", "na acidose metabólica, ocorre um aumento na PaCO2."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Médico Pneumologia: alternativa B. Resposta indicada no gabarito: na sepse, ocorre um aumento na VO2..' from public.exams where slug='pmerj-2010-medico-pneumologia' on conflict(exam_id,number) do nothing;
