insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Pedagogia','A Língua Brasileira de Sinais – LIBRAS - foi rec Pessoa Surda, com a publicação da Lei nº 10.436, de 24 De acordo com o Art. 1°, A Língua de Sinai expressão. [...] Parágrafo único. Entende-se como Língu expressão, em que o sistema linguístico de natureza v um sistema linguístico de transmissão de ideias e fatos, Quando nos referimos às línguas de sinais, sabem linguísticas específicas, tal como nas línguas orais. P sistema linguístico de transmissão de ideias e fatos que a','','','["Querologia, Sintaxe, Pragmática.", "Querologia, Morfologia, Sintaxe, Semântica", "Fonética e fonologia (Querologia), Sintaxe, S", "Fonologia, Morfologia, Sintaxe, Pragmática."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Pedagogia: alternativa B. Resposta indicada no gabarito: Querologia, Morfologia, Sintaxe, Semântica.' from public.exams where slug='pmerj-2010-pedagogia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Pedagogia','Grande parte dos cariocas acredita que feijoada é dos malandros e que manga com álcool faz mal à saúde. A partir dessas atitudes de muitos cariocas, pode conhecimento','','','["popular, porque faz parte da cultura universa", "científico, pois pode ser observável, é racion", "filosófico, porque é oriundo da realidade soc", "popular, pois é fruto da experiência e das rel"]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Pedagogia: alternativa D. Resposta indicada no gabarito: popular, pois é fruto da experiência e das rel.' from public.exams where slug='pmerj-2010-pedagogia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Pedagogia','Leia o enunciado e as alternativas da questão 3 na imagem do caderno.','','["/pmerj-arquivo/pmerj-2010-pedagogia-q03-1-v3.png", "/pmerj-arquivo/pmerj-2010-pedagogia-q03-2-v3.png", "/pmerj-arquivo/pmerj-2010-pedagogia-q03-3-v3.png"]','["Alternativa A — consulte o caderno na imagem.", "Alternativa B — consulte o caderno na imagem.", "Alternativa C — consulte o caderno na imagem.", "Alternativa D — consulte o caderno na imagem."]'::jsonb,'A','Gabarito publicado da PMERJ — Oficial — Pedagogia: alternativa A. Consulte o enunciado original nas imagens para relacionar esta alternativa aos dados apresentados. Este comentário registra o gabarito, sem atribuir à banca uma resolução que ela não publicou.' from public.exams where slug='pmerj-2010-pedagogia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Pedagogia','De acordo com o MEC o Fundo de Manutenção dos Profissionais da Educação - FUNDEB - é um provenientes das três esferas de governo (Federal, Estad Constitucional n.º 53, de 19 de dezembro de 2006 e dezembro do mesmo ano, convertida na Lei 11.494, de em 1º de janeiro de 2007. Essa implantação está sendo 2009, quando o Fundo estará funcionando com todo o u os percentuais de receitas que o compõem terão alcanç dos recursos do Fundo serão usados no pagamento dos e, para fins de remuneração, considera','','','["os docentes, profissionais que oferecem incluindo--se direção ou administração escol", "os docentes, profissionais que oferecem incluindo--se direção ou administração escol", "os docentes, profissionais que oferecem incluindo- -se direção ou administração escolar, planeja", "os docentes, profissionais que oferecem incluindo- -se direção ou administração escolar, plane coordenação pedagógica."]'::jsonb,'D','Gabarito publicado da PMERJ — Oficial — Pedagogia: alternativa D. Resposta indicada no gabarito: os docentes, profissionais que oferecem incluindo- -se direção ou administração escolar, plane coordenação pedagógica..' from public.exams where slug='pmerj-2010-pedagogia' on conflict(exam_id,number) do nothing;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Pedagogia','De acordo com a LDB 9394/96, artigo 24, inc seguintes critérios: a) avaliação contínua e cumulativa do desempen sobre os quantitativos e dos resultados ao long b) possibilidade de aceleração de estudos para al c) possibilidade de avanço nos cursos e nas série d) aproveitamento de estudos concluídos com êx e) obrigatoriedade de estudos de recuperação, de baixo rendimento escolar, a serem disciplinad As orientações da LDB são importantes porque n ao se pensar na construção dos parâmetros de avaliaç concretas que efetivem ritos e rituais promotores de apre Esses critérios referem-se, exclusivamente, à aval','','','["conteúdos.", "aprendizagem.", "descritores.", "habilidades."]'::jsonb,'B','Gabarito publicado da PMERJ — Oficial — Pedagogia: alternativa B. Resposta indicada no gabarito: aprendizagem..' from public.exams where slug='pmerj-2010-pedagogia' on conflict(exam_id,number) do nothing;
